def agency_spaces_payload():
    limits = license_entitlements()
    registry = agency_registry()
    active = next((space for space in registry.get("spaces", []) if space.get("id") == registry.get("active_id")), None)
    usage = {
        "used": len(registry.get("spaces", [])),
        "limit": int(limits.get("workspace_limit") or 1),
        "remaining": max(0, int(limits.get("workspace_limit") or 1) - len(registry.get("spaces", []))),
    }
    return {**limits, **registry, "active_workspace": active or {}, "workspace_usage": usage}


def active_workspace_payload():
    spaces = agency_spaces_payload()
    if spaces["is_agency"]:
        return spaces.get("active_workspace") or {}
    binding = read_json(INDIVIDUAL_BINDING_FILE, {}) or business_identity()
    name_parts = [binding.get("ad_account_id"), binding.get("page_id")]
    return {
        "id": "individual-active-business",
        "name": " · ".join([part for part in name_parts if part]) or "Negocio activo",
        "type": "individual",
    }


def workspace_usage_payload():
    spaces = agency_spaces_payload()
    return spaces.get("workspace_usage") or {
        "used": 1 if any(business_identity().values()) else 0,
        "limit": license_entitlements()["workspace_limit"],
        "remaining": 0,
    }


def business_binding_payload():
    binding = read_json(INDIVIDUAL_BINDING_FILE, {})
    identity = business_identity()
    managed = managed_ad_accounts_payload()
    return {
        **identity,
        **binding,
        "managed_ad_accounts": managed,
        "business_manager": managed.get("business_manager", {}),
        "locked": not license_entitlements().get("is_agency") and bool(binding or load_onboarding_state().get("completed")),
    }


def create_agency_space(payload):
    limits = license_entitlements()
    if not limits.get("can_use_agency_workspaces", bool(limits.get("is_agency"))):
        raise ValueError("Tu licencia Individual cuida un solo negocio activo. Para manejar otro negocio, usa otra licencia separada.")
    name = str(payload.get("name") or "").strip()
    if not name:
        raise ValueError("Escribe el nombre del cliente o negocio.")
    registry = agency_registry()
    workspace_limit = int(limits.get("workspace_limit") or 1)
    if len(registry["spaces"]) >= workspace_limit:
        raise ValueError("Alcanzaste el limite de espacios de esta licencia.")
    space = {"id": workspace_slug(name), "name": name[:80], "created_at": now_iso()}
    registry["spaces"].append(space)
    target = AGENCY_SPACES_DIR / space["id"]
    target.mkdir(parents=True, mode=0o700, exist_ok=True)
    target.chmod(0o700)
    write_json(AGENCY_SPACES_FILE, registry)
    log_action("agency_space_create", {"space_id": space["id"], "name": space["name"]}, "completed")
    return {**space, "active": False}


def switch_agency_space(payload):
    global TELEGRAM_THREAD, TELEGRAM_STOP, TELEGRAM_FINGERPRINT
    limits = license_entitlements()
    if not limits.get("can_use_agency_workspaces", bool(limits.get("is_agency"))):
        raise ValueError("Cambiar entre negocios no está disponible en esta licencia.")
    target_id = str(payload.get("space_id") or "").strip()
    registry = agency_registry()
    target = next((space for space in registry["spaces"] if space["id"] == target_id), None)
    if not target:
        raise ValueError("No encontré ese espacio de cliente.")
    if registry.get("active_id"):
        snapshot_workspace(registry["active_id"])
    restore_workspace(target_id)
    registry["active_id"] = target_id
    write_json(AGENCY_SPACES_FILE, registry)
    if TELEGRAM_STOP:
        TELEGRAM_STOP.set()
    TELEGRAM_THREAD = None
    TELEGRAM_STOP = None
    TELEGRAM_FINGERPRINT = None
    ensure_telegram_listener()
    log_action("agency_space_switch", {"space_id": target_id, "name": target["name"]}, "completed")
    return agency_spaces_payload()


def set_mode(payload):
    # Backward-compatible no-op for older dashboards. The product no longer
    # exposes control modes; protected actions are governed by approval risk.
    values = {
        "META_ADS_AGENT_MODE": "dry-run",
        "LIVE_ACTIONS_ENABLED": "false",
    }
    update_env_values(values)
    log_action("mode_switch_deprecated", {"approval_model": "approval_required_for_spend_activation_publish_delete"}, "completed")
    return {"mode": "approval", "approval_model": True, "live_actions_enabled": False}


def save_guardrails(payload):
    bool_value = lambda key, default=True: str(payload.get(key, "true" if default else "false")).strip().lower() in {"1", "true", "yes", "on"}
    values = {
        "META_AUTONOMY_MODE": "approval",
        "META_APPROVAL_REQUIRED_OVER_PCT": str(float(payload.get("approval_required_over_pct") or 20)),
        "META_REQUIRE_APPROVAL_FOR_RESUME": "true" if bool_value("require_approval_for_resume", True) else "false",
        "META_REQUIRE_APPROVAL_FOR_NEW_CAMPAIGNS": "true" if bool_value("require_approval_for_new_campaigns", True) else "false",
        "META_REQUIRE_APPROVAL_FOR_CREATIVES": "true" if bool_value("require_approval_for_creatives", True) else "false",
    }
    update_env_values(values)
    log_action("guardrails_update", values, "completed")
    return {"saved": True, "values": values}


def save_daily_brief_schedule(payload):
    raw_time = str(payload.get("time") or "").strip()
    normalized_time = normalize_daily_time(raw_time, default="")
    if not normalized_time or normalized_time != raw_time:
        raise ValueError("Elige una hora válida para la lectura diaria.")
    raw_timezone = str(payload.get("timezone") or "").strip()
    normalized_timezone = normalize_timezone(raw_timezone, default="")
    if not normalized_timezone or normalized_timezone != raw_timezone:
        raise ValueError("No pude reconocer la zona horaria de este dispositivo.")

    update_env_values({"DAILY_BRIEF_TIME": normalized_time})
    save_timezone_preference(normalized_timezone, "buyer")
    ad_config = read_json(AD_CONFIG_FILE, {})
    ad_config.setdefault("reporting", {})["timezone"] = normalized_timezone
    write_json(AD_CONFIG_FILE, ad_config)

    config = load_config()
    gateway = start_hermes_gateway(config)
    cron = ensure_daily_brief_cron(config)
    social_content_cron = ensure_daily_social_content_cron(config)
    organic_intro_cron = ensure_post_install_organic_intro_cron(config)
    experiment_crons = ensure_experiment_review_crons(config)
    research_cron = ensure_weekly_research_cron(config)
    log_action(
        "daily_brief_schedule_update",
        {"time": normalized_time, "timezone": normalized_timezone, "cron_configured": bool(cron.get("configured"))},
        "completed" if cron.get("configured") else "blocked",
    )
    return {
        "saved": True,
        "time": normalized_time,
        "timezone": normalized_timezone,
        "gateway": gateway,
        "cron": cron,
        "social_content_cron": social_content_cron,
        "organic_intro_cron": organic_intro_cron,
        "experiment_crons": experiment_crons,
        "research_cron": research_cron,
    }


def _truthy_payload_value(payload, key, default=False):
    value = (payload or {}).get(key, default)
    return str(value).strip().lower() in {"1", "true", "yes", "si", "sí", "on", "enabled", "activar", "activo"}


def meaningful_content_strategy_text(payload=None):
    payload = payload or {}
    incoming = str(payload.get("content_strategy") or payload.get("strategy_summary") or payload.get("strategy") or "").strip()
    if incoming:
        return incoming
    try:
        stored = CONTENT_STRATEGY_FILE.read_text(encoding="utf-8") if CONTENT_STRATEGY_FILE.exists() else ""
    except (OSError, UnicodeDecodeError):
        stored = ""
    lines = [
        line.strip()
        for line in stored.splitlines()
        if line.strip()
        and not line.lstrip().startswith("#")
        and "Buyer-approved or agent-proposed direction" not in line
    ]
    return "\n".join(lines).strip()


def organic_content_readiness(payload=None):
    payload = payload or {}
    branding = branding_creative_readiness(require_product=True, payload=payload)
    missing = list(branding.get("missing") or [])
    strategy = meaningful_content_strategy_text(payload)
    if not strategy:
        missing.append(
            {
                "key": "content_strategy",
                "question": "Antes de programar los posts, definamos los pilares, ofertas/temas, frecuencia, CTA y si se publicarán en Facebook después de tu aprobación.",
            }
        )
    return {
        "ready": not missing,
        "missing": missing,
        "next_question": missing[0].get("question", "") if missing else "",
        "branding_ready": bool(branding.get("ready")),
        "strategy_ready": bool(strategy),
        "strategy": strategy,
    }


def save_daily_social_content_settings(payload):
    payload = payload or {}
    requested_enabled = _truthy_payload_value(payload, "enabled", _truthy_payload_value(payload, "daily_social_content_enabled", False))
    raw_time = str(payload.get("time") or payload.get("daily_social_content_time") or "10:00").strip()
    normalized_time = normalize_daily_time(raw_time, default="")
    if not normalized_time or normalized_time != raw_time:
        raise ValueError("Elige una hora válida para preparar los posts diarios.")
    raw_timezone = str(payload.get("timezone") or "").strip()
    if raw_timezone:
        normalized_timezone = normalize_timezone(raw_timezone, default="")
        if not normalized_timezone or normalized_timezone != raw_timezone:
            raise ValueError("No pude reconocer la zona horaria para los posts diarios.")
        save_timezone_preference(normalized_timezone, "buyer")
    try:
        posts_per_day = int(payload.get("posts_per_day") or payload.get("count") or payload.get("daily_social_content_posts_per_day") or 1)
    except (TypeError, ValueError):
        posts_per_day = 1
    posts_per_day = max(1, min(5, posts_per_day))
    try:
        interval_days = int(payload.get("interval_days") or payload.get("frequency_days") or payload.get("every_days") or payload.get("daily_social_content_interval_days") or 1)
    except (TypeError, ValueError):
        interval_days = 1
    interval_days = max(1, min(30, interval_days))
    raw_formats = payload.get("content_formats") or payload.get("formats") or payload.get("daily_social_content_formats")
    if isinstance(raw_formats, str):
        raw_formats = [item.strip() for item in re.split(r"[,;|]+", raw_formats) if item.strip()]
    if not isinstance(raw_formats, (list, tuple, set)):
        raw_formats = []
    format_aliases = {
        "image": "image", "images": "image", "imagen": "image", "imagenes": "image", "imágenes": "image",
        "static": "image", "statics": "image", "estatico": "image", "estático": "image",
        "video": "motion_video", "videos": "motion_video", "motion": "motion_video",
        "motion_video": "motion_video", "motion graphics": "motion_video", "motion_graphics": "motion_video",
        "mixed": "mixed", "mixto": "mixed", "adaptive": "mixed", "adaptativo": "mixed",
    }
    formats = []
    for value in raw_formats:
        normalized = format_aliases.get(str(value or "").strip().lower().replace("-", "_"), "")
        if normalized == "mixed":
            for item in ("image", "motion_video"):
                if item not in formats:
                    formats.append(item)
        elif normalized and normalized not in formats:
            formats.append(normalized)
    if _truthy_payload_value(payload, "include_motion_video", False) and "motion_video" not in formats:
        formats.append("motion_video")
    if not formats:
        existing_formats = str(os.environ.get("DAILY_SOCIAL_CONTENT_FORMATS") or "image").strip().lower()
        formats = [item for item in existing_formats.split(",") if item in {"image", "motion_video"}] or ["image"]
    try:
        video_interval_days = int(
            payload.get("video_frequency_days")
            or payload.get("motion_video_interval_days")
            or payload.get("daily_social_content_video_interval_days")
            or os.environ.get("DAILY_SOCIAL_CONTENT_VIDEO_INTERVAL_DAYS")
            or 7
        )
    except (TypeError, ValueError):
        video_interval_days = 7
    video_interval_days = max(1, min(30, video_interval_days))
    readiness = organic_content_readiness(payload) if requested_enabled else {"ready": True, "missing": [], "next_question": "", "strategy_ready": False, "branding_ready": False}
    enabled = bool(requested_enabled and readiness.get("ready"))
    decision = "enabled" if enabled else ("accepted_pending_setup" if requested_enabled else "declined")
    updates = {
        "DAILY_SOCIAL_CONTENT_ENABLED": "true" if enabled else "false",
        "DAILY_SOCIAL_CONTENT_DECISION": decision,
        "DAILY_SOCIAL_CONTENT_TIME": normalized_time,
        "DAILY_SOCIAL_CONTENT_POSTS_PER_DAY": str(posts_per_day),
        "DAILY_SOCIAL_CONTENT_INTERVAL_DAYS": str(interval_days),
        "DAILY_SOCIAL_CONTENT_FORMATS": ",".join(formats),
        "DAILY_SOCIAL_CONTENT_VIDEO_INTERVAL_DAYS": str(video_interval_days),
    }
    update_env_values(updates)
    strategy_note = str(payload.get("content_strategy") or payload.get("strategy_summary") or payload.get("strategy") or "").strip()
    if strategy_note:
        CONTENT_STRATEGY_FILE.parent.mkdir(parents=True, exist_ok=True)
        CONTENT_STRATEGY_FILE.write_text(
            "# Content strategy\n\n"
            "Buyer-approved or agent-proposed direction for daily organic posts.\n\n"
            f"{strategy_note}\n",
            encoding="utf-8",
        )
    config = load_config()
    # This function is also invoked from the Admira MCP process that is owned by
    # the currently running Hermes Gateway. Restarting the Gateway synchronously
    # from that child tool call terminates the request that is performing the
    # save and can leave Telegram offline. Daily-content settings and their cron
    # are hot-reloadable, so persist/reconcile them without touching the active
    # Gateway process.
    gateway = {
        "mode": "hermes_gateway",
        "untouched": True,
        "restart_deferred": True,
        "restart_required": False,
        "detail": "Contenido recurrente guardado sin interrumpir Telegram.",
    }
    cron = ensure_daily_social_content_cron(config)
    log_action(
        "daily_social_content_settings_update",
        {
            "requested_enabled": requested_enabled,
            "enabled": enabled,
            "decision": decision,
            "time": normalized_time,
            "posts_per_day": posts_per_day,
            "interval_days": interval_days,
            "content_formats": formats,
            "video_interval_days": video_interval_days,
            "cron_configured": bool(cron.get("configured")),
            "missing": [item.get("key") for item in readiness.get("missing", []) if isinstance(item, dict)],
        },
        "completed" if (not requested_enabled or cron.get("configured")) else "blocked",
    )
    return {
        "saved": True,
        "requested_enabled": requested_enabled,
        "enabled": enabled,
        "decision": decision,
        "pending_setup": bool(requested_enabled and not enabled),
        "readiness": readiness,
        "time": normalized_time,
        "timezone": config.daily_brief_timezone,
        "posts_per_day": posts_per_day,
        "interval_days": interval_days,
        "content_formats": formats,
        "video_interval_days": video_interval_days,
        "gateway": gateway,
        "cron": cron,
    }


def stage_organic_social_post(payload):
    payload = dict(payload or {})
    caption = str(payload.get("caption") or payload.get("message") or payload.get("copy") or "").strip()
    if not caption:
        raise ValueError("Antes de pedir aprobación, necesito el texto/caption exacto que se publicará.")
    image_paths = safe_image_paths(payload)
    image_path = image_paths[0] if image_paths else ""
    image_url = str(payload.get("image_url") or "").strip()
    if image_url:
        parsed = urlparse(image_url)
        if parsed.scheme not in {"http", "https"} or not parsed.netloc:
            image_url = ""
    video_path_obj = safe_motion_media_path(payload.get("video_path") or payload.get("motion_video_path"), expected="video")
    video_path = str(video_path_obj) if video_path_obj else ""
    video_url = str(payload.get("video_url") or "").strip()
    if video_url:
        parsed = urlparse(video_url)
        if parsed.scheme not in {"http", "https"} or not parsed.netloc:
            video_url = ""
    if (image_path or image_url) and (video_path or video_url):
        raise ValueError("Envía una sola pieza final por borrador: una imagen o un video, no ambos.")
    if not image_path and not image_url and not video_path and not video_url:
        raise ValueError("Antes de pedir aprobación, necesito la imagen o el video final generado.")
    media_type = "video" if (video_path or video_url) else "image"
    identity = business_identity(payload)
    page_id = str(payload.get("page_id") or payload.get("facebook_page_id") or identity.get("page_id") or "").strip()
    status = publishing_status(load_config(), {"page_id": page_id})
    missing = []
    if not page_id:
        missing.append("Facebook Page")
    if not status.get("token_set"):
        missing.append("Publicación directa")
    if missing:
        return {
            "ok": False,
            "blocked": True,
            "reason": "social_publishing_not_ready",
            "missing": missing,
            "reply": "La pieza está lista, pero antes de publicarla conecta la Página y Publicación directa en Configuración.",
        }
    link = str(payload.get("link") or payload.get("landing_url") or "").strip()
    cta = str(payload.get("cta") or "LEARN_MORE").strip().upper().replace(" ", "_")
    fingerprint_source = json.dumps(
        {"page_id": page_id, "caption": caption, "image_path": image_path, "image_url": image_url, "video_path": video_path, "video_url": video_url, "link": link, "cta": cta},
        ensure_ascii=False,
        sort_keys=True,
    )
    draft_id = hashlib.sha256(fingerprint_source.encode("utf-8")).hexdigest()[:20]
    approval_id = f"approval_social_{draft_id}"
    approval_payload = {
        "approval_id": approval_id,
        "draft_id": draft_id,
        "name": str(payload.get("name") or payload.get("title") or ("Video orgánico para Facebook" if media_type == "video" else "Post orgánico para Facebook")).strip(),
        "page_id": page_id,
        "destination": "facebook",
        "message": caption,
        "image_path": image_path,
        "image_url": image_url,
        "video_path": video_path,
        "video_url": video_url,
        "media_type": media_type,
        "link": link,
        "cta": cta,
        "pillar": str(payload.get("pillar") or "").strip(),
        "objective": str(payload.get("objective") or "").strip(),
        "why_it_fits": str(payload.get("why_it_fits") or payload.get("rationale") or "").strip(),
        "requested": f"Publicar este {media_type} orgánico visible en la Página de Facebook después de aprobación explícita.",
    }
    approval = add_pending("publish_social_post", approval_payload)
    log_action(
        "organic_social_post_stage",
        {"approval_id": approval_id, "draft_id": draft_id, "page_id": page_id, "pillar": approval_payload["pillar"]},
        "pending_approval",
    )
    return {
        "ok": True,
        "executed": False,
        "staged": True,
        "approval_required": True,
        "approval": approval,
        "approval_id": approval_id,
        "draft_id": draft_id,
        "caption": caption,
        "image_path": image_path,
        "video_path": video_path,
        "media_type": media_type,
        "reply": f"{'Video' if media_type == 'video' else 'Post'} listo para revisar. Si te gusta, responde “aprobado” y lo publicaré en Facebook; si quieres cambios, dímelos y no publicaré esta versión.",
    }


