def save_shopify_config(payload):
    config = load_config()
    disconnect = str(payload.get("disconnect") or "").lower() in {"1", "true", "yes", "on"}
    if disconnect:
        update_env_values({"SHOPIFY_SHOP_DOMAIN": "", "SHOPIFY_ADMIN_API_TOKEN": "", "SHOPIFY_API_VERSION": "2026-04"})
        log_action("shopify_disconnect", {}, "completed")
        return {"saved": True, "status": shopify_status(load_config())}
    domain = normalize_shop_domain(payload.get("shop_domain") or getattr(config, "shopify_shop_domain", ""))
    token = str(payload.get("admin_token") or "").strip()
    if token and len(token) < 20:
        raise ValueError("The Shopify Admin API token is too short.")
    if not token:
        token = getattr(config, "shopify_admin_token", "")
    if not token:
        raise ValueError("Paste a read-only Shopify Admin API token with read_orders scope.")
    api_version = str(payload.get("api_version") or getattr(config, "shopify_api_version", "2026-04")).strip()
    if not re.fullmatch(r"20\d{2}-(01|04|07|10)", api_version):
        api_version = "2026-04"
    update_env_values({"SHOPIFY_SHOP_DOMAIN": domain, "SHOPIFY_ADMIN_API_TOKEN": token, "SHOPIFY_API_VERSION": api_version})
    log_action("shopify_config_update", {"shop_domain": domain, "token_set": True, "api_version": api_version}, "completed")
    return {"saved": True, "status": shopify_status(load_config())}


def test_shopify_settings(_payload=None):
    config = load_config()
    if not getattr(config, "shopify_shop_domain", "") or not getattr(config, "shopify_admin_token", ""):
        raise ValueError("Connect Shopify first.")
    result = test_shopify_connection(config.shopify_shop_domain, config.shopify_admin_token, config.shopify_api_version)
    if not result.get("ok"):
        raise ValueError((result.get("error") or {}).get("message") or "Shopify connection failed.")
    log_action("shopify_connection_test", {"shop_domain": config.shopify_shop_domain, "ok": True}, "completed")
    return result


def sync_shopify_outcomes(_payload=None):
    config = load_config()
    if not getattr(config, "shopify_shop_domain", "") or not getattr(config, "shopify_admin_token", ""):
        raise ValueError("Connect Shopify first.")
    result = sync_shopify(config.shopify_shop_domain, config.shopify_admin_token, config.shopify_api_version)
    if not result.get("ok"):
        log_action("shopify_sync", {"shop_domain": config.shopify_shop_domain, "error": result.get("error")}, "blocked")
        raise ValueError((result.get("error") or {}).get("message") or "Shopify sync failed.")
    safe_result = {key: value for key, value in result.items() if key != "outcomes"}
    log_action("shopify_sync", safe_result, "completed")
    return safe_result


def telegram_welcome_text(language="es"):
    if str(language or "es").lower().startswith("en"):
        return (
            "Hello, I am connected now.\n\n"
            "You can talk to me here as your Meta Ads manager. "
            "I will first understand your business, then your visual brand, and then your ads strategy.\n\n"
            "Reply here when you are ready and I will continue one question at a time."
        )
    return (
        "Hola, ya quedé conectado.\n\n"
        "Puedes hablarme por aquí como tu manager de Meta Ads. "
        "Primero voy a entender tu negocio, después tu marca visual y luego tu estrategia de anuncios.\n\n"
        "Respóndeme aquí cuando estés listo y seguimos una pregunta a la vez."
    )


def send_telegram_welcome_message(config, chat_id, language="es"):
    chat = str(chat_id or "").strip()
    if not (config.telegram_bot_token and chat):
        return {"sent": False, "error": "telegram_not_ready"}
    try:
        telegram_bot_request(config, "sendMessage", {"chat_id": chat, "text": telegram_welcome_text(language)}, timeout=10)
        log_action("telegram_welcome_send", {"chat_id_set": True}, "completed")
        return {"sent": True}
    except Exception as exc:
        log_action("telegram_welcome_send", {"chat_id_set": True, "error": str(exc)}, "failed")
        return {"sent": False, "error": str(exc)}


def save_telegram_config(payload):
    old_config = load_config()
    limits = license_entitlements()
    registry = agency_registry()
    if limits.get("is_agency") and not limits.get("can_use_multi_telegram_profiles", bool(limits.get("is_agency"))) and len(registry.get("spaces", [])) > 1:
        raise ValueError("Varios perfiles de Telegram no están disponibles en esta licencia.")
    values = {}
    if "enabled" in payload:
        values["TELEGRAM_AGENT_ENABLED"] = "true" if str(payload.get("enabled")).strip().lower() in {"1", "true", "yes", "on"} else "false"
    if str(payload.get("bot_token") or "").strip():
        values["TELEGRAM_BOT_TOKEN"] = str(payload.get("bot_token")).strip()
    if "chat_id" in payload:
        values["TELEGRAM_CHAT_ID"] = str(payload.get("chat_id") or "").strip()
    if "language" in payload:
        values["TELEGRAM_LANGUAGE"] = "en" if str(payload.get("language")).strip().lower() == "en" else "es"
    next_bot = values.get("TELEGRAM_BOT_TOKEN", old_config.telegram_bot_token)
    next_chat = values.get("TELEGRAM_CHAT_ID", old_config.telegram_chat_id)
    # A BotFather token entered from the setup UI must never inherit a stored
    # private chat.  This also handles installs whose Docker/runtime volume
    # survived a reinstall, and forces the buyer to send the required "hola"
    # to the bot currently being configured.  An explicit chat_id is still
    # honored for the detected-chat save path.
    if str(payload.get("bot_token") or "").strip() and "chat_id" not in payload:
        values["TELEGRAM_CHAT_ID"] = ""
        next_chat = ""
    connection_changed = next_bot != old_config.telegram_bot_token or next_chat != old_config.telegram_chat_id
    if values:
        update_env_values(values)
    if connection_changed:
        reset_telegram_polling_state()
    config = load_config()
    status = telegram_settings(config)
    gateway = ensure_telegram_listener()
    status["listener_started"] = bool(gateway.get("started") if isinstance(gateway, dict) else gateway)
    status["gateway"] = gateway if isinstance(gateway, dict) else {}
    if str(payload.get("send_welcome") or "").strip().lower() in {"1", "true", "yes", "on"} and status.get("chat_id"):
        welcome = send_telegram_welcome_message(config, status.get("chat_id"), status.get("language") or values.get("TELEGRAM_LANGUAGE") or "es")
        status["welcome_sent"] = bool(welcome.get("sent"))
        if welcome.get("error"):
            status["welcome_error"] = welcome.get("error")
    if status.get("enabled") and status.get("bot_configured") and status.get("chat_id"):
        profile = read_json(BUSINESS_PROFILE_FILE, {})
        if isinstance(profile, dict) and not profile.get("telegram_onboarding_message_sent_at"):
            write_onboarding_questions_memory(profile, "pending")
            profile["telegram_onboarding_message_sent_at"] = now_iso()
            profile["telegram_onboarding_channel"] = "hermes_gateway"
            write_json(BUSINESS_PROFILE_FILE, profile)
            status["onboarding_message_ready"] = True
        status["daily_brief_cron"] = ensure_daily_brief_cron(config)
        status["daily_social_content_cron"] = ensure_daily_social_content_cron(config)
        status["post_install_organic_intro_cron"] = ensure_post_install_organic_intro_cron(config)
        status["experiment_review_crons"] = ensure_experiment_review_crons(config)
        status["research_cron"] = ensure_weekly_research_cron(config)
    log_action("telegram_config_save", {"enabled": status["enabled"], "mode": status.get("mode"), "bot_configured": status["bot_configured"], "chat_id_set": bool(status["chat_id"])}, "completed")
    return status


def ensure_telegram_listener():
    global TELEGRAM_THREAD, TELEGRAM_STOP, TELEGRAM_FINGERPRINT
    config = load_config()
    status = telegram_settings(config)
    if status.get("mode") != "legacy":
        if TELEGRAM_STOP:
            TELEGRAM_STOP.set()
        TELEGRAM_THREAD = None
        TELEGRAM_STOP = None
        TELEGRAM_FINGERPRINT = None
        _ensure_nvidia_runtime_fallback_catalog(config)
        gateway = start_hermes_gateway(config)
        # Facebook OAuth is an installation prerequisite, not a sales/spend
        # action.  Do not delegate the first link to model prose: a model can
        # ask for permission, mention a stale inline button, or simply omit
        # the tool call.  Once Telegram has a real private chat, dispatch the
        # ordinary-text OAuth URL deterministically in the background.  The
        # pending request prevents duplicate links if Hermes also calls the
        # explicit tool in the same turn.
        threading.Thread(
            target=_dispatch_initial_meta_oauth_link,
            args=(config,),
            daemon=True,
            name="admira-initial-meta-oauth",
        ).start()
        return gateway
    fingerprint = (config.telegram_bot_token, status["chat_id"], status["enabled"], status["language"])
    if not (status["enabled"] and status["bot_configured"] and status["chat_id"]):
        if TELEGRAM_STOP:
            TELEGRAM_STOP.set()
        TELEGRAM_FINGERPRINT = None
        return False
    if TELEGRAM_THREAD and TELEGRAM_THREAD.is_alive() and not (TELEGRAM_STOP and TELEGRAM_STOP.is_set()) and TELEGRAM_FINGERPRINT == fingerprint:
        return True
    if TELEGRAM_STOP:
        TELEGRAM_STOP.set()
    TELEGRAM_STOP = threading.Event()
    from telegram_agent import run as run_telegram_listener
    TELEGRAM_THREAD = threading.Thread(target=run_telegram_listener, args=(TELEGRAM_STOP,), name="telegram-agent", daemon=True)
    TELEGRAM_THREAD.start()
    TELEGRAM_FINGERPRINT = fingerprint
    return {"started": True, "mode": "legacy"}


def _ensure_nvidia_runtime_fallback_catalog(config):
    """Refresh the account-verified NIM catalog before Hermes writes config.

    A new installation used to write its Hermes fallback chain before it had
    ever queried ``/models``.  The chain was therefore empty even when a
    different NVIDIA hosted model was healthy.  This is metadata only (not an
    inference request), is cached for six hours, and failures never interrupt
    Telegram or create a second request loop.
    """
    brain = normalize_agent_brain_provider(
        getattr(config, "agent_brain_provider", ""),
        legacy_chat_provider=getattr(config, "agent_chat_provider", "hermes"),
        base_url=getattr(config, "agent_chat_base_url", ""),
    )
    if brain != "nvidia_nim":
        return {}
    key = str(getattr(config, "agent_chat_api_key", "") or "").strip()
    if not key:
        try:
            key = str(agent_model_connections(config, include_secrets=True).get("nvidia_nim", {}).get("api_key") or "").strip()
        except Exception:
            key = ""
    if not key:
        return {}
    try:
        return nvidia_model_catalog(api_key=key, config=config, force_refresh=False)
    except Exception as exc:
        # Existing saved fallback data remains usable.  Do not turn a model
        # catalog refresh into a buyer-facing outage.
        log_action("nvidia_runtime_catalog", {"error": str(exc)[:180]}, "attention")
        return {}


def _dispatch_initial_meta_oauth_link(config):
    """Send the first OAuth URL without waiting for an LLM decision.

    Existing token-based installations retain their current connection.  New
    OAuth-first installations receive exactly the direct text link; account
    and Page selection still happens conversationally after OAuth returns.
    """
    try:
        status = telegram_settings(config)
        if not (status.get("enabled") and status.get("bot_configured") and status.get("chat_id")):
            return
        # This helper obtains the current config internally. Passing the
        # config object here caused the first-link dispatcher to raise before
        # contacting Telegram, leaving a new buyer with prose about a button
        # but no actual OAuth URL.
        current = social_oauth_status()
        if current.get("connected") or current.get("pending") or config.meta_access_token:
            return
        social_oauth_start({"telegram_chat_id": status["chat_id"], "source": "initial_telegram_setup"})
    except Exception as exc:
        # A failed broker must not prevent the gateway itself from answering.
        log_action("meta_oauth_initial_link", {"error": str(exc)[:240]}, "blocked")


def detect_telegram_chats():
    config = load_config()
    if not config.telegram_bot_token:
        raise ValueError("Primero guarda la clave que te entregó @BotFather.")
    updates = telegram_bot_request(config, "getUpdates", {"timeout": 0, "allowed_updates": json.dumps(["message"])}, timeout=10) or []
    candidates = {}
    for update in updates:
        chat = (update.get("message") or {}).get("chat") or {}
        if chat.get("type") != "private" or not chat.get("id"):
            continue
        label = " ".join(filter(None, [chat.get("first_name"), chat.get("last_name")])).strip()
        username = f"@{chat.get('username')}" if chat.get("username") else ""
        candidates[str(chat["id"])] = {"id": str(chat["id"]), "label": label or username or "Chat privado", "username": username}
    return list(candidates.values())[-5:]


def test_telegram_connection():
    config = load_config()
    status = telegram_settings(config)
    if not status["bot_configured"] or not status["chat_id"]:
        raise ValueError("Guarda el bot y el chat antes de enviar la prueba.")
    gateway = ensure_telegram_listener()
    log_action("telegram_gateway_check", {"chat_id_set": True, "mode": status.get("mode")}, "completed")
    return {"ready": bool(gateway.get("started") if isinstance(gateway, dict) else gateway), "gateway": gateway if isinstance(gateway, dict) else {}}


def activate_license_now(payload=None):
    payload = payload or {}
    env_updates = {}
    license_key = str(payload.get("license_key") or "").strip()
    buyer_email = str(payload.get("license_buyer_email") or payload.get("buyer_email") or "").strip().lower()
    if license_key:
        env_updates["LICENSE_KEY"] = license_key.upper()
    if buyer_email:
        env_updates["LICENSE_BUYER_EMAIL"] = buyer_email
    if env_updates:
        update_env_values(env_updates)
    config = load_config()
    status = activate_license(config, transfer_device=bool(payload.get("transfer_device")))
    if status.get("valid"):
        remember_license_binding_state(config, status, "local_activated")
        if load_onboarding_state().get("completed"):
            remember_license_binding_state(
                config,
                mark_license_install_state(config, "onboarding_completed"),
                "onboarding_completed",
            )
        else:
            remember_license_binding_state(config, mark_license_install_state(config, "local_activated"), "local_activated")
            remember_license_binding_state(config, mark_license_install_state(config, "onboarding_opened"), "onboarding_opened")
    log_action("license_activate", {"status": status.get("status"), "valid": bool(status.get("valid")), "online": bool(status.get("online"))}, "completed" if status.get("valid") else "blocked")
    return status


def remember_license_binding_state(config, result, event=""):
    if not isinstance(result, dict) or not result.get("valid"):
        return False
    binding = str(result.get("device_binding") or "").strip().lower()
    if event == "onboarding_completed":
        binding = "confirmed"
    if binding not in {"provisional", "confirmed"}:
        return False
    write_private_json(
        LICENSE_BINDING_STATE_FILE,
        {
            "device_id": resolved_device_id(config.license_device_id, config.license_key),
            "status": binding,
            "event": event or "local_activated",
            "updated_at": now_iso(),
        },
    )
    return True


def sync_completed_onboarding_license_binding(config=None):
    """Retry final device confirmation after temporary network/server failures."""
    config = config or load_config()
    onboarding = load_onboarding_state()
    if not onboarding.get("completed") or not config.license_key:
        return {"confirmed": False, "reason": "onboarding_incomplete"}
    device_id = resolved_device_id(config.license_device_id, config.license_key)
    cached = read_json(LICENSE_BINDING_STATE_FILE, {})
    if (
        isinstance(cached, dict)
        and cached.get("status") == "confirmed"
        and cached.get("device_id") == device_id
    ):
        return {"confirmed": True, "cached": True}
    result = mark_license_install_state(config, "onboarding_completed")
    confirmed = remember_license_binding_state(config, result, "onboarding_completed")
    return {"confirmed": confirmed, "cached": False, "status": result.get("status", "")}


def social_auth_status():
    config = load_config()
    if not config.meta_access_token:
        return {
            "ok": False,
            "code": 1,
            "command": "Meta Graph token check",
            "output": "Missing Meta access token.",
            "facebook_ready": False,
            "token_expired": False,
            "default_account": config.ad_account_id,
            "oauth": social_oauth_status(),
        }
    result = graph_get("/me", {"fields": "id,name"})
    raw = json.dumps(result.get("data") if result.get("ok") else result.get("error"), ensure_ascii=False)
    raw_lower = raw.lower()
    expired = any(token in raw_lower for token in ["expired", "oauthexception", "code: 190", "validating access token"])
    return {
        "ok": bool(result.get("ok")),
        "code": 0 if result.get("ok") else 1,
        "command": "Meta Graph /me",
        "output": raw[-5000:],
        "facebook_ready": bool(result.get("ok")) and not expired,
        "token_expired": expired,
        "default_account": config.ad_account_id,
        "oauth": social_oauth_status(),
    }


def social_login_url():
    return {
        "url": "",
        "instructions": {
            "es": "Conecta Facebook desde el enlace seguro que Admira envía a tu Telegram. No pegues claves de Meta.",
            "en": "Connect Facebook with the secure link Admira sends to Telegram. Do not paste Meta keys.",
        },
    }


def _meta_oauth_broker_url(config=None):
    config = config or load_config()
    raw = str(getattr(config, "meta_oauth_broker_url", "") or "").strip().rstrip("/")
    parsed = urllib.parse.urlparse(raw)
    if parsed.scheme != "https" or not parsed.netloc or parsed.username or parsed.password:
        return ""
    return raw


def _meta_oauth_request(url, payload):
    body = json.dumps(payload).encode("utf-8")
    request = urllib.request.Request(url, data=body, method="POST", headers={"Content-Type": "application/json", "Accept": "application/json"})
    try:
        with urllib.request.urlopen(request, timeout=20) as response:
            data = json.loads(response.read().decode("utf-8"))
    except urllib.error.HTTPError as exc:
        try:
            data = json.loads(exc.read().decode("utf-8"))
        except Exception:
            data = {"ok": False, "error": "oauth_broker_unavailable"}
    except Exception:
        data = {"ok": False, "error": "oauth_broker_unavailable"}
    return data if isinstance(data, dict) else {"ok": False, "error": "oauth_broker_invalid_response"}


def _meta_oauth_pending():
    value = read_json(META_OAUTH_PENDING_FILE, {})
    return value if isinstance(value, dict) else {}


def _meta_oauth_connection():
    value = read_json(META_OAUTH_CONNECTION_FILE, {})
    return value if isinstance(value, dict) else {}


def _meta_oauth_selection_authorizer():
    """Return the private, persistent authorizer used by the Telegram runtime."""
    return MetaSelectionAuthorizer(
        META_OAUTH_SELECTION_AUTH_FILE,
        key_path=META_OAUTH_SELECTION_KEY_FILE,
        ttl_seconds=1800,
    )


def _meta_oauth_selection_inventory(connection=None):
    """Build the selectable inventory; the authorizer strips all token fields."""
    connection = connection if isinstance(connection, dict) else _meta_oauth_connection()
    return {
        "accounts": [
            item for item in (connection.get("accounts") or [])
            if isinstance(item, dict) and clean_ad_account_id(item.get("id"))
        ][:50],
        "pages": _oauth_publishable_pages(connection)[:50],
    }


def _meta_oauth_selection_current_pair(connection=None):
    connection = connection if isinstance(connection, dict) else _meta_oauth_connection()
    return {
        "ad_account_id": clean_ad_account_id(connection.get("active_ad_account_id")),
        "page_id": str(connection.get("active_page_id") or "").strip(),
    }


def _public_meta_selection_authorization(result):
    result = result if isinstance(result, dict) else {}
    return {
        key: result.get(key)
        for key in (
            "status",
            "reason",
            "mode",
            "missing",
            "expires_at",
            "inventory_hash",
            "message_sequence",
        )
        if result.get(key) not in (None, "")
    }


def _open_meta_oauth_selection_intent_for_trusted_turn(*, allow_switch=False):
    """Open/reuse a selection intent for the current server-recorded turn.

    The ordinary status endpoint opens this only while the OAuth connection
    still lacks a complete active pair. A trusted runtime handling an explicit
    workspace-switch workflow may opt into ``allow_switch=True``.
    """
    turn = _trusted_buyer_turn()
    if not turn:
        return {"status": "unavailable", "reason": "missing_trusted_buyer_turn"}
    if str(turn.get("meta_selection_ticket") or "").strip():
        # The buyer's current message already produced a private capability.
        # Reopening an intent here would correctly revoke that ticket as stale
        # and would make a normal get-workspaces -> select sequence impossible.
        return {
            "status": "authorized_pending_persistence",
            "message_sequence": turn.get("message_sequence"),
        }
    chat_id = str(turn.get("chat_id") or "").strip()
    session_id = str(turn.get("session_id") or "").strip()
    try:
        message_sequence = int(turn.get("message_sequence"))
    except (TypeError, ValueError):
        return {"status": "unavailable", "reason": "missing_trusted_message_sequence"}
    if not chat_id or not session_id:
        return {"status": "unavailable", "reason": "missing_trusted_runtime_binding"}

    connection = _meta_oauth_connection()
    inventory = _meta_oauth_selection_inventory(connection)
    current_pair = _meta_oauth_selection_current_pair(connection)
    if not connection.get("connected") or not inventory["accounts"] or not inventory["pages"]:
        return {"status": "unavailable", "reason": "oauth_inventory_not_ready"}
    pair_complete = bool(current_pair["ad_account_id"] and current_pair["page_id"])
    if pair_complete and not allow_switch:
        return {"status": "not_required", "reason": "workspace_already_selected"}

    authorizer = _meta_oauth_selection_authorizer()
    existing = authorizer.current_intent(chat_id=chat_id, session_id=session_id)
    expected_hash = inventory_fingerprint(inventory)
    if existing:
        if (
            existing.get("inventory_hash") == expected_hash
            and existing.get("current_pair") == current_pair
        ):
            return {
                "status": "waiting_for_buyer_selection",
                "mode": existing.get("mode"),
                "expires_at": existing.get("expires_at"),
                "inventory_hash": existing.get("inventory_hash"),
            }
        authorizer.clear(chat_id=chat_id, session_id=session_id)

    opened = authorizer.open_intent(
        chat_id=chat_id,
        session_id=session_id,
        inventory=inventory,
        current_pair=current_pair,
        # The current trusted buyer message can already identify both assets.
        # Inventory only becomes available during this call, so resolve that
        # message now instead of forcing a redundant confirmation turn.
        opened_after_sequence=max(0, message_sequence - 1),
        mode="switch" if pair_complete else "initial",
    )
    try:
        authorization = authorizer.authorize_current_message(
            chat_id=chat_id,
            session_id=session_id,
            message_sequence=message_sequence,
            raw_message=str(turn.get("message") or ""),
            inventory=inventory,
            current_pair=current_pair,
        )
    except (SelectionIntentNotFound, SelectionBindingMismatch, SelectionAuthorizationError):
        authorization = {}
    if authorization.get("status") == "authorized" and authorization.get("ticket"):
        with _trusted_buyer_turn_lock():
            latest_turn = _trusted_buyer_turn_unlocked()
            if isinstance(latest_turn, dict) and hmac.compare_digest(
                str(latest_turn.get("message_hash") or ""),
                str(turn.get("message_hash") or ""),
            ):
                latest_turn["meta_selection_ticket"] = str(authorization["ticket"])
                latest_turn["meta_selection_authorization"] = _public_meta_selection_authorization(authorization)
                write_private_json(TRUSTED_BUYER_TURN_FILE, latest_turn)
        return {
            **_public_meta_selection_authorization(authorization),
            "status": "authorized_pending_persistence",
        }
    return {
        "status": "waiting_for_buyer_selection",
        "mode": opened.get("mode"),
        "expires_at": opened.get("expires_at"),
        "inventory_hash": opened.get("inventory_hash"),
    }


def _trusted_meta_workspace_switch_requested(turn=None):
    """Recognize a buyer-led request to inspect or change the active workspace.

    Listing assets is harmless, but opening a switch authorization is not a
    decision the model may make by itself. This check runs only against the
    exact transport-captured buyer text. Once an intent exists, the separate
    authorizer still requires an unambiguous account/Page choice and issues a
    one-use ticket before anything can be persisted.
    """
    turn = turn if isinstance(turn, dict) else _trusted_buyer_turn()
    raw = str(turn.get("message") or "").strip()
    if not raw:
        return False
    normalized = unicodedata.normalize("NFKD", raw.casefold())
    normalized = " ".join(
        re.findall(
            r"[a-z0-9]+",
            "".join(char for char in normalized if not unicodedata.combining(char)),
        )
    )
    asset_scope = re.search(
        r"\b(?:cuenta|cuentas|account|accounts|pagina|paginas|page|pages|"
        r"facebook|meta|negocio|business|workspace)\b",
        normalized,
    )
    switch_action = re.search(
        r"\b(?:cambi\w*|switch\w*|eleg\w*|seleccion\w*|escog\w*|"
        r"usar|usa|use|reemplaz\w*|conect\w*|mostr\w*|muestr\w*|"
        r"listar|lista|ver|revis\w*)\b",
        normalized,
    )
    other_asset = re.search(
        r"\b(?:otra|otro|different|distinta|distinto|nueva|nuevo)\b",
        normalized,
    )
    return bool(asset_scope and (switch_action or other_asset))


def social_oauth_workspaces_for_text_selection(*, allow_switch=False):
    """List workspaces and establish the server-owned text-selection intent.

    ``allow_switch`` is trusted runtime workflow state, never an MCP/model
    argument. The normal first selection needs no flag because no pair exists.
    """
    result = social_oauth_status()
    if result.get("connected"):
        trusted_switch = bool(allow_switch) and _trusted_meta_workspace_switch_requested()
        result["selection_authorization"] = _open_meta_oauth_selection_intent_for_trusted_turn(
            allow_switch=trusted_switch
        )
    return result


def _trusted_turn_message_hash(raw_message, message_sequence):
    canonical = json.dumps(
        {"message": str(raw_message or ""), "message_sequence": int(message_sequence)},
        ensure_ascii=False,
        sort_keys=True,
        separators=(",", ":"),
    )
    return hashlib.sha256(canonical.encode("utf-8")).hexdigest()


@contextlib.contextmanager
def _trusted_buyer_turn_lock():
    """Serialize turn evidence across dashboard and short-lived MCP processes."""
    TRUSTED_BUYER_TURN_LOCK_FILE.parent.mkdir(parents=True, exist_ok=True)
    with TRUSTED_BUYER_TURN_THREAD_LOCK:
        with TRUSTED_BUYER_TURN_LOCK_FILE.open("a+", encoding="utf-8") as handle:
            if fcntl is not None:
                fcntl.flock(handle.fileno(), fcntl.LOCK_EX)
            try:
                yield
            finally:
                if fcntl is not None:
                    fcntl.flock(handle.fileno(), fcntl.LOCK_UN)


def _clear_trusted_buyer_turn_unlocked():
    try:
        TRUSTED_BUYER_TURN_FILE.unlink()
    except FileNotFoundError:
        pass
    except OSError:
        # An unreadable or unwritable evidence file must never be accepted by
        # the validation path below.
        return False
    return True


def clear_trusted_buyer_turn():
    """Fail closed after any transport-capture failure."""
    with _trusted_buyer_turn_lock():
        return _clear_trusted_buyer_turn_unlocked()


def _trusted_turn_transport(value, chat_id=""):
    transport = str(value or "").strip().lower().replace("-", "_")
    if not transport:
        prefix = str(chat_id or "").split(":", 1)[0].lower()
        transport = prefix if prefix in {"dashboard", "simulated_telegram", "legacy_telegram"} else "telegram"
    if transport not in {"telegram", "dashboard", "simulated_telegram", "legacy_telegram"}:
        raise ValueError("El transporte del turno confiable no es válido.")
    return transport


def _new_trusted_turn_capabilities():
    return {
        kind: {
            "nonce": secrets.token_urlsafe(24),
            "used": False,
            "used_at": "",
        }
        for kind in TRUSTED_BUYER_CAPABILITY_KINDS
    }


def _trusted_turn_public_result(turn, *, idempotent=False):
    authorization = turn.get("meta_selection_authorization") if isinstance(turn, dict) else {}
    return {
        "recorded": bool(turn),
        "idempotent": bool(idempotent),
        "chat_id": str((turn or {}).get("chat_id") or ""),
        "session_id": str((turn or {}).get("session_id") or ""),
        "message_sequence": (turn or {}).get("message_sequence"),
        "message_hash": str((turn or {}).get("message_hash") or ""),
        "transport": str((turn or {}).get("transport") or ""),
        "meta_selection_authorization": _public_meta_selection_authorization(authorization),
    }


def record_trusted_buyer_turn(
    chat_id,
    session_id,
    message_sequence,
    raw_message,
    transport="",
):
    """Record one real inbound buyer message before it reaches the model.

    If a Meta selection prompt is open, the message is resolved and an opaque
    ticket is kept privately for ``social_oauth_select``. The ticket is never
    returned to the model-facing caller.
    """
    with _trusted_buyer_turn_lock():
        try:
            chat_id = str(chat_id or "").strip()
            session_id = str(session_id or "").strip()
            raw_message = str(raw_message or "").strip()
            transport = _trusted_turn_transport(transport, chat_id)
            if not chat_id or not session_id or not raw_message:
                raise ValueError("chat_id, session_id y el mensaje real del comprador son obligatorios.")
            if len(chat_id) > 256 or len(session_id) > 256 or len(raw_message) > 4000:
                raise ValueError("El turno confiable excede el tamaño permitido.")
            if transport == "telegram":
                configured_chat = _meta_oauth_chat_id(load_config())
                if configured_chat and configured_chat != chat_id:
                    raise ValueError("El turno no pertenece al chat de Telegram autorizado.")
            else:
                expected_prefix = f"{transport}:"
                if not chat_id.startswith(expected_prefix):
                    raise ValueError("El turno no coincide con su transporte confiable.")
            try:
                message_sequence = int(message_sequence)
            except (TypeError, ValueError) as exc:
                raise ValueError("message_sequence debe ser un entero.") from exc
            if message_sequence < 0:
                raise ValueError("message_sequence no puede ser negativo.")

            message_hash = _trusted_turn_message_hash(raw_message, message_sequence)
            previous = read_json(TRUSTED_BUYER_TURN_FILE, {})
            if (
                isinstance(previous, dict)
                and previous.get("chat_id") == chat_id
                and previous.get("session_id") == session_id
                and previous.get("transport") == transport
            ):
                try:
                    previous_sequence = int(previous.get("message_sequence"))
                except (TypeError, ValueError):
                    previous_sequence = -1
                if previous_sequence == message_sequence:
                    if hmac.compare_digest(str(previous.get("message_hash") or ""), message_hash):
                        return _trusted_turn_public_result(previous, idempotent=True)
                    raise ValueError("El mismo message_sequence ya fue usado por otro mensaje.")
                if previous_sequence > message_sequence:
                    raise ValueError("El mensaje entrante es anterior al último turno confiable.")

            turn = {
                "chat_id": chat_id,
                "session_id": session_id,
                "transport": transport,
                "message_sequence": message_sequence,
                "message": raw_message,
                "message_hash": message_hash,
                "capabilities": _new_trusted_turn_capabilities(),
                "created_at": now_iso(),
            }
            authorizer = _meta_oauth_selection_authorizer()
            try:
                current_intent = authorizer.current_intent(chat_id=chat_id, session_id=session_id)
                if current_intent:
                    connection = _meta_oauth_connection()
                    authorization = authorizer.authorize_current_message(
                        chat_id=chat_id,
                        session_id=session_id,
                        message_sequence=message_sequence,
                        raw_message=raw_message,
                        inventory=_meta_oauth_selection_inventory(connection),
                        current_pair=_meta_oauth_selection_current_pair(connection),
                    )
                    turn["meta_selection_authorization"] = _public_meta_selection_authorization(authorization)
                    if authorization.get("status") == "authorized" and authorization.get("ticket"):
                        turn["meta_selection_ticket"] = str(authorization["ticket"])
            except SelectionIntentNotFound:
                pass
            except (SelectionBindingMismatch, SelectionAuthorizationError) as exc:
                authorizer.clear(chat_id=chat_id, session_id=session_id)
                turn["meta_selection_authorization"] = {
                    "status": "rejected",
                    "reason": type(exc).__name__,
                }
            write_private_json(TRUSTED_BUYER_TURN_FILE, turn)
            return _trusted_turn_public_result(turn)
        except Exception:
            # Never leave an older buyer message available after a failed new
            # capture attempt.
            _clear_trusted_buyer_turn_unlocked()
            raise


def _clear_meta_oauth_selection_authorization(*, clear_trusted_turn=True):
    removed = _meta_oauth_selection_authorizer().clear()
    if clear_trusted_turn:
        try:
            TRUSTED_BUYER_TURN_FILE.unlink()
        except OSError:
            pass
    else:
        turn = read_json(TRUSTED_BUYER_TURN_FILE, {})
        if isinstance(turn, dict) and turn:
            turn.pop("meta_selection_ticket", None)
            turn.pop("meta_selection_authorization", None)
            write_private_json(TRUSTED_BUYER_TURN_FILE, turn)
    return removed


def _safe_meta_oauth_summary(connection):
    connection = connection if isinstance(connection, dict) else {}
    return {
        "connected": bool(connection.get("connected")),
        "connected_at": str(connection.get("connected_at") or ""),
        "expires_at": str(connection.get("expires_at") or ""),
        "user": {"id": str((connection.get("user") or {}).get("id") or ""), "name": str((connection.get("user") or {}).get("name") or "")},
        "accounts": [{key: item.get(key) for key in ("id", "account_id", "name", "currency", "timezone_name", "timezone_offset_hours_utc", "account_status")} for item in connection.get("accounts", []) if isinstance(item, dict)],
        "pages": [{key: item.get(key) for key in ("id", "name", "category", "instagram", "can_publish", "sources", "business_ids")} for item in connection.get("pages", []) if isinstance(item, dict)],
        "businesses": [{key: item.get(key) for key in ("id", "name")} for item in connection.get("businesses", []) if isinstance(item, dict)],
        "discovery_issues": [{key: item.get(key) for key in ("stage", "graph_code", "graph_subcode", "graph_type")} for item in connection.get("discovery_issues", []) if isinstance(item, dict)],
        "active_ad_account_id": str(connection.get("active_ad_account_id") or ""),
        "active_page_id": str(connection.get("active_page_id") or ""),
    }


def _refresh_meta_oauth_pending_once():
    """Apply a completed one-time OAuth handoff from any caller process.

    Hermes MCP tools may run in a short-lived process, so a daemon polling
    thread started while sending the link is not a reliable completion path.
    The buyer's next workspace-status request must be able to finish the
    handoff itself.
    """
    pending = _meta_oauth_pending()
    if not pending.get("request_id") or not pending.get("handoff_secret"):
        return None
    result = _meta_oauth_request(
        str(pending.get("broker_url") or ""),
        {
            "flow": "poll",
            "request_id": pending["request_id"],
            "handoff_secret": pending["handoff_secret"],
        },
    )
    if result.get("ok") and result.get("status") == "connected":
        summary = _apply_meta_oauth_credentials(result.get("credentials"))
        try:
            META_OAUTH_PENDING_FILE.unlink()
        except OSError:
            pass
        log_action(
            "meta_oauth_connected",
            {
                "accounts": len(summary.get("accounts") or []),
                "pages": len(summary.get("pages") or []),
                "workspace_selection": "strict_numeric_page_then_account",
                "completion": "status_refresh",
            },
            "completed",
        )
        return summary
    if result.get("error") in {"oauth_request_expired", "oauth_callback_failed"}:
        try:
            META_OAUTH_PENDING_FILE.unlink()
        except OSError:
            pass
    return None


def social_oauth_status():
    config = load_config()
    try:
        _refresh_meta_oauth_pending_once()
    except Exception:
        # Status remains safe and readable during a transient broker/network
        # failure. A later buyer message can retry the same pending handoff.
        pass
    connection = _meta_oauth_connection()
    pending = _meta_oauth_pending()
    result = _safe_meta_oauth_summary(connection)
    result.update({
        "ok": bool(result["connected"]),
        "broker_configured": bool(_meta_oauth_broker_url(config)),
        "pending": bool(pending.get("request_id")),
        "pending_created_at": str(pending.get("created_at") or ""),
        "legacy_token_connected": bool(config.meta_access_token and str(config.meta_access_token_kind or "").lower() != "oauth"),
    })
    selection_required = bool(
        result.get("connected")
        and not (
            str(result.get("active_ad_account_id") or "").strip()
            and str(result.get("active_page_id") or "").strip()
        )
    )
    result["selection_required"] = selection_required
    if selection_required:
        result["selection_authorization"] = _open_meta_oauth_selection_intent_for_trusted_turn(
            allow_switch=False
        )
    return result


def _runtime_telegram_chat_id():
    value = read_json(TELEGRAM_RUNTIME_CHAT_FILE, {})
    chat_id = str(value.get("chat_id") or "").strip() if isinstance(value, dict) else ""
    return chat_id if chat_id.lstrip("-").isdigit() else ""


def _meta_oauth_chat_id(config, explicit_chat_id=""):
    for candidate in (explicit_chat_id, getattr(config, "telegram_chat_id", ""), _runtime_telegram_chat_id()):
        chat_id = str(candidate or "").strip()
        if chat_id.lstrip("-").isdigit():
            return chat_id
    return ""


def _send_meta_oauth_link(config, authorization_url, chat_id=""):
    chat_id = _meta_oauth_chat_id(config, chat_id)
    if not chat_id:
        raise ValueError("Conecta primero tu bot de Telegram para enviarte el enlace seguro de Facebook.")
    telegram_bot_request(config, "sendMessage", {
        "chat_id": chat_id,
        # Keep this as a normal URL in the message. Inline buttons are handled
        # by the native Hermes callback loop and have repeatedly been lost or
        # left stale on fresh Telegram connections. The buyer can tap the URL
        # directly in Telegram Desktop or on their phone.
        "text": f"Conecta Facebook y Meta Ads abriendo este enlace seguro:\n{authorization_url}\n\nInicia sesión con la cuenta que administra tus activos. Nunca compartas una clave de Meta por chat.",
    }, timeout=20)


def _oauth_publishable_pages(connection):
    return [item for item in (connection.get("pages") or []) if isinstance(item, dict) and item.get("id") and item.get("access_token")]


def _send_meta_oauth_account_picker(config, connection, chat_id=""):
    """Show the canonical numeric Page/ad-account selection in Telegram.

    The OAuth link is deliberately plain text and the workspace choice is
    deliberately a strict numeric pair. This avoids a second Telegram callback
    consumer and prevents names, typos, or model interpretation from selecting
    the wrong business assets.
    """
    accounts = [item for item in (connection.get("accounts") or []) if isinstance(item, dict) and item.get("id")]
    pages = [item for item in _oauth_publishable_pages(connection) if isinstance(item, dict) and item.get("id")]
    if not accounts or not pages:
        return
    account_lines = []
    for index, account in enumerate(accounts[:50], 1):
        account_id = clean_ad_account_id(account.get("id"))
        if not account_id:
            continue
        label = str(account.get("name") or account_id).strip()[:42]
        currency = str(account.get("currency") or "").strip()
        account_lines.append(f"{index}. {label}{' · ' + currency if currency else ''}")
    page_lines = [f"{index}. {str(page.get('name') or page.get('id')).strip()[:52]}" for index, page in enumerate(pages[:50], 1)]
    if not account_lines or not page_lines:
        return
    telegram_bot_request(config, "sendMessage", {
        "chat_id": _meta_oauth_chat_id(config, chat_id),
        "text": (
            "Facebook quedó conectado. Encontré estas opciones:\n\n"
            "PÁGINAS DE FACEBOOK:\n" + "\n".join(page_lines) +
            "\n\nCUENTAS PUBLICITARIAS:\n" + "\n".join(account_lines) +
            "\n\nResponde únicamente con dos números: primero Página y después cuenta publicitaria. "
            "Ejemplo: 1, 8"
        ),
    }, timeout=20)


def social_oauth_select_account(account_id):
    """Reject the retired account-first Telegram callback flow."""
    raise ValueError(
        "El selector anterior fue retirado. Usa el par numérico completo: Página y cuenta publicitaria."
    )


def live_ad_account_timezone_metadata(account):
    account = dict(account) if isinstance(account, dict) else {"id": account}
    account_id = clean_ad_account_id(account.get("id") or account.get("account_id"))
    if not account_id:
        return account
    result = graph_get(
        f"/{account_id}",
        {"fields": "id,account_id,name,currency,timezone_name,timezone_offset_hours_utc,account_status,business{id,name}"},
    )
    live = result.get("data") if result.get("ok") and isinstance(result.get("data"), dict) else {}
    return {**account, **{key: value for key, value in live.items() if value not in (None, "")}}


def synchronize_selected_ad_account_timezone(account=None, reconcile_crons=False):
    """Use the selected Meta account timezone unless the buyer overrode it."""
    account_id = clean_ad_account_id((account or {}).get("id") if isinstance(account, dict) else account)
    account_id = account_id or current_configured_ad_account_id()
    if not account_id:
        return {"ok": False, "reason": "missing_ad_account"}
    account = live_ad_account_timezone_metadata(account or {"id": account_id})
    raw_timezone = str(account.get("timezone_name") or "").strip()
    timezone_name = normalize_timezone(raw_timezone, default="") if raw_timezone else ""
    if not timezone_name or timezone_name != raw_timezone:
        return {"ok": False, "reason": "missing_meta_account_timezone", "account_id": account_id, "account": account}
    existing = timezone_preference_state()
    if str(existing.get("source") or "").strip().lower() == "buyer" and existing.get("timezone"):
        return {
            "ok": True,
            "changed": False,
            "source": "buyer",
            "timezone": existing["timezone"],
            "meta_timezone": timezone_name,
            "account_id": account_id,
            "account": account,
        }
    changed = existing.get("timezone") != timezone_name or existing.get("account_id") != account_id or existing.get("source") != "meta_ad_account"
    state = save_timezone_preference(timezone_name, "meta_ad_account", account_id=account_id)
    cron_result = reconcile_timezone_crons(load_config()) if reconcile_crons and changed else {"reconciled": False, "needed": False}
    return {"ok": True, "changed": changed, **state, "meta_timezone": timezone_name, "account": account, "crons": cron_result}


_META_OAUTH_SELECTION_TRANSACTION_STATE = threading.local()
_META_OAUTH_SELECTION_ENV_KEYS = (
    "META_AD_ACCOUNT_ID",
    "META_PUBLISHING_ACCESS_TOKEN",
    "META_PUBLISHING_TOKEN_SAVED_AT",
    "DAILY_BRIEF_TIMEZONE",
    "DAILY_BRIEF_TIMEZONE_SOURCE",
)


def _meta_oauth_selection_snapshot_paths():
    """Files that together define the selected Meta workspace."""
    return tuple(dict.fromkeys((
        Path(ENV_FILE),
        Path(AD_CONFIG_FILE),
        Path(META_OAUTH_CONNECTION_FILE),
        Path(MANAGED_AD_ACCOUNTS_FILE),
        Path(TIMEZONE_PREFERENCE_FILE),
        Path(INDIVIDUAL_BINDING_FILE),
    )))


def _snapshot_private_files(paths):
    snapshot = {}
    for raw_path in paths:
        path = Path(raw_path)
        if path.exists():
            snapshot[path] = {
                "exists": True,
                "content": path.read_bytes(),
                "mode": path.stat().st_mode & 0o777,
            }
        else:
            snapshot[path] = {"exists": False, "content": b"", "mode": 0o600}
    return snapshot


def _restore_private_files(snapshot):
    for path, original in snapshot.items():
        if not original["exists"]:
            try:
                path.unlink()
            except FileNotFoundError:
                pass
            continue
        path.parent.mkdir(parents=True, exist_ok=True)
        descriptor, temporary = tempfile.mkstemp(prefix=f".{path.name}.rollback.", dir=str(path.parent))
        try:
            os.fchmod(descriptor, int(original["mode"]))
            with os.fdopen(descriptor, "wb") as handle:
                handle.write(original["content"])
                handle.flush()
                os.fsync(handle.fileno())
            os.replace(temporary, path)
            os.chmod(path, int(original["mode"]))
        except BaseException:
            try:
                os.close(descriptor)
            except OSError:
                pass
            try:
                os.unlink(temporary)
            except OSError:
                pass
            raise


@contextlib.contextmanager
def _meta_oauth_workspace_transaction():
    """Serialize and rollback the complete account/Page persistence unit.

    The process-wide file lock protects multiple short-lived MCP/dashboard
    processes, while the in-process RLock protects threads.  Nested calls in
    the same thread share the outer snapshot so the selection ticket can be
    committed inside the same rollback boundary as the configuration files.
    """
    depth = int(getattr(_META_OAUTH_SELECTION_TRANSACTION_STATE, "depth", 0) or 0)
    if depth:
        _META_OAUTH_SELECTION_TRANSACTION_STATE.depth = depth + 1
        try:
            yield
        finally:
            _META_OAUTH_SELECTION_TRANSACTION_STATE.depth = depth
        return

    with META_OAUTH_SELECTION_PERSIST_LOCK:
        lock_path = Path(META_OAUTH_CONNECTION_FILE).with_suffix(".selection-persist.lock")
        lock_path.parent.mkdir(parents=True, exist_ok=True, mode=0o700)
        with lock_path.open("a+", encoding="utf-8") as lock_handle:
            try:
                os.chmod(lock_path, 0o600)
            except OSError:
                pass
            if fcntl is not None:
                fcntl.flock(lock_handle.fileno(), fcntl.LOCK_EX)
            files_before = _snapshot_private_files(_meta_oauth_selection_snapshot_paths())
            environment_before = {
                key: (key in os.environ, os.environ.get(key, ""))
                for key in _META_OAUTH_SELECTION_ENV_KEYS
            }
            _META_OAUTH_SELECTION_TRANSACTION_STATE.depth = 1
            try:
                yield
            except BaseException as persistence_error:
                rollback_error = None
                try:
                    _restore_private_files(files_before)
                except BaseException as exc:  # pragma: no cover - disk failure.
                    rollback_error = exc
                finally:
                    for key, (existed, value) in environment_before.items():
                        if existed:
                            os.environ[key] = value
                        else:
                            os.environ.pop(key, None)
                if rollback_error is not None:
                    raise RuntimeError(
                        "La selección de Meta falló y no pude restaurar completamente su estado previo."
                    ) from persistence_error
                raise
            finally:
                _META_OAUTH_SELECTION_TRANSACTION_STATE.depth = 0
                if fcntl is not None:
                    fcntl.flock(lock_handle.fileno(), fcntl.LOCK_UN)


def _env_file_values():
    values = {}
    try:
        lines = Path(ENV_FILE).read_text(encoding="utf-8").splitlines()
    except OSError:
        return values
    for line in lines:
        stripped = line.strip()
        if not stripped or stripped.startswith("#") or "=" not in line:
            continue
        key, value = line.split("=", 1)
        values[key.strip()] = value
    return values


def _verify_meta_oauth_workspace_persistence(account_id, page_id, page_access_token, timezone_sync):
    """Read every durable projection back before committing authorization."""
    persisted = _meta_oauth_connection()
    if (
        clean_ad_account_id(persisted.get("active_ad_account_id")) != account_id
        or str(persisted.get("active_page_id") or "").strip() != page_id
    ):
        raise RuntimeError("La selección de Meta no quedó persistida correctamente.")

    env_file = _env_file_values()
    expected_env = {
        "META_AD_ACCOUNT_ID": account_id,
        "META_PUBLISHING_ACCESS_TOKEN": str(page_access_token or ""),
    }
    for key, expected in expected_env.items():
        if env_file.get(key) != expected or os.environ.get(key) != expected:
            raise RuntimeError("La selección de Meta quedó incompleta en la configuración del proceso.")

    ad_config = read_json(AD_CONFIG_FILE, {})
    destination = (ad_config.get("creative") or {}).get("destination") or {}
    if (
        clean_ad_account_id((ad_config.get("account") or {}).get("id")) != account_id
        or str(destination.get("page_id") or "").strip() != page_id
    ):
        raise RuntimeError("La selección de Meta quedó incompleta en ad-config.json.")

    managed = read_json(MANAGED_AD_ACCOUNTS_FILE, {})
    if clean_ad_account_id(managed.get("active_ad_account_id")) != account_id:
        raise RuntimeError("La cuenta activa no quedó sincronizada en el inventario administrado.")

    if isinstance(timezone_sync, dict) and timezone_sync.get("changed"):
        timezone_state = read_json(TIMEZONE_PREFERENCE_FILE, {})
        expected_timezone = str(timezone_sync.get("timezone") or "").strip()
        if (
            clean_ad_account_id(timezone_state.get("account_id")) != account_id
            or str(timezone_state.get("timezone") or "").strip() != expected_timezone
            or env_file.get("DAILY_BRIEF_TIMEZONE") != expected_timezone
            or os.environ.get("DAILY_BRIEF_TIMEZONE") != expected_timezone
        ):
            raise RuntimeError("La zona horaria de la cuenta no quedó sincronizada.")
    return persisted


def _persist_meta_oauth_workspace_pair(
    account_id,
    page_id,
    *,
    source,
    connection=None,
    expected_old_pair=None,
    defer_post_commit=False,
):
    """Persist one already-authorized account/Page pair as a single unit."""
    account_id = clean_ad_account_id(account_id)
    page_id = str(page_id or "").strip()
    with _meta_oauth_workspace_transaction():
        if isinstance(expected_old_pair, dict):
            connection = _meta_oauth_connection()
            if _meta_oauth_selection_current_pair(connection) != {
                "ad_account_id": clean_ad_account_id(expected_old_pair.get("ad_account_id")),
                "page_id": str(expected_old_pair.get("page_id") or "").strip(),
            }:
                raise ValueError(
                    "La cuenta o Página activa cambió antes de guardar la selección. "
                    "Vuelve a listar los espacios de Meta."
                )
        else:
            connection = connection if isinstance(connection, dict) else _meta_oauth_connection()
        account = next((item for item in connection.get("accounts", []) if clean_ad_account_id(item.get("id")) == account_id), None)
        page = next((item for item in _oauth_publishable_pages(connection) if str(item.get("id") or "") == page_id), None)
        if not account or not page:
            raise ValueError("La cuenta o Página elegida no pertenece a esta conexión de Facebook.")
        timezone_sync = synchronize_selected_ad_account_timezone(account, reconcile_crons=False)
        account = timezone_sync.get("account") if isinstance(timezone_sync.get("account"), dict) else account

        # Every dependent configuration write receives the same exact pair.
        # There is no intermediate pending account in the authorized text path.
        update_env_values({
            "META_AD_ACCOUNT_ID": account_id,
            "META_PUBLISHING_ACCESS_TOKEN": str(page.get("access_token") or ""),
            "META_PUBLISHING_TOKEN_SAVED_AT": now_iso(),
        })
        save_setup_config({
            "ad_account_id": account_id,
            "account_name": account.get("name", ""),
            "account_currency": account.get("currency", ""),
            "account_timezone": account.get("timezone_name", ""),
            "account_timezone_offset": account.get("timezone_offset_hours_utc"),
            "page_id": page_id,
            "instagram_actor_id": str((page.get("instagram") or {}).get("id") or ""),
            "_skip_meta_profile_sync": True,
        })

        next_connection = dict(connection)
        next_connection["accounts"] = [
            account if clean_ad_account_id(item.get("id")) == account_id else item
            for item in connection.get("accounts", [])
        ]
        next_connection["active_ad_account_id"] = account_id
        next_connection["active_page_id"] = page_id
        next_connection.pop("pending_ad_account_id", None)
        # This atomic replace is the durable authority for the active pair and
        # is intentionally the last state write before read-back verification.
        write_private_json(META_OAUTH_CONNECTION_FILE, next_connection)
        persisted = _verify_meta_oauth_workspace_persistence(
            account_id,
            page_id,
            str(page.get("access_token") or ""),
            timezone_sync,
        )
        result = {
            "ok": True,
            "selected": True,
            "verified_persisted": True,
            "account": account,
            "page": page,
            **_safe_meta_oauth_summary(persisted),
        }
    if defer_post_commit:
        result["_deferred_timezone_sync"] = timezone_sync
    else:
        _finalize_meta_oauth_workspace_persistence(
            result,
            account_id=account_id,
            page_id=page_id,
            source=source,
            timezone_sync=timezone_sync,
        )
    return result


def _finalize_meta_oauth_workspace_persistence(result, *, account_id, page_id, source, timezone_sync):
    """Run non-authoritative side effects only after the core transaction."""
    if isinstance(timezone_sync, dict) and timezone_sync.get("changed"):
        try:
            timezone_sync["crons"] = reconcile_timezone_crons(load_config())
        except Exception:
            # The selected account/Page pair is already durable. A cron can be
            # reconciled on the next gateway start without invalidating it.
            timezone_sync["crons"] = {"reconciled": False, "needed": True, "retry_on_gateway_start": True}
    try:
        log_action(
            "meta_oauth_workspace_selected",
            {"account_id": account_id, "page_id": page_id, "source": str(source or "internal")[:40]},
            "completed",
        )
    except Exception:
        # Audit logging is useful but cannot invalidate a verified workspace
        # after its authorization capability has been committed.
        pass
    if isinstance(result, dict) and isinstance(timezone_sync, dict):
        result["timezone_sync"] = timezone_sync
    return result


def social_oauth_select_page(page_id):
    """Reject the retired Page callback; selection needs a trusted pair."""
    raise ValueError(
        "El selector anterior fue retirado. Usa el par numérico completo: Página y cuenta publicitaria."
    )


def social_oauth_start(payload=None):
    payload = payload or {}
    config = load_config()
    broker_url = _meta_oauth_broker_url(config)
    if not broker_url:
        raise ValueError("La conexión segura de Facebook aún no está configurada en esta versión. Actualiza o contacta soporte.")
    # Idempotency guard: a model may call the setup tool again after a
    # context compaction or campaign request. Never create a second OAuth
    # handoff while a valid connection is already persisted.
    connected = _meta_oauth_connection()
    if bool(connected.get("connected")):
        return {
            "ok": True,
            "connected": True,
            "already_connected": True,
            "sent_to_telegram": False,
            **_safe_meta_oauth_summary(connected),
        }
    existing = _meta_oauth_pending()
    # A dashboard/gateway restart can stop the bounded polling worker before
    # it removes an expired broker request. Never resend an old URL: OAuth
    # codes are single-use and Facebook will correctly reject that handoff.
    try:
        existing_created_at = datetime.fromisoformat(str(existing.get("created_at") or "").replace("Z", "+00:00"))
    except ValueError:
        existing_created_at = None
    if existing_created_at and existing_created_at.tzinfo is None:
        existing_created_at = existing_created_at.replace(tzinfo=timezone.utc)
    existing_is_fresh = bool(existing_created_at and (datetime.now(timezone.utc) - existing_created_at).total_seconds() < 14 * 60)
    if existing.get("request_id") and not existing_is_fresh:
        try: META_OAUTH_PENDING_FILE.unlink()
        except OSError: pass
        existing = {}
    if existing.get("request_id") and existing.get("handoff_secret"):
        # Do not create another browser handoff, but do resend the actual
        # visible URL if the buyer explicitly asks again.  A prior message may
        # have been buried in Telegram; telling them to use a nonexistent
        # callback button is never an acceptable fallback.
        existing_url = str(existing.get("authorization_url") or "").strip()
        chat_id = _meta_oauth_chat_id(config, str(payload.get("telegram_chat_id") or ""))
        resent = False
        if existing_url and chat_id:
            _send_meta_oauth_link(config, existing_url, chat_id)
            resent = True
        return {
            "ok": True,
            "sent_to_telegram": bool(resent),
            "pending": True,
            "already_pending": True,
            "link_resent": bool(resent),
            "expires_in_seconds": 900,
        }
    # A new browser handoff supersedes every outstanding workspace prompt or
    # capability from an older OAuth inventory.
    _clear_meta_oauth_selection_authorization()
    handoff_secret = secrets.token_urlsafe(48)
    result = _meta_oauth_request(broker_url, {
        "flow": "start",
        "handoff_secret": handoff_secret,
        "installation_id": resolved_device_id(config.license_device_id, config.license_key),
    })
    if not result.get("ok") or not result.get("request_id") or not result.get("authorization_url"):
        raise ValueError("No pude preparar la conexión segura de Facebook. Intenta de nuevo en un minuto.")
    chat_id = _meta_oauth_chat_id(config, str(payload.get("telegram_chat_id") or ""))
    if not chat_id:
        raise ValueError("Aún no detecto tu chat de Telegram. Envía un mensaje al bot y vuelve a intentar.")
    pending = {
        "request_id": str(result["request_id"]),
        "handoff_secret": handoff_secret,
        # Stored only in the installation's private runtime data so an
        # explicit retry can resend this same one-time OAuth handoff.
        "authorization_url": str(result["authorization_url"]),
        "created_at": now_iso(),
        "broker_url": broker_url,
        "telegram_chat_id": chat_id,
    }
    write_private_json(META_OAUTH_PENDING_FILE, pending)
    _send_meta_oauth_link(config, str(result["authorization_url"]), chat_id)
    # Completion is intentionally lazy: the next workspace-status request
    # consumes the broker handoff. Hermes MCP calls can be short-lived, so a
    # daemon thread here would disappear as soon as the current turn exits.
    log_action("meta_oauth_started", {"telegram_sent": True, "request_id_present": True}, "completed")
    return {"ok": True, "sent_to_telegram": True, "pending": True, "expires_in_seconds": int(result.get("expires_in_seconds") or 900)}


def _poll_meta_oauth_in_background():
    if not META_OAUTH_POLL_LOCK.acquire(blocking=False):
        return
    try:
        deadline = time.monotonic() + 15 * 60
        while time.monotonic() < deadline:
            pending = _meta_oauth_pending()
            if not pending.get("request_id"):
                return
            try:
                result = _meta_oauth_request(str(pending.get("broker_url") or ""), {"flow": "poll", "request_id": pending["request_id"], "handoff_secret": pending["handoff_secret"]})
                if result.get("ok") and result.get("status") == "connected":
                    _apply_meta_oauth_credentials(result.get("credentials"))
                    chat_id = str(pending.get("telegram_chat_id") or "")
                    try: META_OAUTH_PENDING_FILE.unlink()
                    except OSError: pass
                    # Do not send a second unsolicited Telegram message here.
                    # Hermes will read the workspaces on the buyer's next
                    # natural-language turn (for example, “ya lo hice”),
                    # present the numbered accounts/Pages, and wait for an
                    # explicit default choice.
                    log_action("meta_oauth_connected", {"background": True}, "completed")
                    return
                if result.get("error") in {"oauth_request_expired", "oauth_request_not_found", "oauth_callback_failed"}:
                    try: META_OAUTH_PENDING_FILE.unlink()
                    except OSError: pass
                    return
            except Exception:
                # A temporary network error is not a reason to tell the buyer
                # the connection failed. The next bounded poll can recover.
                pass
            time.sleep(4)
    finally:
        META_OAUTH_POLL_LOCK.release()


def _apply_meta_oauth_credentials(credentials):
    if not isinstance(credentials, dict):
        raise ValueError("La respuesta de Facebook llegó incompleta.")
    # A completed reconnect invalidates every prompt/ticket issued for the old
    # OAuth inventory before any new credential state is installed.
    _clear_meta_oauth_selection_authorization(clear_trusted_turn=False)
    token = str(credentials.get("user_token") or "").strip()
    accounts = [item for item in credentials.get("accounts") or [] if isinstance(item, dict) and item.get("id")]
    pages = []
    for raw_page in credentials.get("pages") or []:
        if not isinstance(raw_page, dict) or not raw_page.get("id"):
            continue
        page = dict(raw_page)
        page["can_publish"] = bool(page.get("access_token"))
        pages.append(page)
    publishable_pages = [item for item in pages if item.get("can_publish")]
    businesses = [item for item in credentials.get("businesses") or [] if isinstance(item, dict) and item.get("id")]
    if len(token) < 20:
        raise ValueError("Facebook no devolvió una conexión utilizable. Revisa los permisos aceptados.")
    connection = {
        "connected": True,
        "connected_at": now_iso(),
        "expires_at": str(credentials.get("expires_at") or ""),
        "user": credentials.get("user") if isinstance(credentials.get("user"), dict) else {},
        "user_token": token,
        "accounts": accounts,
        "pages": pages,
        "businesses": businesses,
        "discovery_issues": [item for item in credentials.get("discovery_issues") or [] if isinstance(item, dict)],
        # Never silently choose a workspace. Hermes presents the numbered
        # accounts/Pages and selects only after the buyer answers in text.
        "active_ad_account_id": "",
        "active_page_id": "",
    }
    write_private_json(META_OAUTH_CONNECTION_FILE, connection)
    updates = {
        "META_ACCESS_TOKEN": token,
        "META_ACCESS_TOKEN_KIND": "oauth",
        "META_ACCESS_TOKEN_SAVED_AT": now_iso(),
        "META_OAUTH_CONNECTED_AT": connection["connected_at"],
        "META_OAUTH_EXPIRES_AT": connection["expires_at"],
        "META_OAUTH_USER_ID": str((connection["user"] or {}).get("id") or ""),
    }
    # OAuth user token is used for discovery. The selected account/Page
    # credentials are persisted only by social_oauth_select after the buyer's
    # natural-language choice.
    # Clear any stale selection from a previous connection so no Meta action
    # can accidentally run against the old account while Hermes is waiting
    # for the buyer's new default choice.
    update_env_values({
        "META_AD_ACCOUNT_ID": "",
        "META_PUBLISHING_ACCESS_TOKEN": "",
        "META_PUBLISHING_TOKEN_SAVED_AT": "",
    })
    save_setup_config({
        "ad_account_id": "",
        "page_id": "",
        "instagram_actor_id": "",
        "_skip_business_enforcement": True,
        "_skip_meta_profile_sync": True,
    })
    ad_config = read_json(AD_CONFIG_FILE, {})
    ad_config.setdefault("account", {})["id"] = ""
    destination = ad_config.setdefault("creative", {}).setdefault("destination", {})
    destination["page_id"] = ""
    destination["instagram_actor_id"] = ""
    write_json(AD_CONFIG_FILE, ad_config)
    update_env_values(updates)
    return _safe_meta_oauth_summary(connection)


def social_oauth_poll(payload=None):
    pending = _meta_oauth_pending()
    if not pending.get("request_id") or not pending.get("handoff_secret"):
        return {"ok": True, "status": "idle", **social_oauth_status()}
    result = _meta_oauth_request(str(pending.get("broker_url") or ""), {"flow": "poll", "request_id": pending["request_id"], "handoff_secret": pending["handoff_secret"]})
    if result.get("status") == "pending":
        return {"ok": True, "status": "pending"}
    if not result.get("ok") or result.get("status") != "connected":
        # The background worker may have applied the one-time broker result
        # between this UI poll and the request above. Treat that as success,
        # rather than showing a misleading expired-link error.
        existing = _meta_oauth_connection()
        if result.get("error") in {"oauth_request_expired", "oauth_request_not_found", "oauth_callback_failed"} and existing.get("connected"):
            try: META_OAUTH_PENDING_FILE.unlink()
            except OSError: pass
            return {"ok": True, "status": "connected", **_safe_meta_oauth_summary(existing)}
        if result.get("error") in {"oauth_request_expired", "oauth_request_not_found", "oauth_callback_failed"}:
            try: META_OAUTH_PENDING_FILE.unlink()
            except OSError: pass
        failure_code = str(result.get("failure_code") or "").strip()
        suffix = f" (paso: {failure_code})" if failure_code else ""
        raise ValueError("La conexión de Facebook no pudo verificarse. Solicita un enlace nuevo." + suffix)
    summary = _apply_meta_oauth_credentials(result.get("credentials"))
    try: META_OAUTH_PENDING_FILE.unlink()
    except OSError: pass
    log_action("meta_oauth_connected", {"accounts": len(summary.get("accounts") or []), "pages": len(summary.get("pages") or []), "workspace_selection": "strict_numeric_page_then_account"}, "completed")
    return {"ok": True, "status": "connected", **summary}


def social_oauth_select(payload=None):
    """Consume the server-owned ticket and persist its exact authorized pair.

    ``ad_account_id`` and ``page_id`` supplied by an MCP/model payload are not
    authorization and are deliberately ignored. They remain accepted in the
    function signature only so older callers fail safely with a clear missing-
    ticket response instead of breaking request decoding.
    """
    payload = payload or {}
    turn = _trusted_buyer_turn()
    ticket = str(turn.get("meta_selection_ticket") or "").strip() if turn else ""
    if not ticket:
        raise ValueError(
            "La selección no fue autorizada por una respuesta reciente del comprador. "
            "Lista primero las Páginas y después las cuentas, y espera exactamente dos números: Página y cuenta."
        )
    authorizer = _meta_oauth_selection_authorizer()
    try:
        # The outer workspace transaction snapshots all selected-workspace
        # files and process environment. The authorizer keeps its own
        # cross-process lock until persistence and read-back both succeed.
        # If either ticket commit or persistence fails, files roll back and
        # the exact private ticket remains available for a bounded retry.
        with _meta_oauth_workspace_transaction():
            connection = _meta_oauth_connection()
            with authorizer.ticket_transaction(
                ticket=ticket,
                chat_id=str(turn.get("chat_id") or ""),
                session_id=str(turn.get("session_id") or ""),
                inventory=_meta_oauth_selection_inventory(connection),
                current_pair=_meta_oauth_selection_current_pair(connection),
            ) as authorized:
                selection = authorized.get("selection") or {}
                account_id = clean_ad_account_id(selection.get("ad_account_id"))
                page_id = str(selection.get("page_id") or "").strip()
                if not account_id or not page_id:
                    raise ValueError("La autorización no contiene un par completo de cuenta y Página.")
                result = _persist_meta_oauth_workspace_pair(
                    account_id,
                    page_id,
                    source="trusted_buyer_text_ticket",
                    connection=connection,
                    expected_old_pair=authorized.get("old_selection") or {},
                    defer_post_commit=True,
                )
    except (SelectionTicketInvalid, SelectionBindingMismatch) as exc:
        raise ValueError(
            "La autorización de selección venció o ya fue usada. "
            "Vuelve a listar las cuentas y Páginas y responde con tu elección."
        ) from exc

    # Persistence and ticket consumption are now both committed. Only now may
    # the private turn lose its capability; failed writes intentionally leave
    # it untouched so the same strict numeric choice can be retried.
    # Keep the full read/compare/modify/write under the same cross-process
    # lock used by ``record_trusted_buyer_turn``. Without this critical
    # section, a newer buyer message could be persisted after our read and
    # then be overwritten by the stale ticket-cleanup write below.
    with _trusted_buyer_turn_lock():
        latest_turn = _trusted_buyer_turn_unlocked()
        if isinstance(latest_turn, dict) and hmac.compare_digest(
            str(latest_turn.get("message_hash") or ""),
            str(turn.get("message_hash") or ""),
        ):
            latest_turn.pop("meta_selection_ticket", None)
            latest_turn["meta_selection_authorization"] = {
                **(latest_turn.get("meta_selection_authorization") or {}),
                "status": "consumed",
            }
            write_private_json(TRUSTED_BUYER_TURN_FILE, latest_turn)

    timezone_sync = result.pop("_deferred_timezone_sync", {})
    _finalize_meta_oauth_workspace_persistence(
        result,
        account_id=account_id,
        page_id=page_id,
        source="trusted_buyer_text_ticket",
        timezone_sync=timezone_sync,
    )
    model_account_id = clean_ad_account_id(payload.get("ad_account_id"))
    model_page_id = str(payload.get("page_id") or "").strip()
    result["selection_authorized_by_trusted_turn"] = True
    result["model_arguments_ignored"] = bool(
        (model_account_id and model_account_id != account_id)
        or (model_page_id and model_page_id != page_id)
    )
    return result


def social_save_facebook_token(payload):
    token = str(payload.get("token") or "").strip()
    if len(token) < 20:
        raise ValueError("Token is too short")
    token_kind = str(payload.get("token_kind") or "unknown").strip().lower()
    if token_kind not in {"stable", "quick"}:
        token_kind = "unknown"
    env_updates = {
        "META_ACCESS_TOKEN": token,
        "META_ACCESS_TOKEN_KIND": token_kind,
        "META_ACCESS_TOKEN_SAVED_AT": now_iso(),
    }
    update_env_values(env_updates)
    result = graph_get("/me", {"fields": "id,name"})
    redacted = {
        "ok": bool(result.get("ok")),
        "code": 0 if result.get("ok") else 1,
        "command": "Meta Graph /me",
        "output": json.dumps(result.get("data") if result.get("ok") else result.get("error"), ensure_ascii=False)[-5000:],
    }
    redacted["saved"] = True
    redacted["graph_ready"] = bool(result.get("ok"))
    redacted["token_kind"] = token_kind
    return redacted


def publishing_status(config=None, destination=None):
    config = config or load_config()
    if destination is None:
        destination = read_json(AD_CONFIG_FILE, {}).get("creative", {}).get("destination", {})
    # New installs use one Meta token for Ads and Page publishing. Keep the
    # legacy publishing token as a fallback so older installs continue to
    # work while they migrate.
    token_set = bool(getattr(config, "meta_access_token", "") or getattr(config, "meta_publishing_access_token", ""))
    page_id = str((destination or {}).get("page_id") or "").strip()
    return {
        "ok": token_set and bool(page_id),
        "token_set": token_set,
        "ready": token_set and bool(page_id),
        "page_id": page_id,
        "saved_at": getattr(config, "meta_access_token_saved_at", "") or getattr(config, "meta_publishing_token_saved_at", ""),
        "token_source": "meta_access_token" if getattr(config, "meta_access_token", "") else "legacy_meta_publishing_access_token",
        "description": "Direct publishing uses the same Meta token as Ads and is available for approved organic Facebook posts." if token_set else "Direct publishing is not connected.",
    }


def direct_publishing_campaign_plan(payload=None, creative_controls=None, config=None, destination=None):
    payload = payload or {}
    creative_controls = creative_controls or normalize_creative_controls(payload)
    config = config or load_config()
    destination = destination if destination is not None else read_json(AD_CONFIG_FILE, {}).get("creative", {}).get("destination", {})
    status = publishing_status(config, destination)
    explicit = creative_controls.get("use_direct_publishing")
    strategy = str(payload.get("creative_creation_strategy") or payload.get("publishing_strategy") or "").strip().lower()
    manual_completion = manual_creative_completion_enabled({**payload, **creative_controls})
    placeholder_static = placeholder_static_ad_enabled({**payload, **creative_controls})
    has_existing_post = bool(creative_controls.get("object_story_id"))
    has_video_url = bool(creative_controls.get("video_path") or creative_controls.get("video_url") or creative_controls.get("video_id"))
    has_static_image = bool(payload.get("creative_image_path") or creative_controls.get("image_url")) and not has_video_url
    has_native_asset = has_static_image or has_video_url or placeholder_static
    # Old flags remain readable for upgrade compatibility, but no longer
    # change campaign creative creation. Ads use the Live Ads app inline;
    # Publicación directa is for organic posts and an optional credential retry.
    requested = explicit is True or strategy in {"direct", "direct_publishing", "native_post", "page_post", "dark_post", "unpublished_post"}
    disabled = explicit is False
    will_create = False
    missing = []
    if placeholder_static:
        route = "paused_static_placeholder_ads"
    elif manual_completion:
        route = "manual_ads_manager_completion"
    else:
        route = "existing_object_story_id" if has_existing_post else "native_inline_ads_app"
    return {
        "requested": requested,
        "disabled": disabled,
        "ready": bool(status.get("ready")),
        "token_set": bool(status.get("token_set")),
        "page_id": status.get("page_id", ""),
        "has_existing_post": has_existing_post,
        "has_static_image": has_static_image,
        "has_video_url": has_video_url,
        "will_create_unpublished_post": will_create,
        "manual_creative_completion": manual_completion,
        "create_placeholder_ad": placeholder_static,
        "placeholder_ad_count": placeholder_ad_count({**payload, **creative_controls}, default=len(placeholder_ad_names({**payload, **creative_controls})) or 1) if placeholder_static else 0,
        "placeholder_ad_names": placeholder_ad_names({**payload, **creative_controls}) if placeholder_static else [],
        "creative_route": route,
        "missing_requirements": missing,
        "note": "Los anuncios usan la app Live de Ads directamente; no se crea un dark post." if has_native_asset and not has_existing_post else "",
    }


def _debug_token_scopes(debug_result):
    data = debug_result.get("data") if isinstance(debug_result, dict) else {}
    if isinstance(data, dict) and isinstance(data.get("data"), dict):
        scopes = data["data"].get("scopes") or data["data"].get("granular_scopes") or []
    else:
        scopes = []
    if isinstance(scopes, list):
        normalized = []
        for scope in scopes:
            if isinstance(scope, dict):
                normalized.append(str(scope.get("scope") or "").strip())
            else:
                normalized.append(str(scope or "").strip())
        return {scope for scope in normalized if scope}
    return set()


def test_publishing_connection(payload=None):
    payload = payload or {}
    config = load_config()
    token = str(payload.get("token") or getattr(config, "meta_access_token", "") or getattr(config, "meta_publishing_access_token", "") or "").strip()
    destination = read_json(AD_CONFIG_FILE, {}).get("creative", {}).get("destination", {})
    page_id = str(payload.get("page_id") or destination.get("page_id") or "").strip()
    if not token:
        return {"ok": False, "code": "missing_token", "message": "Falta conectar el token único de Meta.", "page_id": page_id}
    debug = graph_get("/debug_token", {"input_token": token}, page_token=token)
    # `tasks`/`perms` are not consistently available on current Graph API
    # Page-token responses. Resolve access from the token and Page ID instead
    # of making the whole validation fail on an obsolete field.
    pages = graph_get("/me/accounts", {"fields": "id,name,access_token", "limit": 100}, page_token=token)
    scopes = _debug_token_scopes(debug)
    required_scopes = {"pages_manage_posts", "pages_read_engagement"}
    missing_scopes = sorted(required_scopes - scopes) if scopes else []
    native_whatsapp_scopes = {"ads_management", "ads_read"}
    missing_native_whatsapp_scopes = sorted(native_whatsapp_scopes - scopes) if scopes else sorted(native_whatsapp_scopes)
    pages_data = []
    if pages.get("ok") and isinstance(pages.get("data"), dict):
        pages_data = pages["data"].get("data") or []
    page = next((entry for entry in pages_data if str(entry.get("id") or "") == page_id), None) if page_id else None
    page_found = bool(page) if page_id else bool(pages_data)
    ok = bool(pages.get("ok")) and page_found and not missing_scopes
    ad_account_id = str(getattr(config, "ad_account_id", "") or "").strip()
    ad_account_result = graph_get(
        f"/{ad_account_id}",
        {"fields": "id,name,account_status"},
        page_token=token,
    ) if ad_account_id else {"ok": False, "error": "missing_ad_account"}
    native_whatsapp_ads_ready = bool(
        ok
        and not missing_native_whatsapp_scopes
        and ad_account_result.get("ok")
    )
    message = "Publicación directa lista con el token único de Meta." if ok else "El token único de Meta todavía no está listo para publicar."
    if missing_scopes:
        message = f"Faltan permisos: {', '.join(missing_scopes)}."
    elif page_id and not page_found:
        message = "La clave de publicación no puede acceder a la página guardada."
    elif not pages.get("ok"):
        message = graph_error_message(pages) or message
    elif ok and not native_whatsapp_ads_ready:
        message = "Publicación directa lista para posts. Los anuncios nativos de WhatsApp usarán primero la app principal de Ads cuando esté Live."
    debug_data = debug.get("data", {}).get("data", {}) if isinstance(debug.get("data"), dict) else {}
    return {
        "ok": ok,
        "code": "ready" if ok else "not_ready",
        "message": message,
        "app_id": debug_data.get("app_id", ""),
        "application": debug_data.get("application", ""),
        "scopes": sorted(scopes),
        "missing_scopes": missing_scopes,
        "page_id": page_id,
        "page_found": page_found,
        "page_name": (page or {}).get("name", ""),
        "pages_seen": len(pages_data),
        "native_whatsapp_ads_ready": native_whatsapp_ads_ready,
        "missing_native_whatsapp_scopes": missing_native_whatsapp_scopes,
        "ad_account_access": bool(ad_account_result.get("ok")),
    }


def save_publishing_config(payload):
    payload = payload or {}
    if payload.get("disconnect"):
        update_env_values({
            "META_PUBLISHING_ACCESS_TOKEN": "",
            "META_PUBLISHING_TOKEN_SAVED_AT": "",
        })
        return {"ok": True, "saved": True, "disconnected": True, "message": "Publicación directa desconectada."}
    token = str(payload.get("token") or payload.get("publishing_token") or payload.get("meta_publishing_access_token") or "").strip()
    if len(token) < 20:
        raise ValueError("La clave de publicación es demasiado corta.")
    check = test_publishing_connection({"token": token, "page_id": payload.get("page_id") or ""})
    # Compatibility endpoint for pre-unification clients. Store the token as
    # the primary credential too; new UI never presents a second token field.
    update_env_values({
        "META_ACCESS_TOKEN": token,
        "META_ACCESS_TOKEN_KIND": "stable",
        "META_ACCESS_TOKEN_SAVED_AT": now_iso(),
        "META_PUBLISHING_ACCESS_TOKEN": token,
        "META_PUBLISHING_TOKEN_SAVED_AT": now_iso(),
    })
    log_action("meta_direct_publishing_config", {"ready": bool(check.get("ok")), "page_found": bool(check.get("page_found")), "missing_scopes": check.get("missing_scopes", []), "native_whatsapp_ads_ready": bool(check.get("native_whatsapp_ads_ready")), "missing_native_whatsapp_scopes": check.get("missing_native_whatsapp_scopes", [])}, "completed" if check.get("ok") else "warn")
    return {**check, "saved": True, "token_set": True}


def graph_get(path, params=None, page_token=""):
    config = load_config()
    token = page_token or config.meta_access_token
    if not token:
        return {"ok": False, "error": "missing_token", "data": None}
    version = config.meta_graph_api_version or "v24.0"
    query = {"access_token": token, **(params or {})}
    url = f"https://graph.facebook.com/{version}/{path.lstrip('/')}?{urllib.parse.urlencode(query)}"
    try:
        with urllib.request.urlopen(url, timeout=20) as response:
            data = json.loads(response.read().decode("utf-8"))
        return {"ok": True, "data": data}
    except urllib.error.HTTPError as exc:
        try:
            data = json.loads(exc.read().decode("utf-8"))
        except Exception:
            data = {"error": str(exc)}
        return {"ok": False, "error": data}
    except Exception as exc:
        return {"ok": False, "error": str(exc)}


def graph_error_message(result):
    error = result.get("error") if isinstance(result, dict) else result
    if isinstance(error, dict):
        nested = error.get("error")
        if isinstance(nested, dict):
            return nested.get("message") or json.dumps(nested)[:500]
        return error.get("message") or json.dumps(error)[:500]
    return str(error or "")


def clamp_int(value, default=10, minimum=1, maximum=25):
    try:
        parsed = int(value)
    except (TypeError, ValueError):
        parsed = default
    return max(minimum, min(maximum, parsed))


def normalize_targeting_item(item, kind):
    if not isinstance(item, dict):
        return {}
    if kind == "location":
        key = str(item.get("key") or item.get("id") or "").strip()
        name = str(item.get("name") or item.get("canonical_name") or key).strip()
        location_type = str(item.get("type") or item.get("location_type") or "").strip().lower()
        country_code = str(item.get("country_code") or item.get("country") or "").strip().upper()
        if not location_type and len(key) == 2 and key.isalpha():
            location_type = "country"
            country_code = key.upper()
        label_bits = [name]
        if country_code and country_code not in name.upper():
            label_bits.append(country_code)
        return {
            "kind": "location",
            "id": key,
            "key": key,
            "name": name,
            "label": " · ".join([part for part in label_bits if part]),
            "type": location_type or "location",
            "country_code": country_code,
        }
    interest_id = str(item.get("id") or item.get("key") or "").strip()
    name = str(item.get("name") or interest_id).strip()
    path = item.get("path") if isinstance(item.get("path"), list) else []
    audience_size = item.get("audience_size") or item.get("audience_size_lower_bound") or item.get("audience_size_upper_bound") or ""
    return {
        "kind": "interest",
        "id": interest_id,
        "name": name,
        "label": name,
        "path": path[:5],
        "audience_size": audience_size,
    }


def meta_targeting_search(payload):
    kind = str(payload.get("kind") or payload.get("type") or "interest").strip().lower()
    if kind in {"interests", "adinterest"}:
        kind = "interest"
    if kind in {"locations", "geo", "adgeolocation"}:
        kind = "location"
    if kind not in {"interest", "location"}:
        raise ValueError("Tipo de segmentación no soportado.")
    query = str(payload.get("q") or payload.get("query") or "").strip()
    if len(query) < 2:
        raise ValueError("Escribe al menos 2 letras para buscar en Meta.")
    limit = clamp_int(payload.get("limit"), default=8, minimum=1, maximum=25)
    params = {"type": "adinterest" if kind == "interest" else "adgeolocation", "q": query, "limit": limit}
    if kind == "location":
        params["location_types"] = json.dumps(["country", "region", "city"])
        country_code = str(payload.get("country_code") or "").strip().upper()
        if country_code:
            params["country_code"] = country_code
    result = graph_get("search", params)
    if not result.get("ok"):
        reason = result.get("error")
        raw_message = graph_error_message(result)
        if reason == "missing_token":
            message = "Primero conecta Meta para buscar opciones reales de público."
        elif any(token_hint in raw_message.lower() for token_hint in ["expired", "oauth", "access token", "validating access token"]):
            message = "Tu conexión con Meta venció. Vuelve al paso de conexión, pega una clave nueva y luego busca el público otra vez."
        else:
            message = "No pude consultar opciones de Meta todavía. Revisa internet, permisos de tu clave o intenta con otra palabra."
        return {"ok": False, "kind": kind, "query": query, "items": [], "message": message}
    rows = ((result.get("data") or {}).get("data") or [])[:limit]
    items = [normalize_targeting_item(row, kind) for row in rows]
    items = [item for item in items if item.get("id") or item.get("name")]
    if kind == "interest":
        # Meta interest IDs are decimal strings. Never expose malformed or
        # synthetic values to Hermes/UI where they could be copied into an ad
        # set and fail after the campaign object was already created.
        items = [item for item in items if re.fullmatch(r"[0-9]+", str(item.get("id") or ""))]
    return {"ok": True, "kind": kind, "query": query, "items": items}


def meta_targeting_interest_ids(targeting):
    if not isinstance(targeting, dict):
        return []
    values = []
    for item in targeting.get("interests") or []:
        if isinstance(item, dict) and item.get("id"):
            values.append(str(item.get("id")))
    for group in targeting.get("flexible_spec") or []:
        if not isinstance(group, dict):
            continue
        for item in group.get("interests") or []:
            if isinstance(item, dict) and item.get("id"):
                values.append(str(item.get("id")))
    return list(dict.fromkeys(values))


def meta_targeting_advantage_value(targeting):
    automation = targeting.get("targeting_automation") if isinstance(targeting, dict) else {}
    if not isinstance(automation, dict) or "advantage_audience" not in automation:
        return None
    enabled = boolish(automation.get("advantage_audience"))
    return (1 if enabled else 0) if enabled is not None else None


def meta_adset_targeting_status(payload):
    """Read the persisted ad-set audience directly from Meta Graph.

    This proves the live Graph object contains the requested interest IDs and
    Advantage+ audience flag. It deliberately does not claim where or under
    which wording Ads Manager renders those values in its current UI.
    """
    adset_id = str(payload.get("adset_id") or payload.get("id") or "").strip()
    if not adset_id.isdigit():
        raise ValueError("Necesito el ID numérico exacto del conjunto de anuncios.")
    result = graph_get(
        adset_id,
        {
            "fields": (
                "id,name,status,effective_status,configured_status,targeting,"
                "optimization_goal,promoted_object,destination_type"
            )
        },
    )
    if not result.get("ok"):
        return {
            "ok": False,
            "source": "meta_live",
            "adset_id": adset_id,
            "confirmed": False,
            "error": graph_error_message(result) or "No pude leer este conjunto directamente desde Meta.",
        }
    body = result.get("data") if isinstance(result.get("data"), dict) else {}
    targeting = body.get("targeting") or {}
    if isinstance(targeting, str):
        try:
            targeting = json.loads(targeting)
        except json.JSONDecodeError:
            targeting = {}
    if not isinstance(targeting, dict):
        targeting = {}
    interests = []
    for item in targeting.get("interests") or []:
        if isinstance(item, dict) and item.get("id"):
            interests.append({"id": str(item.get("id")), "name": str(item.get("name") or "")})
    for group in targeting.get("flexible_spec") or []:
        if not isinstance(group, dict):
            continue
        for item in group.get("interests") or []:
            if isinstance(item, dict) and item.get("id"):
                interests.append({"id": str(item.get("id")), "name": str(item.get("name") or "")})
    interest_ids = list(dict.fromkeys(item["id"] for item in interests))
    requested = payload.get("requested_interest_ids") or payload.get("interest_ids") or []
    if isinstance(requested, str):
        requested = [part.strip() for part in requested.split(",") if part.strip()]
    requested_ids = list(dict.fromkeys(str(value) for value in requested if str(value or "").strip())) if isinstance(requested, list) else []
    missing_ids = [value for value in requested_ids if value not in interest_ids]
    advantage = meta_targeting_advantage_value(targeting)
    requested_advantage = None
    if "advantage_audience" in payload:
        enabled = boolish(payload.get("advantage_audience"))
        requested_advantage = (1 if enabled else 0) if enabled is not None else None
    advantage_matches = requested_advantage is None or requested_advantage == advantage
    confirmed = not missing_ids and advantage_matches
    if advantage == 1 and interest_ids:
        mode = "advantage_plus_suggestions"
    elif interest_ids:
        mode = "manual_detailed_targeting"
    elif advantage == 1:
        mode = "advantage_plus_broad"
    else:
        mode = "broad_or_unspecified"
    return {
        "ok": True,
        "source": "meta_live",
        "adset_id": adset_id,
        "name": body.get("name") or "",
        "status": body.get("status") or "",
        "effective_status": body.get("effective_status") or "",
        "targeting": targeting,
        "interests": interests,
        "interest_ids": interest_ids,
        "advantage_audience": advantage,
        "targeting_mode": mode,
        "requested_interest_ids": requested_ids,
        "missing_interest_ids": missing_ids,
        "requested_advantage_audience": requested_advantage,
        "advantage_audience_matches": advantage_matches,
        "confirmed": confirmed,
        "ui_confirmation": False,
        "ui_note": "Esto confirma el estado persistido en Meta Graph, no la ubicación o el texto exacto de la interfaz de Ads Manager.",
    }


def parse_targeting_items(value, kind):
    if not value:
        return []
    if isinstance(value, str):
        try:
            raw = json.loads(value)
        except json.JSONDecodeError:
            return []
    else:
        raw = value
    if not isinstance(raw, list):
        return []
    items = []
    seen = set()
    for entry in raw[:25]:
        item = normalize_targeting_item(entry, kind)
        key = item.get("id") or item.get("name")
        if not key or key in seen:
            continue
        seen.add(key)
        items.append(item)
    return items


def targeting_location_values(selected, fallback):
    values = []
    for item in selected:
        if item.get("type") == "country" and item.get("key"):
            values.append(str(item["key"]).upper())
        elif item.get("country_code"):
            values.append(str(item["country_code"]).upper())
        elif item.get("name"):
            values.append(str(item["name"]))
    return normalize_location_codes(values, default=[]) or normalize_location_codes(fallback, default=[])


def _plain_location_text(value):
    text = unicodedata.normalize("NFKD", str(value or ""))
    return "".join(char for char in text if not unicodedata.combining(char)).strip().casefold()


def campaign_location_query_terms(value):
    """Return non-country place names that must be resolved through Meta.

    Country names/codes remain handled by normalize_location_codes. Regions,
    cities and towns are deliberately preserved instead of being discarded
    from inputs such as ``Antioquia, Colombia``.
    """
    if value in (None, "", [], ()):
        return []
    if isinstance(value, dict):
        # Structured picker results already contain their live Meta key.
        if value.get("key") or value.get("id"):
            return []
        values = [value.get("name") or value.get("label") or ""]
    elif isinstance(value, (list, tuple, set)):
        values = list(value)
    else:
        text = str(value or "").strip()
        if text.startswith(("[", "{")):
            try:
                return campaign_location_query_terms(json.loads(text))
            except json.JSONDecodeError:
                pass
        values = re.split(r"\s*(?:,|;|/|\||\by\b|\band\b)\s*", text, flags=re.IGNORECASE)
    queries = []
    seen = set()
    for item in values:
        if isinstance(item, dict):
            queries.extend(campaign_location_query_terms(item))
            continue
        if isinstance(item, str) and re.search(r",|;|/|\||\by\b|\band\b", item, flags=re.IGNORECASE):
            # Terra commonly emits a JSON list whose single item is the
            # buyer's natural "City, Country" phrase. Parse that item with
            # the same logic as a scalar instead of letting the country name
            # cause the whole combined value to be classified as a country.
            for nested in campaign_location_query_terms(item):
                identity = _plain_location_text(nested)
                if identity and identity not in seen:
                    seen.add(identity)
                    queries.append(nested)
            continue
        term = str(item or "").strip().strip("[](){}'\" ")
        if not term or normalize_location_codes(term, default=[]):
            continue
        identity = _plain_location_text(term)
        if identity and identity not in seen:
            seen.add(identity)
            queries.append(term)
    return queries


def resolve_campaign_location_queries(queries, country_codes=None):
    """Resolve natural city/region names against Meta's current catalog."""
    resolved = []
    country_codes = [str(code or "").strip().upper() for code in (country_codes or []) if code]
    for query in queries or []:
        request = {"kind": "location", "q": query, "limit": 25}
        if len(country_codes) == 1:
            request["country_code"] = country_codes[0]
        result = meta_targeting_search(request)
        if not isinstance(result, dict) or not result.get("ok"):
            raise ValueError(
                f"targeting_location_catalog_unavailable: Meta no pudo validar '{query}'. No se creó ningún objeto."
            )
        items = result.get("items") or []
        query_key = _plain_location_text(query)
        exact = [item for item in items if _plain_location_text(item.get("name")) == query_key]
        candidates = exact or (items if len(items) == 1 else [])
        if country_codes:
            same_country = [item for item in candidates if str(item.get("country_code") or "").upper() in country_codes]
            candidates = same_country
        # Prefer the narrow place the buyer named over a broad country result.
        candidates = sorted(
            candidates,
            key=lambda item: ({"city": 0, "region": 1, "country": 2}.get(str(item.get("type") or "").lower(), 3)),
        )
        if not candidates:
            raise ValueError(
                f"targeting_location_ambiguous_or_not_found: Meta no devolvió una coincidencia única para '{query}'. No se creó ningún objeto."
            )
        selected = dict(candidates[0])
        selected["id"] = str(selected.get("id") or selected.get("key") or "").strip()
        resolved.append(selected)
    return resolved


def targeting_summary(audience):
    meta = audience.get("meta_targeting") or {}
    locations = [item.get("label") or item.get("name") or item.get("key") for item in meta.get("locations") or []]
    interests = [item.get("name") for item in meta.get("interests") or []]
    return {
        "locations": locations or audience.get("locations", []),
        "interests": interests or audience.get("interests", []),
        "source": "meta_search" if (locations or interests) else "manual_or_broad",
    }


def action_metric_value(rows, names):
    # Keep the legacy dashboard fallback aligned with the primary collector.
    # Import locally so old installations can still load this module while an
    # official update is copying the new shared reporting module into place.
    from meta_action_metrics import deduplicated_alias_value

    return deduplicated_alias_value(rows, names)


def conversion_metric_value(rows):
    # Generic "results" must select one outcome family rather than adding
    # sequential funnel events such as Lead + Contact + Purchase.
    from meta_action_metrics import conversion_result_value

    return conversion_result_value(rows)


def funnel_metric_values(rows):
    from meta_action_metrics import canonical_funnel_values

    return canonical_funnel_values(rows)


def normalize_insights_rows(rows, account_id=""):
    campaigns = []
    purchase_value_actions = {
        "purchase",
        "omni_purchase",
        "offsite_conversion.fb_pixel_purchase",
        "onsite_conversion.purchase",
    }
    for row in rows or []:
        if not isinstance(row, dict):
            continue
        campaign_id = str(row.get("campaign_id") or row.get("id") or "").strip()
        campaign_name = row.get("campaign_name") or row.get("name") or campaign_id or "Campaign"
        spend = money(row.get("spend", 0))
        clicks = int(float(row.get("clicks") or row.get("inline_link_clicks") or 0))
        impressions = int(float(row.get("impressions") or 0))
        actions = row.get("actions") or []
        action_values = row.get("action_values") or []
        conversions = int(round(conversion_metric_value(actions)))
        revenue = money(action_metric_value(action_values, purchase_value_actions))
        funnel = funnel_metric_values(actions)
        ctr = float(row.get("ctr") or 0)
        cpc = float(row.get("cpc") or 0)
        frequency = float(row.get("frequency") or 1.0)
        campaign = {
            "id": campaign_id or campaign_name,
            "campaign_id": campaign_id,
            "name": campaign_name,
            "status": str(row.get("effective_status") or row.get("status") or "active").lower(),
            "target_type": "campaign",
            "target_id": campaign_id or campaign_name,
            "daily_budget": money(float(row.get("daily_budget") or 0) / 100) if row.get("daily_budget") else 0,
            "spend": spend,
            "impressions": impressions,
            "clicks": clicks,
            "conversions": conversions,
            "revenue": revenue,
            "funnel": funnel,
            "frequency": frequency,
            "ctr": ctr,
            "cpc": cpc,
            "previous_ctr": ctr,
            "previous_cpc": cpc,
            "updated_at": now_iso(),
        }
        campaigns.append(campaign)
    return {
        "timestamp": now_iso(),
        "source": "meta_graph",
        "source_label": "Meta Ads real data",
        "account_id": account_id,
        "date_preset": "last_7d",
        "campaigns": campaigns,
        "summary": {},
    }


def current_dashboard_metrics_range(date_preset=None, since="", until=""):
    """Resolve the dashboard period, defaulting new installs to all-time.

    A previously selected period is stored alongside the real metrics so
    automatic refreshes, account switches and browser reloads do not silently
    jump back to a different date range.
    """
    if date_preset is not None:
        return normalize_insight_range(date_preset, since, until)
    stored = read_json(METRICS_FILE, {})
    selected = stored.get("metrics_range") if isinstance(stored, dict) else {}
    if not isinstance(selected, dict):
        selected = {}
    preset = str(selected.get("preset") or "maximum").strip().lower()
    try:
        return normalize_insight_range(preset, selected.get("since"), selected.get("until"))
    except ValueError:
        return normalize_insight_range("maximum")


def _inventory_insight_totals(rows):
    """Aggregate read-only insight rows by their Meta object ID."""
    totals = {}
    for row in rows or []:
        if not isinstance(row, dict):
            continue
        object_id = str(row.get("id") or "").strip()
        if not object_id:
            continue
        item = totals.setdefault(
            object_id,
            {
                "spend": 0.0,
                "impressions": 0,
                "reach": 0,
                "clicks": 0,
                "conversions": 0.0,
                "revenue": 0.0,
                "funnel": {},
                "date_start": "",
                "date_stop": "",
            },
        )
        item["spend"] += float(row.get("spend") or 0)
        item["impressions"] += int(float(row.get("impressions") or 0))
        item["reach"] += int(float(row.get("reach") or 0))
        item["clicks"] += int(float(row.get("clicks") or 0))
        item["conversions"] += float(row.get("conversions") or 0)
        item["revenue"] += float(row.get("revenue") or 0)
        item["date_start"] = min(filter(None, [item.get("date_start"), str(row.get("date_start") or "")]), default="")
        item["date_stop"] = max(item.get("date_stop") or "", str(row.get("date_stop") or ""))
        for key, value in (row.get("funnel") or {}).items():
            item["funnel"][key] = round(float(item["funnel"].get(key) or 0) + float(value or 0), 2)
    for item in totals.values():
        spend = item["spend"]
        impressions = item["impressions"]
        clicks = item["clicks"]
        conversions = item["conversions"]
        revenue = item["revenue"]
        item.update(
            {
                "spend": round(spend, 2),
                "conversions": round(conversions, 2),
                "revenue": round(revenue, 2),
                "ctr": round(clicks / impressions * 100, 3) if impressions else 0,
                "cpc": round(spend / clicks, 2) if clicks else 0,
                "cpa": round(spend / conversions, 2) if conversions else 0,
                "roas": round(revenue / spend, 3) if spend else 0,
                "frequency": round(impressions / item["reach"], 2) if item["reach"] else 0,
            }
        )
    return totals


def _attach_inventory_insights(items, rows):
    totals = _inventory_insight_totals(rows)
    return [{**item, **totals.get(str(item.get("id") or ""), {})} for item in items or []]


def _meta_connection_probe(account_id, token, version):
    """Separate a broken Meta edge from a broken credential/account connection."""
    identity = meta_graph_get("me", {"fields": "id"}, token, version, max_attempts=1)
    account = meta_graph_get(
        account_id,
        {"fields": "id,name,account_status,disable_reason"},
        token,
        version,
        max_attempts=1,
    )
    account_data = account.get("data") if isinstance(account.get("data"), dict) else {}
    return {
        "reachable": bool(identity.get("ok") or account.get("ok")),
        "identity_ok": bool(identity.get("ok")),
        "account_ok": bool(account.get("ok")),
        "account_id": str(account_data.get("id") or account_id),
        "account_status": account_data.get("account_status"),
        "disable_reason": account_data.get("disable_reason"),
        "identity_error": identity.get("error") if not identity.get("ok") else None,
        "account_error": account.get("error") if not account.get("ok") else None,
    }


def _classify_meta_read_failure(error, connection=None):
    error = error if isinstance(error, dict) else {}
    connection = connection if isinstance(connection, dict) else {}
    category = str(error.get("category") or meta_graph_error_category(error))
    connected = bool(connection.get("reachable"))
    if category == "authentication":
        return {
            "reason": "meta_auth_error",
            "message": "La credencial de Meta no fue aceptada. Reconecta Meta desde Configuración.",
            "category": category,
        }
    if category == "permission":
        return {
            "reason": "meta_permission_error",
            "message": "Meta respondió, pero esta credencial no tiene acceso suficiente a ese recurso.",
            "category": category,
        }
    if category in {"meta_transient", "network", "rate_limit"}:
        if connected:
            message = (
                "Meta responde y la cuenta está conectada, pero su servicio de campañas o reportes está "
                "temporalmente no disponible. Se reintentó la lectura; una lista vacía no significa que no haya campañas."
            )
        else:
            message = "La lectura de Meta falló temporalmente. Se reintentó sin asumir que la cuenta está vacía."
        return {
            "reason": "meta_endpoint_temporarily_unavailable",
            "message": message,
            "category": category,
        }
    return {
        "reason": "graph_error",
        "message": str(error.get("message") or "Meta Graph request failed"),
        "category": category,
    }


def fetch_real_metrics(account_id="", persist_snapshot=True, live_dashboard=False, date_preset=None, since="", until="", include_breakdowns=True):
    config = load_config()
    account_id = str(account_id or config.ad_account_id or "").strip()
    if account_id and not account_id.startswith("act_"):
        account_id = f"act_{account_id}"
    if not account_id:
        return {"ok": False, "reason": "missing_account", "message": "Missing Meta ad account."}
    if not config.meta_access_token:
        return {"ok": False, "reason": "missing_token", "message": "Missing Meta access token."}
    def collect_known_campaign_ids():
        found = []
        def visit(value, key=""):
            if isinstance(value, dict):
                for nested_key, nested in value.items():
                    visit(nested, str(nested_key or ""))
            elif isinstance(value, list):
                for nested in value:
                    visit(nested, key)
            elif key in {"campaign_id", "campaignId"}:
                candidate = str(value or "").strip()
                if candidate.isdigit() and 12 <= len(candidate) <= 24 and candidate not in found:
                    found.append(candidate)
        # A stored live snapshot can provide IDs for direct verification when
        # an account edge is temporarily incomplete. Local plans, action logs,
        # created-campaign drafts and approvals are deliberately excluded:
        # none of them proves that an object currently exists in Meta.
        for path, default in ((METRICS_FILE, {}),):
            visit(read_json(path, default))
        return found[:50]

    metrics_range = current_dashboard_metrics_range(date_preset, since, until)
    snapshot = collect_meta_snapshot(
        account_id,
        config.meta_access_token,
        config.meta_graph_api_version or "v24.0",
        date_preset=metrics_range["preset"],
        time_range=metrics_range.get("time_range"),
        known_campaign_ids=collect_known_campaign_ids(),
        insight_levels=("campaign",) if live_dashboard else None,
        include_breakdowns=bool(include_breakdowns and not live_dashboard),
    )
    campaigns = aggregate_meta_campaigns(snapshot)
    visible_campaign_ids = {str(campaign.get("id") or "") for campaign in campaigns}
    adsets = _attach_inventory_insights([
        item for item in (snapshot.get("adset_statuses") or {}).values()
        if str(item.get("campaign_id") or "") in visible_campaign_ids
    ], (snapshot.get("levels") or {}).get("adset", []))
    visible_adset_ids = {str(item.get("id") or "") for item in adsets}
    ads = _attach_inventory_insights([
        item for item in (snapshot.get("ad_statuses") or {}).values()
        if str(item.get("campaign_id") or "") in visible_campaign_ids
        and (not item.get("adset_id") or str(item.get("adset_id")) in visible_adset_ids)
    ], (snapshot.get("levels") or {}).get("ad", []))
    campaign_tree = meta_campaign_inventory_tree(snapshot)
    if not campaigns and snapshot.get("data_quality", {}).get("unavailable"):
        first_error = snapshot["data_quality"]["unavailable"][0].get("reason") or {}
        connection = _meta_connection_probe(account_id, config.meta_access_token, config.meta_graph_api_version or "v24.0")
        diagnosis = _classify_meta_read_failure(first_error, connection)
        return {
            "ok": False,
            **diagnosis,
            "raw": first_error,
            "connection": connection,
            "data_quality": snapshot.get("data_quality"),
        }
    account = managed_account_context(account_id)
    for campaign in campaigns:
        campaign["account_id"] = account_id
        campaign["ad_account_id"] = account_id
        campaign["account_name"] = account.get("name") or account_id
        if account.get("business_id"):
            campaign["business_manager_id"] = account.get("business_id")
            campaign["business_manager_name"] = account.get("business_name", "")
    for collection in (adsets, ads, campaign_tree):
        for item in collection:
            item["account_id"] = account_id
            item["ad_account_id"] = account_id
            item["account_name"] = account.get("name") or account_id
    metrics = {
        "timestamp": now_iso(),
        "source": "meta_graph",
        "source_label": "Meta Ads real data",
        "account_id": account_id,
        "date_preset": snapshot.get("date_preset") or metrics_range["preset"],
        "metrics_range": snapshot.get("metrics_range") or {
            "preset": metrics_range["preset"],
            "since": metrics_range.get("since", ""),
            "until": metrics_range.get("until", ""),
        },
        "campaigns": campaigns,
        "adsets": adsets,
        "ads": ads,
        "campaign_tree": campaign_tree,
        "summary": {},
        "data_quality": snapshot.get("data_quality"),
        "breakdowns": snapshot.get("breakdowns") or {},
    }
    if persist_snapshot:
        save_meta_snapshot(snapshot)
    data_quality = snapshot.get("data_quality") or {}
    errors = data_quality.get("unavailable") or []
    return {
        "ok": True,
        "partial": bool(errors),
        "metrics": metrics,
        "rows": len(campaigns),
        "account_id": account_id,
        "errors": errors,
        "data_quality": data_quality,
    }


def refresh_managed_real_metrics(reason="manual", live_dashboard=False, date_preset=None, since="", until="", persist=True, include_breakdowns=True):
    accounts = managed_metric_accounts()
    if len(accounts) <= 1:
        return refresh_real_metrics(
            accounts[0]["id"] if accounts else "",
            reason=reason,
            live_dashboard=live_dashboard,
            date_preset=date_preset,
            since=since,
            until=until,
            persist=persist,
            include_breakdowns=include_breakdowns,
        )
    campaigns = []
    adsets = []
    ads = []
    campaign_tree = []
    breakdowns = {}
    account_results = []
    errors = []
    partial = False
    selected_metrics_range = current_dashboard_metrics_range(date_preset, since, until)
    for account in accounts:
        account_id = account.get("id")
        result = fetch_real_metrics(
            account_id,
            persist_snapshot=False,
            live_dashboard=live_dashboard,
            date_preset=selected_metrics_range["preset"],
            since=selected_metrics_range.get("since", ""),
            until=selected_metrics_range.get("until", ""),
            include_breakdowns=include_breakdowns,
        )
        if result.get("ok"):
            partial = bool(partial or result.get("partial"))
            rows = result.get("rows", 0)
            account_results.append({"id": account_id, "name": account.get("name") or account_id, "rows": rows})
            for item in result.get("errors") or []:
                item = item if isinstance(item, dict) else {"reason": item}
                errors.append({
                    "id": account_id,
                    "name": account.get("name") or account_id,
                    "view": item.get("view"),
                    "reason": item.get("reason") or item,
                })
            metrics_result = result.get("metrics", {})
            campaigns.extend(metrics_result.get("campaigns", []))
            adsets.extend(metrics_result.get("adsets", []))
            ads.extend(metrics_result.get("ads", []))
            campaign_tree.extend(metrics_result.get("campaign_tree", []))
            for name, rows in (metrics_result.get("breakdowns") or {}).items():
                breakdowns.setdefault(name, []).extend(rows or [])
        else:
            errors.append({
                "id": account_id,
                "name": account.get("name") or account_id,
                "reason": result.get("reason"),
                "message": result.get("message"),
                "category": result.get("category"),
                "raw": result.get("raw"),
                "connection": result.get("connection"),
            })
    if campaigns or account_results:
        managed = normalize_managed_accounts_state()
        metrics = {
            "timestamp": now_iso(),
            "source": "meta_graph",
            "source_label": "Meta Ads real data · multiple accounts",
            "account_id": managed.get("active_ad_account_id") or (accounts[0].get("id") if accounts else ""),
            "date_preset": metrics_result.get("date_preset") or selected_metrics_range["preset"],
            "metrics_range": metrics_result.get("metrics_range") or {
                "preset": selected_metrics_range["preset"],
                "since": selected_metrics_range.get("since", ""),
                "until": selected_metrics_range.get("until", ""),
            },
            "business_manager": managed.get("business_manager", {}),
            "accounts": account_results,
            "campaigns": campaigns,
            "adsets": adsets,
            "ads": ads,
            "campaign_tree": campaign_tree,
            "breakdowns": breakdowns,
            "summary": {},
            "data_quality": {"complete": not errors and not partial, "unavailable": errors, "source": "meta_graph_read_only_multi_account"},
        }
        metrics = apply_campaign_metric_profiles(metrics)
        if persist:
            save_metrics(metrics)
            status = "completed" if not errors else "partial"
            log_action("live_insights_pull", {"account_ids": [item.get("id") for item in accounts], "rows": len(campaigns), "errors": len(errors), "reason": reason}, status)
        return {"ok": True, "partial": bool(errors or partial), "saved": bool(persist), "source": "meta_graph", "rows": len(campaigns), "accounts": account_results, "errors": errors, "account_id": metrics["account_id"], "metrics": metrics}
    message = errors[0]["message"] if errors else "Missing Meta ad account."
    if persist:
        log_action("live_insights_pull", {"account_ids": [item.get("id") for item in accounts], "reason": reason, "errors": errors}, "blocked")
    first_error = errors[0] if errors else {}
    return {
        "ok": False,
        "saved": False,
        "reason": first_error.get("reason") or "missing_account",
        "message": message,
        "category": first_error.get("category"),
        "raw": first_error.get("raw"),
        "connection": first_error.get("connection"),
        "errors": errors,
    }


def refresh_real_metrics(account_id="", reason="manual", live_dashboard=False, date_preset=None, since="", until="", persist=True, include_breakdowns=True):
    result = fetch_real_metrics(
        account_id,
        persist_snapshot=bool(persist and not live_dashboard),
        live_dashboard=live_dashboard,
        date_preset=date_preset,
        since=since,
        until=until,
        include_breakdowns=include_breakdowns,
    )
    if result.get("ok"):
        metrics = apply_campaign_metric_profiles(result["metrics"])
        if persist:
            save_metrics(metrics)
            log_action("live_insights_pull", {"account_id": result.get("account_id"), "rows": result.get("rows"), "reason": reason}, "completed")
        return {
            "ok": True,
            "partial": bool(result.get("partial")),
            "saved": bool(persist),
            "source": "meta_graph",
            "rows": result.get("rows"),
            "account_id": result.get("account_id"),
            "errors": result.get("errors") or [],
            "data_quality": result.get("data_quality") or {},
            "metrics": metrics,
        }
    if persist:
        log_action("live_insights_pull", {"account_id": account_id or load_config().ad_account_id, "reason": reason, "error": result.get("message"), "code": result.get("reason")}, "blocked")
    return {**result, "saved": False}


def normalize_page_asset(row):
    if not isinstance(row, dict):
        return None
    page = {
        "id": str(row.get("id") or "").strip(),
        "name": row.get("name") or "",
        "category": row.get("category") or "",
        "link": row.get("link") or "",
        "website": row.get("website") or "",
        "instagram": None,
    }
    for key in ["instagram_business_account", "connected_instagram_account"]:
        ig = row.get(key)
        if isinstance(ig, dict) and ig.get("id"):
            page["instagram"] = {
                "id": str(ig.get("id")),
                "username": ig.get("username") or ig.get("name") or "",
                "name": ig.get("name") or ig.get("username") or "",
            }
            break
    return page if page["id"] else None


def extract_urls(value):
    urls = []
    if isinstance(value, str):
        urls.extend(re.findall(r"https?://[^\s\"'<>]+", value))
    elif isinstance(value, dict):
        for nested in value.values():
            urls.extend(extract_urls(nested))
    elif isinstance(value, list):
        for nested in value:
            urls.extend(extract_urls(nested))
    cleaned = []
    for url in urls:
        url = url.rstrip(".,);]")
        if url and url not in cleaned:
            cleaned.append(url)
    return cleaned


def read_meta_page_profile(page_id):
    page_id = str(page_id or "").strip()
    if not page_id:
        return {}
    field_sets = [
        "id,name,category,link,website,about,description,phone,emails,instagram_business_account{id,username,name},connected_instagram_account{id,username,name}",
        "id,name,category,link,website,about,description,instagram_business_account{id,username,name},connected_instagram_account{id,username,name}",
        "id,name,category,link,website,instagram_business_account{id,username,name},connected_instagram_account{id,username,name}",
        "id,name,category,link,website",
    ]
    last_error = ""
    for fields in field_sets:
        result = graph_get(f"/{page_id}", {"fields": fields})
        if result.get("ok") and isinstance(result.get("data"), dict):
            data = result["data"]
            page = normalize_page_asset(data) or {"id": page_id}
            for key in ["about", "description", "phone"]:
                if data.get(key):
                    page[key] = str(data.get(key) or "")[:800]
            emails = data.get("emails")
            if isinstance(emails, list):
                page["emails"] = [str(item or "")[:120] for item in emails if item][:3]
            return page
        last_error = str(result.get("error") or "")[:300]
    return {"id": page_id, "graph_error": last_error}


def social_discover_assets(payload):
    account_id = str(payload.get("ad_account_id") or "").strip() or load_config().ad_account_id
    if account_id and not account_id.startswith("act_"):
        account_id = f"act_{account_id}"
    pages_result = graph_get(
        "/me/accounts",
        {
            "fields": "id,name,category,link,website,access_token,instagram_business_account{id,username,name},connected_instagram_account{id,username,name}",
            "limit": 100,
        },
    )
    pages = []
    for row in (pages_result.get("data") or {}).get("data", []) if pages_result.get("ok") else []:
        page = normalize_page_asset(row)
        if page:
            pages.append(page)

    page_with_ig = next((page for page in pages if page.get("instagram")), None)
    first_page = page_with_ig or (pages[0] if pages else None)
    suggested = {
        "page_id": first_page.get("id", "") if first_page else "",
        "page_name": first_page.get("name", "") if first_page else "",
        "instagram_actor_id": (first_page.get("instagram") or {}).get("id", "") if first_page else "",
        "instagram_username": (first_page.get("instagram") or {}).get("username", "") if first_page else "",
        "landing_url": first_page.get("website", "") if first_page else "",
    }

    urls = []
    ads_result = {"ok": False, "skipped": True}
    if account_id:
        ads_result = graph_get(
            f"/{account_id}/ads",
            {"fields": "creative{object_story_spec,asset_feed_spec,url_tags,link_url}", "limit": 25},
        )
        if ads_result.get("ok"):
            urls = extract_urls(ads_result.get("data"))
            if urls and not suggested["landing_url"]:
                suggested["landing_url"] = urls[0]

    if any(suggested.get(key) for key in ["page_id", "instagram_actor_id", "landing_url"]) and not load_onboarding_state().get("completed"):
        save_setup_config({**{key: value for key, value in suggested.items() if key in {"page_id", "instagram_actor_id", "landing_url"} and value}, "_skip_meta_profile_sync": True})
        sync_business_profile_from_meta_assets(first_page, suggested, urls)

    result = {
        "ok": pages_result.get("ok") or bool(urls),
        "ad_account_id": account_id,
        "pages": pages,
        "urls": urls[:8],
        "suggested": suggested,
        "saved": any(suggested.get(key) for key in ["page_id", "instagram_actor_id", "landing_url"]),
        "needs_page_permissions": not pages_result.get("ok") or not pages,
        "pages_error": pages_result.get("error") if not pages_result.get("ok") else "",
        "ads_error": ads_result.get("error") if isinstance(ads_result, dict) and not ads_result.get("ok") and not ads_result.get("skipped") else "",
    }
    log_action("meta_asset_discovery", redact_payload(result), "completed" if result["ok"] else "warn")
    return result


def sync_business_profile_from_meta_assets(page, suggested, urls=None):
    profile = read_json(BUSINESS_PROFILE_FILE, {})
    if not isinstance(profile, dict):
        profile = {}
    links = []
    for existing in profile.get("social_links") or []:
        if existing:
            links.append(str(existing))
    page = page or {}
    page_id = str((suggested or {}).get("page_id") or page.get("id") or "").strip()
    if page_id:
        graph_page = read_meta_page_profile(page_id)
        if graph_page and not graph_page.get("graph_error"):
            page = {**page, **graph_page}
        elif graph_page.get("graph_error"):
            page = {**page, "graph_error": graph_page.get("graph_error")}
    if page.get("link"):
        links.append(str(page.get("link")))
    instagram = page.get("instagram") if isinstance(page.get("instagram"), dict) else {}
    if instagram.get("username"):
        links.append(f"https://instagram.com/{str(instagram.get('username')).strip().lstrip('@')}")
    clean_links = []
    for link in links:
        value = str(link or "").strip()
        if value and value not in clean_links:
            clean_links.append(value[:300])
    if clean_links:
        profile["social_links"] = clean_links[:8]
    landing = str((suggested or {}).get("landing_url") or "").strip()
    if not landing and urls:
        landing = str((urls or [""])[0] or "").strip()
    if landing:
        profile["website_url"] = landing[:300]
        profile["website_skipped"] = False
    profile["meta_assets"] = {
        "page_id": page_id,
        "page_name": str((suggested or {}).get("page_name") or page.get("name") or "").strip(),
        "instagram_actor_id": str((suggested or {}).get("instagram_actor_id") or "").strip(),
        "instagram_username": str((suggested or {}).get("instagram_username") or "").strip(),
    }
    meta_page_profile = {
        "id": page_id,
        "name": str(page.get("name") or (suggested or {}).get("page_name") or "").strip(),
        "category": str(page.get("category") or "").strip(),
        "link": str(page.get("link") or "").strip(),
        "website": str(page.get("website") or landing or "").strip(),
        "about": str(page.get("about") or "").strip(),
        "description": str(page.get("description") or "").strip(),
        "phone_set": bool(page.get("phone")),
        "email_count": len(page.get("emails") or []) if isinstance(page.get("emails"), list) else 0,
        "instagram": instagram,
        "graph_error": str(page.get("graph_error") or "").strip(),
    }
    profile["meta_page_profile"] = {key: value for key, value in meta_page_profile.items() if value not in ("", [], {}, None)}
    graph_context = " ".join(str(meta_page_profile.get(key) or "") for key in ["name", "category", "about", "description"]).strip()
    if graph_context:
        profile["meta_page_context"] = graph_context[:1200]
        profile.setdefault("positioning", graph_context[:900])
        if not profile.get("business_type") and meta_page_profile.get("category"):
            profile["business_type"] = str(meta_page_profile.get("category"))[:220]
        if not profile.get("main_offer") and (meta_page_profile.get("about") or meta_page_profile.get("description")):
            profile["main_offer"] = str(meta_page_profile.get("about") or meta_page_profile.get("description"))[:220]
    profile.setdefault("source", "meta_asset_discovery")
    profile["updated_at"] = now_iso()
    write_json(BUSINESS_PROFILE_FILE, profile)
    write_onboarding_questions_memory(profile, "pending")
    return profile


def extract_json_payload(text):
    text = text.strip()
    for opener, closer in [("[", "]"), ("{", "}")]:
        start = text.find(opener)
        end = text.rfind(closer)
        if start >= 0 and end > start:
            try:
                return json.loads(text[start : end + 1])
            except json.JSONDecodeError:
                continue
    return None


def normalize_social_accounts(payload):
    if isinstance(payload, dict):
        rows = payload.get("data") or payload.get("accounts") or payload.get("items") or []
    elif isinstance(payload, list):
        rows = payload
    else:
        rows = []
    accounts = []
    for row in rows:
        if not isinstance(row, dict):
            continue
        account = managed_account_from(row)
        if not account:
            continue
        accounts.append(account)
    return accounts


def merge_account_metadata(accounts, richer_accounts):
    richer_by_id = {account.get("id"): account for account in richer_accounts or [] if account.get("id")}
    merged = []
    for account in accounts or []:
        richer = richer_by_id.get(account.get("id"), {})
        merged.append({
            **account,
            **{key: value for key, value in richer.items() if value and not account.get(key)}
        })
    return merged


def normalize_graph_account_rows(rows):
    accounts = normalize_social_accounts(rows)
    deduped = []
    seen = set()
    for account in accounts:
        account_id = account.get("id")
        if not account_id or account_id in seen:
            continue
        seen.add(account_id)
        deduped.append(account)
    return deduped


def graph_business_account_rows(rows):
    found = []
    for business in rows or []:
        if not isinstance(business, dict):
            continue
        business_info = {"business_id": business.get("id", ""), "business_name": business.get("name", "")}
        for edge in ("owned_ad_accounts", "client_ad_accounts"):
            nested = business.get(edge) or {}
            if isinstance(nested, dict):
                for account in nested.get("data") or []:
                    if isinstance(account, dict):
                        found.append({**account, **business_info, "account_source": edge})
    return found


def graph_marketing_accounts():
    direct = graph_get(
        "/me/adaccounts",
        {"fields": "id,account_id,name,currency,timezone_name,timezone_offset_hours_utc,account_status,business{id,name}", "limit": 100},
    )
    if direct.get("ok"):
        accounts = normalize_graph_account_rows((direct.get("data") or {}).get("data") or [])
        if accounts:
            return {"ok": True, "accounts": accounts, "source": "graph_api", "graph_checked": True}
    businesses = graph_get(
        "/me/businesses",
        {
            "fields": "id,name,owned_ad_accounts{id,account_id,name,currency,timezone_name,timezone_offset_hours_utc,account_status},client_ad_accounts{id,account_id,name,currency,timezone_name,timezone_offset_hours_utc,account_status}",
            "limit": 50,
        },
    )
    if businesses.get("ok"):
        accounts = normalize_graph_account_rows(graph_business_account_rows((businesses.get("data") or {}).get("data") or []))
        if accounts:
            return {"ok": True, "accounts": accounts, "source": "graph_businesses", "graph_checked": True}
    errors = []
    if not direct.get("ok"):
        errors.append(graph_error_message(direct))
    if not businesses.get("ok"):
        errors.append(graph_error_message(businesses))
    return {
        "ok": direct.get("ok") or businesses.get("ok"),
        "accounts": [],
        "source": "graph_api",
        "graph_checked": True,
        "graph_empty": direct.get("ok") or businesses.get("ok"),
        "graph_error": " | ".join([item for item in errors if item])[:900],
    }


def social_accounts_friendly_message(graph_result):
    raw = str(graph_result.get("graph_error") or "")
    raw_lower = raw.lower()
    if any(token in raw_lower for token in ["expired", "oauthexception", "code: 190", "validating access token"]):
        return "Tu clave de Meta venció o Meta la rechazó. Pega una clave nueva y vuelve a buscar tus cuentas."
    if any(token in raw_lower for token in ["permission", "permissions", "permis", "ads_read", "ads_management"]):
        return "La clave está guardada, pero Meta no permitió leer cuentas publicitarias. Revisa que la clave tenga permisos de anuncios y que tu usuario tenga acceso a esa cuenta."
    if graph_result.get("graph_empty"):
        return "La clave respondió, pero Meta devolvió 0 cuentas publicitarias. Revisa que estés usando el usuario correcto y que ese usuario tenga acceso a la cuenta de anuncios en Meta Business."
    return "No pude traer cuentas todavía. La clave quedó guardada; revisa permisos de anuncios o intenta crear una clave nueva."


def social_marketing_accounts():
    graph_result = graph_marketing_accounts()
    accounts = graph_result.get("accounts") or []
    accounts = annotate_accounts_with_management(accounts)
    managed = managed_ad_accounts_payload()
    friendly_message = social_accounts_friendly_message(graph_result) if not accounts else ""
    graph_error_lower = str(graph_result.get("graph_error") or "").lower()
    graph_expired = "expired" in graph_error_lower or "oauthexception" in graph_error_lower or "code: 190" in graph_error_lower or "validating access token" in graph_error_lower
    return {
        "ok": bool(accounts) or bool(graph_result.get("ok")),
        "code": 0 if (accounts or graph_result.get("ok")) else 1,
        "command": "Meta Graph ad accounts",
        "output": str(graph_result.get("graph_error") or "")[-5000:],
        "accounts": accounts,
        "managed_ad_accounts": managed,
        "business_manager": managed.get("business_manager", {}),
        "max_managed_accounts": MAX_MANAGED_META_AD_ACCOUNTS,
        "source": "graph_api",
        "graph_checked": bool(graph_result.get("graph_checked")),
        "needs_login": not accounts and graph_expired,
        "token_expired": graph_expired,
        "friendly_reason": "token_expired" if graph_expired else ("empty_accounts" if not accounts else ""),
        "message": friendly_message,
    }


def discover_account_metadata(account_id):
    account_id = clean_ad_account_id(account_id)
    if not account_id:
        return {}
    try:
        graph_accounts = graph_marketing_accounts().get("accounts") or []
    except Exception:
        graph_accounts = []
    return next((account for account in graph_accounts if account.get("id") == account_id), {"id": account_id})


def social_set_default_account(payload):
    account_id = str(payload.get("ad_account_id") or "").strip()
    if not account_id:
        raise ValueError("Missing ad account")
    account_id = clean_ad_account_id(account_id)
    account = {
        **discover_account_metadata(account_id),
        **{key: value for key, value in {
            "id": account_id,
            "name": payload.get("name"),
            "currency": payload.get("currency"),
            "status": payload.get("status"),
            "business_id": payload.get("business_id") or payload.get("business_manager_id"),
            "business_name": payload.get("business_name") or payload.get("business_manager_name"),
        }.items() if value}
    }
    timezone_sync = synchronize_selected_ad_account_timezone(account, reconcile_crons=False)
    account = timezone_sync.get("account") if isinstance(timezone_sync.get("account"), dict) else account
    business = business_manager_info_from(account)
    replace_payload = {
        "ad_account_id": account_id,
        "business_manager_id": business["id"],
        "business_manager_name": business["name"],
        "account_name": account.get("name", ""),
        "account_currency": account.get("currency", ""),
        "account_timezone": account.get("timezone_name", ""),
        "account_timezone_offset": account.get("timezone_offset_hours_utc"),
        "account_status": account.get("status", ""),
        "confirm_replace_business": payload.get("confirm_replace_business"),
    }
    replaced = enforce_individual_business_change(replace_payload)
    saved = save_setup_config({
        **replace_payload,
        "_skip_business_enforcement": True,
        # social_set_default_account already performed the explicit
        # replacement check above. Tell setup persistence to replace the
        # managed-account registry too, rather than seeding the old account
        # back from the still-loaded config during this same request.
        "_replace_business_state": bool(payload.get("confirm_replace_business")) or replaced,
    })
    saved["business_replaced"] = replaced
    saved["managed_ad_accounts"] = managed_ad_accounts_payload()
    if timezone_sync.get("changed"):
        saved["timezone_crons"] = reconcile_timezone_crons(load_config())
    return {
        "ok": True,
        "code": 0,
        "command": "Meta Graph local account selection",
        "output": "",
        "local_saved": True,
        "graph_account_selected": True,
        "saved": saved,
        "ad_account_id": account_id,
        "managed_ad_accounts": saved["managed_ad_accounts"],
    }


def set_dashboard_password(payload):
    password = str(payload.get("password") or "").strip()
    confirm = str(payload.get("confirm_password") or "").strip()
    if len(password) < 8:
        raise ValueError("Dashboard password must have at least 8 characters")
    if confirm and confirm != password:
        raise ValueError("Dashboard password confirmation does not match")
    password_hash = hash_dashboard_password(password)
    update_env_values({"DASHBOARD_PASSWORD_HASH": password_hash, "DASHBOARD_PASSWORD": "", "DASHBOARD_TOKEN": ""})
    save_dashboard_identity_backup(password_hash)
    session = create_dashboard_session(remember=bool(payload.get("remember_device", True)))
    log_action("dashboard_password_set", {"status": "configured"}, "completed")
    return {"configured": True, **session}


def normalize_agent_chat_provider(value):
    raw = str(value or "").strip().lower().replace("-", "_").replace(" ", "_")
    aliases = {
        "hermes": "openai_codex",
        "chatgpt": "openai_codex",
        "chatgpt_subscription": "openai_codex",
        "codex": "openai_codex",
        "openai_codex": "openai_codex",
        "openai": "openai_api",
        "openai_api": "openai_api",
        "openai_compatible": "custom_api",
        "openai_compat": "custom_api",
        "compatible": "custom_api",
        "custom": "custom_api",
        "custom_api": "custom_api",
        "minimax": "minimax",
        "minimax_m3": "minimax",
        "nvidia": "nvidia_nim",
        "nvidia_api": "nvidia_nim",
        "nvidia_nim": "nvidia_nim",
    }
    return aliases.get(raw, "")


def validate_agent_chat_base_url(value):
    url = str(value or "").strip().rstrip("/")
    if not url:
        return ""
    parsed = urllib.parse.urlparse(url)
    if parsed.scheme == "https" and parsed.netloc:
        return url
    if parsed.scheme == "http" and is_local_host(parsed.hostname or ""):
        return url
    raise ValueError("La URL del modelo debe usar https://, excepto modelos locales en http://127.0.0.1 o http://localhost.")


def running_inside_container():
    return Path("/.dockerenv").exists() or bool(os.environ.get("container") or os.environ.get("KUBERNETES_SERVICE_HOST"))


def hermes_shell_command(config):
    cli = str(getattr(config, "hermes_cli", "") or "hermes").strip() or "hermes"
    home = str(getattr(config, "hermes_home", "") or "").strip()
    prefix = f"HERMES_HOME={shlex.quote(home)} " if home else ""
    return f"{prefix}{shlex.quote(cli)} model"


def hermes_explicit_codex_auth_supported(config):
    cli = shutil.which(str(getattr(config, "hermes_cli", "") or "hermes").strip() or "hermes")
    if not cli:
        return False
    cached = _HERMES_AUTH_CAPABILITY_CACHE.get(cli)
    if cached is not None:
        return bool(cached)
    try:
        result = subprocess.run(
            [cli, "auth", "add", "--help"],
            cwd=str(ROOT_DIR),
            env=hermes_environment(config),
            text=True,
            capture_output=True,
            timeout=6,
            check=False,
        )
        output = "\n".join([result.stdout or "", result.stderr or ""]).lower()
        supported = result.returncode == 0 and "openai-codex" in output and "--no-browser" in output
    except (OSError, subprocess.TimeoutExpired):
        supported = False
    _HERMES_AUTH_CAPABILITY_CACHE[cli] = supported
    return supported


def hermes_browserless_command(config):
    # Use Codex' native device flow as the single source of truth. It writes a
    # complete CLI credential (including id_token) under this buyer's isolated
    # CODEX_HOME; after login we import that session into Hermes. Starting with
    # Hermes auth here created two independent stores and allowed the dashboard
    # to show a newly connected account while Image/Codex CLI kept the old one.
    codex_cli = shutil.which(str(getattr(config, "codex_cli", "") or "codex").strip() or "codex")
    if codex_cli:
        return [codex_cli, "login", "--device-auth"]
    cli = str(getattr(config, "hermes_cli", "") or "hermes").strip() or "hermes"
    if hermes_explicit_codex_auth_supported(config):
        return [cli, "auth", "add", "openai-codex", "--no-browser", "--timeout", "300"]
    return [cli, "model", "--no-browser"]


def hermes_browserless_shell_command(config):
    return " ".join(shlex.quote(part) for part in hermes_browserless_command(config))


def browserless_chatgpt_ready(config):
    """Treat a stored Codex subscription as connected even with Gemini primary.

    ``hermes_codex_ready`` intentionally requires Codex to be the active text
    provider.  This browserless flow connects the shared subscription used by
    Image 2 and the Terra fallback, so a positive Codex authentication signal
    is sufficient while Google AI Studio remains the primary brain.
    """
    status = hermes_codex_session_status(
        config,
        timeout=runtime_codex_status_timeout(config),
    )
    authenticated = bool(status.get("authenticated")) and not bool(status.get("reauth_required"))
    return authenticated, str(status.get("detail") or "OpenAI Codex auth unknown")


def hermes_browserless_launch_command(config):
    """Resolve the executable selected by ``hermes_browserless_command``.

    The native Codex device flow deliberately uses the Codex CLI, while the
    compatibility paths use Hermes.  Resolve that selected binary instead of
    replacing it with ``hermes`` immediately before launch.
    """
    command = list(hermes_browserless_command(config))
    if not command:
        return []
    selected = str(command[0] or "").strip()
    candidate = Path(selected).expanduser()
    executable = selected if candidate.is_absolute() else shutil.which(selected)
    if not executable:
        if candidate.is_file() and os.access(candidate, os.X_OK):
            executable = str(candidate)
    if not executable:
        return []
    command[0] = executable
    return command


def _clean_codex_model_ids(values):
    cleaned = []
    for value in values or []:
        model = str(value or "").strip()
        if not re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9._:/-]{1,100}", model):
            continue
        if model not in cleaned:
            cleaned.append(model)
        if len(cleaned) >= 40:
            break
    return cleaned


def _hermes_python_candidates(config):
    """Find Python runtimes that can import the installed Hermes package.

    Docker installs normally share ``sys.executable`` with Hermes. Native
    installs may keep Hermes in its own managed venv, so using only the
    dashboard Python silently falls back to an old product catalog.
    """
    candidates = [Path(sys.executable)]
    environment = hermes_environment(config)
    hermes_home = Path(str(environment.get("HERMES_HOME") or Path.home() / ".hermes")).expanduser()
    for home in (hermes_home, Path.home() / ".hermes"):
        candidates.extend([
            home / "hermes-agent" / "venv" / "bin" / "python",
            home / "hermes-agent" / ".venv" / "bin" / "python",
        ])
    cli = str(getattr(config, "hermes_cli", "") or "hermes").strip() or "hermes"
    cli_path = shutil.which(cli, path=environment.get("PATH"))
    if cli_path:
        resolved = Path(cli_path).expanduser().resolve()
        candidates.extend([resolved.parent / "python", resolved.parent / "python3"])
    result = []
    for candidate in candidates:
        value = str(candidate)
        if value not in result and candidate.exists() and os.access(candidate, os.X_OK):
            result.append(value)
    return result or [sys.executable]


def codex_model_catalog(config=None, force_refresh=False):
    """Return the installed Hermes account-aware Codex catalog with a stale-safe cache."""
    config = config or load_config()
    cached = read_json(CODEX_MODEL_CATALOG_FILE, {})
    cached_models = _clean_codex_model_ids(cached.get("models") if isinstance(cached, dict) else [])
    cached_at = float((cached or {}).get("checked_epoch") or 0) if isinstance(cached, dict) else 0
    if cached_models and not force_refresh and time.time() - cached_at < CODEX_MODEL_CATALOG_TTL_SECONDS:
        return {**cached, "models": cached_models, "recommended": preferred_hermes_model(cached_models), "stale": False}

    code = (
        "import json\n"
        "result={'models': [], 'account_verified': False, 'auth_resolved': False}\n"
        "try:\n"
        " from hermes_cli.auth import resolve_codex_runtime_credentials\n"
        " from hermes_cli.models import provider_model_ids\n"
        " token=''\n"
        " try:\n"
        "  creds=resolve_codex_runtime_credentials(refresh_if_expiring=True) or {}\n"
        "  token=str(creds.get('api_key') or '')\n"
        "  result['auth_resolved']=bool(token)\n"
        " except Exception: token=''\n"
        " if token:\n"
        "  try:\n"
        "   from hermes_cli.codex_models import _fetch_models_from_api\n"
        "   live=_fetch_models_from_api(token) or []\n"
        "   if live:\n"
        "    result['models']=live\n"
        "    result['account_verified']=True\n"
        "  except Exception: pass\n"
        " if not result['models']:\n"
        "  try: result['models']=provider_model_ids('openai-codex', force_refresh=" + ("True" if force_refresh else "False") + ")\n"
        "  except TypeError: result['models']=provider_model_ids('openai-codex')\n"
        "except Exception: pass\n"
        "print(json.dumps(result))\n"
    )
    discovered = []
    account_verified = False
    auth_resolved = False
    for python_cli in _hermes_python_candidates(config):
        try:
            result = subprocess.run(
                [python_cli, "-c", code],
                cwd=str(ROOT_DIR),
                env=hermes_environment(config),
                text=True,
                capture_output=True,
                timeout=18,
                check=False,
            )
            output_lines = [line.strip() for line in (result.stdout or "").splitlines() if line.strip()]
            parsed = json.loads(output_lines[-1]) if result.returncode == 0 and output_lines else {}
            # Older probes returned a bare list; keep that compatible.
            if isinstance(parsed, list):
                discovered = _clean_codex_model_ids(parsed)
                account_verified = bool(discovered)
            elif isinstance(parsed, dict):
                discovered = _clean_codex_model_ids(parsed.get("models"))
                account_verified = bool(parsed.get("account_verified") and discovered)
                auth_resolved = bool(parsed.get("auth_resolved"))
            if discovered:
                break
        except (OSError, ValueError, json.JSONDecodeError, subprocess.TimeoutExpired):
            continue

    models = discovered or cached_models
    source = (
        "account_codex_catalog"
        if account_verified
        else "hermes_runtime_catalog"
        if discovered
        else "last_known_catalog"
        if cached_models
        else "safe_fallback"
    )
    if not models:
        current = str(getattr(config, "hermes_model", "") or "").strip()
        models = _clean_codex_model_ids([current, "gpt-5.6-luna", "gpt-5.6-terra", "gpt-5.6-mini", "gpt-5.4-mini", "gpt-5.6-sol", "gpt-5.5", "gpt-5.4"])
    payload = {
        "models": models,
        "recommended": preferred_hermes_model(models),
        "source": source,
        "account_verified": account_verified,
        "auth_resolved": auth_resolved,
        "checked_at": now_iso(),
        "checked_epoch": time.time(),
        "stale": not bool(discovered),
    }
    if discovered:
        write_private_json(CODEX_MODEL_CATALOG_FILE, payload)
    return payload


def resolve_codex_model_choice(value, config=None):
    config = config or load_config()
    raw = str(value or "").strip()
    catalog = codex_model_catalog(config=config)
    models = catalog.get("models") or []
    if raw and raw.lower() not in {"auto", "recommended", "recomendado", "default"} and raw in models:
        return raw
    # Luna is the explicit ChatGPT-subscription default. If the account
    # catalog has not answered yet, keep that requested default instead of
    # allowing a stale, previously selected model to win. A verified catalog
    # still remains authoritative and can safely fall back when Luna is not
    # available on that account or plan.
    if raw.lower() == "gpt-5.6-luna" and not catalog.get("account_verified"):
        return raw
    current = str(getattr(config, "hermes_model", "") or "").strip()
    user_selected = bool(getattr(config, "hermes_model_user_selected", False))
    if user_selected and current in models:
        return current
    # A curated/runtime catalog is useful for display but is not entitlement
    # proof. Until the connected account API has answered, keep the stable
    # product default instead of silently switching a buyer to an older
    # catalog entry. Once the account is verified, its recommended model is
    # authoritative (and may legitimately be an older model on that plan).
    if catalog.get("account_verified"):
        return str(preferred_hermes_model(models) or normalize_hermes_model(raw)).strip()
    return str(normalize_hermes_model(raw or current)).strip()


def runtime_dependency_versions(config=None):
    config = config or load_config()
    now = time.time()
    if now - float(_RUNTIME_VERSION_CACHE.get("checked_at") or 0) < 10 * 60:
        return dict(_RUNTIME_VERSION_CACHE.get("value") or {})

    def first_line(command):
        try:
            result = subprocess.run(command, cwd=str(ROOT_DIR), env=hermes_environment(config), text=True, capture_output=True, timeout=5, check=False)
        except (OSError, subprocess.TimeoutExpired):
            return ""
        return clean_terminal_text("\n".join([result.stdout or "", result.stderr or ""])).splitlines()[0] if (result.stdout or result.stderr) else ""

    value = {
        "hermes": first_line([str(getattr(config, "hermes_cli", "") or "hermes"), "--version"]),
        "codex": first_line([str(getattr(config, "codex_cli", "") or "codex"), "--version"]),
        "explicit_codex_auth": hermes_explicit_codex_auth_supported(config),
    }
    _RUNTIME_VERSION_CACHE.update({"checked_at": now, "value": value})
    return dict(value)


def cached_codex_model_catalog(config=None):
    """Return the last model catalog without starting Hermes or Codex."""
    config = config or load_config()
    cached = read_json(CODEX_MODEL_CATALOG_FILE, {})
    models = _clean_codex_model_ids(cached.get("models") if isinstance(cached, dict) else [])
    if not models:
        current = str(getattr(config, "hermes_model", "") or "").strip()
        models = _clean_codex_model_ids([current, "gpt-5.6-luna", "gpt-5.6-terra", "gpt-5.6-mini", "gpt-5.4-mini", "gpt-5.6-sol", "gpt-5.5", "gpt-5.4"])
    return {
        **(cached if isinstance(cached, dict) else {}),
        "models": models,
        "recommended": preferred_hermes_model(models),
        "source": str((cached or {}).get("source") or "safe_fallback"),
        "checked_at": str((cached or {}).get("checked_at") or ""),
        "stale": True,
    }


NVIDIA_NIM_BASE_URL = "https://integrate.api.nvidia.com/v1"
NVIDIA_NIM_DEFAULT_MODEL = DEFAULT_NVIDIA_NIM_MODEL
NVIDIA_NIM_MODEL_PREFERENCE = (
    "minimaxai/minimax-m3",
    "openai/gpt-oss-20b",
    "nvidia/nemotron-3-nano-30b-a3b",
    "deepseek-ai/deepseek-v4-flash-0731",
    "deepseek-ai/deepseek-v4-flash",
    "z-ai/glm-5.2",
    "minimaxai/minimax-m2.7",
)
NVIDIA_NIM_SAFE_FALLBACK_MODELS = (
    "minimaxai/minimax-m3",
    "openai/gpt-oss-20b",
    "nvidia/nemotron-3-nano-30b-a3b",
    "deepseek-ai/deepseek-v4-flash-0731",
    "z-ai/glm-5.2",
)
NVIDIA_NIM_NON_CHAT_MARKERS = (
    "embed", "rerank", "retriev", "diffusion", "grounding", "segmentation",
    "detection", "nemoguard", "safety", "gliner", "parse", "ocr", "deplot",
    "whisper", "speech", "audio", "tts", "translate", "molmim", "protein",
    "sparsedrive", "streampetr", "nvclip", "/bge-",
)


def _clean_nvidia_model_ids(values):
    cleaned = []
    for value in values or []:
        model = str(value or "").strip()
        lowered = model.lower()
        if not re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9._:/-]{1,160}", model):
            continue
        if any(marker in lowered for marker in NVIDIA_NIM_NON_CHAT_MARKERS):
            continue
        if model not in cleaned:
            cleaned.append(model)
        if len(cleaned) >= 160:
            break
    return sorted(cleaned, key=lambda item: item.lower())


def preferred_nvidia_model(models):
    cleaned = _clean_nvidia_model_ids(models)
    by_key = {item.lower(): item for item in cleaned}
    for preferred in NVIDIA_NIM_MODEL_PREFERENCE:
        if preferred in by_key:
            return by_key[preferred]
    return cleaned[0] if cleaned else NVIDIA_NIM_DEFAULT_MODEL


def cached_nvidia_model_catalog():
    cached = read_json(NVIDIA_MODEL_CATALOG_FILE, {})
    models = _clean_nvidia_model_ids((cached or {}).get("models") if isinstance(cached, dict) else [])
    if not models:
        models = [NVIDIA_NIM_DEFAULT_MODEL, *NVIDIA_NIM_SAFE_FALLBACK_MODELS]
    return {
        **(cached if isinstance(cached, dict) else {}),
        "models": models,
        "recommended": preferred_nvidia_model(models),
        "source": str((cached or {}).get("source") or "safe_fallback"),
        "checked_at": str((cached or {}).get("checked_at") or ""),
        "account_verified": bool((cached or {}).get("account_verified")),
        "stale": True,
    }


def nvidia_model_catalog(api_key="", config=None, force_refresh=False):
    """Read the buyer's current NVIDIA API Catalog without persisting its key."""
    config = config or load_config()
    cached = cached_nvidia_model_catalog()
    key = str(api_key or "").strip()
    brain = str(getattr(config, "agent_brain_provider", "") or "").strip().lower().replace("-", "_")
    base_url = str(getattr(config, "agent_chat_base_url", "") or "").strip().lower()
    if not key and (brain == "nvidia_nim" or "api.nvidia.com" in base_url):
        key = str(getattr(config, "agent_chat_api_key", "") or "").strip()
    if not key:
        return cached
    if not force_refresh and cached.get("account_verified"):
        checked_epoch = float(cached.get("checked_epoch") or 0)
        if time.time() - checked_epoch < CODEX_MODEL_CATALOG_TTL_SECONDS:
            return {**cached, "stale": False}
    request = urllib.request.Request(
        f"{NVIDIA_NIM_BASE_URL}/models",
        headers={"Authorization": f"Bearer {key}", "Accept": "application/json"},
        method="GET",
    )
    try:
        with urllib.request.urlopen(request, timeout=30) as response:
            data = json.loads(response.read().decode("utf-8"))
    except urllib.error.HTTPError as exc:
        if exc.code in {401, 403}:
            raise ValueError("La clave de NVIDIA no fue aceptada. Crea o copia una API key desde build.nvidia.com.") from None
        if exc.code == 429:
            raise ValueError("NVIDIA alcanzó temporalmente su cuota. Conservé la última lista válida; intenta actualizar más tarde.") from None
        raise ValueError(f"NVIDIA no pudo entregar el catálogo ahora (HTTP {exc.code}).") from None
    except (OSError, TimeoutError, json.JSONDecodeError):
        raise ValueError("No pude consultar NVIDIA ahora. Conservé la última lista válida.") from None
    entries = data.get("data") if isinstance(data, dict) else []
    models = _clean_nvidia_model_ids(item.get("id") for item in (entries or []) if isinstance(item, dict))
    if not models:
        raise ValueError("NVIDIA respondió, pero no devolvió modelos de conversación utilizables.")
    payload = {
        "models": models,
        "recommended": preferred_nvidia_model(models),
        "source": "nvidia_live_catalog",
        "account_verified": True,
        "checked_at": now_iso(),
        "checked_epoch": time.time(),
        "stale": False,
    }
    write_private_json(NVIDIA_MODEL_CATALOG_FILE, payload)
    return payload


def refresh_nvidia_model_catalog(payload=None):
    payload = payload or {}
    config = load_config()
    saved_nvidia = agent_model_connections(config, include_secrets=True).get("nvidia_nim", {})
    catalog = nvidia_model_catalog(
        api_key=payload.get("agent_chat_api_key") or saved_nvidia.get("api_key"),
        config=config,
        force_refresh=True,
    )
    if not catalog.get("account_verified"):
        raise ValueError("Pega primero tu API key de NVIDIA para cargar los modelos disponibles.")
    return catalog


def empty_codex_session_status():
    return {
        "authenticated": False,
        "ready": False,
        "reauth_required": False,
        "auth_state": "checking",
        "identity": {},
        "detail": "",
    }


def runtime_codex_status_timeout(config):
    """Use a VPS-safe timeout for the asynchronous Hermes status probe.

    ``hermes status`` commonly needs more than three seconds while the small
    DigitalOcean container is also checking the model catalog and image
    bridge. The connect endpoint already waits for the configured Hermes
    timeout, so the dashboard must not contradict that successful check with
    a shorter probe.
    """
    try:
        configured = int(getattr(config, "hermes_status_timeout_seconds", 20) or 20)
    except (TypeError, ValueError):
        configured = 20
    return max(8, min(30, configured))


def cache_codex_session_status(config, purpose="agent", authenticated=False, detail=""):
    """Immediately mirror a verified connect/disconnect result into the UI cache.

    The dashboard payload is intentionally cache-only so it can paint fast.
    Without this write, a successful login can still render as disconnected
    until a later slow runtime probe finishes. This cache never manufactures a
    login: callers invoke it only after Hermes verified the session or after
    the product removed the auth artifacts and restarted the gateway.
    """
    purpose = normalize_connect_purpose(purpose)
    cached = read_json(AGENT_RUNTIME_STATUS_FILE, {})
    if not isinstance(cached, dict):
        cached = {}
    authenticated = bool(authenticated)
    status_detail = str(detail or ("OpenAI Codex session connected" if authenticated else "OpenAI Codex disconnected"))
    session = {
        "ready": authenticated,
        "authenticated": authenticated,
        "provider_ready": authenticated,
        "reauth_required": False,
        "auth_state": "stored" if authenticated else "disconnected",
        "detail": status_detail,
        "identity": extract_codex_account_identity(status_detail) if authenticated else {},
        "returncode": 0 if authenticated else None,
    }
    if purpose == "image":
        cached["image_codex_session"] = session
    else:
        cached["main_codex_session"] = session
        if effective_codex_image_source(config) != "dedicated_chatgpt":
            cached["image_codex_session"] = session
    cached.update({"checked_at": now_iso(), "checked_epoch": time.time(), "stale": False})
    write_private_json(AGENT_RUNTIME_STATUS_FILE, redact_payload(cached))
    return session


def cached_agent_runtime_status(config=None):
    """Read the last safe runtime diagnosis; never launch a subprocess here."""
    config = config or load_config()
    cached = read_json(AGENT_RUNTIME_STATUS_FILE, {})
    if not isinstance(cached, dict):
        cached = {}
    checked_epoch = float(cached.get("checked_epoch") or 0)
    return {
        **cached,
        "main_codex_session": cached.get("main_codex_session") or empty_codex_session_status(),
        "image_codex_session": cached.get("image_codex_session") or cached.get("main_codex_session") or empty_codex_session_status(),
        "codex_image_status": cached.get("codex_image_status") or {"ok": False, "error": "", "detail": ""},
        "model_catalog": cached.get("model_catalog") or cached_codex_model_catalog(config),
        "runtime_versions": cached.get("runtime_versions") or dict(_RUNTIME_VERSION_CACHE.get("value") or {}),
        "checked_epoch": checked_epoch,
        "stale": not checked_epoch or time.time() - checked_epoch >= AGENT_RUNTIME_STATUS_TTL_SECONDS,
    }


def invalidate_agent_runtime_status_cache():
    try:
        AGENT_RUNTIME_STATUS_FILE.unlink(missing_ok=True)
    except OSError:
        pass


def refresh_agent_runtime_status(payload=None):
    """Refresh slow Hermes/Codex probes outside the initial dashboard request."""
    payload = payload or {}
    config = load_config()
    cached = cached_agent_runtime_status(config)
    if not bool(payload.get("force")) and not cached.get("stale"):
        return cached
    if not AGENT_RUNTIME_STATUS_LOCK.acquire(blocking=False):
        return cached
    try:
        codex_image_source = effective_codex_image_source(config)
        status_timeout = runtime_codex_status_timeout(config)
        with ThreadPoolExecutor(max_workers=5, thread_name_prefix="admira-runtime") as executor:
            main_future = executor.submit(hermes_codex_session_status, config, status_timeout)
            image_future = (
                executor.submit(hermes_codex_session_status, image_codex_config(config), status_timeout)
                if codex_image_source == "dedicated_chatgpt"
                else None
            )
            image_status_future = executor.submit(
                hermes_codex_image_status,
                timeout=max(8, min(15, status_timeout)),
                config=config,
            )
            catalog_future = executor.submit(codex_model_catalog, config=config)
            versions_future = executor.submit(runtime_dependency_versions, config=config)
            main_session = main_future.result()
            image_status = image_status_future.result()
            image_session = image_future.result() if image_future else main_session
            if image_status.get("ok"):
                # The text brain can be Gemini while the shared ChatGPT
                # subscription independently powers openai-codex Image. Do
                # not copy Gemini's Codex-session status into the Image card.
                image_session = {
                    "ready": True,
                    "authenticated": True,
                    "provider_ready": True,
                    "reauth_required": False,
                    "auth_state": "stored",
                    "detail": image_status.get("detail") or "ChatGPT/Codex listo para imágenes",
                    "identity": (image_session or {}).get("identity") or {},
                    "returncode": 0,
                }
            result = {
                "main_codex_session": main_session,
                "image_codex_session": image_session,
                "codex_image_status": image_status,
                "model_catalog": catalog_future.result(),
                "runtime_versions": versions_future.result(),
                "checked_at": now_iso(),
                "checked_epoch": time.time(),
                "stale": False,
            }
        safe_result = redact_payload(result)
        write_private_json(AGENT_RUNTIME_STATUS_FILE, safe_result)
        return safe_result
    finally:
        AGENT_RUNTIME_STATUS_LOCK.release()


def clean_terminal_text(value):
    text = str(value or "")
    text = re.sub(r"\x1b\][^\a]*(?:\a|\x1b\\)", "", text)
    text = re.sub(r"\x1b\[[0-?]*[ -/]*[@-~]", "", text)
    text = text.replace("\r\n", "\n").replace("\r", "\n")
    text = re.sub(r"\n{4,}", "\n\n\n", text)
    return text.strip()


def extract_urls_from_text(value):
    urls = []
    for match in re.findall(r"https?://[^\s<>'\")]+", str(value or "")):
        url = match.rstrip(".,;:")
        if url not in urls:
            urls.append(url)
        if len(urls) >= 4:
            break
    return urls


def extract_login_codes_from_text(value):
    cleaned = clean_terminal_text(value)
    if not cleaned:
        return []
    codes = []
    lines = cleaned.splitlines()
    hint_re = re.compile(r"\b(code|codigo|código|verification|verify|device|one-time|otp)\b", re.I)
    token_re = re.compile(r"\b[A-Z0-9]{4}(?:[- ][A-Z0-9]{2,8}){1,5}\b|\b[A-Z0-9]{6,24}\b")
    label_re = re.compile(
        r"(?:verification|device|one[- ]time|login|openai|codex|auth)?\s*(?:code|codigo|código)\s*[:=\-]?\s*([A-Z0-9][A-Z0-9\- ]{4,40}[A-Z0-9])\s*$",
        re.I,
    )
    blocked_parts = {
        "OPENAI",
        "HERMES",
        "CODEX",
        "MODEL",
        "DEVICE",
        "CODE",
        "CODIGO",
        "VERIFICATION",
        "VERIFY",
        "TERMINAL",
        "DISPLAYED",
        "BROWSER",
        "OPEN",
        "THIS",
        "URL",
        "CONTINUE",
        "AUTH",
        "ASK",
        "FOR",
        "LOGIN",
        "PROVIDER",
        "DEFAULT",
    }

    def add_code(raw, contextual=False):
        normalized = re.sub(r"[^A-Z0-9]+", "-", str(raw or "").upper()).strip("-")
        if not normalized:
            return
        parts = [part for part in normalized.split("-") if part]
        compact = "".join(parts)
        if not 6 <= len(compact) <= 24:
            return
        if compact in blocked_parts or any(part in blocked_parts for part in parts):
            return
        looks_like_code = contextual or "-" in normalized or any(char.isdigit() for char in compact)
        if looks_like_code and normalized not in codes:
            codes.append(normalized)

    def standalone_code_line(line):
        candidate = re.sub(r"https?://[^\s<>'\")]+", " ", str(line or ""))
        candidate = candidate.strip().strip("`'\"|>.,;:()[]{}")
        if not re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9\- ]{4,40}[A-Za-z0-9]", candidate):
            return ""
        compact = re.sub(r"[^A-Za-z0-9]+", "", candidate)
        if not 6 <= len(compact) <= 24:
            return ""
        tokens = [token for token in re.split(r"[-\s]+", candidate.strip()) if token]
        has_separator = len(tokens) > 1
        if has_separator and any(len(token) > 8 for token in tokens):
            return ""
        has_digit = any(char.isdigit() for char in compact)
        has_upper_signal = any(char.isupper() for char in candidate) and candidate.upper() == candidate
        if not (has_digit or has_upper_signal or has_separator):
            return ""
        return candidate

    explicit_code_prompt_re = re.compile(
        r"\b(?:enter|copy|use|paste|ingresa|copia|usa|pega)\b.{0,40}\b(?:code|codigo|código)\b|\b(?:verification|device|login|auth|openai|codex)\s+(?:code|codigo|código)\b",
        re.I,
    )

    def prioritized_codes():
        found = []

        def remember(raw):
            before = len(codes)
            add_code(raw, contextual=True)
            if len(codes) > before:
                found.append(codes.pop())

        for index in range(len(lines) - 1, -1, -1):
            line_without_urls = re.sub(r"https?://[^\s<>'\")]+", " ", lines[index])
            if not explicit_code_prompt_re.search(line_without_urls):
                continue
            match = label_re.search(line_without_urls)
            if match:
                remember(match.group(1))
            tail = line_without_urls.split(":", 1)[1] if ":" in line_without_urls else ""
            tail_candidate = standalone_code_line(tail)
            if tail_candidate:
                remember(tail_candidate)
            for candidate_line in lines[index + 1 : min(len(lines), index + 7)]:
                candidate = standalone_code_line(candidate_line)
                if candidate:
                    remember(candidate)
                    break
            if len(found) >= 2:
                break
        unique = []
        for code in found:
            if code not in unique:
                unique.append(code)
        return unique[:2]

    high_confidence = prioritized_codes()
    if high_confidence:
        return high_confidence

    for line in lines:
        line_without_urls = re.sub(r"https?://[^\s<>'\")]+", " ", line)
        match = label_re.search(line_without_urls)
        if match:
            add_code(match.group(1), contextual=True)
        if len(codes) >= 2:
            return codes[:2]
    for index, line in enumerate(lines):
        line_without_urls = re.sub(r"https?://[^\s<>'\")]+", " ", line)
        if not hint_re.search(line_without_urls):
            continue
        for candidate_line in lines[index + 1 : min(len(lines), index + 10)]:
            candidate = standalone_code_line(candidate_line)
            if candidate:
                add_code(candidate, contextual=True)
                break
        segment_lines = lines[max(0, index - 1) : min(len(lines), index + 8)]
        segment_for_menu_check = "\n".join(segment_lines).lower()
        if "select provider" in segment_for_menu_check or "(○)" in segment_for_menu_check or "(●)" in segment_for_menu_check:
            continue
        segment = " ".join(segment_lines)
        segment = re.sub(r"https?://[^\s<>'\")]+", " ", segment)
        for match in token_re.findall(segment.upper()):
            add_code(match)
        if len(codes) >= 2:
            break
    return codes[:2]


def hermes_provider_prompt_visible(output):
    lower = clean_terminal_text(output).lower()
    provider_prompt = "select provider" in lower or "select openai provider" in lower
    return provider_prompt and (
        "select by number" in lower
        or "enter to confirm" in lower
        or "enter/space select" in lower
        or "navigate" in lower
        or "choice [default" in lower
        or "choice:" in lower
    )


def hermes_model_prompt_visible(output):
    lower = clean_terminal_text(output).lower()
    return (
        ("select model" in lower or "choose model" in lower or "default model" in lower)
        and ("select by number" in lower or "enter to confirm" in lower or "default" in lower)
    )


def hermes_openai_subprovider_prompt_visible(output):
    lower = clean_terminal_text(output).lower()
    return hermes_provider_prompt_visible(output) and "openai codex" in lower and "openai api" in lower


def hermes_choice_number_for_label(output, labels):
    wanted = [str(label or "").lower() for label in labels if str(label or "").strip()]
    for line in clean_terminal_text(output).splitlines():
        lower = line.lower()
        if not any(label in lower for label in wanted):
            continue
        match = re.match(r"^\s*(?:[\[\(]?(\d{1,2})[\]\).:-]?|\b(\d{1,2})\b)\s+", line)
        if match:
            return next((part for part in match.groups() if part), "")
        before_label = lower.split(next((label for label in wanted if label in lower), ""), 1)[0]
        reverse_match = re.search(r"(\d{1,2})\D*$", before_label)
        if reverse_match:
            return reverse_match.group(1)
    return ""


def hermes_arrow_menu_payload_for_label(output, labels):
    cleaned = clean_terminal_text(output)
    lower = cleaned.lower()
    provider_prompt = "select provider" in lower or "select openai provider" in lower
    if not provider_prompt or not ("navigate" in lower or "enter/space select" in lower):
        return ""
    wanted = [str(label or "").lower() for label in labels if str(label or "").strip()]
    if not wanted:
        return ""
    menu_lines = []
    for line in cleaned.splitlines():
        menu_text = line.strip()
        menu_lower = menu_text.lower()
        if not menu_text:
            continue
        if "(●)" in menu_text or "(○)" in menu_text or menu_text.startswith("→"):
            menu_lines.append((menu_text, menu_lower))
    if not menu_lines:
        return ""
    current_index = next((index for index, (line, _lower) in enumerate(menu_lines) if "→" in line), 0)
    target_index = next(
        (
            index
            for index, (_line, menu_lower) in enumerate(menu_lines)
            if any(label in menu_lower for label in wanted)
        ),
        -1,
    )
    if target_index < 0:
        return ""
    delta = target_index - current_index
    if delta > 0:
        return ("\x1b[B" * delta) + "\n"
    if delta < 0:
        return ("\x1b[A" * abs(delta)) + "\n"
    return "\n"


def hermes_model_choice(output, preferred_model=""):
    preferred = str(preferred_model or "").strip()
    if preferred and hermes_model_prompt_visible(output):
        parsed = hermes_choice_number_for_label(output, [preferred])
        if parsed:
            return parsed
    return ""


def hermes_codex_provider_choice(output):
    arrow_payload = hermes_arrow_menu_payload_for_label(output, ["openai ▸", "openai (codex cli", "openai"])
    if arrow_payload:
        return arrow_payload
    parsed = hermes_choice_number_for_label(output, ["openai ▸", "openai (codex cli", "openai"])
    if parsed:
        return f"{parsed}\n"
    parsed = hermes_choice_number_for_label(output, ["openai codex", "chatgpt/codex", "chatgpt codex"])
    if parsed:
        return f"{parsed}\n"
    if hermes_provider_prompt_visible(output):
        explicit_choice = str(os.environ.get("HERMES_CODEX_PROVIDER_CHOICE") or "").strip()
        if explicit_choice:
            return f"{explicit_choice}\n"
    return ""


def codex_device_auth_disabled(output):
    lower = clean_terminal_text(output).lower()
    return (
        "enable device code authorization" in lower
        or ("device code authorization" in lower and "chatgpt security settings" in lower)
        or ("codex login --device-auth" in lower and "security settings" in lower)
    )


def hermes_login_prompt_state(output, state=None):
    state = state or {}
    cleaned = clean_terminal_text(output)
    lower = cleaned.lower()
    urls = extract_urls_from_text(cleaned)
    login_codes = extract_login_codes_from_text(cleaned)
    auto_provider_sent = bool(state.get("auto_provider_sent"))
    auto_codex_subprovider_sent = bool(state.get("auto_codex_subprovider_sent"))
    auto_model_sent = bool(state.get("auto_model_sent"))
    manual_input = any(marker in lower for marker in ["invalid choice", "invalid selection", "try again", "not recognized"])
    if codex_device_auth_disabled(cleaned):
        return {
            "phase": "device_auth_settings",
            "needs_input": False,
            "title": "Activa el login por código",
            "detail": "ChatGPT pide activar el login por código para Codex. Abre ChatGPT, entra a Ajustes > Seguridad y activa Enable device code authorization for Codex. Luego vuelve aquí y toca Conectar ahora.",
            "auto_note": "Es una protección de ChatGPT para permitir login desde servidores o contenedores.",
            "login_code": "",
        }
    if urls and login_codes:
        return {
            "phase": "login_code",
            "needs_input": False,
            "title": "Copia el código de OpenAI",
            "detail": "OpenAI abrió una pantalla segura y te pedirá este código. Cópialo, vuelve a la pestaña de login y pégalo allí.",
            "auto_note": state.get("auto_note") or "",
            "login_code": login_codes[0],
        }
    if urls:
        return {
            "phase": "login_link",
            "needs_input": False,
            "title": "Termina el login",
            "detail": "Abre el enlace de ChatGPT/Codex que aparece aquí. Después vuelve a esta pantalla y revisaré la conexión.",
            "auto_note": state.get("auto_note") or "",
            "login_code": "",
        }
    if hermes_openai_subprovider_prompt_visible(cleaned):
        return {
            "phase": "codex_subprovider_selection",
            "needs_input": manual_input,
            "title": "Confirmando OpenAI Codex",
            "detail": "El agente pidió elegir entre OpenAI Codex y OpenAI API. Estoy confirmando OpenAI Codex automáticamente.",
            "auto_note": "OpenAI Codex confirmado." if auto_codex_subprovider_sent else "Confirmando OpenAI Codex automáticamente.",
            "login_code": "",
        }
    if hermes_provider_prompt_visible(cleaned):
        return {
            "phase": "provider_selection",
            "needs_input": manual_input,
            "title": "Eligiendo OpenAI Codex",
            "detail": "El agente pidió elegir proveedor. Estoy seleccionando OpenAI Codex automáticamente para que no tengas que leer la terminal.",
            "auto_note": "OpenAI Codex se selecciona automáticamente." if not auto_provider_sent else state.get("auto_note") or "OpenAI Codex seleccionado. Continúo con el siguiente paso.",
            "login_code": "",
        }
    if hermes_model_prompt_visible(cleaned):
        preferred_model = normalize_hermes_model(state.get("preferred_model"))
        chosen = bool(preferred_model and hermes_model_choice(cleaned, preferred_model))
        return {
            "phase": "model_selection",
            "needs_input": manual_input,
            "title": "Eligiendo modelo del agente",
            "detail": f"El agente pidió elegir modelo. Estoy usando {preferred_model}." if chosen else "El agente pidió elegir modelo. Estoy aceptando el recomendado para no detener la instalación.",
            "auto_note": f"Modelo {preferred_model} confirmado." if auto_model_sent and chosen else ("Modelo recomendado confirmado." if auto_model_sent else (f"Confirmando {preferred_model} automáticamente." if preferred_model else "Confirmando el modelo recomendado automáticamente.")),
            "login_code": "",
        }
    return {
        "phase": "waiting",
        "needs_input": manual_input,
        "title": "El agente está trabajando",
        "detail": "Estoy preparando la conexión. Si aparece un enlace de ChatGPT/Codex, ábrelo desde este navegador.",
        "auto_note": state.get("auto_note") or "",
        "login_code": login_codes[0] if login_codes else "",
    }


def maybe_auto_drive_hermes_browserless(session_id, master_fd):
    with HERMES_LOGIN_LOCK:
        if HERMES_LOGIN_STATE.get("id") != session_id:
            return False
        output = HERMES_LOGIN_STATE.get("output") or ""
        provider_sent = bool(HERMES_LOGIN_STATE.get("auto_provider_sent"))
        codex_subprovider_sent = bool(HERMES_LOGIN_STATE.get("auto_codex_subprovider_sent"))
        model_sent = bool(HERMES_LOGIN_STATE.get("auto_model_sent"))
        if provider_sent and not codex_subprovider_sent and hermes_openai_subprovider_prompt_visible(output):
            HERMES_LOGIN_STATE["auto_codex_subprovider_sent"] = True
            HERMES_LOGIN_STATE["phase"] = "codex_subprovider_selection"
            HERMES_LOGIN_STATE["auto_note"] = "Estoy confirmando OpenAI Codex automáticamente."
            payload = hermes_arrow_menu_payload_for_label(output, ["openai codex", "chatgpt/codex", "chatgpt codex"]) or "1\n"
        elif not provider_sent:
            provider_payload = hermes_codex_provider_choice(output)
            if provider_payload:
                HERMES_LOGIN_STATE["auto_provider_sent"] = True
                HERMES_LOGIN_STATE["phase"] = "provider_selection"
                HERMES_LOGIN_STATE["auto_note"] = "Estoy eligiendo OpenAI Codex automáticamente."
                payload = provider_payload
            else:
                payload = ""
        elif not model_sent and hermes_model_prompt_visible(output):
            preferred_model = normalize_hermes_model(HERMES_LOGIN_STATE.get("preferred_model"))
            model_choice = hermes_model_choice(output, preferred_model)
            HERMES_LOGIN_STATE["auto_model_sent"] = True
            HERMES_LOGIN_STATE["phase"] = "model_selection"
            HERMES_LOGIN_STATE["auto_note"] = f"Estoy eligiendo {preferred_model} automáticamente." if model_choice else "Estoy confirmando el modelo recomendado automáticamente."
            payload = f"{model_choice}\n" if model_choice else "\n"
        else:
            payload = ""
    if not payload:
        return False
    try:
        os.write(master_fd, payload.encode("utf-8", errors="replace"))
        return True
    except OSError:
        return False


def nudge_hermes_browserless_autodrive():
    with HERMES_LOGIN_LOCK:
        session_id = HERMES_LOGIN_STATE.get("id") or ""
        fd = HERMES_LOGIN_STATE.get("fd")
        proc = HERMES_LOGIN_STATE.get("proc")
        running = bool(session_id and proc and proc.poll() is None and fd is not None)
    if running:
        return maybe_auto_drive_hermes_browserless(session_id, fd)
    return False


def hermes_connect_response(status, title, detail, **extra):
    command = extra.pop("command", "hermes model")
    should_log = extra.pop("log", True)
    output = redact_error_text(clean_terminal_text(extra.pop("output", "")), limit=HERMES_LOGIN_OUTPUT_LIMIT)
    login_codes = extract_login_codes_from_text(output)
    payload = {
        "ok": status in {"terminal_opened", "completed", "needs_login", "needs_terminal", "browser_login_started", "browser_login_waiting", "browser_login_ready"},
        "status": status,
        "title": title,
        "detail": detail,
        "command": command,
        "urls": extract_urls_from_text(output),
        "login_codes": login_codes,
        "login_code": extra.pop("login_code", login_codes[0] if login_codes else ""),
        "output": output,
        **extra,
    }
    if should_log:
        log_status = "completed" if status in {"terminal_opened", "completed"} else "warn"
        log_action("agent_model_connect", {"status": status, "mode": payload.get("mode"), "urls_found": len(payload["urls"])}, log_status)
    return payload


def terminal_launcher_command(config):
    command = hermes_shell_command(config)
    root = shlex.quote(str(ROOT_DIR))
    return (
        f"cd {root}\n"
        "echo 'Conectando ChatGPT/Codex para Admira IA...'\n"
        "echo 'Si el agente pregunta por proveedor, elige OpenAI Codex / ChatGPT.'\n"
        "echo\n"
        f"{command}\n"
        "status=$?\n"
        "echo\n"
        "if [ $status -eq 0 ]; then\n"
        "  echo 'Listo. Vuelve al dashboard y toca Revisar conexion.'\n"
        "else\n"
        "  echo 'La conexión terminó con un aviso. Si ves un enlace o código, complétalo y vuelve al dashboard.'\n"
        "fi\n"
        "echo\n"
    )


def launch_hermes_terminal(config):
    if running_inside_container():
        return False
    command = terminal_launcher_command(config)
    try:
        if sys.platform == "darwin":
            command_dir = DATA_DIR / "runtime_commands"
            command_dir.mkdir(parents=True, exist_ok=True)
            script_path = command_dir / "connect-chatgpt-codex.command"
            script_path.write_text(
                "#!/bin/zsh\n"
                "clear\n"
                f"{command}"
                "echo 'Puedes cerrar esta ventana cuando termines.'\n"
                "read -k 1 '?Presiona cualquier tecla para cerrar...'\n",
                encoding="utf-8",
            )
            script_path.chmod(0o700)
            subprocess.Popen(["open", "-a", "Terminal", str(script_path)], cwd=str(ROOT_DIR))
            return True
        if os.name == "nt":
            ps_root = str(ROOT_DIR).replace("'", "''")
            ps_cli = str(getattr(config, "hermes_cli", "") or "hermes").replace("'", "''")
            ps_home = str(getattr(config, "hermes_home", "") or "").replace("'", "''")
            ps_home_prefix = f"$env:HERMES_HOME='{ps_home}'; " if ps_home else ""
            ps_command = (
                f"Set-Location -LiteralPath '{ps_root}'; "
                f"{ps_home_prefix}"
                "Write-Host 'Conectando ChatGPT/Codex para Admira IA...'; "
                "Write-Host 'Si el agente pregunta por proveedor, elige OpenAI Codex / ChatGPT.'; "
                f"& '{ps_cli}' model"
            )
            # This login really is interactive, so it needs its own console.
            # Do not use `cmd start`, `-NoExit`, or a final Read-Host: those
            # leave an empty PowerShell window covering the buyer's browser
            # after Hermes has already finished or opened the login page.
            creationflags = getattr(subprocess, "CREATE_NEW_CONSOLE", 0)
            subprocess.Popen(
                [
                    "powershell.exe",
                    "-NoProfile",
                    "-ExecutionPolicy",
                    "Bypass",
                    "-Command",
                    ps_command,
                ],
                cwd=str(ROOT_DIR),
                creationflags=creationflags,
            )
            return True
        if os.environ.get("DISPLAY") or os.environ.get("WAYLAND_DISPLAY"):
            shell_command = command + "read -n 1 -s -r -p 'Presiona una tecla para cerrar...'"
            launchers = [
                ("gnome-terminal", ["gnome-terminal", "--", "bash", "-lc", shell_command]),
                ("konsole", ["konsole", "-e", "bash", "-lc", shell_command]),
                ("xfce4-terminal", ["xfce4-terminal", "--command", f"bash -lc {shlex.quote(shell_command)}"]),
                ("xterm", ["xterm", "-e", "bash", "-lc", shell_command]),
            ]
            for binary, args in launchers:
                if shutil.which(binary):
                    subprocess.Popen(args, cwd=str(ROOT_DIR))
                    return True
    except Exception:
        return False
    return False


def normalize_connect_purpose(value):
    return "image" if str(value or "").strip().lower() in {"image", "images", "codex_image", "image_only", "dedicated_chatgpt"} else "agent"


def config_for_connect_purpose(purpose):
    config = load_config()
    return image_codex_config(config) if normalize_connect_purpose(purpose) == "image" else config


HERMES_CODEX_AUTH_FILES = {
    "account.json",
    "auth.json",
    "auth.lock",
    "credentials.json",
    "credential.json",
    "login.json",
    "oauth.json",
    "openai.json",
    "token.json",
    "tokens.json",
    "session.json",
    "sessions.json",
    "openai-auth.json",
    "codex-auth.json",
}

HERMES_CODEX_AUTH_DIRS = {
    "account",
    "auth",
    "login",
    "oauth",
    "tokens",
    "credentials",
    "openai-auth",
    "codex-auth",
}
HERMES_CODEX_AUTH_NAME_PARTS = {
    "account",
    "auth",
    "credential",
    "login",
    "oauth",
    "session",
    "token",
}
HERMES_CODEX_AUTH_SUFFIXES = {"", ".json", ".lock", ".db", ".sqlite", ".sqlite3"}

HERMES_CODEX_AUTH_RELATIVE_FILES = {
    ".codex/auth.json",
    ".codex/auth.lock",
    ".codex/credentials.json",
    "codex/auth.json",
    "codex/auth.lock",
    "openai/auth.json",
    "openai/tokens.json",
}


def safe_hermes_auth_home(path):
    home = Path(str(path or "")).expanduser()
    if not home.is_absolute():
        home = ROOT_DIR / home
    try:
        resolved = home.resolve()
    except OSError:
        resolved = home.absolute()
    allowed_roots = [
        (ROOT_DIR / "dashboard" / "data").resolve(),
        (ROOT_DIR / "runtime").resolve(),
    ]
    if not any(resolved == root or root in resolved.parents for root in allowed_roots):
        raise ValueError("No puedo desconectar esa sesión porque la ruta de autenticación no pertenece a Admira IA.")
    return resolved


def stop_hermes_login_session(purpose="agent"):
    purpose = normalize_connect_purpose(purpose)
    with HERMES_LOGIN_LOCK:
        state_purpose = normalize_connect_purpose(HERMES_LOGIN_STATE.get("purpose"))
        proc = HERMES_LOGIN_STATE.get("proc")
        fd = HERMES_LOGIN_STATE.get("fd")
        running = bool(proc and proc.poll() is None)
        if state_purpose != purpose:
            return False
        HERMES_LOGIN_STATE.update({"proc": None, "fd": None, "status": "disconnected", "output": "", "updated_at": now_iso()})
    if running:
        try:
            proc.terminate()
        except Exception:
            pass
    if fd is not None:
        try:
            os.close(fd)
        except OSError:
            pass
    return running


def clear_hermes_codex_auth(home):
    auth_home = safe_hermes_auth_home(home)
    removed = []
    auth_home.mkdir(parents=True, exist_ok=True)
    for child in auth_home.iterdir():
        name = child.name
        lowered = name.lower()
        target = None
        if child.is_file() and name in HERMES_CODEX_AUTH_FILES:
            target = child
        elif child.is_dir() and name in HERMES_CODEX_AUTH_DIRS:
            target = child
        elif child.is_file() and child.suffix.lower() in HERMES_CODEX_AUTH_SUFFIXES and any(part in lowered for part in HERMES_CODEX_AUTH_NAME_PARTS):
            target = child
        elif child.is_dir() and any(part in lowered for part in HERMES_CODEX_AUTH_NAME_PARTS):
            target = child
        if not target:
            continue
        try:
            if target.is_dir():
                shutil.rmtree(target)
            else:
                target.unlink()
            removed.append(str(target.relative_to(auth_home)))
        except OSError:
            continue
    for relative in HERMES_CODEX_AUTH_RELATIVE_FILES:
        target = auth_home / relative
        if not target.exists():
            continue
        try:
            target.unlink()
            removed.append(relative)
        except OSError:
            continue
    return {"home": str(auth_home), "removed": removed}


def disconnect_auth_homes(config, purpose="agent"):
    """Return safe auth homes that must be cleared for a true ChatGPT disconnect.

    New installs use HERMES_HOME as the isolated Codex/ChatGPT auth home, but
    older gateway processes inherited CODEX_HOME from the container/runtime.
    Clearing both safe homes avoids the UI saying "desconectado" while an old
    Codex session still prevents connecting a different account.
    """
    normalized_purpose = normalize_connect_purpose(purpose)
    homes = []
    seen = set()

    def add_home(path):
        if not path:
            return None
        try:
            safe_home = safe_hermes_auth_home(path)
        except ValueError:
            return None
        key = str(safe_home)
        if key not in seen:
            seen.add(key)
            homes.append(safe_home)
        return safe_home

    configured_home = add_home(getattr(config, "hermes_home", ""))
    codex_home = os.environ.get("CODEX_HOME")
    if codex_home:
        try:
            safe_codex_home = safe_hermes_auth_home(codex_home)
        except ValueError:
            safe_codex_home = None
        if safe_codex_home and (normalized_purpose == "agent" or configured_home == safe_codex_home):
            add_home(safe_codex_home)
    return homes


def clear_hermes_codex_auth_homes(homes):
    cleared = []
    removed = []
    for home in homes:
        result = clear_hermes_codex_auth(home)
        cleared.append(result)
        home_label = result.get("home", "")
        for item in result.get("removed", []):
            removed.append(f"{home_label}:{item}" if home_label else item)
    first_home = cleared[0].get("home", "") if cleared else ""
    return {
        "home": first_home,
        "homes": [item.get("home", "") for item in cleared if item.get("home")],
        "removed": removed,
        "cleared": cleared,
    }


def disconnect_agent_model(payload=None):
    payload = payload or {}
    purpose = normalize_connect_purpose(payload.get("connection_purpose") or payload.get("purpose"))
    base_config = load_config()
    if purpose == "image" and agent_brain_uses_chatgpt_codex(base_config):
        log_action("agent_model_disconnect", {"purpose": purpose, "removed": 0, "uses_main_chatgpt": True}, "completed")
        return {
            "ok": True,
            "status": "using_main_chatgpt",
            "connection_purpose": purpose,
            "title": "Image 2 usa la cuenta principal",
            "detail": "Como el cerebro principal es ChatGPT/Codex, Image 2 reutiliza esa misma sesión. Para cambiarla, desconecta la cuenta principal de ChatGPT/Codex.",
            "removed": [],
            "home": "",
            "homes": [],
            "env_updated": [],
            "gateway": None,
        }
    config = config_for_connect_purpose(purpose)
    stop_hermes_login_session(purpose)
    cleared = clear_hermes_codex_auth_homes(disconnect_auth_homes(config, purpose))
    env_updates = {}
    gateway = None
    if purpose == "agent":
        env_updates = {
            "HERMES_REQUIRE_CODEX_AUTH": "true" if agent_brain_uses_chatgpt_codex(config) else "false"
        }
        update_env_values(env_updates)
        gateway = refresh_telegram_gateway_after_agent_model_change(
            {"HERMES_MODEL": getattr(config, "hermes_model", "")},
            force_restart=True,
        )
    else:
        env_updates = {
            "CODEX_IMAGE_SOURCE": "dedicated_chatgpt",
            "CODEX_IMAGE_HERMES_HOME": str(default_codex_image_hermes_home()),
            "CODEX_IMAGE_HERMES_MODEL": normalize_hermes_model(getattr(config, "codex_image_hermes_model", "") or getattr(config, "hermes_model", "")),
        }
        update_env_values(env_updates)
    cache_codex_session_status(config, purpose=purpose, authenticated=False, detail="OpenAI Codex disconnected by the buyer")
    log_action("agent_model_disconnect", {"purpose": purpose, "removed": len(cleared.get("removed", []))}, "completed")
    label = "ChatGPT/Codex de imágenes" if purpose == "image" else "ChatGPT/Codex"
    return {
        "ok": True,
        "status": "disconnected",
        "connection_purpose": purpose,
        "title": f"{label} desconectado",
        "detail": "Puedes conectar otra cuenta cuando quieras. No borré memoria, campañas ni configuración del agente.",
        "removed": cleared.get("removed", []),
        "home": cleared.get("home", ""),
        "homes": cleared.get("homes", []),
        "env_updated": sorted(env_updates.keys()),
        "gateway": gateway,
    }


def codex_cli_auth_fingerprint(config):
    """Hash only the canonical Codex CLI credential used by device login."""
    environment = hermes_environment(config)
    raw_home = str(environment.get("CODEX_HOME") or "").strip()
    if not raw_home:
        return ""
    home = Path(raw_home).expanduser()
    if not home.is_absolute():
        home = ROOT_DIR / home
    digest = hashlib.sha256()
    found = False
    for relative in ("auth.json", ".codex/auth.json", "credentials.json"):
        path = home / relative
        try:
            data = path.read_bytes()
        except OSError:
            continue
        found = True
        digest.update(relative.encode("utf-8"))
        digest.update(b"\0")
        digest.update(data)
        digest.update(b"\0")
    return digest.hexdigest() if found else ""


def hermes_browserless_snapshot(config=None, purpose="agent"):
    config = config or load_config()
    purpose = normalize_connect_purpose(purpose)
    with HERMES_LOGIN_LOCK:
        state = dict(HERMES_LOGIN_STATE)
        proc = state.get("proc")
        running = bool(proc and proc.poll() is None)
        output = state.get("output", "")
    # While a replacement login is running, its PTY output is the source of
    # truth. Probing the old Codex credential first can take 10-15 seconds per
    # poll and delays the device link long enough for the Telegram request to
    # time out. Validate the credential only after the login process exits.
    if running:
        ready, auth_detail = False, "ChatGPT account switch is in progress"
    else:
        ready, auth_detail = browserless_chatgpt_ready(config)
    force_reconnect = bool(state.get("force_reconnect"))
    baseline_fingerprint = str(state.get("baseline_auth_fingerprint") or "")
    replacement_changed = codex_cli_auth_fingerprint(config) != baseline_fingerprint
    replacement_ready = bool(ready and (not force_reconnect or replacement_changed))
    if not replacement_ready:
        nudge_hermes_browserless_autodrive()
    if replacement_ready:
        gateway = refresh_telegram_gateway_after_agent_model_change(
            {"HERMES_MODEL": getattr(config, "hermes_model", "")}
        ) if purpose == "agent" else None
        cache_codex_session_status(config, purpose=purpose, authenticated=True, detail=auth_detail)
        return hermes_connect_response(
            "completed",
            "ChatGPT/Codex conectado",
            "El agente ya tiene lista la conexión con ChatGPT/Codex en esta instalación.",
            mode="browserless_ready",
            command=hermes_browserless_shell_command(config),
            output=output or auth_detail,
            running=False,
            job_id=state.get("id") or "",
            connection_purpose=purpose,
            gateway=gateway,
            log=False,
        )
    if running:
        prompt = hermes_login_prompt_state(output, state)
        status = "needs_login" if extract_urls_from_text(output) else "browser_login_waiting"
        return hermes_connect_response(
            status,
            prompt["title"],
            prompt["detail"],
            mode="browserless_running",
            command=hermes_browserless_shell_command(config),
            output=output,
            running=True,
            job_id=state.get("id") or "",
            connection_purpose=purpose,
            needs_input=prompt["needs_input"],
            phase=prompt["phase"],
            auto_note=prompt["auto_note"],
            log=False,
        )
    if output:
        prompt = hermes_login_prompt_state(output, state)
        if prompt["phase"] == "device_auth_settings":
            return hermes_connect_response(
                "needs_login",
                prompt["title"],
                prompt["detail"],
                mode="browserless_device_auth_disabled",
                command=hermes_browserless_shell_command(config),
                output=output or auth_detail,
                running=False,
                job_id=state.get("id") or "",
                connection_purpose=purpose,
                needs_input=False,
                phase=prompt["phase"],
                auto_note=prompt["auto_note"],
                log=False,
            )
        return hermes_connect_response(
            "needs_terminal",
            "El agente necesita una respuesta",
            "La sesión terminó antes de quedar conectada. Revisa el detalle, vuelve a tocar Conectar ahora o usa una API compatible.",
            mode="browserless_finished",
            command=hermes_browserless_shell_command(config),
            output=output or auth_detail,
            running=False,
            job_id=state.get("id") or "",
            connection_purpose=purpose,
            log=False,
        )
    return hermes_connect_response(
        "needs_terminal",
        "Falta conectar ChatGPT/Codex",
        "Toca Conectar ahora para iniciar el login en este servidor.",
        mode="browserless_idle",
        command=hermes_browserless_shell_command(config),
        output=auth_detail,
        running=False,
        job_id=state.get("id") or "",
        connection_purpose=purpose,
        log=False,
    )


def append_hermes_login_output(session_id, text):
    if not text:
        return
    with HERMES_LOGIN_LOCK:
        if HERMES_LOGIN_STATE.get("id") != session_id:
            return
        output = (HERMES_LOGIN_STATE.get("output") or "") + text
        HERMES_LOGIN_STATE["output"] = output[-HERMES_LOGIN_OUTPUT_LIMIT:]
        HERMES_LOGIN_STATE["updated_at"] = now_iso()


def import_codex_cli_session_into_hermes(config):
    """Import the just-completed native Codex login into the matching Hermes home."""
    environment = hermes_environment(config)
    script = (
        "from hermes_cli.auth import _import_codex_cli_tokens as load, _save_codex_tokens as save; "
        "tokens=load(); assert tokens, 'Codex CLI login did not produce credentials'; save(tokens)"
    )
    try:
        result = subprocess.run(
            [sys.executable, "-c", script],
            cwd=str(ROOT_DIR),
            env=environment,
            text=True,
            capture_output=True,
            timeout=15,
            check=False,
        )
        return result.returncode == 0
    except (OSError, subprocess.TimeoutExpired):
        return False


def finish_hermes_browserless_session(session_id, returncode):
    with HERMES_LOGIN_LOCK:
        if HERMES_LOGIN_STATE.get("id") != session_id:
            return
        purpose = HERMES_LOGIN_STATE.get("purpose") or "agent"
    config = config_for_connect_purpose(purpose)
    if returncode == 0:
        import_codex_cli_session_into_hermes(config)
    ready, auth_detail = browserless_chatgpt_ready(config)
    with HERMES_LOGIN_LOCK:
        force_reconnect = bool(HERMES_LOGIN_STATE.get("force_reconnect"))
        baseline_fingerprint = str(HERMES_LOGIN_STATE.get("baseline_auth_fingerprint") or "")
    replacement_changed = codex_cli_auth_fingerprint(config) != baseline_fingerprint
    ready = bool(ready and (not force_reconnect or replacement_changed))
    if force_reconnect and not replacement_changed:
        auth_detail = "La cuenta anterior sigue activa; el nuevo login todavía no reemplazó la credencial de Codex."
    if ready and purpose == "agent":
        # Only after the replacement credential is safely persisted may the
        # shared Image 2/fallback route be updated. A gateway restart is safe
        # here because the device URL and code were delivered earlier.
        update_env_values({
            "CODEX_IMAGE_SOURCE": "main_chatgpt",
            "CODEX_IMAGE_HERMES_HOME": "",
            "HERMES_REQUIRE_CODEX_AUTH": "false",
        })
        try:
            codex_model_catalog(config=config, force_refresh=True)
        except Exception:
            pass
        # The long-lived Telegram gateway may still hold the previous OAuth
        # provider instance. Rebuild it only after the new credential is fully
        # persisted so the next buyer message uses the selected account.
        try:
            refresh_telegram_gateway_after_agent_model_change(
                {"HERMES_MODEL": getattr(config, "hermes_model", "")},
                force_restart=True,
            )
        except Exception:
            pass
    if ready:
        cache_codex_session_status(config, purpose=purpose, authenticated=True, detail=auth_detail)
    with HERMES_LOGIN_LOCK:
        if HERMES_LOGIN_STATE.get("id") != session_id:
            return
        HERMES_LOGIN_STATE["status"] = "completed" if ready else "needs_terminal"
        HERMES_LOGIN_STATE["title"] = "ChatGPT/Codex conectado" if ready else "El agente necesita una respuesta"
        HERMES_LOGIN_STATE["detail"] = auth_detail
        HERMES_LOGIN_STATE["phase"] = "completed" if ready else "finished"
        HERMES_LOGIN_STATE["auto_note"] = ""
        HERMES_LOGIN_STATE["returncode"] = returncode
        HERMES_LOGIN_STATE["updated_at"] = now_iso()
        fd = HERMES_LOGIN_STATE.get("fd")
        HERMES_LOGIN_STATE["proc"] = None
        HERMES_LOGIN_STATE["fd"] = None
    if fd is not None:
        try:
            os.close(fd)
        except OSError:
            pass


def read_hermes_browserless_output(session_id, master_fd, proc):
    while True:
        try:
            chunk = os.read(master_fd, 4096)
        except OSError:
            break
        if not chunk:
            break
        append_hermes_login_output(session_id, chunk.decode("utf-8", errors="replace"))
        maybe_auto_drive_hermes_browserless(session_id, master_fd)
    try:
        returncode = proc.wait(timeout=1)
    except subprocess.TimeoutExpired:
        returncode = proc.poll()
    finish_hermes_browserless_session(session_id, returncode)


def start_hermes_browserless_login(config, purpose="agent", force_reconnect=False):
    purpose = normalize_connect_purpose(purpose)
    command = hermes_browserless_launch_command(config)
    if not command:
        return hermes_connect_response(
            "not_installed",
            "Falta la base del agente",
            "Instala o actualiza Admira IA y vuelve a tocar Conectar ahora.",
            mode="missing_runtime",
            command=hermes_browserless_shell_command(config),
            connection_purpose=purpose,
        )
    # A forced account switch must open the device flow immediately. Checking
    # the credential being replaced adds latency and cannot satisfy the switch.
    if force_reconnect:
        ready, auth_detail = False, "ChatGPT account switch requested"
    else:
        ready, auth_detail = browserless_chatgpt_ready(config)
    if ready and not force_reconnect:
        gateway = refresh_telegram_gateway_after_agent_model_change(
            {"HERMES_MODEL": getattr(config, "hermes_model", "")}
        ) if purpose == "agent" else None
        cache_codex_session_status(config, purpose=purpose, authenticated=True, detail=auth_detail)
        return hermes_connect_response(
            "completed",
            "ChatGPT/Codex conectado",
            "El agente ya tiene lista la conexión con ChatGPT/Codex.",
            mode="already_ready",
            command=hermes_browserless_shell_command(config),
            output=auth_detail,
            running=False,
            connection_purpose=purpose,
            gateway=gateway,
        )
    with HERMES_LOGIN_LOCK:
        proc = HERMES_LOGIN_STATE.get("proc")
        running = bool(proc and proc.poll() is None)
    if running:
        return hermes_browserless_snapshot(config, purpose=purpose)
    if os.name == "nt":
        return probe_hermes_model_login(config)
    try:
        import pty

        baseline_auth_fingerprint = codex_cli_auth_fingerprint(config)
        master_fd, slave_fd = pty.openpty()
        explicit_auth = (
            ("auth" in command and "openai-codex" in command)
            or ("login" in command and "--device-auth" in command)
        )
        env = hermes_environment(config)
        env["PYTHONUNBUFFERED"] = "1"
        proc = subprocess.Popen(
            command,
            cwd=str(ROOT_DIR),
            stdin=slave_fd,
            stdout=slave_fd,
            stderr=slave_fd,
            env=env,
            close_fds=True,
        )
        os.close(slave_fd)
        session_id = f"hermes-{int(datetime.utcnow().timestamp())}"
        with HERMES_LOGIN_LOCK:
            HERMES_LOGIN_STATE.update(
                {
                    "id": session_id,
                    "status": "browser_login_started",
                    "title": "Conecta ChatGPT desde este navegador",
                    "detail": "Sesion segura abierta dentro de este servidor.",
                    "output": "",
                    "phase": "starting",
                    "auto_note": "Estoy abriendo el login directo de OpenAI Codex." if explicit_auth else "Estoy preparando el agente para usar OpenAI Codex.",
                    "auto_provider_sent": False,
                    "auto_codex_subprovider_sent": False,
                    "auto_model_sent": False,
                    "preferred_model": normalize_hermes_model(getattr(config, "hermes_model", "")),
                    "purpose": purpose,
                    "started_at": now_iso(),
                    "updated_at": now_iso(),
                    "proc": proc,
                    "fd": master_fd,
                    "command": " ".join(shlex.quote(part) for part in command),
                    "auth_mode": "explicit_openai_codex" if explicit_auth else "legacy_picker",
                    "force_reconnect": bool(force_reconnect),
                    "baseline_auth_fingerprint": baseline_auth_fingerprint,
                }
            )
        threading.Thread(target=read_hermes_browserless_output, args=(session_id, master_fd, proc), name="hermes-browserless-login", daemon=True).start()
        return hermes_connect_response(
            "browser_login_started",
            "Conecta ChatGPT desde este navegador",
            "Abrí directamente el login seguro de OpenAI Codex. Cuando aparezcan el enlace y el código, los mostraré aquí." if explicit_auth else f"Abrí la sesión segura dentro de este servidor. Voy a elegir OpenAI Codex y el modelo {normalize_hermes_model(config.hermes_model)} automáticamente. Si aparece un enlace, ábrelo aquí.",
            mode="browserless_started",
            command=hermes_browserless_shell_command(config),
            running=True,
            job_id=session_id,
            connection_purpose=purpose,
            needs_input=False,
            phase="starting",
            auto_note="Estoy abriendo el login directo de OpenAI Codex." if explicit_auth else "Estoy preparando el agente para usar OpenAI Codex.",
            auth_mode="explicit_openai_codex" if explicit_auth else "legacy_picker",
        )
    except Exception as exc:
        return hermes_connect_response(
            "needs_terminal",
            "No pude abrir la sesión segura",
            "Este servidor no permitió abrir la sesión desde el dashboard. Usa una API compatible o revisa la instalación con soporte.",
            mode="browserless_error",
            command=hermes_browserless_shell_command(config),
            output=str(exc),
        )


def agent_model_connect_status(payload=None):
    payload = payload or {}
    purpose = normalize_connect_purpose(payload.get("connection_purpose") or payload.get("purpose"))
    return hermes_browserless_snapshot(config_for_connect_purpose(purpose), purpose=purpose)


def refresh_agent_model_catalog(_payload=None):
    return codex_model_catalog(config=load_config(), force_refresh=True)


def agent_model_connect_input(payload=None):
    payload = payload or {}
    text = str((payload or {}).get("input") or "")
    if not text.strip():
        purpose = normalize_connect_purpose(payload.get("connection_purpose") or payload.get("purpose"))
        return hermes_browserless_snapshot(config_for_connect_purpose(purpose), purpose=purpose)
    if not text.endswith("\n"):
        text += "\n"
    with HERMES_LOGIN_LOCK:
        fd = HERMES_LOGIN_STATE.get("fd")
        proc = HERMES_LOGIN_STATE.get("proc")
        running = bool(proc and proc.poll() is None and fd is not None)
    if not running:
        purpose = normalize_connect_purpose(payload.get("connection_purpose") or payload.get("purpose"))
        return hermes_browserless_snapshot(config_for_connect_purpose(purpose), purpose=purpose)
    os.write(fd, text.encode("utf-8", errors="replace"))
    with HERMES_LOGIN_LOCK:
        purpose = normalize_connect_purpose(HERMES_LOGIN_STATE.get("purpose"))
    return hermes_browserless_snapshot(config_for_connect_purpose(purpose), purpose=purpose)


def probe_hermes_model_login(config):
    cli = str(getattr(config, "hermes_cli", "") or "hermes").strip() or "hermes"
    try:
        result = subprocess.run([cli, "model", "--no-browser"], cwd=str(ROOT_DIR), env=hermes_environment(config), text=True, capture_output=True, timeout=10, check=False)
    except FileNotFoundError:
        return hermes_connect_response(
            "not_installed",
            "Falta la base del agente",
            "Instala o actualiza Admira IA y vuelve a tocar Conectar ahora.",
            mode="missing_runtime",
        )
    except subprocess.TimeoutExpired as exc:
        stdout = exc.stdout if isinstance(exc.stdout, str) else ""
        stderr = exc.stderr if isinstance(exc.stderr, str) else ""
        output = "\n".join([stdout, stderr]).strip()
        return hermes_connect_response(
            "needs_login" if extract_urls_from_text(output) else "needs_terminal",
            "Falta terminar el login",
            "No pude abrir una terminal en este entorno. Si apareció un enlace, ábrelo; si no, usa Conectar desde este navegador o una API compatible.",
            mode="probe_timeout",
            command=hermes_browserless_shell_command(config),
            output=output,
        )
    output = "\n".join([(result.stdout or ""), (result.stderr or "")]).strip()
    if result.returncode == 0:
        return hermes_connect_response(
            "completed",
            "Conexión revisada",
            "El agente terminó correctamente. Ahora revisa la conexión y prueba el chat.",
            mode="probe_completed",
            command=hermes_browserless_shell_command(config),
            output=output,
        )
    return hermes_connect_response(
        "needs_login" if extract_urls_from_text(output) else "needs_terminal",
        "Falta terminar la conexión",
        "El agente respondió, pero todavía necesita que termines el login o elijas el proveedor.",
        mode="probe_failed",
        command=hermes_browserless_shell_command(config),
        output=output,
    )


def connect_agent_model(payload=None):
    payload = payload or {}
    purpose = normalize_connect_purpose(payload.get("connection_purpose") or payload.get("purpose"))
    if purpose == "image":
        base_config = load_config()
        if agent_brain_uses_chatgpt_codex(base_config):
            ready, auth_detail = hermes_codex_ready(base_config)
            if ready:
                cache_codex_session_status(base_config, purpose="agent", authenticated=True, detail=auth_detail)
                return hermes_connect_response(
                    "completed",
                    "Image 2 listo con la cuenta principal",
                    "Como el cerebro principal es ChatGPT/Codex, Image 2 usa esa misma sesión. No hace falta conectar una segunda cuenta.",
                    mode="image_uses_main_chatgpt",
                    command=hermes_browserless_shell_command(base_config),
                    output=auth_detail,
                    running=False,
                    connection_purpose="image",
                )
            return hermes_connect_response(
                "needs_terminal",
                "Conecta ChatGPT/Codex principal",
                "Image 2 usa la misma cuenta ChatGPT/Codex del agente. Conecta primero el cerebro principal y luego vuelve a generar los creativos.",
                mode="image_needs_main_chatgpt",
                command=hermes_browserless_shell_command(base_config),
                output=auth_detail,
                running=False,
                connection_purpose="image",
            )
        image_model = normalize_hermes_model(payload.get("codex_image_hermes_model") or payload.get("hermes_model") or "")
        update_env_values(
            {
                "CODEX_IMAGE_SOURCE": "dedicated_chatgpt",
                "CODEX_IMAGE_HERMES_HOME": str(default_codex_image_hermes_home()),
                "CODEX_IMAGE_HERMES_MODEL": image_model,
            }
        )
        config = image_codex_config(load_config())
        ready, auth_detail = hermes_codex_ready(config)
        if ready:
            cache_codex_session_status(config, purpose="image", authenticated=True, detail=auth_detail)
            return hermes_connect_response(
                "completed",
                "ChatGPT/Codex para imágenes conectado",
                "Image 2 ya tiene lista una sesión de ChatGPT/Codex separada. El cerebro principal del agente no cambió.",
                mode="image_already_ready",
                command=hermes_browserless_shell_command(config),
                output=auth_detail,
                running=False,
                connection_purpose="image",
            )
        if launch_hermes_terminal(config):
            return hermes_connect_response(
                "terminal_opened",
                "Abrí la terminal",
                "Sigue la ventana que se abrió para conectar ChatGPT/Codex solo para imágenes. El modelo principal no cambiará.",
                mode="image_terminal",
                connection_purpose="image",
            )
        return start_hermes_browserless_login(
            config,
            purpose="image",
            force_reconnect=bool(payload.get("force_reconnect")),
        )
    current_config = load_config()
    env_updates = {
        "HERMES_MODEL": resolve_codex_model_choice(
            payload.get("hermes_model") if "hermes_model" in payload else "",
            config=current_config,
        )
    }
    if str(payload.get("agent_model_action") or "").strip().lower() == "set_primary":
        env_updates.update({
            "AGENT_CHAT_PROVIDER": "hermes",
            "AGENT_BRAIN_PROVIDER": "openai_codex",
            "HERMES_REQUIRE_CODEX_AUTH": "true",
        })
    update_env_values(env_updates)
    config = load_config()
    ready, auth_detail = hermes_codex_ready(config)
    if ready:
        gateway = refresh_telegram_gateway_after_agent_model_change(env_updates)
        cache_codex_session_status(config, purpose="agent", authenticated=True, detail=auth_detail)
        return hermes_connect_response(
            "completed",
            "ChatGPT/Codex conectado",
            "El agente ya tiene lista tu sesión de ChatGPT/Codex. No hace falta abrir otro login.",
            mode="already_ready",
            command=hermes_browserless_shell_command(config),
            output=auth_detail,
            running=False,
            gateway=gateway,
        )
    if launch_hermes_terminal(config):
        return hermes_connect_response(
            "terminal_opened",
            "Abrí la terminal",
            "Sigue la ventana que se abrió. Cuando termines, vuelve al dashboard y toca Revisar conexión.",
            mode="terminal",
        )
    return start_hermes_browserless_login(
        config,
        force_reconnect=bool(payload.get("force_reconnect")),
    )


def reconnect_shared_chatgpt_subscription():
    """Start one buyer-controlled ChatGPT login shared by fallback and Image 2."""
    stop_hermes_login_session("agent")
    # Keep the current credential until a replacement login completes. An
    # unavailable browser/device flow must not destroy the working Image 2
    # subscription and then misreport the failure as a quota problem. Do not
    # rewrite gateway environment here: its watcher would restart Telegram
    # before the command handler can return the device URL and code.
    config = load_config()
    cache_codex_session_status(config, purpose="agent", authenticated=False, detail="ChatGPT account switch started by buyer")
    return start_hermes_browserless_login(config, purpose="agent", force_reconnect=True)


AGENT_MODEL_GATEWAY_ENV_KEYS = {
    "AGENT_BRAIN_PROVIDER",
    "AGENT_CHAT_PROVIDER",
    "AGENT_CHAT_BASE_URL",
    "AGENT_CHAT_MODEL",
    "AGENT_CHAT_API",
    "AGENT_CHAT_API_KEY",
    "HERMES_MODEL",
    "HERMES_REQUIRE_CODEX_AUTH",
    "ADMIRA_OPENAI_API_KEY",
    "ADMIRA_OPENAI_BASE_URL",
    "ADMIRA_OPENAI_MODEL",
    "ADMIRA_OPENAI_API",
    "ADMIRA_MINIMAX_API_KEY",
    "ADMIRA_MINIMAX_BASE_URL",
    "ADMIRA_MINIMAX_MODEL",
    "ADMIRA_MINIMAX_API",
    "ADMIRA_NVIDIA_API_KEY",
    "ADMIRA_NVIDIA_BASE_URL",
    "ADMIRA_NVIDIA_MODEL",
    "ADMIRA_NVIDIA_API",
    "AGENT_NVIDIA_MODEL_USER_SELECTED",
    "ADMIRA_CUSTOM_API_KEY",
    "ADMIRA_CUSTOM_BASE_URL",
    "ADMIRA_CUSTOM_MODEL",
    "ADMIRA_CUSTOM_API",
}


def refresh_telegram_gateway_after_agent_model_change(env_updates, force_restart=False):
    changed = sorted(set(env_updates or {}) & AGENT_MODEL_GATEWAY_ENV_KEYS)
    if not changed:
        return None
    try:
        config = load_config()
        # Dashboard model changes are authoritative for Telegram. A real
        # restart avoids retaining an older per-session model or an in-memory
        # credential-pool cooldown after the UI already shows the new model.
        effective_force_restart = force_restart or bool(
            set(changed) & {"HERMES_MODEL", "AGENT_BRAIN_PROVIDER", "AGENT_CHAT_PROVIDER"}
        ) or any(key.startswith("ADMIRA_") for key in changed)
        if effective_force_restart:
            stop_hermes_gateway()
        gateway = start_hermes_gateway(config)
    except Exception as exc:
        return {"started": False, "mode": "hermes_gateway", "detail": "No pude refrescar Telegram con el modelo nuevo.", "error": str(exc), "changed": changed}
    if isinstance(gateway, dict):
        return {**gateway, "changed": changed}
    return {"started": bool(gateway), "mode": "hermes_gateway", "changed": changed}


def save_setup_config(payload):
    replaced = False if payload.get("_skip_business_enforcement") else enforce_individual_business_change(payload)
    managed_state = None
    cleaned_ad_account_id = clean_ad_account_id(payload.get("ad_account_id")) if "ad_account_id" in payload else ""
    if cleaned_ad_account_id:
        managed_state = prepare_managed_ad_account_update(
            {
                "id": cleaned_ad_account_id,
                "name": payload.get("account_name") or cleaned_ad_account_id,
                "currency": payload.get("account_currency", ""),
                "timezone_name": payload.get("account_timezone", ""),
                "timezone_offset_hours_utc": payload.get("account_timezone_offset"),
                "status": payload.get("account_status", ""),
                "business_id": payload.get("business_id") or payload.get("business_manager_id"),
                "business_name": payload.get("business_name") or payload.get("business_manager_name"),
            },
            replace_business=bool(payload.get("_replace_business_state")) or bool(payload.get("confirm_replace_business")) or replaced,
        )
    env_updates = {}
    text_fields = {
        "license_key": "LICENSE_KEY",
        "license_buyer_email": "LICENSE_BUYER_EMAIL",
        "ad_account_id": "META_AD_ACCOUNT_ID",
    }
    for field, env_key in text_fields.items():
        if field not in payload:
            continue
        value = cleaned_ad_account_id if field == "ad_account_id" else str(payload.get(field) or "").strip()
        if field == "license_key" and not value:
            continue
        env_updates[env_key] = value
    provider = normalize_agent_chat_provider(payload.get("agent_chat_provider")) if "agent_chat_provider" in payload else ""
    model_action = str(payload.get("agent_model_action") or ("set_primary" if provider else "")).strip().lower()
    if model_action not in {"", "save_connection", "set_primary"}:
        raise ValueError("La acción del modelo no es válida.")
    if provider:
        if provider == "openai_codex":
            if model_action == "set_primary":
                env_updates["AGENT_CHAT_PROVIDER"] = "hermes"
                env_updates["AGENT_BRAIN_PROVIDER"] = provider
                env_updates["HERMES_REQUIRE_CODEX_AUTH"] = "true"
        else:
            current_config = load_config()
            current_primary = normalize_agent_brain_provider(
                getattr(current_config, "agent_brain_provider", ""),
                legacy_chat_provider=getattr(current_config, "agent_chat_provider", "hermes"),
                base_url=getattr(current_config, "agent_chat_base_url", ""),
            )
            stored = agent_model_connections(current_config, include_secrets=True).get(provider, {})
            base_url = str(payload.get("agent_chat_base_url") or stored.get("base_url") or "").strip().rstrip("/")
            if provider == "nvidia_nim":
                base_url = NVIDIA_NIM_BASE_URL
            base_url = validate_agent_chat_base_url(base_url)
            model = str(payload.get("agent_chat_model") or stored.get("model") or "").strip()
            api = str(payload.get("agent_chat_api") or stored.get("api") or "openai-chat-completions").strip().lower()
            api_key = str(payload.get("agent_chat_api_key") or stored.get("api_key") or "").strip()
            if provider == "nvidia_nim" and not re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9._:/-]{1,160}", model):
                raise ValueError("El nombre del modelo NVIDIA no es válido.")
            if not base_url or not model or not api_key:
                raise ValueError("Completa la URL, el modelo y la API key antes de guardar esta conexión.")
            profile_keys = agent_model_connection_env_keys(provider)
            env_updates.update({
                profile_keys["base_url"]: base_url,
                profile_keys["model"]: model,
                profile_keys["api"]: api,
                profile_keys["api_key"]: api_key,
            })
            if provider == "nvidia_nim":
                # Saving from this form is an explicit buyer choice. Preserve
                # it on future updates, including an intentional GLM choice;
                # untouched legacy GLM profiles are migrated to M3 below.
                env_updates["AGENT_NVIDIA_MODEL_USER_SELECTED"] = "true"
            # Updating the profile that is already primary must update the live
            # compatibility fields too, without changing which provider owns
            # the single primary marker.
            if model_action == "set_primary" or provider == current_primary:
                env_updates.update({
                    "AGENT_CHAT_PROVIDER": "hermes",
                    "AGENT_BRAIN_PROVIDER": provider,
                    "HERMES_REQUIRE_CODEX_AUTH": "false",
                    "AGENT_CHAT_BASE_URL": base_url,
                    "AGENT_CHAT_MODEL": model,
                    "AGENT_CHAT_API": api,
                    "AGENT_CHAT_API_KEY": api_key,
                })
    if "hermes_model" in payload and (not provider or provider == "openai_codex"):
        hermes_model = resolve_codex_model_choice(payload.get("hermes_model"), config=load_config())
        env_updates["HERMES_MODEL"] = hermes_model
        # A model selected and saved from the dashboard is an intentional
        # override. New installs without this marker continue to follow the
        # smallest model returned by the connected account catalog.
        env_updates["HERMES_MODEL_USER_SELECTED"] = "true"
    if "codex_image_source" in payload:
        image_source = normalize_codex_image_source(payload.get("codex_image_source"))
        env_updates["CODEX_IMAGE_SOURCE"] = image_source
        if image_source == "dedicated_chatgpt":
            env_updates["CODEX_IMAGE_HERMES_HOME"] = str(default_codex_image_hermes_home())
    if "codex_image_hermes_model" in payload:
        env_updates["CODEX_IMAGE_HERMES_MODEL"] = normalize_hermes_model(payload.get("codex_image_hermes_model"))
    if env_updates:
        update_env_values(env_updates)
    gateway_refresh = None

    ad_config = read_json(AD_CONFIG_FILE, {})
    ad_config.setdefault("account", {})
    ad_config.setdefault("creative", {})
    ad_config["creative"].setdefault("destination", {})
    destination = ad_config["creative"]["destination"]
    if cleaned_ad_account_id:
        ad_config["account"]["id"] = cleaned_ad_account_id
        if payload.get("business_manager_id") or payload.get("business_id"):
            ad_config["account"]["business_manager_id"] = str(payload.get("business_manager_id") or payload.get("business_id") or "").strip()
        if payload.get("business_manager_name") or payload.get("business_name"):
            ad_config["account"]["business_manager_name"] = str(payload.get("business_manager_name") or payload.get("business_name") or "").strip()
    for field, key in {
        "page_id": "page_id",
        "instagram_actor_id": "instagram_actor_id",
        "default_adset_id": "default_adset_id",
        "landing_url": "url",
    }.items():
        if field in payload:
            destination[key] = str(payload.get(field) or "").strip()
    write_json(AD_CONFIG_FILE, ad_config)
    if managed_state:
        managed_state = write_managed_accounts_state(managed_state)
    if str(payload.get("page_id") or "").strip() and not payload.get("_skip_meta_profile_sync"):
        page = read_meta_page_profile(payload.get("page_id"))
        suggested = {
            "page_id": destination.get("page_id", ""),
            "page_name": page.get("name", ""),
            "instagram_actor_id": destination.get("instagram_actor_id", "") or (page.get("instagram") or {}).get("id", ""),
            "instagram_username": (page.get("instagram") or {}).get("username", ""),
            "landing_url": destination.get("url", "") or page.get("website", ""),
        }
        sync_business_profile_from_meta_assets(page, suggested, [suggested["landing_url"]] if suggested.get("landing_url") else [])
    gateway_refresh = refresh_telegram_gateway_after_agent_model_change(env_updates)
    log_action("setup_config_save", {"updated": sorted(list(env_updates.keys()) + ["ad-config.json"] + (["managed_ad_accounts.json"] if managed_state else [])), "business_replaced": replaced}, "completed")
    return {"saved": True, "business_replaced": replaced, "env_updated": sorted(env_updates.keys()), "ad_config": ad_config, "managed_ad_accounts": managed_ad_accounts_payload(), "gateway": gateway_refresh}


class WebsiteSummaryParser(HTMLParser):
    def __init__(self):
        super().__init__()
        self.title = ""
        self.meta = {}
        self.headings = []
        self.links = []
        self._tag = ""
        self._buffer = []

    def handle_starttag(self, tag, attrs):
        attrs = dict(attrs)
        self._tag = tag
        self._buffer = []
        if tag == "meta":
            name = (attrs.get("name") or attrs.get("property") or "").lower()
            content = (attrs.get("content") or "").strip()
            if name and content:
                self.meta[name] = content[:500]
        if tag == "a" and attrs.get("href"):
            href = attrs.get("href", "")
            if len(self.links) < 30:
                self.links.append({"href": href[:300], "text": ""})

    def handle_data(self, data):
        if self._tag in {"title", "h1", "h2", "a"}:
            text = re.sub(r"\s+", " ", data or "").strip()
            if text:
                self._buffer.append(text)

    def handle_endtag(self, tag):
        text = " ".join(self._buffer).strip()
        if tag == "title" and text and not self.title:
            self.title = text[:180]
        elif tag in {"h1", "h2"} and text and len(self.headings) < 12:
            self.headings.append(text[:180])
        elif tag == "a" and text and self.links:
            self.links[-1]["text"] = text[:120]
        self._tag = ""
        self._buffer = []


def normalize_website_url(value):
    url = str(value or "").strip()
    if not url:
        return ""
    if not re.match(r"^https?://", url, flags=re.I):
        url = "https://" + url
    parsed = urllib.parse.urlparse(url)
    if not parsed.netloc:
        raise ValueError("Escribe una web valida, por ejemplo https://tumarca.com")
    if parsed.scheme.lower() not in {"http", "https"}:
        raise ValueError("Solo puedo leer webs http o https.")
    return urllib.parse.urlunparse((parsed.scheme, parsed.netloc, parsed.path or "/", "", parsed.query, ""))


def public_website_host(hostname):
    host = str(hostname or "").strip().strip("[]").lower()
    if not host or host == "localhost" or host.endswith(".localhost"):
        return False
    try:
        parsed_ip = ipaddress.ip_address(host)
        return not (
            parsed_ip.is_loopback
            or parsed_ip.is_private
            or parsed_ip.is_link_local
            or parsed_ip.is_reserved
            or parsed_ip.is_multicast
            or parsed_ip.is_unspecified
        )
    except ValueError:
        pass
    try:
        infos = socket.getaddrinfo(host, None)
    except OSError:
        return True
    if not infos:
        return False
    for family, _, _, _, sockaddr in infos:
        address = sockaddr[0]
        try:
            parsed_ip = ipaddress.ip_address(address)
        except ValueError:
            return False
        if (
            parsed_ip.is_loopback
            or parsed_ip.is_private
            or parsed_ip.is_link_local
            or parsed_ip.is_reserved
            or parsed_ip.is_multicast
            or parsed_ip.is_unspecified
        ):
            return False
    return True


def validate_public_website_url(url):
    parsed = urllib.parse.urlparse(str(url or ""))
    if parsed.scheme.lower() not in {"http", "https"} or not parsed.hostname:
        raise ValueError("Escribe una web publica valida, por ejemplo https://tumarca.com")
    if not public_website_host(parsed.hostname):
        raise ValueError("Por seguridad, solo puedo leer webs publicas. No puedo abrir direcciones locales o privadas.")
    return True


class SafeWebsiteRedirectHandler(urllib.request.HTTPRedirectHandler):
    def redirect_request(self, req, fp, code, msg, headers, newurl):
        validate_public_website_url(newurl)
        return super().redirect_request(req, fp, code, msg, headers, newurl)


def infer_business_profile(url, parser, context):
    description = parser.meta.get("description") or parser.meta.get("og:description") or ""
    title = parser.title or parser.meta.get("og:title") or ""
    headings = [h for h in parser.headings if len(h) > 3]
    joined = " ".join([title, description, *headings, context]).lower()
    business_type = "negocio online"
    if any(word in joined for word in ["curso", "mentoria", "mentor", "coaching", "academia", "masterclass"]):
        business_type = "infoproducto, curso o mentoría"
    elif any(word in joined for word in ["shop", "tienda", "producto", "carrito", "envio", "ecommerce", "comprar"]):
        business_type = "tienda online o ecommerce"
    elif any(word in joined for word in ["consulta", "servicio", "agenda", "reserva", "abogado", "clinica", "asesoria"]):
        business_type = "servicio local o profesional"
    elif any(word in joined for word in ["software", "app", "saas", "plataforma", "demo"]):
        business_type = "software o plataforma digital"
    offer = headings[0] if headings else title or "oferta principal por definir"
    audience = "personas con intención de comprar o pedir información"
    if "empresa" in joined or "negocio" in joined or "emprendedor" in joined:
        audience = "dueños de negocio, emprendedores o equipos pequeños"
    elif "mujer" in joined or "belleza" in joined or "estetica" in joined:
        audience = "personas interesadas en belleza, cuidado personal o bienestar"
    elif "curso" in joined or "aprende" in joined:
        audience = "personas que quieren aprender o mejorar una habilidad concreta"
    pain = context or "El comprador quiere entender mejor sus anuncios, decidir con menos estrés y mejorar resultados con ayuda del agente."
    angles = [
        f"Claridad: explicar rápido por qué {offer} resuelve un problema concreto.",
        "Confianza: mostrar prueba, experiencia, resultados o garantías antes de pedir la compra.",
        "Acción simple: llevar a una sola decisión clara, sin llenar el anuncio de demasiadas ideas.",
    ]
    plan = [
        "Primero leer datos reales de Meta para no decidir a ciegas.",
        f"Preparar una campaña inicial para {business_type} con 2 o 3 ángulos creativos.",
        "Preparar el primer ciclo en pausa: el agente recomienda y deja la estructura lista; el comprador aprueba solo antes de activar o gastar.",
        "Revisar en la lectura diaria qué sube, qué se cansa y qué conviene escalar.",
    ]
    return {
        "website_url": url,
        "business_type": business_type,
        "offer": offer,
        "main_offer": offer,
        "audience": audience,
        "ideal_customer": audience,
        "current_stage": context[:800],
        "what_to_improve": "Entender mejor qué anuncios pueden vender esta oferta y preparar el primer plan sin adivinar.",
        "positioning": description or title,
        "detected_title": title,
        "detected_headings": headings[:8],
        "suggested_angles": angles,
        "initial_plan": plan,
        "source": "website_scan_basic",
        "created_at": now_iso(),
    }


def extract_json_object_from_text(text):
    raw = str(text or "").strip()
    if not raw:
        return {}
    candidates = [raw]
    fenced = re.search(r"```(?:json)?\s*(\{.*?\})\s*```", raw, flags=re.DOTALL | re.IGNORECASE)
    if fenced:
        candidates.insert(0, fenced.group(1))
    if "{" in raw and "}" in raw:
        candidates.append(raw[raw.find("{") : raw.rfind("}") + 1])
    for candidate in candidates:
        try:
            parsed = json.loads(candidate)
        except json.JSONDecodeError:
            continue
        if isinstance(parsed, dict):
            return parsed
    return {}


def apply_business_profile_enrichment(profile, enrichment):
    allowed_strings = [
        "business_type",
        "offer",
        "main_offer",
        "audience",
        "ideal_customer",
        "current_stage",
        "what_to_improve",
        "positioning",
    ]
    allowed_lists = ["suggested_angles", "initial_plan", "detected_headings", "products_services"]
    merged = dict(profile or {})
    for key in allowed_strings:
        value = str((enrichment or {}).get(key) or "").strip()
        if value:
            merged[key] = value[:1200]
    for key in allowed_lists:
        value = (enrichment or {}).get(key)
        if isinstance(value, list):
            merged[key] = [str(item or "").strip()[:300] for item in value if str(item or "").strip()][:8]
    if merged.get("main_offer") and not merged.get("offer"):
        merged["offer"] = merged["main_offer"]
    if merged.get("offer") and not merged.get("main_offer"):
        merged["main_offer"] = merged["offer"]
    if merged.get("ideal_customer") and not merged.get("audience"):
        merged["audience"] = merged["ideal_customer"]
    if merged.get("audience") and not merged.get("ideal_customer"):
        merged["ideal_customer"] = merged["audience"]
    return merged


BUSINESS_QUESTION_FIELDS = {
    "main_offer",
    "ideal_customer",
    "sales_channel",
    "current_stage",
    "current_ads",
    "biggest_blocker",
    "what_to_improve",
    "success_goal",
    "budget_comfort",
    "brand_tone",
}


def default_business_context_questions(business_type="", language="es"):
    business_type = str(business_type or "").strip()
    if language != "en":
        offer_hint = f"Ej: vendo {business_type}" if business_type else "Ej: vendo cursos, ropa, servicios, tratamientos..."
        return [
            {"key": "main_offer", "label": "¿Qué vendes?", "help": "Una frase corta.", "placeholder": offer_hint},
            {"key": "ideal_customer", "label": "¿Quién compra?", "help": "La persona que más quieres atraer.", "placeholder": "Ej: mujeres de 25 a 40, dueños de negocio, mamás..."},
            {"key": "sales_channel", "label": "¿Dónde vendes?", "help": "Web, WhatsApp, Instagram, tienda física o llamada.", "placeholder": "Ej: vendo por WhatsApp y mi web."},
            {"key": "current_stage", "label": "¿En qué punto estás?", "help": "Dime si empiezas, ya vendes o ya tienes anuncios.", "placeholder": "Ej: ya vendo, pero mis anuncios me confunden."},
            {"key": "biggest_blocker", "label": "¿Qué te frena hoy?", "help": "Lo que más te preocupa ahora.", "placeholder": "Ej: no sé qué anuncio pausar o escalar."},
            {"key": "success_goal", "label": "¿Qué sería una victoria?", "help": "Algo claro para los próximos 30 días.", "placeholder": "Ej: bajar costo por compra o vender 20 unidades más."},
        ]
    offer_hint = f"Ex: I sell {business_type}" if business_type else "Ex: courses, clothing, services, treatments..."
    return [
        {"key": "main_offer", "label": "What do you sell?", "help": "One short sentence.", "placeholder": offer_hint},
        {"key": "ideal_customer", "label": "Who buys?", "help": "The person you most want to attract.", "placeholder": "Ex: women 25-40, business owners, moms..."},
        {"key": "sales_channel", "label": "Where do you sell?", "help": "Website, WhatsApp, Instagram, store, or call.", "placeholder": "Ex: I sell through WhatsApp and my website."},
        {"key": "current_stage", "label": "Where are you now?", "help": "Starting, already selling, or already running ads.", "placeholder": "Ex: I sell already, but ads confuse me."},
        {"key": "biggest_blocker", "label": "What blocks you today?", "help": "The thing that worries you most.", "placeholder": "Ex: I do not know what to pause or scale."},
        {"key": "success_goal", "label": "What would be a win?", "help": "Something clear for the next 30 days.", "placeholder": "Ex: lower purchase cost or sell 20 more units."},
    ]


def normalize_business_context_questions(value, business_type="", language="es"):
    questions = []
    seen = set()
    for item in value if isinstance(value, list) else []:
        if not isinstance(item, dict):
            continue
        key = re.sub(r"[^a-z0-9_]+", "_", str(item.get("key") or "").strip().lower()).strip("_")
        if key not in BUSINESS_QUESTION_FIELDS or key in seen:
            continue
        label = str(item.get("label") or "").strip()
        help_text = str(item.get("help") or "").strip()
        placeholder = str(item.get("placeholder") or "").strip()
        if not label:
            continue
        questions.append({
            "key": key,
            "label": label[:90],
            "help": help_text[:180] or ("Respuesta corta." if language != "en" else "Short answer."),
            "placeholder": placeholder[:180],
        })
        seen.add(key)
        if len(questions) >= 6:
            break
    required = ["main_offer", "ideal_customer", "current_stage", "what_to_improve"]
    existing = {question["key"] for question in questions}
    fallback = default_business_context_questions(business_type, language)
    for key in required:
        if key in existing:
            continue
        match = next((question for question in fallback if question["key"] == key), None)
        if match:
            questions.append(match)
            existing.add(key)
    if len(questions) < 4:
        return fallback
    return questions[:6]


def generate_business_context_questions(payload):
    language = str((payload or {}).get("language") or "es").lower()
    if language not in {"es", "en"}:
        language = "es"
    profile = read_json(BUSINESS_PROFILE_FILE, {})
    if not isinstance(profile, dict):
        profile = {}
    business_type = str((payload or {}).get("business_type") or (payload or {}).get("business_short") or "").strip()
    website_url = str((payload or {}).get("website_url") or "").strip()
    extra_context = str((payload or {}).get("context") or "").strip()
    if not business_type:
        raise ValueError("Escribe en pocas palabras qué tipo de negocio tienes.")
    profile["business_type"] = business_type[:220]
    profile["business_short"] = business_type[:220]
    profile["onboarding_questions_started"] = True
    if website_url:
        normalized_url = normalize_website_url(website_url)
        validate_public_website_url(normalized_url)
        profile["website_url"] = normalized_url
        profile["website_skipped"] = False
        save_setup_config({"landing_url": normalized_url})
    else:
        profile["website_skipped"] = True
    config = load_config()
    questions = []
    source = "fallback_questions"
    agent_detail = ""
    model_ready = False
    if config.agent_chat_provider == "hermes":
        model_ready, agent_detail = hermes_codex_ready(config)
    else:
        model_ready = bool(config.agent_chat_api_key and config.agent_chat_base_url and config.agent_chat_model)
    if model_ready:
        message = (
            "Eres un manager experto de Meta Ads para compradores principiantes. "
            "Crea preguntas de onboarding tipo Typeform, una pregunta a la vez, para entender este negocio antes de mostrar el dashboard. "
            "Si hay web, puedes usar browser/retrieval para entenderla, pero no inventes datos delicados. "
            "Devuelve SOLO JSON valido con esta forma: "
            '{"questions":[{"key":"main_offer","label":"...","help":"...","placeholder":"..."}]}. '
            "Usa solo estas keys cuando apliquen: main_offer, ideal_customer, sales_channel, current_stage, current_ads, biggest_blocker, what_to_improve, success_goal, budget_comfort, brand_tone. "
            "Haz 5 o 6 preguntas maximo. Lenguaje para una persona de 8 años: corto, claro, sin jerga. "
            "La primera pregunta debe confirmar qué vende. Incluye current_stage y what_to_improve. "
            f"Idioma: {'español latino' if language == 'es' else 'English'}.\n"
            f"Tipo de negocio dicho por el comprador: {business_type}\n"
            f"Web: {profile.get('website_url') or 'sin web'}\n"
            f"Contexto extra: {extra_context or 'sin contexto'}"
        )
        result = agent_chat(
            config,
            {
                "message": message,
                "language": language,
                "metrics": {},
                "recommendations": [],
                "fatigue": [],
                "pending": [],
                "business_profile": profile,
                "brand_guides": {},
                "channel": "onboarding_business_questions",
            },
        )
        parsed = extract_json_object_from_text(result.get("raw_reply") or result.get("reply") or "") if result.get("ok") and not result.get("fallback") else {}
        questions = normalize_business_context_questions(parsed.get("questions"), business_type, language)
        source = "agent_questions" if parsed.get("questions") else "fallback_questions"
        agent_detail = str(result.get("error") or result.get("reply") or agent_detail or "")[:300]
    else:
        questions = default_business_context_questions(business_type, language)
    profile["onboarding_questions"] = questions
    profile["onboarding_questions_source"] = source
    profile["agent_questions_detail"] = agent_detail
    profile["updated_at"] = now_iso()
    profile.setdefault("source", "manual_context")
    write_json(BUSINESS_PROFILE_FILE, profile)
    log_action("business_questions_generate", {"business_type": business_type, "website_url": profile.get("website_url", ""), "source": source, "count": len(questions)}, "completed")
    return {"saved": True, "profile": profile, "questions": questions, "source": source}


