def scan_business_website(payload):
    url = normalize_website_url(payload.get("website_url"))
    context = str(payload.get("current_stage") or "").strip()
    if not url:
        raise ValueError("Escribe la web de tu negocio.")
    validate_public_website_url(url)
    request = urllib.request.Request(
        url,
        headers={"User-Agent": "MetaAdsAgentWebsiteScanner/1.0 (+local onboarding)"},
        method="GET",
    )
    try:
        opener = urllib.request.build_opener(SafeWebsiteRedirectHandler)
        with opener.open(request, timeout=15) as response:
            validate_public_website_url(response.geturl())
            body = response.read(350000).decode(response.headers.get_content_charset() or "utf-8", errors="ignore")
    except Exception as exc:
        profile = {
            "website_url": url,
            "business_type": "negocio por definir",
            "offer": "oferta por definir",
            "main_offer": "oferta por definir",
            "audience": "audiencia por definir",
            "ideal_customer": "audiencia por definir",
            "current_stage": context,
            "what_to_improve": "Preparar una primera lectura clara del negocio y convertirla en anuncios simples.",
            "positioning": "",
            "detected_title": "",
            "detected_headings": [],
            "suggested_angles": [
                "Claridad: explicar la oferta en una frase simple.",
                "Confianza: mostrar prueba o razón para creer.",
                "Acción: llevar a una sola acción clara.",
            ],
            "initial_plan": [
                "Completar la conexión de Meta.",
                "Contarle al agente qué vendes y qué quieres mejorar.",
                "Preparar una primera campaña en pausa.",
            ],
            "source": "manual_context",
            "scan_error": str(exc)[:300],
            "created_at": now_iso(),
        }
    else:
        parser = WebsiteSummaryParser()
        parser.feed(body)
        profile = infer_business_profile(url, parser, context)
    profile, source = enrich_business_profile_with_agent(url, profile, context)
    profile["source"] = source or profile.get("source") or "website_scan_basic"
    profile["onboarding_questions_started"] = True
    profile["onboarding_questions"] = normalize_business_context_questions(profile.get("onboarding_questions") or [], profile.get("business_type") or "", "es")
    write_json(BUSINESS_PROFILE_FILE, profile)
    save_setup_config({"landing_url": url})
    log_action("business_website_scan", {"website_url": url, "source": profile.get("source"), "scan_error": profile.get("scan_error", "")}, "completed" if not profile.get("scan_error") else "warn")
    return {"saved": True, "profile": profile}


def active_meta_page_id():
    """Return the durably selected Page without polling OAuth or Graph."""
    connection = _meta_oauth_connection()
    return str(connection.get("active_page_id") or "").strip()


def _profile_scope_page_id(strategic):
    return str(((strategic or {}).get("scope") or {}).get("page_id") or "").strip()


def strategic_profile_for_page(profile=None, page_id="", activate=False):
    """Resolve one Page-scoped profile while preserving profiles for other Pages.

    Reads never silently reinterpret one business as another.  A confirmed
    Page switch may activate an archived profile for that same Page, or create
    a fresh empty profile while keeping the prior Page profile in the archive.
    """
    profile = profile if isinstance(profile, dict) else read_json(BUSINESS_PROFILE_FILE, {})
    if not isinstance(profile, dict):
        profile = {}
    page_id = str(page_id or active_meta_page_id()).strip()
    current_raw = profile.get("strategic_profile")
    current = migrate_strategic_profile(current_raw if isinstance(current_raw, dict) else profile, page_id=page_id)
    current_page = _profile_scope_page_id(current)
    if not page_id or not current_page or current_page == page_id:
        return current

    archived = profile.get("strategic_profiles") if isinstance(profile.get("strategic_profiles"), dict) else {}
    candidate = archived.get(page_id)
    if not activate:
        # Preserve the mismatch so readiness fails closed until the selected
        # Page is deliberately activated in the business-memory write path.
        return current

    archived = dict(archived)
    archived[current_page] = current
    selected = migrate_strategic_profile(candidate, page_id=page_id) if isinstance(candidate, dict) else new_strategic_profile(page_id)
    profile["strategic_profiles"] = archived
    profile["strategic_profile"] = selected
    return selected


def strategic_business_profile_readiness(profile=None, page_id=""):
    profile = profile if isinstance(profile, dict) else read_json(BUSINESS_PROFILE_FILE, {})
    if not isinstance(profile, dict):
        profile = {}
    page_id = str(page_id or active_meta_page_id()).strip()
    strategic = strategic_profile_for_page(profile, page_id=page_id, activate=False)
    return strategic_profile_readiness(strategic, active_page_id=page_id)


def strategic_product_action_eligibility(action_category, profile=None, page_id=""):
    profile = profile if isinstance(profile, dict) else read_json(BUSINESS_PROFILE_FILE, {})
    if not isinstance(profile, dict):
        profile = {}
    page_id = str(page_id or active_meta_page_id()).strip()
    strategic = strategic_profile_for_page(profile, page_id=page_id, activate=False)
    category = str(action_category or "").strip().lower()
    # Logo candidates, moodboards and other brand exploration are part of
    # onboarding itself.  They must not depend on the *completed* strategic
    # profile, otherwise the UI advertises Image during onboarding while this
    # second gate makes it impossible to use.  The smaller, purpose-specific
    # brand_exploration_readiness() gate still enforces the actual inputs
    # needed to create a useful brand asset.
    if category == "brand_exploration":
        return {
            "allowed": True,
            "code": "brand_exploration_allowed_during_onboarding",
            "profile_status": strategic.get("status") or "collecting",
            "revision": strategic.get("revision"),
            "confirmed_revision": strategic.get("confirmed_revision"),
            "unresolved_topics": [],
        }
    decision = strategic_profile_action_eligibility(
        strategic,
        active_page_id=page_id,
        action_category=action_category,
    )
    if not decision.get("allowed"):
        return decision
    if category in {
        "campaign_create", "campaign_edit", "campaign_brief", "campaign_activate",
        "spend_increase", "paid_creative", "organic_creative", "organic_publish",
        "ad_motion_graphics",
    }:
        branding = branding_creative_readiness(require_product=False, payload=None)
        if not branding.get("ready"):
            return {
                "allowed": False,
                "code": "branding_required",
                "profile_status": decision.get("profile_status") or "complete",
                "revision": decision.get("revision"),
                "confirmed_revision": decision.get("confirmed_revision"),
                "unresolved_topics": [item.get("key") for item in branding.get("missing") or []],
                "next_question": branding.get("next_question") or "Antes de producir, terminemos juntos el branding y el logo.",
            }
    return decision


def _trusted_buyer_turn_unlocked(max_age_seconds=300):
    turn = read_json(TRUSTED_BUYER_TURN_FILE, {})
    if not isinstance(turn, dict) or not str(turn.get("message") or "").strip():
        return {}
    try:
        created = datetime.fromisoformat(str(turn.get("created_at") or "").replace("Z", "+00:00"))
    except ValueError:
        return {}
    if created.tzinfo is None:
        created = created.replace(tzinfo=timezone.utc)
    if (datetime.now(timezone.utc) - created.astimezone(timezone.utc)).total_seconds() > max_age_seconds:
        return {}
    try:
        transport = _trusted_turn_transport(turn.get("transport"), turn.get("chat_id"))
    except ValueError:
        return {}
    turn_chat = str(turn.get("chat_id") or "").strip()
    if transport == "telegram":
        configured_chat = _meta_oauth_chat_id(load_config())
        if configured_chat and turn_chat and configured_chat != turn_chat:
            return {}
    elif not turn_chat.startswith(f"{transport}:"):
        return {}
    capabilities = turn.get("capabilities")
    if not isinstance(capabilities, dict):
        # Pre-upgrade files do not carry a one-use authorization lifecycle.
        return {}
    return turn


def _trusted_buyer_turn(max_age_seconds=300):
    with _trusted_buyer_turn_lock():
        return _trusted_buyer_turn_unlocked(max_age_seconds=max_age_seconds)


def _normalized_confirmation_text(value):
    text = unicodedata.normalize("NFKD", str(value or "").casefold())
    text = "".join(ch for ch in text if not unicodedata.combining(ch))
    return re.sub(r"\s+", " ", re.sub(r"[^a-z0-9 ]+", " ", text)).strip()


def trusted_profile_review_confirmation(turn=None):
    """Recognize a natural review answer only from server-recorded buyer text."""
    turn = turn if isinstance(turn, dict) else _trusted_buyer_turn()
    text = _normalized_confirmation_text(turn.get("message"))
    if not text:
        return False, {}
    no_changes = re.search(
        r"\bno (?:hay|tengo|haria|cambiaria) (?:cambios|correcciones|ajustes|nada)\b",
        text,
    )
    correction = re.search(
        r"\b(?:pero|excepto|salvo|cambi\w*|corrig\w*|ajust\w*|incorrect\w*|"
        r"equivoc\w*|falta\w*|not correct|change|except|wrong)\b",
        text,
    )
    negative_start = re.match(r"^no\b", text) and not no_changes
    if (correction and not no_changes) or negative_start:
        return False, turn
    affirmative = bool(re.search(
        r"(?:^|\b)(?:si+|sip|confirm\w*|correct\w*|todo bien|de acuerdo|esta bien|"
        r"me parece bien|asi esta bien|asi es|quedo bien|perfecto|perfecta|aprobado|"
        r"aprobada|adelante|listo|ok|okay|yes|looks good|all correct)(?:\b|$)",
        text,
    ))
    return affirmative, turn


def _canonical_buyer_evidence(value):
    """Canonicalize transport text without paraphrasing or correcting it."""
    return re.sub(r"\s+", " ", unicodedata.normalize("NFKC", str(value or ""))).strip()


def _short_natural_confirmation(value):
    normalized = _normalized_confirmation_text(value)
    if not normalized or len(normalized.split()) > 8:
        return False
    no_changes = re.search(
        r"\bno (?:hay|tengo|haria|cambiaria) (?:cambios|correcciones|ajustes|nada)\b",
        normalized,
    )
    correction = re.search(
        r"\b(?:pero|excepto|salvo|cambi\w*|corrig\w*|ajust\w*|incorrect\w*|"
        r"equivoc\w*|falta\w*|change|except|wrong)\b",
        normalized,
    )
    if correction and not no_changes:
        return False
    return bool(re.search(
        r"(?:^|\b)(?:si+|sip|confirm\w*|correct\w*|todo bien|de acuerdo|esta bien|"
        r"me parece bien|asi esta bien|asi es|perfecto|perfecta|aprobado|aprobada|"
        r"adelante|listo|ok|okay|yes|looks good|all correct)(?:\b|$)",
        normalized,
    ))


def _lifecycle_confirmation(target, artifact_text, buyer_message, config=None):
    """Classify one later buyer reply, failing closed on all uncertainty."""
    raw = _canonical_buyer_evidence(buyer_message)
    if not raw:
        return False, "empty"
    # Cheap local recognition is useful when the independent worker is not
    # available.  It never overrides a correction or a scope/binding check.
    if _non_authorizing_buyer_message(raw):
        return False, "non_authorizing"
    if _short_natural_confirmation(raw):
        return True, "local_short_confirmation"
    try:
        result = classify_lifecycle_transition(
            str(target), str(artifact_text or ""), raw, config=config
        )
    except Exception:
        return False, "classifier_error"
    if not isinstance(result, dict):
        return False, "classifier_invalid"
    value = str(
        result.get("confirmation")
        or result.get("confirmacion")
        or result.get("confirmed")
        or result.get("confirmacion_transicion")
        or result.get("decision")
        or ""
    ).strip().lower()
    if value in {"si", "sí", "yes", "true", "confirmed", "confirmado"}:
        return True, "semantic_classifier"
    return False, str(result.get("reason") or "not_confirmed")


def _strategic_plan_update_requested(current_plan, buyer_message, config=None):
    """Fail closed unless this exact buyer turn asks to alter the saved plan."""
    raw = _canonical_buyer_evidence(buyer_message)
    if not raw or not isinstance(current_plan, dict) or not current_plan:
        return False, "missing_plan_or_buyer_message"
    try:
        result = classify_strategic_plan_update_request(
            render_business_strategic_plan(current_plan),
            raw,
            config=config,
        )
    except Exception:
        return False, "classifier_error"
    if not isinstance(result, dict):
        return False, "classifier_invalid"
    value = str(
        result.get("confirmation")
        or result.get("solicitud_actualizacion_plan")
        or result.get("decision")
        or ""
    ).strip().lower()
    if value in {"si", "sí", "yes", "true"}:
        return True, "explicit_buyer_plan_update_request"
    return False, str(result.get("reason") or "plan_update_not_requested")


def _non_authorizing_buyer_message(value):
    normalized = _normalized_confirmation_text(value)
    return bool(re.fullmatch(
        r"(?:hola|hol+a|hello|hi|hey|buenas|buenos dias|buenas tardes|buenas noches|"
        r"como estas|que tal|gracias|muchas gracias|que|como|por que|porque)",
        normalized,
    ))


_MEMORY_AUTH_INTERNAL_FIELDS = {
    "confirmation_state",
    "buyer_evidence",
    "confirm_profile_review",
    "profile_review_confirmation",
    "confirm_strategic_profile",
    "confirm_master_plan",
}

_MASTER_PLAN_FIELDS = (
    "advertising_opportunity",
    "audience_and_message",
    "campaign_and_creative_plan",
    "budget_and_measurement",
    "next_steps_and_questions",
)

_MASTER_PLAN_LABELS = {
    "advertising_opportunity": "Oportunidad publicitaria",
    "audience_and_message": "Audiencia y mensaje",
    "campaign_and_creative_plan": "Campaña y conceptos creativos",
    "budget_and_measurement": "Presupuesto y medición",
    "next_steps_and_questions": "Próximos pasos para pulirlo",
}


def _normalize_master_plan(value):
    if not isinstance(value, dict):
        return {}
    normalized = {}
    for field in _MASTER_PLAN_FIELDS:
        item = value.get(field)
        if item in (None, "", [], {}):
            continue
        if isinstance(item, str):
            # Preserve the compiler's readable paragraphs/bullets. Collapsing
            # everything into one line made a complete plan look like a terse
            # campaign note when it reached Telegram.
            lines = [re.sub(r"[ \t]+", " ", line).strip() for line in item.splitlines()]
            normalized[field] = "\n".join(lines).strip()[:420]
        else:
            normalized[field] = redact_payload(item)
    return normalized


def business_master_plan_for_page(profile, page_id=None):
    page_id = str(page_id or active_meta_page_id() or "").strip()
    plans = (profile or {}).get("business_master_plans")
    plan = plans.get(page_id) if isinstance(plans, dict) else None
    return dict(plan) if isinstance(plan, dict) else {}


def business_master_plan_readiness(profile=None, page_id=None):
    profile = profile if isinstance(profile, dict) else read_json(BUSINESS_PROFILE_FILE, {})
    page_id = str(page_id or active_meta_page_id() or "").strip()
    strategic = strategic_profile_for_page(profile, page_id=page_id, activate=False) if page_id else {}
    strategic_ready = strategic_profile_readiness(strategic, active_page_id=page_id) if strategic else {}
    plan = business_master_plan_for_page(profile, page_id)
    current_revision = int(strategic_ready.get("revision") or 0)
    stored_status = str(plan.get("status") or "").strip().lower()
    confirmed = stored_status == "confirmed"
    material = (
        plan.get("content") if confirmed
        else plan.get("draft")
    )
    material = material if isinstance(material, dict) else {}
    missing_fields = [
        field for field in _MASTER_PLAN_FIELDS
        if material.get(field) in (None, "", [], {})
    ]
    material_complete = not missing_fields
    # ``profile_revision`` is provenance only. New services, prices or other
    # business facts must not silently alter or invalidate an approved plan.
    # The plan changes state only when the buyer explicitly asks to revise the
    # plan and the backend stores a proposal/stale transition for that request.
    stale = stored_status == "stale"
    plan_complete = bool(confirmed and material_complete)
    if not plan or not material_complete:
        effective_status = "missing"
    elif stale:
        effective_status = "stale"
    elif confirmed:
        effective_status = "confirmed"
    else:
        effective_status = "proposed"
    return {
        "status": effective_status,
        "ready": bool(confirmed and not stale and plan_complete and strategic_ready.get("complete")),
        "stale": stale,
        "complete": plan_complete,
        "missing_fields": missing_fields,
        "profile_revision": current_revision,
        "plan_revision": int(plan.get("revision") or 0),
        "draft_revision": int(plan.get("draft_revision") or 0),
        "draft_hash": str(plan.get("draft_hash") or ""),
        "presented": bool(_plan_presentation_matches_current_draft(plan)),
        "plan": plan,
    }


def _canonical_memory_value(value):
    if isinstance(value, dict):
        return {
            str(key): _canonical_memory_value(item)
            for key, item in sorted(value.items(), key=lambda pair: str(pair[0]))
            if key not in _MEMORY_AUTH_INTERNAL_FIELDS and item not in (None, "", [], {})
        }
    if isinstance(value, (list, tuple, set)):
        return [_canonical_memory_value(item) for item in value]
    if isinstance(value, str):
        return _normalized_confirmation_text(value)
    return value


def _memory_payload_for_match(payload):
    return _canonical_memory_value({
        key: value
        for key, value in dict(payload or {}).items()
        if key not in _MEMORY_AUTH_INTERNAL_FIELDS and value not in (None, "", [], {})
    })


def _saved_memory_draft_matches(kind, payload, scope):
    submitted = _memory_payload_for_match(payload)
    if not submitted:
        return False
    library = read_json(MEMORY_DRAFTS_FILE, {"items": []})
    items = library.get("items") if isinstance(library, dict) else []
    candidates = [
        item for item in (items or [])
        if isinstance(item, dict)
        and str(item.get("kind") or "") == str(kind or "")
        and str(item.get("scope") or "") == str(scope or "")
    ]
    candidates.sort(key=lambda item: str(item.get("updated_at") or ""), reverse=True)
    for candidate in candidates:
        draft = _memory_payload_for_match(candidate.get("payload") or {})
        if submitted == draft:
            return True
    return False


def _official_brand_payload_matches(payload, scope):
    """Return whether a brand save is already represented by official memory.

    This is deliberately stricter than merely matching the brand name: every
    submitted canonical brand field must already have the same value in the
    official guide.  It exists so a short natural acknowledgement can be an
    idempotent confirmation of an identity that was already saved, without
    granting authority to introduce any new or changed brand fact.
    """
    active_page = active_meta_page_id()
    if scope and active_page and str(scope) != str(active_page):
        return False
    library = guide_library()
    if not library.get("general_exists"):
        return False
    official = ((library.get("general") or {}).get("fields") or {})
    submitted = normalize_general_payload(payload or {})
    comparable = {
        key: value
        for key, value in submitted.items()
        if key in official
        and key not in _MEMORY_AUTH_INTERNAL_FIELDS
        and value not in (None, "", [], {})
    }
    if not comparable:
        return False
    anchor_fields = ("brand_name", "offer", "logo_path")
    if not any(
        key in comparable
        and _canonical_memory_value(comparable.get(key))
        == _canonical_memory_value(official.get(key))
        for key in anchor_fields
    ):
        return False
    return all(
        official.get(key) not in (None, "", [], {})
        and _canonical_memory_value(value)
        == _canonical_memory_value(official.get(key))
        for key, value in comparable.items()
    )


def _business_profile_draft_matches(profile, payload, page_id):
    if payload.get("confirm_master_plan"):
        plan = business_master_plan_for_page(profile, page_id)
        return bool(plan.get("draft") and str(plan.get("status") or "") == "proposed")
    strategic = strategic_profile_for_page(profile, page_id=page_id, activate=True)
    updates = _strategic_topic_updates(payload)
    if not updates:
        return False
    topics = strategic.get("topics") if isinstance(strategic.get("topics"), dict) else {}
    for topic, update in updates.items():
        current = topics.get(topic) if isinstance(topics.get(topic), dict) else {}
        draft = current.get("draft") if isinstance(current.get("draft"), dict) else {}
        if not draft:
            return False
        submitted_status = str(update.get("status") or "confirmed")
        draft_status = str(draft.get("proposed_status") or "confirmed")
        if submitted_status != draft_status:
            return False
        if _canonical_memory_value(update.get("value")) != _canonical_memory_value(draft.get("value")):
            return False
    return True


@contextlib.contextmanager
def _trusted_memory_capability(kind, payload, *, scope="", profile=None):
    """Reserve one current-turn store capability and consume it on commit.

    The private nonce never enters an MCP response. A short acknowledgement
    may promote only the exact draft already shown to the buyer, or acknowledge
    an unchanged official brand idempotently. A substantive natural-language
    answer remains flexible and is interpreted by the model, but its full raw
    text must be copied into ``buyer_evidence``.
    """
    kind = str(kind or "").strip()
    claimed = str((payload or {}).get("confirmation_state") or "inferred").strip().lower()
    authorization = {
        "authorized": False,
        "commit": False,
        "reason": "confirmation_state_not_buyer_confirmed",
        "turn": {},
    }
    with _trusted_buyer_turn_lock():
        turn = _trusted_buyer_turn_unlocked()
        authorization["turn"] = turn
        capability = (
            (turn.get("capabilities") or {}).get(kind)
            if isinstance(turn, dict)
            else None
        )
        if claimed == "buyer_confirmed":
            evidence = _canonical_buyer_evidence((payload or {}).get("buyer_evidence"))
            exact_message = _canonical_buyer_evidence(turn.get("message") if turn else "")
            if not turn:
                authorization["reason"] = "missing_current_trusted_buyer_turn"
            elif not evidence or not hmac.compare_digest(
                evidence.encode("utf-8"),
                exact_message.encode("utf-8"),
            ):
                authorization["reason"] = "buyer_evidence_not_exact_current_message"
            elif not isinstance(capability, dict) or not str(capability.get("nonce") or ""):
                authorization["reason"] = "trusted_turn_capability_unavailable"
            elif capability.get("used"):
                authorization["reason"] = "trusted_turn_capability_already_used"
            elif _non_authorizing_buyer_message(exact_message):
                authorization["reason"] = "buyer_message_does_not_confirm_memory"
            elif _short_natural_confirmation(exact_message) and kind != "profile_review":
                if kind == "business":
                    draft_matches = _business_profile_draft_matches(
                        profile or {}, payload, scope
                    )
                else:
                    draft_matches = _saved_memory_draft_matches(kind, payload, scope)
                official_brand_matches = bool(
                    kind == "brand"
                    and _official_brand_payload_matches(payload, scope)
                )
                if not draft_matches and not official_brand_matches:
                    authorization["reason"] = "short_confirmation_has_no_matching_draft"
                else:
                    authorization["authorized"] = True
                    authorization["reason"] = (
                        "official_brand_already_confirmed"
                        if official_brand_matches and not draft_matches
                        else "matching_draft_confirmed"
                    )
            else:
                authorization["authorized"] = True
                authorization["reason"] = "current_buyer_evidence_verified"
        try:
            yield authorization
        finally:
            if authorization.get("authorized") and authorization.get("commit"):
                latest = _trusted_buyer_turn_unlocked()
                latest_capability = (
                    (latest.get("capabilities") or {}).get(kind)
                    if isinstance(latest, dict)
                    else None
                )
                if (
                    latest.get("message_hash") == turn.get("message_hash")
                    and isinstance(latest_capability, dict)
                    and hmac.compare_digest(
                        str(latest_capability.get("nonce") or ""),
                        str(capability.get("nonce") or ""),
                    )
                    and not latest_capability.get("used")
                ):
                    latest_capability["used"] = True
                    latest_capability["used_at"] = now_iso()
                    write_private_json(TRUSTED_BUYER_TURN_FILE, latest)


_STRATEGIC_REVIEW_LABELS = {
    "services": "Servicios y productos",
    "ideal_customer": "Cliente ideal",
    "differentiators": "Diferenciadores y prueba",
    "markets": "Mercados y ubicaciones",
    "capacity": "Capacidad y restricciones",
    "pricing": "Precios",
    "margins": "Costos y márgenes",
    "global_objectives": "Objetivos globales",
    "advertising_experience": "Experiencia publicitaria",
    "branding": "Marca y activos",
}
_STRATEGIC_REVIEW_STATUSES = {
    "confirmed": "confirmado",
    "provisional_confirmed": "confirmado provisionalmente",
    "unknown": "desconocido",
    "not_applicable": "no aplica",
    "withheld": "reservado por el comprador",
}


def _strategic_review_value(entry):
    status = str((entry or {}).get("status") or "")
    value = (entry or {}).get("value")
    if value in (None, "", [], {}):
        value = _STRATEGIC_REVIEW_STATUSES.get(status, status or "sin dato")
    elif isinstance(value, str):
        value = value.strip()
    else:
        value = json.dumps(value, ensure_ascii=False, sort_keys=True)
    return re.sub(r"\s+", " ", str(value or "")).strip()[:320]


def business_profile_review_summary(profile):
    canonical = migrate_strategic_profile(profile)
    revision = int(canonical.get("revision") or 0)
    lines = [f"Resumen del negocio — revisión {revision}"]
    topics = canonical.get("topics") if isinstance(canonical.get("topics"), dict) else {}
    for topic in STRATEGIC_PROFILE_TOPICS:
        entry = topics.get(topic) if isinstance(topics.get(topic), dict) else {}
        label = _STRATEGIC_REVIEW_LABELS[topic]
        status = _STRATEGIC_REVIEW_STATUSES.get(str(entry.get("status") or ""), "pendiente")
        lines.append(f"- {label} [{status}]: {_strategic_review_value(entry)}")
    lines.append("Puedes corregir cualquier punto o confirmar este resumen del negocio con tus propias palabras.")
    return "\n".join(lines)


def strategic_profile_review_summary(profile):
    """Compatibility alias; new user-facing text uses the business label."""
    return business_profile_review_summary(profile)


def _assistant_summary_covers_strategic_profile(profile, assistant_text):
    """Require every label/status/value line, never labels alone."""
    normalized_output = _normalized_confirmation_text(assistant_text)
    if not normalized_output:
        return False
    return all(
        _normalized_confirmation_text(line) in normalized_output
        for line in business_profile_review_summary(profile).splitlines()[1:-1]
    )


def ensure_canonical_strategic_review_visible(assistant_text):
    """Append the canonical review only when the agent is already requesting it.

    The model may naturally combine several topics into fewer buyer-friendly
    bullets.  That is fine conversationally, but the confirmation transaction
    must bind to every current official value.  At the finalized outbound
    boundary, add the canonical server-owned summary if (and only if) the
    agent's own response clearly presents a strategic review and asks the
    buyer to confirm or correct it.  Ordinary onboarding replies are untouched.
    """
    text = str(assistant_text or "")
    normalized = _normalized_confirmation_text(text)
    review_intent = bool(
        (
            re.search(r"\b(?:resumen|perfil|revision) estrateg\w*\b", normalized)
            or re.search(
                r"\b(?:resumen|perfil|revision|base) (?:del )?negocio\b",
                normalized,
            )
        )
        and re.search(
            r"\b(?:confirm\w*|correg\w*|correccion\w*|ajust\w*|correct\w*)\b",
            normalized,
        )
    )
    if not review_intent:
        return text
    page_id = active_meta_page_id()
    profile = read_json(BUSINESS_PROFILE_FILE, {})
    if not page_id or not isinstance(profile, dict):
        return text
    strategic = strategic_profile_for_page(profile, page_id=page_id, activate=False)
    readiness = strategic_profile_readiness(strategic, active_page_id=page_id)
    if not readiness.get("review_required"):
        return text
    if _assistant_summary_covers_strategic_profile(strategic, text):
        return text
    canonical = business_profile_review_summary(strategic)
    # Replace an incomplete model artifact instead of sending two competing
    # summaries.  The model's useful prose is retained only as a short intro.
    intro = "He consolidado el resumen actual del negocio para revisarlo contigo:"
    return f"{intro}\n\n{canonical}".strip()


def record_strategic_review_presented(session_id, assistant_text, chat_id=""):
    """Bind an actually finalized outbound summary to the current revision."""
    with _trusted_buyer_turn_lock():
        turn = _trusted_buyer_turn_unlocked()
        if not turn:
            return {"recorded": False, "reason": "missing_current_trusted_buyer_turn"}
        if str(session_id or "").strip() != str(turn.get("session_id") or "").strip():
            return {"recorded": False, "reason": "review_session_mismatch"}
        if chat_id and str(chat_id).strip() != str(turn.get("chat_id") or "").strip():
            return {"recorded": False, "reason": "review_chat_mismatch"}
        page_id = active_meta_page_id()
        profile = read_json(BUSINESS_PROFILE_FILE, {})
        if not page_id or not isinstance(profile, dict):
            return {"recorded": False, "reason": "strategic_profile_scope_unavailable"}
        strategic = strategic_profile_for_page(profile, page_id=page_id, activate=False)
        readiness = strategic_profile_readiness(strategic, active_page_id=page_id)
        if not readiness.get("review_required"):
            return {"recorded": False, "reason": "review_not_ready"}
        if not _assistant_summary_covers_strategic_profile(strategic, assistant_text):
            return {"recorded": False, "reason": "review_summary_incomplete"}
        message_hash = hashlib.sha256(
            str(assistant_text or "").encode("utf-8", errors="replace")
        ).hexdigest()
        strategic = mark_strategic_profile_review_presented(
            strategic,
            page_id=page_id,
            after_buyer_message_sequence=turn.get("message_sequence"),
            assistant_message_hash=message_hash,
            evidence={
                "source": "finalized_outbound_transport",
                "chat_id": str(turn.get("chat_id") or ""),
                "session_id": str(turn.get("session_id") or ""),
                "transport": str(turn.get("transport") or ""),
                "message_sequence": turn.get("message_sequence"),
                "trusted_server_evidence": True,
            },
        )
        profile = embed_strategic_profile(profile, strategic)
        profile["updated_at"] = now_iso()
        write_json(BUSINESS_PROFILE_FILE, profile)
        return {
            "recorded": True,
            "revision": strategic.get("revision"),
            "message_sequence": turn.get("message_sequence"),
        }


def _plan_content_hash(content):
    canonical = json.dumps(content or {}, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
    return hashlib.sha256(canonical.encode("utf-8")).hexdigest()


def _master_plan_missing_fields(content):
    content = content if isinstance(content, dict) else {}
    return [
        field for field in _MASTER_PLAN_FIELDS
        if content.get(field) in (None, "", [], {})
    ]


def _master_plan_is_complete(content):
    return bool(isinstance(content, dict) and not _master_plan_missing_fields(content))


def _master_plan_record_is_complete(plan):
    """Return whether an existing record is safe to preserve as a real plan.

    Old releases could leave partial ``confirmed``/``proposed`` dictionaries.
    The runtime correctly treats those as missing; the compiler must do the
    same so an upgrade can repair them instead of being stranded forever.
    """
    if not isinstance(plan, dict) or not plan:
        return False
    status = str(plan.get("status") or "").strip().lower()
    if status == "confirmed":
        material = plan.get("content")
    elif status == "stale":
        material = plan.get("draft") or plan.get("content")
    else:
        material = plan.get("draft") or plan.get("content")
    return _master_plan_is_complete(material)


def _strategic_plan_generation_time(value):
    try:
        parsed = datetime.fromisoformat(str(value or "").replace("Z", "+00:00"))
    except (TypeError, ValueError):
        return None
    if parsed.tzinfo is None:
        parsed = parsed.replace(tzinfo=timezone.utc)
    return parsed.astimezone(timezone.utc)


def _strategic_plan_business_source(profile, strategic, page_id, account_id=""):
    """Collect the single-business memory set for isolated plan compilation."""
    topics = {}
    for topic in STRATEGIC_PROFILE_TOPICS:
        item = (strategic.get("topics") or {}).get(topic)
        if isinstance(item, dict) and item.get("value") not in (None, "", [], {}):
            topics[topic] = {"status": str(item.get("status") or ""), "value": item.get("value")}
    meta_assets = profile.get("meta_assets") if isinstance(profile.get("meta_assets"), dict) else {}
    meta_page = profile.get("meta_page_profile") if isinstance(profile.get("meta_page_profile"), dict) else {}
    page_name = str(meta_page.get("name") or meta_assets.get("page_name") or "").strip()
    try:
        library = guide_library()
    except Exception:
        library = {}
    general = library.get("general") if isinstance(library.get("general"), dict) else {}
    general_fields = general.get("fields") if isinstance(general.get("fields"), dict) else {}
    products = []
    for item in library.get("products") or []:
        if isinstance(item, dict):
            products.append({"id": str(item.get("id") or ""), "name": str(item.get("name") or ""), "fields": item.get("fields") if isinstance(item.get("fields"), dict) else {}})
    ad_briefs = []
    for item in library.get("ad_briefs") or []:
        if isinstance(item, dict):
            ad_briefs.append({"id": str(item.get("id") or ""), "name": str(item.get("name") or ""), "fields": item.get("fields") if isinstance(item.get("fields"), dict) else {}})
    try:
        ads_onboarding = ADS_ONBOARDING_FILE.read_text(encoding="utf-8")[:24000]
    except OSError:
        ads_onboarding = ""
    audience_strategy = read_json(AUDIENCE_FILE, {})
    profitability_context = decision_memory_payload()
    source = {
        "page_scope": {"page_id": str(page_id), "page_name": page_name, "ad_account_id": clean_ad_account_id(account_id), "profile_revision": int(strategic.get("revision") or 0)},
        "confirmed_business_topics": topics,
        "public_business_context": {"website_url": str(profile.get("website_url") or ""), "social_links": profile.get("social_links") or [], "meta_page_profile": meta_page},
        "official_brand": general_fields,
        "official_products_and_services": products,
        "existing_campaign_briefs": ad_briefs,
        "ads_onboarding": ads_onboarding,
        "saved_audience_strategy": audience_strategy,
        "saved_profitability_context": profitability_context,
    }
    return redact_payload(source)


def _strategic_plan_live_meta_source(account_id="", timeout=90):
    """Fetch an all-time, read-only Meta snapshot for plan grounding."""
    account_id = clean_ad_account_id(account_id or current_configured_ad_account_id())
    account = managed_account_context(account_id)
    result_box = {}

    def fetch():
        try:
            result_box["result"] = refresh_real_metrics(
                account_id,
                reason="strategic_plan_compiler",
                date_preset="maximum",
                persist=False,
                include_breakdowns=False,
            )
        except Exception as exc:
            result_box["result"] = {
                "ok": False,
                "reason": "live_meta_sync_failed",
                "message": type(exc).__name__,
            }

    reader = threading.Thread(target=fetch, name="strategic-plan-meta-read", daemon=True)
    reader.start()
    reader.join(max(0.01, float(timeout or 0.01)))
    result = result_box.get("result")
    if not isinstance(result, dict):
        result = {
            "ok": False,
            "reason": "live_meta_sync_timeout",
            "message": "The bounded all-time Meta read did not finish before plan compilation.",
        }
    metrics = result.get("metrics") if isinstance(result.get("metrics"), dict) else {}
    campaigns = metrics.get("campaigns") if isinstance(metrics.get("campaigns"), list) else []
    adsets = metrics.get("adsets") if isinstance(metrics.get("adsets"), list) else []
    ads = metrics.get("ads") if isinstance(metrics.get("ads"), list) else []

    def status_counts(rows):
        counts = {}
        for row in rows:
            if not isinstance(row, dict):
                continue
            status = str(row.get("effective_status") or row.get("status") or "UNKNOWN").upper()
            counts[status] = counts.get(status, 0) + 1
        return counts

    source = {
        "verified": bool(result.get("ok")),
        "partial": bool(result.get("partial")),
        "reason": str(result.get("reason") or ""),
        "message": str(result.get("message") or "")[:500],
        "account": account,
        "account_id": str(result.get("account_id") or account_id or ""),
        "fetched_at": str(metrics.get("timestamp") or now_iso()),
        "metrics_range": metrics.get("metrics_range") or {},
        "data_quality": metrics.get("data_quality") or result.get("data_quality") or {},
        "inventory_totals": {
            "campaigns": len(campaigns),
            "adsets": len(adsets),
            "ads": len(ads),
            "campaign_statuses": status_counts(campaigns),
            "adset_statuses": status_counts(adsets),
            "ad_statuses": status_counts(ads),
        },
        # Campaigns are the strategic evidence. Keep a generous complete view
        # for normal accounts and declare any safety cap instead of silently
        # implying that a truncated inventory is exhaustive.
        "campaigns": campaigns[:500],
        "adsets": adsets[:750],
        "ads": ads[:1000],
        "inventory_truncated": {
            "campaigns": len(campaigns) > 500,
            "adsets": len(adsets) > 750,
            "ads": len(ads) > 1000,
        },
        "summary": metrics.get("summary") or {},
        "errors": result.get("errors") or [],
    }
    return redact_payload(source)


def _strategic_plan_attempts_for_storage(attempts):
    clean = []
    for attempt in attempts or []:
        if not isinstance(attempt, dict):
            continue
        clean.append({
            "provider": str(attempt.get("provider") or "")[:80],
            "model": str(attempt.get("model") or "")[:80],
            "reasoning_effort": str(attempt.get("reasoning_effort") or "")[:20],
            "ok": bool(attempt.get("ok")),
            "reason": str(attempt.get("reason") or "")[:120],
            "elapsed_ms": int(attempt.get("elapsed_ms") or 0),
        })
    return clean[:3]


def _strategic_plan_expected_turn_matches(turn, expected_turn):
    """Bind generation to the exact inbound event currently being handled."""
    if not isinstance(turn, dict) or not isinstance(expected_turn, dict):
        return False
    chat_id = str(expected_turn.get("chat_id") or "").strip()
    session_id = str(expected_turn.get("session_id") or "").strip()
    raw_message = str(expected_turn.get("raw_message") or "").strip()
    raw_transport = str(expected_turn.get("transport") or "").strip().lower().replace("-", "_")
    if not chat_id or not session_id or not raw_message:
        return False
    if raw_transport not in {"telegram", "dashboard", "simulated_telegram", "legacy_telegram"}:
        return False
    try:
        transport = _trusted_turn_transport(raw_transport, chat_id)
    except ValueError:
        return False
    for key, expected in (
        ("chat_id", chat_id),
        ("session_id", session_id),
        ("transport", transport),
        ("message", raw_message),
    ):
        if not hmac.compare_digest(
            str(turn.get(key) or "").encode("utf-8"),
            expected.encode("utf-8"),
        ):
            return False
    sequence = expected_turn.get("message_sequence")
    if sequence in (None, ""):
        return bool(str(turn.get("message_hash") or ""))
    try:
        sequence = int(sequence)
        stored_sequence = int(turn.get("message_sequence"))
    except (TypeError, ValueError):
        return False
    if sequence != stored_sequence:
        return False
    expected_hash = _trusted_turn_message_hash(raw_message, sequence)
    return hmac.compare_digest(
        expected_hash,
        str(turn.get("message_hash") or ""),
    )


def _release_strategic_plan_generation_lease_unlocked(page_id, request_id):
    state = read_json(STRATEGIC_PLAN_GENERATION_STATE_FILE, {})
    state = state if isinstance(state, dict) else {}
    lease = state.get(page_id) if isinstance(state.get(page_id), dict) else {}
    if str(lease.get("request_id") or "") != str(request_id or ""):
        return False
    state.pop(page_id, None)
    write_private_json(STRATEGIC_PLAN_GENERATION_STATE_FILE, state, ensure_ascii=False)
    return True


def _release_strategic_plan_generation_lease(page_id, request_id):
    """Release only this request's lease; never delete a newer attempt."""
    try:
        with _trusted_buyer_turn_lock():
            return _release_strategic_plan_generation_lease_unlocked(page_id, request_id)
    except Exception:
        return False


def ensure_initial_business_master_plan(*, config=None, timeout=300, expected_turn=None):
    """Compile and atomically store the first plan after onboarding.

    Graph/provider calls deliberately run outside the trusted-turn lock. The
    final write is a compare-and-swap against the Page, exact buyer turn,
    profile revision/hash, generation lease, and absence of any existing plan.
    """
    config = config or load_config()
    try:
        total_timeout = min(300.0, max(1.0, float(timeout)))
    except (TypeError, ValueError):
        total_timeout = 300.0
    deadline = time.monotonic() + total_timeout
    request_id = secrets.token_hex(12)
    now = datetime.now(timezone.utc)
    with _trusted_buyer_turn_lock():
        page_id = str(active_meta_page_id() or "").strip()
        turn = _trusted_buyer_turn_unlocked()
        if not _strategic_plan_expected_turn_matches(turn, expected_turn):
            return {
                "ok": False,
                "attempted": False,
                "reason": "strategic_plan_turn_not_bound_to_current_event",
            }
        profile = read_json(BUSINESS_PROFILE_FILE, {})
        strategic = strategic_profile_for_page(profile, page_id=page_id, activate=False) if page_id else {}
        readiness = strategic_profile_readiness(strategic, active_page_id=page_id) if strategic else {}
        if not page_id or not turn or not readiness.get("complete"):
            return {"ok": False, "attempted": False, "reason": "business_profile_not_complete"}
        account_id = clean_ad_account_id(current_configured_ad_account_id())
        existing = business_master_plan_for_page(profile, page_id)
        if _master_plan_record_is_complete(existing):
            return {
                "ok": True,
                "attempted": False,
                "created": False,
                "reason": "strategic_plan_already_exists",
                "status": str(existing.get("status") or "proposed"),
            }
        profile_identity = _plan_content_hash({
            "page_id": page_id,
            "revision": strategic.get("revision"),
            "status": strategic.get("status"),
            "topics": strategic.get("topics"),
        })
        generation_state = read_json(STRATEGIC_PLAN_GENERATION_STATE_FILE, {})
        generation_state = generation_state if isinstance(generation_state, dict) else {}
        lease = generation_state.get(page_id) if isinstance(generation_state.get(page_id), dict) else {}
        lease_revision = int(lease.get("profile_revision") or 0)
        if lease_revision == int(strategic.get("revision") or 0):
            started_at = _strategic_plan_generation_time(lease.get("started_at"))
            retry_after = _strategic_plan_generation_time(lease.get("retry_after"))
            if str(lease.get("status") or "") == "generating" and started_at and (now - started_at).total_seconds() < 600:
                return {"ok": False, "attempted": False, "reason": "strategic_plan_generation_in_progress"}
            if str(lease.get("status") or "") == "failed" and retry_after and retry_after > now:
                return {
                    "ok": False,
                    "attempted": False,
                    "reason": "strategic_plan_generation_cooldown",
                    "retry_after": retry_after.isoformat(timespec="seconds"),
                }
        turn_identity = {
            key: turn.get(key)
            for key in ("message_hash", "message_sequence", "chat_id", "session_id", "transport")
        }
        try:
            business_source = _strategic_plan_business_source(
                profile, strategic, page_id, account_id=account_id
            )
        except Exception as exc:
            return {
                "ok": False,
                "attempted": True,
                "created": False,
                "reason": "strategic_plan_business_source_failed",
                "error_type": type(exc).__name__,
            }
        generation_state[page_id] = {
            "status": "generating",
            "request_id": request_id,
            "profile_revision": int(strategic.get("revision") or 0),
            "profile_identity": profile_identity,
            "started_at": now.isoformat(timespec="seconds"),
        }
        try:
            write_private_json(STRATEGIC_PLAN_GENERATION_STATE_FILE, generation_state, ensure_ascii=False)
        except Exception as exc:
            return {
                "ok": False,
                "attempted": True,
                "created": False,
                "reason": "strategic_plan_lease_write_failed",
                "error_type": type(exc).__name__,
            }

    attempts = []
    meta_source = {}
    try:
        meta_timeout = min(90.0, max(1.0, total_timeout * 0.30))
        meta_source = _strategic_plan_live_meta_source(
            account_id=account_id,
            timeout=meta_timeout,
        )
        compiler_timeout = max(0.0, deadline - time.monotonic())
        compiled = compile_strategic_plan(
            business_source,
            meta_source,
            config=config,
            timeout=compiler_timeout,
        )
        if not isinstance(compiled, dict):
            compiled = {"ok": False, "reason": "strategic_plan_compiler_invalid_result"}
        attempts = _strategic_plan_attempts_for_storage(compiled.get("attempts"))

        with _trusted_buyer_turn_lock():
            latest_turn = _trusted_buyer_turn_unlocked()
            latest_page = str(active_meta_page_id() or "").strip()
            latest_account = clean_ad_account_id(current_configured_ad_account_id())
            latest_profile = read_json(BUSINESS_PROFILE_FILE, {})
            latest_strategic = strategic_profile_for_page(
                latest_profile, page_id=latest_page, activate=False
            ) if latest_page else {}
            latest_readiness = strategic_profile_readiness(
                latest_strategic, active_page_id=latest_page
            ) if latest_strategic else {}
            latest_identity = _plan_content_hash({
                "page_id": latest_page,
                "revision": latest_strategic.get("revision"),
                "status": latest_strategic.get("status"),
                "topics": latest_strategic.get("topics"),
            })
            state = read_json(STRATEGIC_PLAN_GENERATION_STATE_FILE, {})
            state = state if isinstance(state, dict) else {}
            current_lease = state.get(page_id) if isinstance(state.get(page_id), dict) else {}
            cas_ok = bool(
                latest_page == page_id
                and latest_account == account_id
                and latest_readiness.get("complete")
                and latest_identity == profile_identity
                and _strategic_plan_expected_turn_matches(latest_turn, expected_turn)
                and _turn_matches_exact_identity(latest_turn, turn_identity)
                and str(current_lease.get("request_id") or "") == request_id
                and not _master_plan_record_is_complete(
                    business_master_plan_for_page(latest_profile, page_id)
                )
            )
            if not cas_ok:
                _release_strategic_plan_generation_lease_unlocked(page_id, request_id)
                return {
                    "ok": False,
                    "attempted": True,
                    "created": False,
                    "reason": "strategic_plan_generation_compare_and_swap_failed",
                    "attempts": attempts,
                }
            if not compiled.get("ok") or not _master_plan_is_complete(compiled.get("plan")):
                failed_at = datetime.now(timezone.utc)
                retry_at = failed_at + timedelta(minutes=5)
                state[page_id] = {
                    **current_lease,
                    "status": "failed",
                    "failed_at": failed_at.isoformat(timespec="seconds"),
                    "retry_after": retry_at.isoformat(timespec="seconds"),
                    "reason": str(compiled.get("reason") or "strategic_plan_compiler_failed")[:120],
                    "attempts": attempts,
                }
                write_private_json(STRATEGIC_PLAN_GENERATION_STATE_FILE, state, ensure_ascii=False)
                log_action("strategic_plan_compile", state[page_id], "blocked")
                return {
                    "ok": False,
                    "attempted": True,
                    "created": False,
                    "reason": state[page_id]["reason"],
                    "retry_after": state[page_id]["retry_after"],
                    "attempts": attempts,
                }

            plan = dict(compiled.get("plan") or {})
            draft_hash = _plan_content_hash(plan)
            record = {
                "status": "proposed",
                "profile_revision": int(latest_strategic.get("revision") or 0),
                "draft": plan,
                "draft_hash": draft_hash,
                "draft_revision": 1,
                "proposed_at": now_iso(),
                "presentation": {},
                "proposal_turn": turn_identity,
                "generator": {
                    "kind": "isolated_strategic_plan_compiler",
                    "provider": str(compiled.get("provider") or ""),
                    "model": str(compiled.get("model") or ""),
                    "reasoning_effort": str(compiled.get("reasoning_effort") or ""),
                    "attempts": attempts,
                    "meta_verified": bool(meta_source.get("verified")),
                    "meta_partial": bool(meta_source.get("partial")),
                    "meta_fetched_at": str(meta_source.get("fetched_at") or ""),
                    "meta_account_id": str(meta_source.get("account_id") or ""),
                    "meta_inventory_totals": meta_source.get("inventory_totals") or {},
                },
            }
            latest_profile.setdefault("business_master_plans", {})[page_id] = record
            latest_profile["updated_at"] = now_iso()
            write_json(BUSINESS_PROFILE_FILE, latest_profile)
            state[page_id] = {
                **current_lease,
                "status": "completed",
                "completed_at": now_iso(),
                "model": str(compiled.get("model") or ""),
                "provider": str(compiled.get("provider") or ""),
                "reasoning_effort": str(compiled.get("reasoning_effort") or ""),
                "attempts": attempts,
                "draft_hash": draft_hash,
            }
            write_private_json(STRATEGIC_PLAN_GENERATION_STATE_FILE, state, ensure_ascii=False)
            log_action("strategic_plan_compile", state[page_id], "completed")
    except Exception as exc:
        _release_strategic_plan_generation_lease(page_id, request_id)
        try:
            log_action(
                "strategic_plan_compile",
                {"page_id": page_id, "request_id": request_id, "error_type": type(exc).__name__},
                "blocked",
            )
        except Exception:
            pass
        return {
            "ok": False,
            "attempted": True,
            "created": False,
            "reason": "strategic_plan_compiler_exception",
            "error_type": type(exc).__name__,
            "attempts": attempts,
        }

    try:
        write_agent_onboarding_plan(latest_profile)
    except Exception:
        pass
    return {
        "ok": True,
        "attempted": True,
        "created": True,
        "status": "proposed",
        "model": str(compiled.get("model") or ""),
        "provider": str(compiled.get("provider") or ""),
        "reasoning_effort": str(compiled.get("reasoning_effort") or ""),
        "attempts": attempts,
    }


def _turn_matches_exact_identity(turn, identity):
    """Bind server behavior to one exact trusted buyer event.

    ``message_hash`` already includes the monotonic message sequence.  Older
    stored proposals may not have the explicit sequence field, so the hash is
    mandatory while the remaining populated scope fields are compared too.
    """
    if not isinstance(turn, dict) or not isinstance(identity, dict):
        return False
    expected_hash = str(identity.get("message_hash") or identity.get("buyer_message_hash") or "").strip()
    if not expected_hash or not hmac.compare_digest(
        expected_hash.encode("utf-8"),
        str(turn.get("message_hash") or "").encode("utf-8"),
    ):
        return False
    for key in ("chat_id", "session_id", "transport"):
        expected = str(identity.get(key) or "").strip()
        if expected and expected != str(turn.get(key) or ""):
            return False
    expected_sequence = identity.get("message_sequence")
    if expected_sequence not in (None, "") and int(expected_sequence) != int(turn.get("message_sequence") or -1):
        return False
    return True


def _plan_proposal_turn(plan):
    if not isinstance(plan, dict):
        return {}
    proposal_turn = plan.get("proposal_turn")
    if isinstance(proposal_turn, dict) and proposal_turn:
        return proposal_turn
    authorization = plan.get("update_authorization")
    return authorization if isinstance(authorization, dict) else {}


def _native_media_directives(text):
    return [
        line.strip()
        for line in str(text or "").splitlines()
        if line.strip().startswith("MEDIA:")
    ]


def render_business_strategic_plan(plan, *, include_state=True):
    """Render every canonical plan field for buyer review and runtime context."""
    plan = plan if isinstance(plan, dict) else {}
    status = str(plan.get("status") or "").strip().lower()
    content = (
        plan.get("draft")
        if status in {"proposed", "draft", "stale"} and plan.get("draft")
        else plan.get("content")
    ) or {}
    lines = ["Propuesta inicial de anuncios"]
    if include_state:
        state_label = {
            "proposed": "borrador para conversar",
            "draft": "borrador para conversar",
            "stale": "revisión solicitada",
            "confirmed": "confirmado",
        }.get(status, str(plan.get("status") or "missing"))
        lines.append(f"Estado: {state_label}")
    for index, field in enumerate(_MASTER_PLAN_FIELDS, start=1):
        value = content.get(field) if isinstance(content, dict) else None
        if value in (None, "", [], {}):
            value = "Pendiente"
        if isinstance(value, str):
            rendered_value = "\n".join(
                re.sub(r"[ \t]+", " ", line).strip()
                for line in value.splitlines()
            ).strip()[:420]
        else:
            rendered_value = json.dumps(value, ensure_ascii=False, sort_keys=True, indent=2)[:420]
        lines.extend(["", f"{index}. {_MASTER_PLAN_LABELS[field]}", rendered_value])
    lines.extend([
        "",
        "Es un punto de partida. Dime qué parte cambiarías y lo pulimos juntos antes de convertirlo en el plan publicitario acordado.",
    ])
    return "\n".join(lines)


def _plan_presentation_matches_current_draft(plan):
    if not isinstance(plan, dict) or str(plan.get("status") or "") != "proposed":
        return False
    draft = plan.get("draft") if isinstance(plan.get("draft"), dict) else {}
    presentation = plan.get("presentation") if isinstance(plan.get("presentation"), dict) else {}
    if not draft or not presentation:
        return False
    draft_hash = _plan_content_hash(draft)
    return bool(
        str(plan.get("draft_hash") or "") == draft_hash
        and str(presentation.get("draft_hash") or "") == draft_hash
        and int(presentation.get("draft_revision") or -1)
        == int(plan.get("draft_revision") or -2)
    )


def _assistant_covers_current_plan_draft(plan, assistant_text):
    normalized_output = _normalized_confirmation_text(assistant_text)
    if not normalized_output:
        return False
    plan = plan if isinstance(plan, dict) else {}
    content = plan.get("draft") if str(plan.get("status") or "") in {"proposed", "draft", "stale"} else plan.get("content")
    content = content if isinstance(content, dict) else {}
    required_sections = []
    for field in _MASTER_PLAN_FIELDS:
        value = content.get(field)
        if value in (None, "", [], {}):
            return False
        rendered = value if isinstance(value, str) else json.dumps(
            value, ensure_ascii=False, sort_keys=True, indent=2
        )
        required_sections.append(
            _normalized_confirmation_text(f"{_MASTER_PLAN_LABELS[field]} {rendered}")
        )
    return bool(required_sections) and all(section in normalized_output for section in required_sections)


def business_lifecycle_state(profile=None, page_id=None):
    """Expose the three server-owned business lifecycle states."""
    profile = profile if isinstance(profile, dict) else read_json(BUSINESS_PROFILE_FILE, {})
    page_id = str(page_id or active_meta_page_id() or "").strip()
    business = strategic_profile_readiness(
        strategic_profile_for_page(profile, page_id=page_id, activate=False),
        active_page_id=page_id,
    ) if page_id else {"complete": False}
    if not business.get("complete"):
        return "onboarding"
    plan = business_master_plan_readiness(profile, page_id)
    return (
        "active_with_confirmed_strategic_plan"
        if plan.get("ready")
        else "active_without_confirmed_strategic_plan"
    )


def _turn_matches_presentation(turn, presentation):
    if not isinstance(turn, dict) or not isinstance(presentation, dict):
        return False
    if int(turn.get("message_sequence") or -1) <= int(presentation.get("after_buyer_message_sequence") or -1):
        return False
    for key in ("chat_id", "session_id", "transport"):
        if not str(turn.get(key) or "").strip() or str(turn.get(key) or "") != str(presentation.get(key) or ""):
            return False
    return True


def record_business_lifecycle_artifact_presented(session_id, assistant_text, chat_id="", target=None):
    """Bind a finalized outbound business summary or plan draft to a revision."""
    target = str(target or "business_profile").strip().lower()
    if target in {"profile", "business", "business_profile", "onboarding"}:
        return record_strategic_review_presented(session_id, assistant_text, chat_id)
    if target not in {"strategic_plan", "master_plan", "plan"}:
        return {"recorded": False, "reason": "unknown_lifecycle_artifact"}
    with _trusted_buyer_turn_lock():
        turn = _trusted_buyer_turn_unlocked()
        if not turn or str(session_id or "") != str(turn.get("session_id") or "") or (chat_id and str(chat_id) != str(turn.get("chat_id") or "")):
            return {"recorded": False, "reason": "plan_presentation_binding_mismatch"}
        profile = read_json(BUSINESS_PROFILE_FILE, {})
        page_id = active_meta_page_id()
        plan = business_master_plan_for_page(profile, page_id)
        if str(plan.get("status") or "") != "proposed" or not _master_plan_is_complete(plan.get("draft")):
            return {"recorded": False, "reason": "plan_draft_missing"}
        if not _assistant_covers_current_plan_draft(plan, assistant_text):
            return {"recorded": False, "reason": "plan_presentation_incomplete"}
        if _plan_presentation_matches_current_draft(plan):
            # Preserve the first valid presentation boundary for this exact
            # immutable draft. A retry must not move confirmation to a later
            # unrelated conversation turn.
            return {"recorded": True, "idempotent": True, "revision": plan.get("draft_revision")}
        presentation = plan.get("presentation") if isinstance(plan.get("presentation"), dict) else {}
        same_presented_turn = (
            int(presentation.get("after_buyer_message_sequence") or -1)
            == int(turn.get("message_sequence") or -1)
            and all(
                str(presentation.get(key) or "") == str(turn.get(key) or "")
                for key in ("chat_id", "session_id", "transport")
            )
        )
        if presentation.get("draft_hash") == _plan_content_hash(plan.get("draft")) and same_presented_turn:
            return {"recorded": True, "idempotent": True, "revision": plan.get("draft_revision")}
        plan["presentation"] = {
            "draft_revision": int(plan.get("draft_revision") or 1),
            "draft_hash": _plan_content_hash(plan.get("draft")),
            "after_buyer_message_sequence": int(turn.get("message_sequence") or -1),
            "chat_id": str(turn.get("chat_id") or ""),
            "session_id": str(turn.get("session_id") or ""),
            "transport": str(turn.get("transport") or ""),
            "assistant_message_hash": hashlib.sha256(str(assistant_text or "").encode()).hexdigest(),
            "presented_at": now_iso(),
        }
        profile.setdefault("business_master_plans", {})[page_id] = plan
        write_json(BUSINESS_PROFILE_FILE, profile)
        return {"recorded": True, "revision": plan.get("draft_revision"), "status": "proposed"}


def ensure_business_lifecycle_artifact_visible(assistant_text, target=None, session_id="", chat_id=""):
    """Canonicalize a profile/plan review at the finalized outbound boundary."""
    target = str(target or "").strip().lower()
    text = str(assistant_text or "")
    if target in {"profile", "business", "business_profile", "onboarding"}:
        return ensure_canonical_strategic_review_visible(text)
    if target in {"strategic_plan", "master_plan", "plan"}:
        with _trusted_buyer_turn_lock():
            turn = _trusted_buyer_turn_unlocked()
            if session_id and str(session_id) != str((turn or {}).get("session_id") or ""):
                return text
            if chat_id and str(chat_id) != str((turn or {}).get("chat_id") or ""):
                return text
            profile = read_json(BUSINESS_PROFILE_FILE, {})
            plan = business_master_plan_for_page(profile)
            if str(plan.get("status") or "") != "proposed" or not _master_plan_is_complete(plan.get("draft")):
                return text
            if _plan_presentation_matches_current_draft(plan):
                # The current draft was already shown. It may remain pending
                # indefinitely without hijacking unrelated future answers.
                return text
            if not _turn_matches_exact_identity(turn, _plan_proposal_turn(plan)):
                # Never infer this from broad words such as "confirmar" or
                # "propuesta". Only the exact turn that actually stored this
                # draft can cause automatic canonical presentation.
                return text
            if _assistant_covers_current_plan_draft(plan, text):
                return text
            canonical = (
                "Preparé esta propuesta inicial de anuncios para que la pulamos juntos:\n\n"
                + render_business_strategic_plan(plan)
            )
            media = _native_media_directives(text)
            if media:
                canonical += "\n\n" + "\n".join(media)
            return canonical
    return text


def resolve_pending_business_lifecycle_transition(
    *, target=None, profile=None, page_id=None, config=None,
    session_id="", chat_id="", raw_message="", assistant_text="",
):
    """Resolve one presented artifact with compare-and-swap persistence.

    The semantic classifier runs outside the file lock. Before committing, the
    exact trusted turn, active Page, artifact revision/hash and presentation
    binding are read again. A concurrent save or a replay therefore fails
    closed instead of confirming a different business summary or plan.
    """
    del profile, assistant_text  # Never trust a caller's stale profile snapshot.
    target = str(target or "").strip().lower() or "business_profile"
    profile_targets = {"profile", "business", "business_profile", "onboarding"}
    plan_targets = {"strategic_plan", "master_plan", "plan"}
    if target not in profile_targets | plan_targets:
        current = read_json(BUSINESS_PROFILE_FILE, {})
        return {
            "transitioned": False,
            "reason": "unknown_lifecycle_artifact",
            "state": business_lifecycle_state(current, page_id),
        }

    with _trusted_buyer_turn_lock():
        scoped_page = str(page_id or active_meta_page_id() or "").strip()
        turn = _trusted_buyer_turn_unlocked()
        current_profile = read_json(BUSINESS_PROFILE_FILE, {})
        if not turn or not scoped_page:
            return {
                "transitioned": False,
                "reason": "missing_trusted_turn_or_scope",
                "state": business_lifecycle_state(current_profile, scoped_page),
            }
        if session_id and str(session_id) != str(turn.get("session_id") or ""):
            return {"transitioned": False, "reason": "trusted_turn_session_mismatch", "state": business_lifecycle_state(current_profile, scoped_page)}
        if chat_id and str(chat_id) != str(turn.get("chat_id") or ""):
            return {"transitioned": False, "reason": "trusted_turn_chat_mismatch", "state": business_lifecycle_state(current_profile, scoped_page)}
        if raw_message and not hmac.compare_digest(
            _canonical_buyer_evidence(raw_message).encode("utf-8"),
            _canonical_buyer_evidence(turn.get("message")).encode("utf-8"),
        ):
            return {"transitioned": False, "reason": "trusted_turn_message_mismatch", "state": business_lifecycle_state(current_profile, scoped_page)}

        turn_identity = {
            key: turn.get(key)
            for key in ("message_hash", "message_sequence", "chat_id", "session_id", "transport")
        }
        if target in profile_targets:
            artifact = strategic_profile_for_page(current_profile, page_id=scoped_page, activate=False)
            readiness = strategic_profile_readiness(artifact, active_page_id=scoped_page)
            if readiness.get("complete") or readiness.get("onboarding_completed") or not readiness.get("review_required"):
                return {
                    "transitioned": False,
                    "reason": "business_onboarding_already_complete" if readiness.get("complete") or readiness.get("onboarding_completed") else "business_review_not_pending",
                    "state": business_lifecycle_state(current_profile, scoped_page),
                }
            presentation = artifact.get("review_presentation") if isinstance(artifact, dict) else None
            bound_presentation = {
                **(presentation or {}),
                **((presentation or {}).get("evidence") or {}),
            }
            if not isinstance(presentation, dict) or not _turn_matches_presentation(turn, bound_presentation):
                return {"transitioned": False, "reason": "profile_not_presented_to_later_bound_turn", "state": business_lifecycle_state(current_profile, scoped_page)}
            artifact_text = business_profile_review_summary(artifact)
            artifact_identity = _plan_content_hash({
                "revision": artifact.get("revision"),
                "status": artifact.get("status"),
                "presentation": presentation,
                "artifact": artifact_text,
            })
            canonical_target = "business_profile"
        else:
            artifact = business_master_plan_for_page(current_profile, scoped_page)
            presentation = artifact.get("presentation") if isinstance(artifact.get("presentation"), dict) else None
            strategic = strategic_profile_for_page(current_profile, page_id=scoped_page, activate=False)
            strategic_readiness = strategic_profile_readiness(strategic, active_page_id=scoped_page)
            if (
                not strategic_readiness.get("complete")
                or str(artifact.get("status") or "") != "proposed"
                or not _master_plan_is_complete(artifact.get("draft"))
                or not _plan_presentation_matches_current_draft(artifact)
                or not _turn_matches_presentation(turn, presentation or {})
            ):
                return {"transitioned": False, "reason": "plan_not_presented_to_later_bound_turn", "state": business_lifecycle_state(current_profile, scoped_page)}
            artifact_text = render_business_strategic_plan(artifact)
            artifact_identity = _plan_content_hash({
                "status": artifact.get("status"),
                "draft_revision": artifact.get("draft_revision"),
                "draft_hash": artifact.get("draft_hash"),
                "presentation": presentation,
            })
            canonical_target = "strategic_plan"

    confirmed, reason = _lifecycle_confirmation(
        canonical_target,
        artifact_text,
        turn.get("message"),
        config,
    )
    if not confirmed:
        latest = read_json(BUSINESS_PROFILE_FILE, {})
        return {"transitioned": False, "reason": reason, "state": business_lifecycle_state(latest, scoped_page)}

    with _trusted_buyer_turn_lock():
        latest_turn = _trusted_buyer_turn_unlocked()
        latest_profile = read_json(BUSINESS_PROFILE_FILE, {})
        latest_page = str(active_meta_page_id() or "").strip()
        if latest_page != scoped_page or any(
            latest_turn.get(key) != value for key, value in turn_identity.items()
        ):
            return {"transitioned": False, "reason": "lifecycle_compare_and_swap_failed", "state": business_lifecycle_state(latest_profile, latest_page)}

        if canonical_target == "business_profile":
            latest_artifact = strategic_profile_for_page(latest_profile, page_id=scoped_page, activate=False)
            latest_readiness = strategic_profile_readiness(latest_artifact, active_page_id=scoped_page)
            latest_presentation = latest_artifact.get("review_presentation") if isinstance(latest_artifact, dict) else None
            latest_identity = _plan_content_hash({
                "revision": latest_artifact.get("revision"),
                "status": latest_artifact.get("status"),
                "presentation": latest_presentation,
                "artifact": business_profile_review_summary(latest_artifact),
            })
            if (
                latest_identity != artifact_identity
                or latest_readiness.get("complete")
                or latest_readiness.get("onboarding_completed")
                or not latest_readiness.get("review_required")
            ):
                return {"transitioned": False, "reason": "lifecycle_compare_and_swap_failed", "state": business_lifecycle_state(latest_profile, scoped_page)}
            evidence = {
                **((latest_presentation or {}).get("evidence") or {}),
                "message_sequence": latest_turn.get("message_sequence"),
                "message_hash": latest_turn.get("message_hash"),
            }
            try:
                latest_artifact = confirm_strategic_profile_revision(
                    latest_artifact,
                    page_id=scoped_page,
                    trusted_buyer_confirmation=True,
                    evidence=evidence,
                )
            except Exception as exc:
                return {"transitioned": False, "reason": str(exc), "state": business_lifecycle_state(latest_profile, scoped_page)}
            latest_profile = embed_strategic_profile(latest_profile, latest_artifact)
        else:
            latest_artifact = business_master_plan_for_page(latest_profile, scoped_page)
            latest_strategic = strategic_profile_for_page(latest_profile, page_id=scoped_page, activate=False)
            latest_strategic_readiness = strategic_profile_readiness(latest_strategic, active_page_id=scoped_page)
            latest_presentation = latest_artifact.get("presentation") if isinstance(latest_artifact.get("presentation"), dict) else None
            latest_identity = _plan_content_hash({
                "status": latest_artifact.get("status"),
                "draft_revision": latest_artifact.get("draft_revision"),
                "draft_hash": latest_artifact.get("draft_hash"),
                "presentation": latest_presentation,
            })
            if (
                latest_identity != artifact_identity
                or not latest_strategic_readiness.get("complete")
                or not _master_plan_is_complete(latest_artifact.get("draft"))
                or not _plan_presentation_matches_current_draft(latest_artifact)
                or not _turn_matches_presentation(latest_turn, latest_presentation or {})
            ):
                return {"transitioned": False, "reason": "lifecycle_compare_and_swap_failed", "state": business_lifecycle_state(latest_profile, scoped_page)}
            latest_artifact["status"] = "confirmed"
            latest_artifact["content"] = dict(latest_artifact.get("draft") or {})
            latest_artifact["confirmed_at"] = now_iso()
            latest_artifact["confirmed_revision"] = int(latest_artifact.get("draft_revision") or 1)
            latest_artifact["revision"] = int(latest_artifact.get("revision") or 0) + 1
            latest_artifact["draft"] = {}
            latest_profile.setdefault("business_master_plans", {})[scoped_page] = latest_artifact
        latest_profile["updated_at"] = now_iso()
        write_json(BUSINESS_PROFILE_FILE, latest_profile)
        return {
            "transitioned": True,
            "target": canonical_target,
            "state": business_lifecycle_state(latest_profile, scoped_page),
            "reason": reason,
        }


def _strategic_topic_updates(payload):
    payload = payload or {}
    claimed = str(payload.get("confirmation_state") or "inferred").strip().lower()
    if claimed not in {"buyer_confirmed", "agent_proposal", "inferred"}:
        claimed = "inferred"
    updates = {}
    explicit = payload.get("strategic_topics")
    if isinstance(explicit, dict):
        for topic in STRATEGIC_PROFILE_TOPICS:
            if topic not in explicit:
                continue
            raw = explicit.get(topic)
            item = dict(raw) if isinstance(raw, dict) else {"value": raw}
            item.setdefault("confirmation_state", claimed)
            updates[topic] = item
    aliases = {
        "services": ("services", "products_services", "main_offer", "offer"),
        "ideal_customer": ("ideal_customer", "audience", "buying_situations"),
        "differentiators": ("differentiators", "proof", "competitive_advantage"),
        "markets": ("markets", "locations", "service_locations", "countries"),
        "capacity": ("capacity", "constraints", "operational_constraints"),
        "pricing": ("pricing", "prices", "price_range"),
        "margins": ("margins", "costs", "contribution_margin", "unit_economics"),
        "global_objectives": ("global_objectives", "success_goal", "what_to_improve"),
        "advertising_experience": ("advertising_experience", "ads_experience", "current_ads", "current_stage"),
        "branding": ("branding", "brand_assets", "brand_tone", "branding_summary"),
    }
    status_map = payload.get("topic_statuses") if isinstance(payload.get("topic_statuses"), dict) else {}
    for topic, keys in aliases.items():
        if topic in updates:
            continue
        value = next((payload.get(key) for key in keys if payload.get(key) not in (None, "", [], {})), None)
        requested_status = str(status_map.get(topic) or "confirmed").strip().lower()
        if value is None and requested_status not in {"unknown", "not_applicable", "withheld"}:
            continue
        updates[topic] = {
            "value": value,
            "status": requested_status,
            "confirmation_state": claimed,
        }
    return updates


def onboarding_interview_status(profile=None):
    profile = profile if isinstance(profile, dict) else read_json(BUSINESS_PROFILE_FILE, {})
    if not isinstance(profile, dict):
        profile = {}
    readiness = strategic_business_profile_readiness(profile)
    if readiness.get("complete"):
        return "completed"
    if readiness.get("status") in {"collecting", "review_required", "scope_mismatch"}:
        return readiness.get("status")
    if profile.get("telegram_onboarding_requested_at"):
        return "pending_telegram"
    if profile.get("website_url") or profile.get("social_links") or profile.get("business_type"):
        return "ready_to_ask"
    return "empty"


UNDEFINED_PRODUCT_CONTEXT_PHRASES = (
    "oferta por definir",
    "audiencia por definir",
    "producto por definir",
    "servicio por definir",
    "negocio por definir",
    "to be defined",
    "tbd",
)


def meaningful_creative_context_text(value, min_len=3):
    text = re.sub(r"\s+", " ", str(value or "").strip())
    if len(text) < min_len:
        return False
    lowered = text.lower()
    return not any(phrase in lowered for phrase in UNDEFINED_PRODUCT_CONTEXT_PHRASES)


def payload_has_product_context(payload):
    payload = normalize_product_payload(payload or {})
    for key in ("name", "product_name", "product", "offer", "main_offer", "audience", "pain", "desire"):
        if meaningful_creative_context_text(payload.get(key)):
            return True
    for key in ("product_guide", "promotion", "request", "image_prompt", "prompt"):
        value = str(payload.get(key) or "").strip()
        if (
            len(value) >= 8
            and not value.lower().strip().startswith((".env", "license_unlock"))
            and meaningful_creative_context_text(value, min_len=8)
        ):
            return True
    return False


def business_profile_product_context(profile=None):
    profile = profile if isinstance(profile, dict) else read_json(BUSINESS_PROFILE_FILE, {})
    if not isinstance(profile, dict):
        return ""
    lines = []

    def add(label, value):
        text = compact_creative_context_value(value)
        if meaningful_creative_context_text(text):
            lines.append(f"{label}: {text}")

    add("Producto/oferta", profile.get("main_offer") or profile.get("offer") or profile.get("products_services"))
    add("Tipo de negocio", profile.get("business_type") or profile.get("business_short"))
    add("Público", profile.get("ideal_customer") or profile.get("audience"))
    add("Etapa", profile.get("current_stage"))
    add("Meta/problema a mejorar", profile.get("what_to_improve") or profile.get("success_goal"))
    return "; ".join(lines)


def truthy_payload_flag(value):
    if isinstance(value, bool):
        return value
    return str(value or "").strip().lower() in {"1", "true", "yes", "si", "sí", "on", "required", "require"}


def logo_text_disables_official_use(value):
    text = str(value or "").strip().lower()
    if not text:
        return False
    conditional_allow = (
        "hasta tener archivo oficial",
        "hasta que tenga archivo oficial",
        "cuando exista archivo oficial",
        "until official",
        "until the official",
    )
    if any(phrase in text for phrase in conditional_allow):
        return False
    opt_out_phrases = (
        "sin logo",
        "no logo",
        "without logo",
        "no incluir logo",
        "no incluyas logo",
        "no usar logo",
        "no uses logo",
        "no mostrar logo",
        "no muestres logo",
        "logo nunca",
        "never use logo",
        "never show logo",
    )
    return any(phrase in text for phrase in opt_out_phrases)


def creative_image_requires_brief(payload=None, purpose="ad_creative"):
    payload = payload or {}
    purpose = str(purpose or "ad_creative").strip().lower()
    if "require_brief" in payload:
        return truthy_payload_flag(payload.get("require_brief"))
    if any(truthy_payload_flag(payload.get(key)) for key in ("asset_only", "draft_only", "standalone_creative")):
        return False
    if purpose in {"logo", "brand_exploration", "moodboard", "brand_sample", "creative_asset", "standalone_creative", "draft_creative", "asset_only", "motion_graphic_asset", "motion_asset", "storyboard_asset", "video_design_element"}:
        return False
    if purpose in {"launch_ad", "campaign_ad", "ad_test", "live_ad", "campaign_ready", "launch_ready"}:
        return True
    request = str(payload.get("request") or payload.get("image_prompt") or payload.get("prompt") or "").lower()
    launch_words = ("lanzar", "activar", "publicar campaña", "subir a meta", "ready to launch", "launch campaign", "stage campaign")
    if any(word in request for word in launch_words):
        return True
    return False


BRAND_EXPLORATION_PURPOSES = {"logo", "brand_exploration", "moodboard", "brand_sample"}


def approved_logo_decision(fields):
    fields = fields or {}
    if official_brand_logo_path(fields):
        return True
    status = str(fields.get("logo_status") or "").strip().lower().replace("-", "_")
    if status in {"official", "approved", "approved_candidate", "no_logo"}:
        return True
    text = " ".join(str(fields.get(key) or "") for key in ("logo_notes", "logo_usage")).lower()
    return any(phrase in text for phrase in (
        "trabajar sin logo", "prefiero sin logo", "no usar logo", "sin incluir logo",
        "without logo", "do not use logo", "no_logo",
    ))


def branding_creative_readiness(require_product=True, payload=None, allow_inline=False):
    payload = payload or {}
    # Final organic/paid production is authorized only by durable,
    # buyer-confirmed brand memory. Inline model payload can describe the
    # active request, but it cannot silently manufacture a finished brand.
    brand_payload = normalize_general_payload(payload) if allow_inline else {}
    library = guide_library()
    profile = read_json(BUSINESS_PROFILE_FILE, {})
    if not isinstance(profile, dict):
        profile = {}
    general = (library.get("general") or {}).get("fields") or {}
    missing = []
    requirements = [
        ("brand_core", bool((library.get("general_exists") and (general.get("brand_name") or general.get("offer"))) or brand_payload.get("brand_name") or brand_payload.get("offer")), "¿Cómo se llama la marca y qué vende exactamente?"),
        ("colors", bool(general.get("colors") or brand_payload.get("colors")), "¿Qué colores exactos debemos respetar, o quieres que te proponga una paleta?"),
        ("visual_style", bool(general.get("visual_style") or brand_payload.get("visual_style")), "¿Cómo deben verse los anuncios: fondos, composición, energía y estilo fotográfico?"),
        ("tone", bool(general.get("tone") or general.get("personality") or brand_payload.get("tone")), "¿Cómo debe sonar la marca: cercana, experta, directa, divertida u otra combinación?"),
        (
            "logo_decision",
            approved_logo_decision(general) or approved_logo_decision(brand_payload),
            "¿Quieres subir tu logo oficial, crear y aprobar uno conmigo, o trabajar explícitamente sin logo?",
        ),
        (
            "reference_decision",
            bool(general.get("references") or library.get("creative_references_exists") or brand_payload.get("references")),
            "¿Tienes algún diseño, anuncio o marca de referencia que te guste? Puedes subirlo; si no tienes, dímelo y busco direcciones contigo.",
        ),
        (
            "real_asset_decision",
            bool(general.get("asset_notes") or brand_payload.get("asset_notes")),
            "¿Tienes fotos reales del producto, fundador, clientes, local o empaque para usar, o debemos generar las imágenes?",
        ),
    ]
    if general.get("logo_path"):
        requirements.append(("logo_usage", bool(general.get("logo_usage") or general.get("logo_path")), "¿El logo oficial debe aparecer siempre, a veces o nunca en los anuncios, y en qué posición prefieres verlo?"))
    if require_product:
        product_ready = (
            any(bool(item.get("ready")) for item in library.get("products") or [])
            or payload_has_product_context(payload)
            or payload_has_product_context(profile)
        )
        requirements.append(("product_guide", product_ready, "¿Cuál es el producto u oferta principal, para quién es y qué problema resuelve?"))
    for key, ready, question in requirements:
        if not ready:
            missing.append({"key": key, "question": question})
    return {
        "ready": not missing,
        "missing": missing,
        "next_question": missing[0]["question"] if missing else "",
        "general": general,
        "library": library,
    }


def brand_exploration_readiness(payload=None, purpose="brand_exploration"):
    """Reduced bootstrap gate for logo/moodboard work inside branding."""
    payload = payload or {}
    incoming = normalize_general_payload(payload)
    general = ((guide_library().get("general") or {}).get("fields") or {})
    combined = {key: incoming.get(key) or general.get(key) for key in set(general) | set(incoming)}
    profile = read_json(BUSINESS_PROFILE_FILE, {})
    if not isinstance(profile, dict):
        profile = {}
    strategic = profile.get("strategic_profile") if isinstance(profile.get("strategic_profile"), dict) else {}
    topics = strategic.get("topics") if isinstance(strategic.get("topics"), dict) else {}

    def topic_value(key):
        topic = topics.get(key) if isinstance(topics.get(key), dict) else {}
        if topic.get("value") not in (None, "", []):
            return topic.get("value")
        draft = topic.get("draft") if isinstance(topic.get("draft"), dict) else {}
        return draft.get("value")

    known_offer = (
        combined.get("offer")
        or combined.get("category")
        or profile.get("main_offer")
        or profile.get("business_type")
        or topic_value("services")
    )
    missing = []
    requirements = [
        ("brand_core", bool(combined.get("brand_name") and known_offer), "Antes de diseñar la marca, ¿cuál es el nombre exacto y qué ofrece el negocio?"),
        ("colors", bool(combined.get("colors")), "¿Qué colores quieres para la marca, o qué sensación debe transmitir la paleta?"),
        ("visual_style", bool(combined.get("visual_style")), "¿Qué estilo visual debe tener la marca y qué quieres evitar?"),
        ("tone", bool(combined.get("tone") or combined.get("personality")), "¿Cómo debe sentirse y sonar la marca?"),
    ]
    for key, ready, question in requirements:
        if not ready:
            missing.append({"key": key, "question": question})
    return {
        "ready": not missing,
        "purpose": str(purpose or "brand_exploration"),
        "missing": missing,
        "next_question": missing[0]["question"] if missing else "",
        "general": general,
        "library": guide_library(),
    }


CREATIVE_TEST_BUDGET_KEYS = (
    "test_budget",
    "budget_comfort",
    "budget",
    "ad_test_budget",
    "daily_test_budget",
    "test_daily_budget",
    "daily_budget",
    "adset_daily_budget",
    "campaign_daily_budget",
    "monthly_budget",
)


def budget_like_text(value):
    text = str(value or "").strip()
    if not text:
        return ""
    lowered = text.lower()
    if any(token in lowered for token in ["presupuesto", "budget", "usd", "us$", "$"]) and re.search(r"\d", text):
        return text[:240]
    if re.search(r"\d+(?:[.,]\d+)?\s*(?:d[oó]lares?|usd|us\$|\$)", lowered):
        return text[:240]
    if re.search(r"\d+(?:[.,]\d+)?\s*(?:/)?\s*(?:d[ií]a|diario|diarios|daily|mes|mensual|monthly|semana|week)", lowered):
        return text[:240]
    return ""


def budget_from_mapping(mapping, scan_notes=False):
    if not isinstance(mapping, dict):
        return ""
    for key in CREATIVE_TEST_BUDGET_KEYS:
        value = str(mapping.get(key) or "").strip()
        if value:
            return value[:240]
    if scan_notes:
        for key, value in mapping.items():
            if key in {"name", "campaign_name", "campaign_id", "adset_id", "base_ad_id"}:
                continue
            detected = budget_like_text(value)
            if detected:
                return detected
    return ""


def creative_test_budget_value(profile, library, payload=None):
    budget = budget_from_mapping(payload)
    if budget:
        return budget
    budget = budget_from_mapping(profile)
    if budget:
        return budget
    briefs = (library or {}).get("ad_briefs") or []
    if briefs:
        brief_fields = (briefs[-1].get("fields") or {}) if isinstance(briefs[-1], dict) else {}
        budget = budget_from_mapping(brief_fields, scan_notes=True)
        if budget:
            return budget
    return ""


def creative_strategy_readiness(require_brief=False, purpose="ad_creative", payload=None):
    purpose = str(purpose or "ad_creative").strip().lower()
    if purpose in BRAND_EXPLORATION_PURPOSES:
        return brand_exploration_readiness(payload, purpose=purpose)
    is_ad = True
    payload = normalize_ad_brief_payload(payload or {})
    branding = branding_creative_readiness(require_product=not image_purpose_is_organic(purpose), payload=None)
    missing = list(branding["missing"])
    library = branding["library"]
    profile = read_json(BUSINESS_PROFILE_FILE, {})
    if not isinstance(profile, dict):
        profile = {}
    budget = creative_test_budget_value(profile, library, payload)
    if is_ad and require_brief:
        briefs = library.get("ad_briefs") or []
        brief_fields = dict((briefs[-1].get("fields") or {}) if briefs else {})
        for key, value in payload.items():
            if key in {
                "name",
                "product_guide",
                "campaign_name",
                "base_ad_name",
                "base_ad",
                "objective",
                "promotion",
                "audience_slice",
                "variation_window",
                "variation_axes",
                "variation_count",
                "concurrent_variations",
                "formats",
                "creative_hypothesis",
            } and str(value or "").strip():
                brief_fields[key] = str(value).strip()
        has_brief_context = bool(
            briefs
            or any(str(brief_fields.get(key) or "").strip() for key in ("name", "promotion", "campaign_name", "base_ad_name", "base_ad", "variation_window", "variation_axes", "creative_hypothesis"))
        )
        if not has_brief_context:
            missing.append({"key": "ad_brief", "question": "Antes de generar, ¿qué oferta, audiencia y acción debe probar este primer grupo de creativos?"})
        else:
            if not str(brief_fields.get("variation_count") or "").strip():
                missing.append({"key": "variation_count", "question": "¿Cuántos creativos quieres producir y cuántos probar al mismo tiempo con ese presupuesto?"})
            if not str(brief_fields.get("concurrent_variations") or "").strip():
                missing.append({"key": "concurrent_variations", "question": "Con ese presupuesto, ¿cuántos creativos vamos a probar simultáneamente y cuáles quedarán en backlog?"})
            if not str(brief_fields.get("formats") or "").strip():
                missing.append({"key": "creative_formats", "question": "¿Qué mezcla vamos a probar: UGC, foto real, demostración, prueba, diseño estático, carrusel o video?"})
            if not str(brief_fields.get("variation_axes") or "").strip():
                missing.append({"key": "variation_axes", "question": "¿Qué perspectivas distintas vamos a probar: dolor, deseo, prueba, demostración, objeción u oferta?"})
            if not str(brief_fields.get("creative_hypothesis") or "").strip():
                missing.append({"key": "creative_hypothesis", "question": "¿Qué queremos aprender con estas variaciones para reconocer al ganador?"})
    return {
        "ready": not missing,
        "purpose": purpose,
        "missing": missing,
        "next_question": missing[0]["question"] if missing else "",
        "budget": budget,
        "branding": branding,
    }


def creative_not_ready_result(reason, readiness):
    missing = readiness.get("missing") or []
    return {
        "ok": False,
        "blocked": True,
        "reason": reason,
        "error": readiness.get("next_question") or "Antes de crear creativos, falta completar la estrategia de marca.",
        "readiness": readiness,
        "missing": [item.get("key") for item in missing if isinstance(item, dict)],
    }


def compact_creative_context_value(value, limit=260):
    text = re.sub(r"\s+", " ", str(value or "").strip())
    if len(text) > limit:
        return text[: limit - 1].rstrip() + "…"
    return text


def creative_direct_context(payload):
    """Return prompt-safe context explicitly sent by Hermes when library files lag behind."""
    payload = payload or {}
    general = normalize_general_payload(payload)
    product = normalize_product_payload(payload)
    brief = normalize_ad_brief_payload(payload)
    lines = []

    def add(label, value):
        text = compact_creative_context_value(value)
        if text:
            lines.append(f"- {label}: {text}")

    add("Marca", general.get("brand_name"))
    add("Qué vende", general.get("offer"))
    add("Mercado/ubicación", general.get("market"))
    add("Colores", general.get("colors"))
    add("Estilo visual", general.get("visual_style"))
    add("Tono", general.get("tone"))
    add("Logo", general.get("logo_notes") or general.get("logo_usage") or general.get("logo_path"))
    add("Referencias", general.get("references"))
    add("Fotos/activos reales", general.get("asset_notes"))
    add("Producto/oferta", product.get("name") or brief.get("product_guide"))
    add("Precio", product.get("price"))
    add("Público", product.get("audience") or brief.get("audience_slice"))
    add("Problema", product.get("pain"))
    add("Beneficio/deseo", product.get("desire"))
    add("Debe mostrar", product.get("show") or brief.get("required_assets"))
    add("Promoción", brief.get("promotion"))
    add("Formatos", brief.get("formats"))
    add("Ejes de variación", brief.get("variation_axes"))
    add("Hipótesis creativa", brief.get("creative_hypothesis"))
    if not lines:
        return ""
    return "Contexto explícito recibido en esta solicitud:\n" + "\n".join(lines)


