def _hybrid_rgb_palette(values):
    """Normalize explicit RGB/hex values and common named brand colors."""
    result = []
    for value in values or []:
        if isinstance(value, (list, tuple)) and len(value) == 3:
            try:
                result.append(tuple(max(0, min(255, int(v))) for v in value))
            except (TypeError, ValueError):
                continue
            continue
        text = str(value or "").strip()
        for raw in re.findall(r"(?i)(?:#|\b)([0-9a-f]{6})\b", text):
            color = tuple(int(raw[i:i + 2], 16) for i in (0, 2, 4))
            if color not in result:
                result.append(color)
        normalized = unicodedata.normalize("NFKD", text.lower()).encode("ascii", "ignore").decode("ascii")
        occupied = []
        for name, color in sorted(HYBRID_NAMED_COLORS.items(), key=lambda item: len(item[0]), reverse=True):
            match = re.search(rf"(?<![a-z]){re.escape(name)}(?![a-z])", normalized)
            if not match or any(match.start() < end and match.end() > start for start, end in occupied):
                continue
            occupied.append(match.span())
            if color not in result:
                result.append(color)
    return result


def _hybrid_real_media(payload, purpose="ad_creative"):
    """Resolve only classified, durable buyer assets; arbitrary paths are rejected."""
    raw = payload.get("real_media")
    if not isinstance(raw, list):
        return [], None
    if not 1 <= len(raw) <= 6:
        raise ValueError("real_media debe contener entre 1 y 6 imágenes.")
    by_id = {str(item.get("id")): item for item in load_content_asset_library().get("items", []) if isinstance(item, dict)}
    organic = image_purpose_is_organic(purpose)
    required_approval = "approved_for_daily_content" if organic else "approved_for_ads"
    allowed_paths = {}
    for item in by_id.values():
        if item.get("classification_status") != "classified" or item.get("preservation_mode") != "pixel_locked":
            continue
        if not item.get(required_approval):
            continue
        for path in safe_image_paths({"image_paths": item.get("file_paths") or []}, limit=8):
            allowed_paths[str(Path(path).resolve())] = item
    slots = []
    seen = set()
    slot_ids = set()
    for index, entry in enumerate(raw, 1):
        if not isinstance(entry, dict):
            raise ValueError("Cada elemento de real_media debe ser un objeto.")
        slot_id = str(entry.get("slot_id") or f"slot-{index}").strip()
        if not slot_id or slot_id in slot_ids:
            raise ValueError("Cada slot de real_media debe tener un slot_id distinto.")
        slot_ids.add(slot_id)
        asset_id = str(entry.get("content_asset_id") or entry.get("asset_id") or "").strip()
        item = by_id.get(asset_id) if asset_id else None
        candidate_paths = safe_image_paths({"image_paths": item.get("file_paths") if item else [entry.get("file_path")]}, limit=2)
        candidate = next((p for p in candidate_paths if str(Path(p).resolve()) in allowed_paths), None)
        if not candidate:
            raise ValueError(f"No pude validar la foto real del slot {entry.get('slot_id') or index} en la biblioteca aprobada.")
        if candidate in seen:
            raise ValueError("Cada slot de real_media debe apuntar a una foto distinta.")
        seen.add(candidate)
        slots.append({
            "slot_id": slot_id,
            "label": str(entry.get("label") or entry.get("role") or "").strip(),
            "role": str(entry.get("role") or "supporting").strip(),
            "source": candidate,
            "asset_id": str(allowed_paths[str(Path(candidate).resolve())].get("id") or asset_id),
        })
    return slots, by_id


def _hybrid_style_reference(payload, by_id, purpose="ad_creative"):
    policy = payload.get("style_reference")
    if not isinstance(policy, dict):
        policy = {"mode": "none"}
    mode = str(policy.get("mode") or "none").strip().lower()
    if mode == "none":
        return None, {"mode": "none"}
    candidates = []
    required_approval = "approved_for_daily_content" if image_purpose_is_organic(purpose) else "approved_for_ads"
    item = None
    if mode == "explicit":
        item = by_id.get(str(policy.get("asset_id") or "").strip())
        if item and item.get("category") == "style_reference" and item.get("preservation_mode") == "style_only" and item.get("classification_status") == "classified" and item.get(required_approval):
            candidates = safe_image_paths({"image_paths": item.get("file_paths") or []}, limit=1)
        if not candidates and policy.get("file_path"):
            requested = str(Path(str(policy.get("file_path")).strip()).resolve())
            for candidate_item in by_id.values():
                if candidate_item.get("category") != "style_reference" or candidate_item.get("preservation_mode") != "style_only" or candidate_item.get("classification_status") != "classified" or not candidate_item.get(required_approval):
                    continue
                paths = safe_image_paths({"image_paths": candidate_item.get("file_paths") or []}, limit=8)
                if any(str(Path(path).resolve()) == requested for path in paths):
                    item = candidate_item
                    candidates = [path for path in paths if str(Path(path).resolve()) == requested]
                    break
        if not candidates:
            raise ValueError("La referencia de diseño explícita no está clasificada y aprobada.")
    elif mode == "pool":
        items = [item for item in by_id.values() if item.get("category") == "style_reference" and item.get("preservation_mode") == "style_only" and item.get("classification_status") == "classified" and item.get(required_approval)]
        for item in items:
            paths = safe_image_paths({"image_paths": item.get("file_paths") or []}, limit=1)
            if paths:
                candidates.append((str(item.get("id")), paths[0]))
        if not candidates:
            raise ValueError("No hay referencias gráficas aprobadas para usar en el pool.")
        state = read_json(HYBRID_STYLE_SHUFFLE_FILE, {"remaining": [], "last": ""})
        remaining = [str(x) for x in state.get("remaining", []) if str(x) in {x[0] for x in candidates}]
        if not remaining:
            remaining = [x[0] for x in candidates]
            secrets.SystemRandom().shuffle(remaining)
            last_id = str(state.get("last") or "")
            if len(remaining) > 1 and remaining[0] == last_id:
                remaining[0], remaining[1] = remaining[1], remaining[0]
        selected_id = remaining.pop(0)
        selected = next(path for asset_id, path in candidates if asset_id == selected_id)
        write_json(HYBRID_STYLE_SHUFFLE_FILE, {"remaining": remaining, "last": selected_id, "updated_at": now_iso()}, ensure_ascii=False)
        return selected, {"mode": "pool", "asset_id": selected_id}
    else:
        raise ValueError("style_reference.mode debe ser none, pool o explicit.")
    return candidates[0], {"mode": mode, "asset_id": str((item or {}).get("id") or policy.get("asset_id") or "")}


def _hybrid_public_evidence(slots, composition):
    """Keep audit identifiers/hashes while never returning buyer filesystem paths."""
    composition = composition if isinstance(composition, dict) else {}
    public_slots = []
    evidence_slots = composition.get("slots") if isinstance(composition.get("slots"), list) else []
    for slot in slots:
        match = next((item for item in evidence_slots if item.get("slot_id") == slot.get("slot_id")), {})
        public_slots.append({
            "slot_id": slot.get("slot_id"),
            "label": slot.get("label"),
            "role": slot.get("role"),
            "asset_id": slot.get("asset_id"),
            "key_rgb": slot.get("key_rgb"),
            "source_sha256": match.get("source_sha256"),
        })
    public_composition = {key: value for key, value in composition.items() if key != "slots"}
    public_composition["slots"] = [{key: value for key, value in item.items() if key not in {"source"}} for item in evidence_slots]
    return public_slots, public_composition


def codex_image_generate(payload):
    """Generate a raster creative through the Codex/Image bridge."""
    payload = payload or {}
    brief_payload = normalize_ad_brief_payload(payload)
    ad_brief = str(payload.get("ad_brief") or "").strip()
    mode = str(payload.get("mode") or payload.get("image_mode") or "fixed").strip().lower()
    variations = payload.get("variations") or brief_payload.get("variation_count") or 1
    request = str(payload.get("request") or payload.get("image_prompt") or payload.get("prompt") or "").strip()
    purpose = str(payload.get("purpose") or "ad_creative").strip().lower()
    background_removal = str(payload.get("background_removal") or "none").strip().lower().replace("-", "_")
    if background_removal in {"green", "green_background", "chroma", "chroma_key"}:
        background_removal = "green_screen"
    if background_removal not in {"none", "green_screen"}:
        background_removal = "none"
    organic_missing = []
    if image_purpose_is_organic(purpose):
        request, organic_missing = normalized_organic_image_request(payload, request)
    if image_purpose_is_organic(purpose) and not organic_image_request_is_specific(request):
        result = {
            "ok": False,
            "blocked": True,
            "reason": "missing_organic_post_request",
            "error": "Antes de generar el post, incluye el tema activo, pilar, objetivo, texto principal, formato y decisión de CTA en esta misma solicitud.",
            "missing": organic_missing or ["organic_post_request"],
        }
        log_action("codex_image_generate", {"purpose": purpose, "ok": False, "reason": result["reason"]}, "blocked")
        return result
    if not request:
        request = "Crear una imagen final para Meta Ads usando las guias de marca disponibles."
    product_guide, product_context_source = selected_product_guide_for_creative(payload)
    context = creative_direct_context(payload)
    if context and context not in request:
        request = f"{request}\n\n{context}"
    require_brief = creative_image_requires_brief(payload, purpose)
    readiness = creative_strategy_readiness(require_brief=require_brief, purpose=purpose, payload=payload)
    if not readiness["ready"]:
        result = creative_not_ready_result("creative_production_not_ready", readiness)
        log_action(
            "codex_image_generate",
            {"product_guide": product_guide, "ad_brief": ad_brief, "mode": mode, "require_brief": require_brief, "ok": False, "reason": result["reason"], "missing": result["missing"]},
            "blocked",
        )
        return result
    try:
        hybrid_requested = bool(payload.get("real_media"))
        if hybrid_requested:
            slots, asset_index = _hybrid_real_media(payload, purpose=purpose)
            if not slots:
                raise ValueError("El modo híbrido necesita al menos una foto real validada.")
            style_path, style_evidence = _hybrid_style_reference(payload, asset_index, purpose=purpose)
            default_layout = "hero" if len(slots) == 1 else "before_after" if len(slots) == 2 and {s.get("role") for s in slots} == {"before", "after"} else "services" if len(slots) == 2 else "collage"
            layout = str(payload.get("layout_intent") or default_layout).strip().lower()
            layout_limits = {
                "hero": (1, 1), "before_after": (2, 2), "services": (2, 6),
                "collage": (3, 6), "freeform": (1, 6),
            }
            if layout not in layout_limits:
                raise ValueError("layout_intent debe ser hero, before_after, services, collage o freeform.")
            low, high = layout_limits[layout]
            if not low <= len(slots) <= high:
                raise ValueError(f"layout_intent={layout} requiere entre {low} y {high} fotos reales.")
            if layout == "before_after" and {s.get("role") for s in slots} != {"before", "after"}:
                raise ValueError("layout_intent=before_after requiere exactamente una foto con role=before y otra con role=after.")
            text_content = payload.get("text_content") if isinstance(payload.get("text_content"), dict) else {}
            brand_fields = (guide_library().get("general") or {}).get("fields") or {}
            official_logo = official_brand_logo_path()
            explicit_logo_value = payload.get("include_logo")
            explicit_logo_requested = (isinstance(explicit_logo_value, str) and explicit_logo_value.strip().lower() in {"1", "true", "yes", "si", "sí", "on"}) or explicit_logo_value is True
            logo_color_mode = str(payload.get("logo_color_mode") or "original").strip().lower()
            logo_position = str(payload.get("logo_position") or "auto").strip().lower().replace("-", "_")
            if logo_color_mode not in {"original", "white", "black", "brand_primary", "brand_secondary", "auto_contrast"}:
                raise ValueError("logo_color_mode no es una variante válida del logo oficial.")
            if logo_position not in {"auto", "top_left", "top_right", "bottom_left", "bottom_right"}:
                raise ValueError("logo_position debe ser auto o una esquina válida.")
            if explicit_logo_requested and not official_logo:
                raise ValueError("Se solicitó el logo oficial, pero no hay un logo clasificado guardado.")
            if explicit_logo_value is None:
                logo_usage = str(brand_fields.get("logo_usage") or "").lower()
                include_logo = bool(not image_purpose_is_motion(purpose) and official_logo and not logo_text_disables_official_use(request.lower()) and not logo_text_disables_official_use(logo_usage))
            else:
                include_logo = explicit_logo_requested
            if include_logo and official_logo:
                # Validate transparency-dependent solid modes before spending
                # an Image 2 generation. `original` remains valid for opaque
                # official files; recolored variants require a transparent PNG.
                prepare_logo(official_logo, logo_color_mode)
            palette_values = payload.get("brand_colors") or brand_fields.get("colors") or []
            if isinstance(palette_values, str):
                palette_values = [x.strip() for x in re.split(r"[,;|]", palette_values) if x.strip()]
            key_colors = choose_key_colors(len(slots), _hybrid_rgb_palette(palette_values))
            keyed_slots = [dict(slot, key_rgb=list(key)) for slot, key in zip(slots, key_colors)]
            image_prompt = build_image2_overlay_prompt(
                layout=layout,
                slots=keyed_slots,
                visual_direction=str(payload.get("visual_direction") or request),
                text_content=text_content,
                brand_palette=[str(x) for x in palette_values],
                style_reference_mode=str(style_evidence.get("mode") or "none"),
            )
            # Deliberately only the opt-in style reference enters the provider.
            hybrid_refs = [style_path] if style_path else []
            raw_result = call_codex_image_cli(
                image_prompt,
                model=load_config().codex_creative_model,
                output_root=CREATIVE_ASSET_ROOT,
                output_name=payload.get("output_name") or "hybrid-meta-ad-creative",
                reference_image_paths=hybrid_refs,
                purpose=purpose,
            )
            result = raw_result if isinstance(raw_result, dict) else {"ok": False, "error": "Image 2 devolvió una respuesta no estructurada."}
            if not result.get("ok") or not result.get("image_path"):
                public_slots, _ = _hybrid_public_evidence(keyed_slots, {})
                result["hybrid"] = {"ok": False, "slots": public_slots, "style_reference": style_evidence, "provider_reference_count": len(hybrid_refs)}
            else:
                overlay_path = result["image_path"]
                final_path = Path(overlay_path).with_name(Path(overlay_path).stem + "-composited.png")
                composition = compose_real_media(overlay_path, keyed_slots, final_path)
                if not composition.get("pass"):
                    raise ValueError("La validación de máscaras del diseño híbrido no pasó; no entregaré una composición ambigua.")
                result["image_path"] = str(final_path)
                result["asset_id"] = str(final_path.resolve().relative_to(CREATIVE_ASSET_ROOT.resolve()))
                public_slots, public_composition = _hybrid_public_evidence(keyed_slots, composition)
                result["hybrid"] = {"ok": True, "layout_intent": layout, "slots": public_slots, "composition": public_composition, "style_reference": style_evidence, "provider_reference_count": len(hybrid_refs)}
                if include_logo and not official_logo:
                    raise ValueError("Se solicitó el logo oficial, pero no hay un logo clasificado guardado.")
                if include_logo and official_logo:
                    brand_rgb = _hybrid_rgb_palette(palette_values)
                    logo_image = composite_logo(result["image_path"], official_logo, mode=logo_color_mode, position=logo_position, brand_primary=brand_rgb[0] if brand_rgb else (255, 128, 0), brand_secondary=brand_rgb[1] if len(brand_rgb) > 1 else (0, 128, 255))
                    logo_image.save(final_path, "PNG")
                    result["hybrid"]["logo"] = {"applied": True, "mode": logo_color_mode}
                if isinstance(result.get("hybrid", {}).get("composition"), dict):
                    composition_evidence = result["hybrid"]["composition"]
                    pre_logo_hash = composition_evidence.get("output_sha256")
                    composition_evidence["pre_logo_output_sha256"] = pre_logo_hash
                    composition_evidence["output_sha256"] = content_asset_sha256(final_path)
                    result["output_sha256"] = composition_evidence["output_sha256"]
                result["preview_url"] = f"/api/creative-asset?id={urllib.parse.quote(result['asset_id'])}"
            result["prompt_package"] = {"hybrid": True, "layout_intent": layout, "real_media_count": len(slots), "style_reference": style_evidence, "reference_image_count": len(hybrid_refs), "provider_reference_count": len(hybrid_refs), "real_media_provider_excluded": True, "official_logo_provider_excluded": True}
            if result.get("ok") and result.get("image_path") and _truthy_payload_value(payload, "reusable_asset", False):
                reusable = save_content_asset_memory({"file_path": result["image_path"], "category": str(payload.get("reusable_category") or "brand_graphic_element"), "purpose": str(payload.get("asset_purpose") or request)[:1200], "notes": "Composición híbrida con fotos reales insertadas programáticamente.", "preservation_mode": "pixel_locked", "source": "codex_hybrid_composite", "approved_for_ads": bool(payload.get("approved_for_ads"))})
                result["reusable_content_asset"] = reusable.get("asset")
            log_action("codex_image_generate", {"purpose": purpose, "hybrid": True, "ok": result.get("ok"), "asset_id": result.get("asset_id", "")}, "completed" if result.get("ok") else "blocked")
            if result.get("ok"):
                retention = recent_generated_creatives(when="last_3_days", limit=24, cleanup=True)
                result["recent_recovery"] = {
                    "retention_days": retention.get("retention_days", RECENT_CREATIVE_RETENTION_DAYS),
                    "expired_removed": retention.get("expired_removed", 0),
                    "instruction": "El comprador puede pedir los creativos de hoy, ayer o los últimos tres días sin recordar IDs.",
                }
            return result
        prompt_package = build_codex_image_prompt_package(
            product_guide=product_guide,
            request=request,
            ad_brief=ad_brief,
            mode=mode,
            variations=variations,
            seed=str(payload.get("seed") or "").strip() or None,
            purpose=purpose,
        )
        selected_prompt = (prompt_package.get("prompts") or [{}])[0]
        image_prompt = (
            f"{selected_prompt.get('image_prompt') or request}\n\n"
            f"Pedido puntual del comprador: {request}\n\n"
            f"Rol exacto dentro del storyboard: {str(payload.get('asset_role') or 'full_frame').strip()}\n"
            f"Función narrativa en la escena: {str(payload.get('narrative_role') or payload.get('scene_intent') or 'apoyar visualmente la idea de la escena').strip()}\n"
            f"Alcance de marca/producto: {str(payload.get('product_scope') or product_guide or 'marca principal').strip()}\n"
            f"Modo creativo: {prompt_package.get('mode')}\n"
            f"Eje visual: {selected_prompt.get('design_axis') or ''}\n"
            f"Composicion: {selected_prompt.get('composition') or ''}\n"
            f"Experimento: {selected_prompt.get('experiment') or ''}\n"
        )
        if purpose == "logo":
            image_prompt += (
                "\nCONTRATO ESTRICTO DE LOGO PURO: genera solamente un único logotipo aislado y utilizable. "
                "No generes un anuncio acerca del logo ni una lámina de presentación. Sin mockups, tarjetas, paredes, "
                "pedestales, oficinas, fotografías, escenas, dispositivos, marcos, encabezados, textos explicativos, "
                "beneficios, ubicación, CTA, botones, precios, ofertas ni frases como 'solicita tu diseño'. El único texto "
                "permitido es el nombre exacto de la marca y, solamente si fue aprobado como parte permanente del logo, "
                "su descriptor/tagline. Presenta el logo centrado sobre fondo blanco completamente plano, con amplio margen "
                "y acabado vectorial limpio; una sola opción, sin variantes alrededor.\n"
            )
        if background_removal == "green_screen":
            image_prompt += (
                "\nASSET AISLADO PARA COMPOSICIÓN DE VIDEO: genera únicamente el elemento solicitado, completo y sin recortes, "
                "sobre un fondo chroma verde absolutamente plano #00FF00. Sin gradientes, escenario, piso, sombras proyectadas, "
                "texto adicional ni objetos extra. Evita verde dentro del elemento. Mantén un borde nítido y separación clara "
                "para retirar el fondo determinísticamente y colocar el PNG dentro del storyboard.\n"
            )
        if payload.get("reference_image_summary"):
            image_prompt += f"\nReferencia visual descrita por el agente: {payload.get('reference_image_summary')}\n"
        reference_paths = safe_image_paths(payload, limit=8)
        library_references = selected_content_asset_references(payload, purpose=purpose)
        for path in library_references["all"]:
            if path not in reference_paths:
                reference_paths.append(path)
        protected_reference_paths = explicit_protected_reference_paths(payload)
        for path in library_references["protected"]:
            if path not in protected_reference_paths:
                protected_reference_paths.append(path)
        background_requested = bool(reference_paths and reference_as_background_requested(payload, request))
        if background_requested and reference_paths[0] not in protected_reference_paths:
            protected_reference_paths.insert(0, reference_paths[0])
        # Keep one input slot available for an official logo when the brand
        # requires it. A daily generation should select the most relevant
        # photos from the durable batch instead of attaching the whole archive.
        protected_reference_paths = [path for path in protected_reference_paths if path in reference_paths][:7]
        reference_paths = [
            *protected_reference_paths,
            *[path for path in reference_paths if path not in protected_reference_paths],
        ][:8]
        background_prompt_lock = reference_background_prompt_lock(reference_paths, payload, request)
        if background_prompt_lock:
            image_prompt += background_prompt_lock
        protected_asset_lock = protected_real_asset_prompt_lock(
            protected_reference_paths,
            use_as_background=background_requested,
        )
        if protected_asset_lock:
            image_prompt += protected_asset_lock
        official_logo = official_brand_logo_path()
        brand_fields = (guide_library().get("general") or {}).get("fields") or {}
        include_logo_value = payload.get("include_logo")
        if include_logo_value is None:
            request_lower = request.lower()
            logo_usage = str(brand_fields.get("logo_usage") or "").lower()
            include_logo = bool(
                not image_purpose_is_motion(purpose)
                and official_logo
                and not logo_text_disables_official_use(request_lower)
                and not logo_text_disables_official_use(logo_usage)
            )
        else:
            include_logo = str(include_logo_value).strip().lower() in {"1", "true", "yes", "si", "sí", "on"}
        logo_position = str(payload.get("logo_position") or "top-right").strip().lower()
        logo_background = str(payload.get("logo_background") or "auto").strip().lower()
        logo_render_mode = str(payload.get("logo_render_mode") or "protected_context").strip().lower()
        if logo_render_mode in {"context", "direct", "model"}:
            logo_render_mode = "protected_context"
        elif logo_render_mode in {"composite", "overlay", "post_process"}:
            logo_render_mode = "exact_composite"
        if logo_render_mode not in {"protected_context", "exact_composite"}:
            raise ValueError("logo_render_mode debe ser protected_context o exact_composite.")
        if include_logo and not official_logo:
            raise ValueError("El brief pide usar el logo, pero todavía no hay un archivo oficial guardado. Pide al comprador que lo suba; no generes uno parecido.")
        if include_logo and official_logo:
            if str(official_logo) not in reference_paths:
                reference_paths = [*reference_paths[:7], str(official_logo)]
            if logo_render_mode == "protected_context":
                image_prompt += f"\n{official_logo_prompt_lock(logo_position)}\n"
            else:
                image_prompt += (
                    "\nMODO DE RESPALDO CON COMPOSICIÓN EXACTA: el logo oficial está adjunto solo como contexto de marca. "
                    f"No dibujes, imites ni incluyas ningún logo en la imagen base. Deja una zona limpia en {logo_position} "
                    "para que el producto aplique después el archivo oficial exacto.\n"
                )
        result = call_codex_image_cli(
            image_prompt,
            model=load_config().codex_creative_model,
            output_root=CREATIVE_ASSET_ROOT,
            output_name=payload.get("output_name") or selected_prompt.get("variant_id") or "meta-ad-creative",
            reference_image_paths=reference_paths,
            purpose=purpose,
        )
        if result.get("ok") and background_removal == "green_screen" and result.get("image_path"):
            removal = remove_green_screen_background(result["image_path"])
            result["background_removal"] = removal
            if removal.get("applied"):
                transparent_path = Path(removal["image_path"])
                result["image_path"] = str(transparent_path)
                result["asset_id"] = str(transparent_path.resolve().relative_to(CREATIVE_ASSET_ROOT.resolve()))
                result["preview_url"] = f"/api/creative-asset?id={urllib.parse.quote(result['asset_id'])}"
            else:
                result = {**result, "ok": False, "blocked": True, "reason": "green_screen_removal_failed", "error": removal.get("error") or "No pude retirar el fondo verde de forma segura."}
        if result.get("ok") and include_logo and official_logo and logo_render_mode == "exact_composite" and result.get("image_path"):
            result["official_logo"] = composite_official_logo(
                result["image_path"],
                official_logo,
                position=logo_position,
                background=logo_background,
            )
            if not result["official_logo"].get("applied"):
                result["warning"] = result["official_logo"].get("error") or "No pude aplicar el logo oficial exacto."
        result["prompt_package"] = {
            "mode": prompt_package["mode"],
            "purpose": prompt_package.get("purpose", purpose),
            "seed": prompt_package["seed"],
            "variation_count": prompt_package["variation_count"],
            "variation_ledger": prompt_package["variation_ledger"],
            "product_guide": prompt_package["product_guide"],
            "product_context_source": product_context_source,
            "ad_brief": prompt_package["ad_brief"],
            "selected_prompt": selected_prompt,
            "logo_context": prompt_package.get("logo_context", ""),
            "reference_image_count": len(reference_paths),
            "include_logo": bool(include_logo and official_logo),
            "logo_render_mode": logo_render_mode if include_logo and official_logo else "none",
            "logo_protection": "exact_prompt_lock" if include_logo and official_logo and logo_render_mode == "protected_context" else ("deterministic_composite" if include_logo and official_logo else "none"),
            "reference_image_role": "real_photo_background" if background_prompt_lock else ("protected_real_asset" if protected_reference_paths else ("reference" if reference_paths else "none")),
            "protected_reference_image_count": len(protected_reference_paths),
            "protected_asset_preservation": "pixel_locked" if protected_reference_paths else "none",
            "selected_content_asset_ids": [item.get("id") for item in library_references.get("items", [])],
            "requires_full_ad_brief": require_brief,
            "motion_asset_role": str(payload.get("asset_role") or "").strip(),
            "narrative_role": str(payload.get("narrative_role") or payload.get("scene_intent") or "").strip(),
            "background_removal": background_removal,
        }
        if result.get("ok") and result.get("image_path") and _truthy_payload_value(payload, "reusable_asset", False):
            reusable_category = str(payload.get("reusable_category") or "motion_graphic_element")
            reusable = save_content_asset_memory(
                {
                    "file_path": result["image_path"],
                    "category": reusable_category,
                    "purpose": str(payload.get("asset_purpose") or request)[:1200],
                    "notes": str(payload.get("asset_notes") or "Elemento generado con Image 2 para composición de video y diseño reutilizable.")[:1600],
                    "preservation_mode": "pixel_locked",
                    "source": "codex_image_generated",
                    "product_scope": str(payload.get("product_scope") or product_guide),
                    "visual_role": str(payload.get("asset_role") or "motion_overlay"),
                    "reusable": True,
                    "background_removed": background_removal == "green_screen",
                    "approved_for_daily_content": True,
                    "approved_for_ads": bool(payload.get("approved_for_ads")),
                }
            )
            result["reusable_content_asset"] = reusable.get("asset")
        if result.get("asset_id"):
            result["preview_url"] = f"/api/creative-asset?id={urllib.parse.quote(str(result['asset_id']))}"
        if result.get("ok") and image_purpose_is_motion(purpose):
            result["storyboard_integration"] = {
                "inspect_before_render": True,
                "instruction": "Revisa la geometría, peso visual, perspectiva, espacio negativo y bordes del archivo real; después ajusta encuadre, capas y movimiento del storyboard antes de renderizar.",
                "suggested_scene_field": "layer_asset_paths" if background_removal == "green_screen" else "media_path",
            }
        if result.get("ok"):
            retention = recent_generated_creatives(when="last_3_days", limit=24, cleanup=True)
            result["recent_recovery"] = {
                "retention_days": retention.get("retention_days", RECENT_CREATIVE_RETENTION_DAYS),
                "expired_removed": retention.get("expired_removed", 0),
                "instruction": "El comprador puede pedir los creativos de hoy, ayer o los últimos tres días sin recordar IDs.",
            }
    except (ValueError, OSError) as exc:
        result = {"ok": False, "error": str(exc)}
    log_action(
        "codex_image_generate",
        {
            "product_guide": product_guide,
            "ad_brief": ad_brief,
            "mode": mode,
            "require_brief": require_brief,
            "ok": result.get("ok"),
            "asset_id": result.get("asset_id", ""),
            "error": result.get("error", ""),
        },
        "completed" if result.get("ok") else "blocked",
    )
    return result


def creative_asset_path(asset_id):
    relative = Path(str(asset_id or "").strip())
    if not str(relative) or relative.is_absolute() or relative.suffix.lower() not in CREATIVE_ASSET_EXTENSIONS:
        raise ValueError("No encontré esa imagen creativa.")
    candidate = (CREATIVE_ASSET_ROOT / relative).resolve()
    try:
        candidate.relative_to(CREATIVE_ASSET_ROOT.resolve())
    except ValueError as exc:
        raise ValueError("No encontré esa imagen creativa.") from exc
    if not candidate.exists() or not candidate.is_file():
        raise ValueError("No encontré esa imagen creativa.")
    return candidate


def brand_logo_extension(filename="", content_type=""):
    ext = Path(str(filename or "")).suffix.lower()
    if ext not in BRAND_LOGO_EXTENSIONS:
        ext = {
            "image/png": ".png",
            "image/jpeg": ".jpg",
            "image/jpg": ".jpg",
            "image/webp": ".webp",
        }.get(str(content_type or "").split(";")[0].strip().lower(), "")
    if ext not in BRAND_LOGO_EXTENSIONS:
        raise ValueError("Sube tu logo en PNG, JPG o WebP.")
    return ext


def brand_logo_bytes_look_valid(raw, ext):
    if not raw:
        return False
    if ext == ".png":
        return raw.startswith(b"\x89PNG\r\n\x1a\n")
    if ext in {".jpg", ".jpeg"}:
        return raw.startswith(b"\xff\xd8")
    if ext == ".webp":
        return raw.startswith(b"RIFF") and raw[8:12] == b"WEBP"
    return False


def store_brand_logo_bytes(raw, ext, original_name="logo"):
    if len(raw) > MAX_BRAND_LOGO_BYTES:
        raise ValueError("Ese logo pesa demasiado. Usa una imagen menor a 1 MB.")
    if not brand_logo_bytes_look_valid(raw, ext):
        raise ValueError("No pude confirmar que ese archivo sea una imagen válida.")
    BRAND_ASSET_DIR.mkdir(parents=True, exist_ok=True)
    slug = re.sub(r"[^a-z0-9]+", "-", Path(str(original_name or "logo")).stem.lower()).strip("-") or "logo"
    digest = hashlib.sha256(raw).hexdigest()[:10]
    target = BRAND_ASSET_DIR / f"{slug[:34]}-{digest}{ext}"
    target.write_bytes(raw)
    return product_reference(target)


def copy_brand_logo_from_path(source_path, logo_notes=""):
    source = Path(str(source_path or "")).expanduser()
    if not source.exists() or not source.is_file():
        raise ValueError("No encontré la imagen del logo.")
    ext = brand_logo_extension(source.name, mimetypes.guess_type(source.name)[0] or "")
    raw = source.read_bytes()
    relative = store_brand_logo_bytes(raw, ext, source.name)
    return {
        "logo_path": relative,
        "logo_status": "official",
        "logo_notes": str(logo_notes or "").strip() or "Logo enviado por el comprador en el chat.",
        "logo_usage": "Usar el logo oficial guardado en futuros creativos salvo que el comprador pida explícitamente sin logo.",
    }


def save_brand_logo_asset(payload):
    data_url = str((payload or {}).get("data_url") or "").strip()
    if not data_url or "," not in data_url:
        raise ValueError("Sube una imagen de logo.")
    header, encoded = data_url.split(",", 1)
    content_type = str((payload or {}).get("content_type") or "")
    if "image/" in header and not content_type:
        content_type = header.split(";", 1)[0].removeprefix("data:")
    ext = brand_logo_extension((payload or {}).get("filename") or "logo", content_type)
    try:
        raw = base64.b64decode(encoded, validate=True)
    except Exception as exc:
        raise ValueError("No pude leer esa imagen de logo.") from exc
    relative = store_brand_logo_bytes(raw, ext, (payload or {}).get("filename") or "logo")
    existing = (guide_library().get("general", {}) or {}).get("fields", {}) or {}
    update = dict(existing)
    update["logo_path"] = relative
    update["logo_status"] = "official"
    if (payload or {}).get("logo_notes"):
        update["logo_notes"] = str((payload or {}).get("logo_notes") or "").strip()
    elif not update.get("logo_notes"):
        update["logo_notes"] = "Logo oficial subido por el comprador. Usarlo como referencia visual de marca."
    if not update.get("brand_name") and not update.get("offer"):
        update["brand_name"] = "Marca principal"
    usage_lower = str(update.get("logo_usage") or "").strip().lower()
    if not usage_lower or any(phrase in usage_lower for phrase in ["hasta tener archivo oficial", "until official", "no usar hasta"]):
        update["logo_usage"] = "Usar el logo oficial guardado en futuros creativos salvo que el comprador pida explícitamente sin logo."
    library = save_general_brand_memory(update)
    return {
        "saved": True,
        "logo_path": relative,
        "preview_url": f"/api/brand-asset?id={urllib.parse.quote(relative)}",
        "library": library,
    }


def brand_asset_path(asset_id):
    relative = Path(urllib.parse.unquote(str(asset_id or "").strip()))
    if not str(relative) or relative.is_absolute() or relative.suffix.lower() not in BRAND_LOGO_EXTENSIONS:
        raise ValueError("No encontré ese logo.")
    if relative.parts[:2] == ("brand_guides", "assets"):
        candidate = (ROOT_DIR / relative).resolve()
    else:
        candidate = (BRAND_ASSET_DIR / relative).resolve()
    try:
        candidate.relative_to(BRAND_ASSET_DIR.resolve())
    except ValueError as exc:
        raise ValueError("No encontré ese logo.") from exc
    if not candidate.exists() or not candidate.is_file():
        raise ValueError("No encontré ese logo.")
    return candidate


def public_asset_path(asset_id):
    relative = Path(urllib.parse.unquote(str(asset_id or "").strip()))
    if not str(relative) or relative.is_absolute() or relative.suffix.lower() not in PUBLIC_ASSET_EXTENSIONS:
        raise ValueError("No encontré ese recurso.")
    candidate = (PUBLIC_ASSETS_DIR / relative).resolve()
    try:
        candidate.relative_to(PUBLIC_ASSETS_DIR.resolve())
    except ValueError as exc:
        raise ValueError("No encontré ese recurso.") from exc
    if not candidate.exists() or not candidate.is_file():
        raise ValueError("No encontré ese recurso.")
    return candidate


def creative_asset_summary(asset, refresh_id):
    path = Path(str(asset.get("path") or ""))
    if not path.exists() or not path.is_file() or path.suffix.lower() not in CREATIVE_ASSET_EXTENSIONS:
        return None
    try:
        relative = path.resolve().relative_to(CREATIVE_ASSET_ROOT.resolve())
    except ValueError:
        return None
    if not relative.parts or relative.parts[0] != refresh_id:
        return None
    storage = asset_storage_state(asset)
    return {
        "aspect_ratio": str(asset.get("aspect_ratio") or ""),
        "mime_type": str(asset.get("mime_type") or mimetypes.guess_type(path.name)[0] or "image/png"),
        "preview_url": f"/api/creative-asset?id={urllib.parse.quote(str(relative))}",
        "filename": path.name,
        "storage": storage,
        "retention": storage,
        "temporary": not bool(storage.get("saved")),
        "saved_for_ad": bool(storage.get("saved")),
        "expires_at": storage.get("expires_at", ""),
        "days_remaining": storage.get("days_remaining"),
    }


def creative_studio_items(limit=8):
    items = []
    for summary in recent_creative_refreshes(limit):
        manifest = read_json(Path(summary.get("manifest_path") or ""), {})
        if not isinstance(manifest, dict) or not manifest.get("id"):
            continue
        variants = []
        for variant in manifest.get("variants", [])[:6]:
            assets = [
                safe_asset
                for safe_asset in (
                    creative_asset_summary(asset, manifest["id"])
                    for asset in variant.get("assets", [])
                )
                if safe_asset
            ]
            errors = [
                str(asset.get("error") or "")[:180]
                for asset in variant.get("assets", [])
                if asset.get("error")
            ]
            variants.append({
                "variant_id": str(variant.get("variant_id") or ""),
                "copy": variant.get("copy", {}),
                "image_prompts": variant.get("image_prompts", [])[:3],
                "assets": assets,
                "has_generated_image": bool(assets),
                "generation_errors": errors,
            })
        items.append({
            **summary,
            "provider": manifest.get("provider", ""),
            "image_mode": manifest.get("image_mode", ""),
            "brand_memory": manifest.get("brand_memory", {}),
            "variants": variants,
            "has_generated_images": any(item["has_generated_image"] for item in variants),
            "requires_approval": bool(manifest.get("upload_policy", {}).get("requires_approval", True)),
        })
    return items


def creative_asset_policy(cleanup=None):
    items = creative_studio_items(25)
    temporary = 0
    saved = 0
    for batch in items:
        for variant in batch.get("variants", []):
            for asset in variant.get("assets", []):
                if asset.get("saved_for_ad"):
                    saved += 1
                elif asset.get("temporary"):
                    temporary += 1
    return {
        "storage_policy": CREATIVE_IMAGE_STORAGE_POLICY,
        "temporary_image_count": temporary,
        "saved_ad_image_count": saved,
        "cleanup": cleanup or {},
    }


def creative_upload_studio_items(limit=8):
    items = []
    for summary in recent_uploads(limit):
        payload = read_json(Path(summary.get("payload_path") or ""), {})
        items.append({
            **summary,
            "missing_requirements": payload.get("missing_requirements", []),
            "selected_ratios": payload.get("selected_ratios", []),
        })
    return items


def load_onboarding_state():
    state = read_json(ONBOARDING_FILE, {})
    if not isinstance(state, dict):
        state = {}
    state.setdefault("completed", False)
    state.setdefault("skipped", False)
    state.setdefault("deferred", False)
    state.setdefault("deferred_reasons", [])
    state.setdefault("completed_at", "")
    state.setdefault("completed_by", "")
    state.setdefault("communication_style", "")
    state.setdefault("ad_experience_level", "")
    state.setdefault("setup_snapshot", {})
    return state


def dashboard_setup_deferred_reasons(reasons):
    return [reason for reason in (reasons or []) if reason in DASHBOARD_SETUP_DEFERRED_REASONS and reason not in AGENT_INTERVIEW_DEFERRED_REASONS]


def save_agent_preferences(payload, restart_gateway=True):
    payload = payload or {}
    raw_style = str(payload.get("communication_style") or "").strip().lower()
    raw_experience = str(payload.get("ad_experience_level") or payload.get("ads_experience_level") or payload.get("ads_experience") or "").strip().lower()
    style = normalize_communication_style(raw_style, default="") if raw_style else communication_style_from_environment(default="")
    ad_experience = normalize_ad_experience_level(raw_experience, default="") if raw_experience else ad_experience_from_environment(default="")
    raw_timezone = str(payload.get("timezone") or "").strip()
    timezone_name = normalize_timezone(raw_timezone, default="") if raw_timezone else ""
    if raw_style and not style:
        raise ValueError("Elige si prefieres palabras simples o explicaciones técnicas.")
    if raw_experience and not ad_experience:
        raise ValueError("Elige si la experiencia en anuncios es principiante, intermedia o avanzada.")
    if raw_timezone and timezone_name != raw_timezone:
        raise ValueError("No pude reconocer esa zona horaria.")
    if not style and not ad_experience and not timezone_name:
        raise ValueError("Elige al menos una preferencia del agente.")
    updates = {}
    if style:
        updates["AGENT_COMMUNICATION_STYLE"] = style
    if ad_experience:
        updates["AGENT_AD_EXPERIENCE_LEVEL"] = ad_experience
    update_env_values(updates)
    if timezone_name:
        save_timezone_preference(timezone_name, "buyer")
    if ONBOARDING_FILE.exists():
        state = load_onboarding_state()
        if style:
            state["communication_style"] = style
        if ad_experience:
            state["ad_experience_level"] = ad_experience
        if timezone_name:
            state["timezone"] = timezone_name
        write_json(ONBOARDING_FILE, state)
    if restart_gateway:
        config = load_config()
        gateway = start_hermes_gateway(config)
    else:
        gateway = {
            "started": False,
            "mode": "hermes_gateway",
            "restart_deferred": True,
            "detail": "Preference saved without restarting the active Telegram gateway.",
        }
    log_action("agent_preferences_update", {"communication_style": style, "ad_experience_level": ad_experience, "timezone": timezone_name}, "completed")
    return {
        "saved": True,
        "ad_experience_level": ad_experience,
        "timezone": timezone_name or load_config().daily_brief_timezone,
        "ad_experience_instruction": ad_experience_instruction(ad_experience, (payload or {}).get("language") or "es"),
        "communication_preference": {
            **communication_preference(style, (payload or {}).get("language") or "es", ad_experience_level=ad_experience),
            "configured": communication_style_is_configured(),
            "ad_experience_configured": ad_experience_is_configured(),
        },
        "gateway": gateway,
    }


def save_communication_style(payload):
    raw_style = str((payload or {}).get("communication_style") or "").strip().lower()
    if not normalize_communication_style(raw_style, default=""):
        raise ValueError("Elige si prefieres palabras simples o explicaciones técnicas.")
    result = save_agent_preferences(payload)
    log_action("communication_style_update", {"communication_style": result.get("communication_preference", {}).get("style")}, "completed")
    return result


def complete_onboarding(payload=None):
    payload = payload or {}
    requested_style = str(payload.get("communication_style") or "").strip().lower()
    requested_experience = str(payload.get("ad_experience_level") or payload.get("ads_experience_level") or "").strip().lower()
    communication_style = normalize_communication_style(requested_style, default="simple") if requested_style else communication_style_from_environment(default="simple")
    ad_experience = normalize_ad_experience_level(requested_experience, default="") if requested_experience else ad_experience_from_environment(default="")
    if requested_experience and not ad_experience:
        raise ValueError("Elige si la experiencia en anuncios es principiante, intermedia o avanzada.")
    updates = {}
    if requested_style:
        updates["AGENT_COMMUNICATION_STYLE"] = communication_style
    if requested_experience and ad_experience:
        updates["AGENT_AD_EXPERIENCE_LEVEL"] = ad_experience
    if updates:
        update_env_values(updates)
    config = load_config()
    if not dashboard_password_configured(config):
        raise ValueError("Create a dashboard password before finishing onboarding")
    license_info = license_status(config)
    if not license_info.get("valid"):
        raise ValueError("No se pudo confirmar tu licencia. Revisa internet o contacta soporte.")
    ad_config = read_json(AD_CONFIG_FILE, {})
    destination = ad_config.get("creative", {}).get("destination", {})
    if not config.meta_access_token:
        raise ValueError("Conecta Facebook desde el enlace seguro enviado a Telegram antes de terminar.")
    if not config.ad_account_id:
        raise ValueError("Elige tu cuenta publicitaria antes de terminar.")
    if not destination.get("page_id") or not destination.get("url"):
        raise ValueError("Elige tu pagina de Facebook y el link de tu web antes de terminar.")
    business_profile = read_json(BUSINESS_PROFILE_FILE, {})
    if not isinstance(business_profile, dict):
        business_profile = {}
    if not business_profile.get("website_url") and not business_profile.get("social_links"):
        write_onboarding_questions_memory(business_profile, "pending")
    setup = build_setup_status()
    insights_refresh = refresh_managed_real_metrics(reason="onboarding_complete") if config.ad_account_id and config.meta_access_token else {"ok": False, "saved": False, "reason": "missing_account_or_token"}
    metrics = load_metrics()
    if not insights_refresh.get("ok") and metrics.get("source") != "meta_graph":
        raise ValueError("Todavía no pude leer datos reales de Meta. Cambia tu clave o revisa sus permisos y vuelve a intentar.")
    state = {
        "completed": True,
        "skipped": False,
        "deferred": False,
        "deferred_reasons": [],
        "completed_at": now_iso(),
        "completed_by": "dashboard",
        "communication_style": communication_style,
        "ad_experience_level": ad_experience,
        "setup_snapshot": setup.get("summary", {}),
        "first_insights_refresh": redact_payload(insights_refresh),
        "business_profile_snapshot": redact_payload(business_profile),
    }
    write_json(ONBOARDING_FILE, state)
    entitlements = license_entitlements()
    if entitlements["is_agency"]:
        registry = agency_registry()
        if not registry["spaces"]:
            name = business_profile.get("detected_title") or business_profile.get("main_offer") or "Cliente principal"
            space = {"id": workspace_slug(name), "name": str(name)[:80], "created_at": now_iso()}
            registry["spaces"].append(space)
            registry["active_id"] = space["id"]
            write_json(AGENCY_SPACES_FILE, registry)
        elif not registry.get("active_id"):
            registry["active_id"] = registry["spaces"][0]["id"]
            write_json(AGENCY_SPACES_FILE, registry)
        snapshot_workspace(registry["active_id"])
    else:
        save_individual_binding()
    confirmation = mark_license_install_state(config, "onboarding_completed")
    remember_license_binding_state(config, confirmation, "onboarding_completed")
    state["license_device_confirmed"] = bool(confirmation.get("valid"))
    gateway = start_hermes_gateway(config)
    state["communication_gateway_updated"] = bool(gateway.get("started")) if isinstance(gateway, dict) else bool(gateway)
    write_json(ONBOARDING_FILE, state)
    log_action("onboarding_complete", {"setup_summary": state["setup_snapshot"], "first_insights_refresh": state["first_insights_refresh"]}, "completed")
    return state


def skip_onboarding():
    config = load_config()
    if not dashboard_password_configured(config):
        raise ValueError("Crea primero la contraseña del dashboard.")
    business_profile = read_json(BUSINESS_PROFILE_FILE, {})
    if not isinstance(business_profile, dict):
        business_profile = {}
    communication_style = communication_style_from_environment()
    ad_experience = ad_experience_from_environment(default="")
    updates = {"AGENT_COMMUNICATION_STYLE": communication_style}
    if ad_experience:
        updates["AGENT_AD_EXPERIENCE_LEVEL"] = ad_experience
    update_env_values(updates)
    if not ONBOARDING_QUESTIONS_FILE.exists():
        write_onboarding_questions_memory(business_profile, "pending")
    missing = []
    if not license_status(config).get("valid"):
        missing.append("licencia")
    if not config.meta_access_token:
        missing.append("conexion_facebook")
    if not config.ad_account_id:
        missing.append("cuenta_publicitaria")
    if not (config.agent_chat_provider == "hermes" or config.agent_chat_api_key):
        missing.append("cerebro_agente")
    if not telegram_settings(config).get("chat_id"):
        missing.append("telegram")
    state = {
        "completed": True,
        "skipped": True,
        "deferred": True,
        "deferred_reasons": missing,
        "completed_at": now_iso(),
        "completed_by": "skip_and_complete_later",
        "communication_style": communication_style,
        "ad_experience_level": ad_experience,
        "setup_snapshot": build_setup_status().get("summary", {}),
        "business_profile_snapshot": redact_payload(business_profile),
    }
    write_json(ONBOARDING_FILE, state)
    confirmation = mark_license_install_state(config, "onboarding_completed")
    remember_license_binding_state(config, confirmation, "onboarding_completed")
    state["license_device_confirmed"] = bool(confirmation.get("valid"))
    write_json(ONBOARDING_FILE, state)
    start_hermes_gateway(config)
    log_action("onboarding_skip", {"deferred_reasons": missing}, "completed")
    return state


def reset_onboarding():
    if load_onboarding_state().get("completed") and not license_entitlements()["is_agency"]:
        save_individual_binding()
    state = {
        "completed": False,
        "skipped": False,
        "deferred": False,
        "deferred_reasons": [],
        "completed_at": "",
        "completed_by": "",
        "communication_style": communication_style_from_environment(default=""),
        "ad_experience_level": ad_experience_from_environment(default=""),
        "setup_snapshot": {},
        "reset_at": now_iso(),
    }
    write_json(ONBOARDING_FILE, state)
    log_action("onboarding_reset", {}, "completed")
    return state


def onboarding_health(state, config, metrics, current_license_status, destination, business_profile):
    """Guide a completed legacy install back through setup if its real connection is gone."""
    result = dict(state)
    result["deferred_reasons"] = dashboard_setup_deferred_reasons(result.get("deferred_reasons", []))
    if result.get("deferred") and not result["deferred_reasons"]:
        result["deferred"] = False
    result["requires_repair"] = False
    result["repair_reasons"] = []
    result.setdefault("deferred", bool(result.get("skipped")))
    result.setdefault("deferred_reasons", [])
    if not result.get("completed"):
        return result
    if result.get("skipped"):
        return result
    checks = [
        (current_license_status.get("valid"), "licencia"),
        (bool(config.meta_access_token), "conexion_meta"),
        (bool(config.ad_account_id), "cuenta_publicitaria"),
        (bool(destination.get("page_id")) and bool(destination.get("url")), "destinos"),
        (metrics.get("source") == "meta_graph", "datos_reales"),
    ]
    result["repair_reasons"] = [reason for ready, reason in checks if not ready]
    result["requires_repair"] = bool(result["repair_reasons"])
    return result


def money(value):
    return round(float(value or 0), 2)


def pct_change(current, previous):
    current = float(current or 0)
    previous = float(previous or 0)
    if previous == 0:
        return 0.0
    return ((current - previous) / previous) * 100


