def looks_like_demo_metrics(metrics):
    if not isinstance(metrics, dict):
        return False
    ids = {str(c.get("id") or "") for c in metrics.get("campaigns", []) if isinstance(c, dict)}
    names = {str(c.get("name") or "") for c in metrics.get("campaigns", []) if isinstance(c, dict)}
    return bool({"camp_001", "camp_002", "camp_003", "camp_004"} & ids) or "Q2 Conversion Campaign" in names


def enrich_campaign(campaign):
    campaign = dict(campaign)
    spend = float(campaign.get("spend", 0))
    clicks = int(campaign.get("clicks", 0))
    impressions = int(campaign.get("impressions", 0))
    conversions = int(campaign.get("conversions", 0))
    revenue = float(campaign.get("revenue", 0))
    campaign.setdefault("daily_budget", 100)
    campaign.setdefault("frequency", 1.0)
    campaign["ctr"] = (clicks / impressions * 100) if impressions else float(campaign.get("ctr", 0))
    campaign["cpa"] = (spend / conversions) if conversions else 0.0
    campaign["cpc"] = (spend / clicks) if clicks else float(campaign.get("cpc", 0))
    campaign["roas"] = (revenue / spend) if spend else float(campaign.get("roas", 0))
    campaign.setdefault("previous_cpa", campaign["cpa"])
    campaign.setdefault("previous_ctr", campaign["ctr"] * 1.05)
    campaign.setdefault("previous_cpc", campaign["cpc"] * 0.92 if campaign["cpc"] else 0)
    campaign.setdefault("trend", [round(campaign["roas"] * v, 2) for v in [0.82, 0.88, 0.93, 0.96, 1.0, 1.03, 1.0]])
    campaign.setdefault("updated_at", now_iso())
    campaign["health"] = classify_campaign(campaign)
    return campaign


def classify_campaign(campaign):
    if str(campaign.get("status") or "").lower() == "paused":
        return "paused"
    ctr_drop = pct_change(campaign.get("ctr"), campaign.get("previous_ctr"))
    cpc_rise = pct_change(campaign.get("cpc"), campaign.get("previous_cpc"))
    cpa_rise = pct_change(campaign.get("cpa"), campaign.get("previous_cpa"))
    deterioration = ctr_drop <= -20 or cpc_rise >= 30 or cpa_rise >= 25
    frequency_with_deterioration = campaign.get("frequency", 0) > 3 and (ctr_drop <= -10 or cpc_rise >= 15 or cpa_rise >= 15)
    if deterioration or frequency_with_deterioration:
        return "fatigue"
    decision = portfolio_recommendations([campaign], load_profitability_rules())[0]
    if decision.get("decision") == "scale":
        return "winning"
    if decision.get("decision") in {"reduce", "pause_candidate"}:
        return "losing"
    return "neutral"


def load_campaign_metric_profiles():
    payload = read_json(CAMPAIGN_METRIC_PROFILES_FILE, {"campaigns": {}})
    if not isinstance(payload, dict):
        return {}
    campaigns = payload.get("campaigns", payload)
    return campaigns if isinstance(campaigns, dict) else {}


def apply_campaign_metric_profiles(metrics):
    metrics = dict(metrics or {})
    campaigns = attach_campaign_metric_profiles(
        metrics.get("campaigns", []),
        metrics.get("adsets", []),
        load_campaign_metric_profiles(),
    )
    metrics["campaigns"] = campaigns
    metrics["account_priority_metrics"] = account_priority_metrics(campaigns)
    metrics["metric_catalog"] = public_metric_catalog()
    return metrics


def load_metrics():
    metrics = read_json(METRICS_FILE, None)
    if metrics is None:
        metrics = empty_meta_metrics()
    if "source" not in metrics and looks_like_demo_metrics(metrics):
        metrics["source"] = "demo"
        metrics["source_label"] = "Demo data"
    legacy_demo_metrics_env = "ADMI" + "RO_ALLOW_DEMO_METRICS"
    demo_metrics_allowed = env_bool("ADMIRA_ALLOW_DEMO_METRICS", env_bool(legacy_demo_metrics_env, False))
    if metrics.get("source") == "demo" and not demo_metrics_allowed:
        metrics = empty_meta_metrics("missing")
    metrics.setdefault("source", "cached")
    metrics.setdefault("source_label", "Cached dashboard data")
    selected_range = metrics.get("metrics_range")
    if not isinstance(selected_range, dict):
        selected_range = {"preset": "maximum", "since": "", "until": ""}
    try:
        selected_range = normalize_insight_range(
            selected_range.get("preset") or "maximum",
            selected_range.get("since"),
            selected_range.get("until"),
        )
    except ValueError:
        selected_range = normalize_insight_range("maximum")
    metrics["metrics_range"] = {
        "preset": selected_range["preset"],
        "since": selected_range.get("since", ""),
        "until": selected_range.get("until", ""),
    }
    raw_campaigns = [c for c in metrics.get("campaigns", []) if isinstance(c, dict)]
    visible_campaigns = raw_campaigns if metrics.get("source") == "demo" and demo_metrics_allowed else [c for c in raw_campaigns if campaign_is_dashboard_visible(c)]
    metrics["hidden_campaigns_count"] = max(0, len(raw_campaigns) - len(visible_campaigns))
    metrics["campaigns"] = [enrich_campaign({**c, "data_source": c.get("data_source") or metrics.get("source", "")}) for c in visible_campaigns]
    visible_campaign_ids = {str(c.get("id") or c.get("campaign_id") or "") for c in metrics["campaigns"]}
    if "adsets" in metrics:
        metrics["adsets"] = [item for item in metrics.get("adsets", []) if str(item.get("campaign_id") or "") in visible_campaign_ids]
    if "ads" in metrics:
        metrics["ads"] = [item for item in metrics.get("ads", []) if str(item.get("campaign_id") or "") in visible_campaign_ids]
    if "campaign_tree" in metrics:
        metrics["campaign_tree"] = [item for item in metrics.get("campaign_tree", []) if str(item.get("id") or item.get("campaign_id") or "") in visible_campaign_ids]
    metrics["summary"] = build_summary(metrics["campaigns"])
    return apply_campaign_metric_profiles(metrics)


def save_metrics(metrics):
    metrics["timestamp"] = now_iso()
    metrics.setdefault("source", "manual")
    metrics.setdefault("source_label", "Dashboard data")
    metrics["campaigns"] = [enrich_campaign({**c, "data_source": c.get("data_source") or metrics.get("source", "")}) for c in metrics.get("campaigns", [])]
    metrics["summary"] = build_summary(metrics["campaigns"])
    metrics = apply_campaign_metric_profiles(metrics)
    write_json(METRICS_FILE, metrics)


def build_summary(campaigns):
    spend = sum(float(c.get("spend", 0)) for c in campaigns)
    revenue = sum(float(c.get("revenue", 0)) for c in campaigns)
    clicks = sum(int(c.get("clicks", 0)) for c in campaigns)
    impressions = sum(int(c.get("impressions", 0)) for c in campaigns)
    conversions = sum(int(c.get("conversions", 0)) for c in campaigns)
    budget = sum(float(c.get("daily_budget", 0)) for c in campaigns if c.get("status") != "paused")
    return {
        "total_spend": money(spend),
        "total_revenue": money(revenue),
        "total_impressions": impressions,
        "total_clicks": clicks,
        "total_conversions": conversions,
        "overall_roas": round(revenue / spend, 2) if spend else 0,
        "overall_ctr": round(clicks / impressions * 100, 2) if impressions else 0,
        "overall_cpa": money(spend / conversions) if conversions else 0,
        "active_budget": money(budget),
        "active_campaigns": len([c for c in campaigns if c.get("status") == "active"]),
    }


def calculate_recommendations(campaigns):
    rules = load_profitability_rules()
    config = load_config()
    state = load_optimization_state()
    recommendations = []
    campaigns_by_id = {str(c.get("id") or c.get("campaign_id")): c for c in campaigns}
    for decision in portfolio_recommendations(campaigns, rules, state):
        campaign = campaigns_by_id.get(str(decision.get("campaign_id")), {})
        current_budget = float(decision.get("current_budget", 0))
        recommended_budget = float(decision.get("recommended_budget", current_budget))
        change = recommended_budget - current_budget
        change_pct = float(decision.get("change_pct", 0))
        recommendation = {
            "campaign_id": decision.get("campaign_id"),
            "campaign_name": decision.get("campaign_name"),
            "current_budget": money(current_budget),
            "recommended_budget": money(recommended_budget),
            "change": money(change),
            "change_pct": round(change_pct, 1),
            "confidence": 90 if decision.get("ready") else 0,
            "reason": decision.get("reason"),
            "proposal_only": decision.get("shadow_mode", True) and decision.get("action") != "observe",
            "requires_approval": decision.get("action") != "observe" and not decision.get("shadow_mode", True),
            "roas": round(campaign.get("roas", 0), 2),
            "health": campaign.get("health"),
            "decision": decision.get("decision"),
            "action": decision.get("action"),
            "objective": decision.get("objective"),
            "evidence_gate": decision.get("evidence_gate"),
            "mutation_allowed": decision.get("mutation_allowed", False),
            "shadow_mode": decision.get("shadow_mode", True),
        }
        recommendation["decision_evidence"] = recommendation_decision_evidence(campaign, recommendation, rules)
        recommendations.append(recommendation)
    return recommendations


def fatigue_items(campaigns):
    items = []
    for campaign in campaigns:
        ctr_drop = pct_change(campaign.get("ctr"), campaign.get("previous_ctr"))
        cpc_rise = pct_change(campaign.get("cpc"), campaign.get("previous_cpc"))
        cpa_rise = pct_change(campaign.get("cpa"), campaign.get("previous_cpa"))
        reasons = []
        deterioration = ctr_drop <= -20 or cpc_rise >= 30 or cpa_rise >= 25
        if campaign.get("frequency", 0) > 3 and deterioration:
            reasons.append(f"frequency {campaign.get('frequency'):.1f}")
        if ctr_drop <= -20:
            reasons.append(f"CTR {abs(ctr_drop):.0f}% down")
        if cpc_rise >= 30:
            reasons.append(f"CPC {cpc_rise:.0f}% up")
        if cpa_rise >= 25:
            reasons.append(f"CPA {cpa_rise:.0f}% up")
        if reasons:
            items.append(
                {
                    "campaign_id": campaign.get("id"),
                    "campaign_name": campaign.get("name"),
                    "severity": "high" if len(reasons) > 1 else "medium",
                    "reasons": reasons,
                    "frequency": campaign.get("frequency", 0),
                    "ctr_change": round(ctr_drop, 1),
                    "cpc_change": round(cpc_rise, 1),
                }
            )
    return items


def business_context_snapshot(profile):
    profile = profile if isinstance(profile, dict) else {}
    business_type = str(profile.get("business_type") or profile.get("business_short") or "").strip()
    main_offer = str(profile.get("main_offer") or profile.get("offer") or "").strip()
    ideal_customer = str(profile.get("ideal_customer") or profile.get("audience") or "").strip()
    current_stage = str(profile.get("current_stage") or "").strip()
    what_to_improve = str(profile.get("what_to_improve") or "").strip()
    success_goal = str(profile.get("success_goal") or "").strip()
    sales_channel = str(profile.get("sales_channel") or profile.get("channel") or "").strip()
    brand_tone = str(profile.get("brand_tone") or "").strip()
    website_url = str(profile.get("website_url") or "").strip()
    current_ads = str(profile.get("current_ads") or "").strip()
    ready = bool(business_type or main_offer or ideal_customer or current_stage or what_to_improve or website_url)
    summary_parts = [part for part in [business_type, main_offer, ideal_customer, current_stage] if part]
    summary = " · ".join(summary_parts)
    if not summary and website_url:
        summary = website_url
    if not summary:
        summary = "Perfil del negocio pendiente"
    if not main_offer:
        next_step = "Definir en una frase qué vendes."
    elif not ideal_customer:
        next_step = "Decir quién compra hoy."
    elif not current_stage:
        next_step = "Contar en qué punto está el negocio."
    elif not what_to_improve:
        next_step = "Decir qué quiere mejorar primero."
    else:
        next_step = "Convertir esto en un plan simple de anuncios."
    if any(term in sales_channel.lower() for term in ["whatsapp", "instagram", "dm", "mensaje", "mensajes"]):
        audience_hint = "Empezar amplio y dejar mensajes o retargeting para personas que ya conocen el negocio."
    elif website_url:
        audience_hint = "Probar una audiencia amplia con el sitio como destino y dejar que Meta aprenda."
    else:
        audience_hint = "Empezar con una audiencia amplia y ajustar luego con datos reales."
    if current_stage.lower().startswith(("ya vendo", "already", "ya tengo", "tengo anuncios")) or current_ads:
        creative_hint = "Buscar un ángulo nuevo sin perder lo que ya funcionó."
    elif what_to_improve:
        creative_hint = f"Crear creativos que ataquen: {what_to_improve.lower()}"
    else:
        creative_hint = "Usar una imagen clara, un beneficio directo y poco texto."
    if "lead" in success_goal.lower() or "mensaje" in success_goal.lower():
        campaign_hint = "Campaña de leads o mensajes, creada en pausa antes de activar."
    elif "venta" in success_goal.lower() or "buy" in success_goal.lower() or website_url:
        campaign_hint = "Campaña de conversiones o compras, con una oferta fácil de entender."
    else:
        campaign_hint = "Campaña simple, visible y fácil de medir."
    return {
        "ready": ready,
        "business_type": business_type,
        "main_offer": main_offer,
        "ideal_customer": ideal_customer,
        "current_stage": current_stage,
        "what_to_improve": what_to_improve,
        "success_goal": success_goal,
        "sales_channel": sales_channel,
        "brand_tone": brand_tone,
        "website_url": website_url,
        "current_ads": current_ads,
        "summary": summary,
        "next_step": next_step,
        "audience_hint": audience_hint,
        "creative_hint": creative_hint,
        "campaign_hint": campaign_hint,
    }


def build_daily_brief(metrics, recommendations, business_profile=None):
    campaigns = metrics.get("campaigns", [])
    summary = metrics.get("summary", {})
    business_context = business_context_snapshot(business_profile)
    active = [c for c in campaigns if c.get("status") == "active"]
    winners = sorted([c for c in campaigns if c.get("health") == "winning"], key=lambda c: c.get("roas", 0), reverse=True)
    losers = sorted([c for c in campaigns if c.get("health") == "losing"], key=lambda c: c.get("roas", 0))
    fatigue = fatigue_items(campaigns)
    projected_spend = summary.get("active_budget", 0)
    action_summary = build_action_summary(recommendations, [], [], fatigue)
    optimization_state = load_optimization_state()
    optimization = {
        "mode": optimization_state.get("mode", "shadow"),
        "unlock": optimization_unlock_status(optimization_state),
        "reconciliation": reconcile_business_outcomes(metrics),
        "anomalies": anomaly_diagnostics(metrics),
        "funnel": funnel_diagnostics(),
        "data_quality": metrics.get("data_quality", {}),
    }
    business_prefix = f"{business_context.get('summary')} · {business_context.get('next_step')} · " if business_context.get("ready") else ""
    return {
        "generated_at": now_iso(),
        "business_context": business_context,
        "questions": [
            {
                "question": "Am I on track?",
                "answer": f"{business_prefix}Active daily budget is ${projected_spend:,.2f}; account ROAS is {summary.get('overall_roas', 0):.2f}x with CPA ${summary.get('overall_cpa', 0):,.2f}.",
            },
            {
                "question": "What's running?",
                "answer": f"{len(active)} active campaigns, {len(campaigns) - len(active)} paused or staged.",
            },
            {
                "question": "How's performance?",
                "answer": f"7-day view shows ${summary.get('total_spend', 0):,.2f} spend, ${summary.get('total_revenue', 0):,.2f} revenue, {summary.get('total_conversions', 0):,} conversions, and {summary.get('overall_ctr', 0):.2f}% CTR.",
            },
            {
                "question": "Who's winning/losing?",
                "answer": f"Top winner: {winners[0]['name']} at {winners[0]['roas']:.2f}x ROAS." if winners else "No clear winner yet.",
            },
            {
                "question": "Any fatigue?",
                "answer": f"{len(fatigue)} campaign(s) show fatigue signals." if fatigue else "No material fatigue triggers right now.",
            },
        ],
        "winners": [{"name": c["name"], "roas": round(c["roas"], 2), "cpa": money(c["cpa"])} for c in winners[:4]],
        "losers": [{"name": c["name"], "roas": round(c["roas"], 2), "cpa": money(c["cpa"])} for c in losers[:4]],
        "pending_actions": [r for r in recommendations if r["requires_approval"]],
        "action_summary": action_summary,
        "optimization": optimization,
    }


def latest_daily_report():
    reports = sorted(OUTPUT_DIR.glob("daily_brief_*.json"), reverse=True)
    for path in reports:
        report = read_json(path, None)
        if isinstance(report, dict) and isinstance(report.get("brief"), dict):
            report["_path"] = str(path)
            return report
    return None


def scheduled_brief_or_live(metrics, recommendations, business_profile=None):
    report = latest_daily_report()
    if not report:
        return build_daily_brief(metrics, recommendations, business_profile)
    brief = report.get("brief", {})
    five = brief.get("five_questions", {})
    business_context = business_context_snapshot(business_profile)
    questions = [
        ("Am I on track?", five.get("am_i_on_track")),
        ("What's running?", five.get("whats_running")),
        ("How's performance?", five.get("hows_performance")),
        ("Who's winning/losing?", five.get("winning_losing")),
        ("Any fatigue?", five.get("fatigue")),
    ]
    fallback = build_daily_brief(metrics, recommendations, business_profile)
    return {
        "generated_at": brief.get("generated_at") or report.get("generated_at") or now_iso(),
        "source": "scheduled_daily_agent",
        "report_path": report.get("_path"),
        "business_context": business_context,
        "questions": [
            {"question": question, "answer": answer or fallback["questions"][idx]["answer"]}
            for idx, (question, answer) in enumerate(questions)
        ],
        "winners": [{"name": c.get("name"), "roas": round(c.get("roas", 0), 2), "cpa": money(c.get("cpa", 0))} for c in brief.get("winners", [])[:4]],
        "losers": [{"name": c.get("name"), "roas": round(c.get("roas", 0), 2), "cpa": money(c.get("cpa", 0))} for c in brief.get("losers", [])[:4]],
        "pending_actions": [r for r in brief.get("recommendations", []) if r.get("requires_approval")],
        "action_summary": brief.get("action_summary") or fallback.get("action_summary"),
        "optimization": brief.get("optimization") or fallback.get("optimization"),
    }


def log_action(action_type, payload, status="completed"):
    actions = read_json(ACTIONS_FILE, [])
    record = {"id": f"act_{datetime.now().strftime('%Y%m%d_%H%M%S_%f')}", "type": action_type, "status": status, "payload": redact_payload(payload), "created_at": now_iso()}
    actions.insert(0, record)
    write_json(ACTIONS_FILE, actions[:200])
    return record


def add_pending(action_type, payload):
    pending = read_json(PENDING_FILE, [])
    approval_id = str((payload or {}).get("approval_id") or f"approval_{datetime.now().strftime('%Y%m%d_%H%M%S_%f')}").strip()
    existing = next((item for item in pending if isinstance(item, dict) and item.get("id") == approval_id and item.get("status", "pending") == "pending"), None)
    if existing:
        return existing
    record = {"id": approval_id, "type": action_type, "status": "pending", "payload": payload, "created_at": now_iso()}
    pending.insert(0, record)
    write_json(PENDING_FILE, pending[:100])
    log_action(action_type, payload, "pending_approval")
    return record


def campaign_by_id(metrics, campaign_id):
    for campaign in metrics.get("campaigns", []):
        if campaign.get("id") == campaign_id:
            return campaign
    return None


def assert_campaign_uses_active_account(config, campaign):
    campaign_account = clean_ad_account_id(campaign.get("ad_account_id") or campaign.get("account_id") or "")
    active_account = clean_ad_account_id(getattr(config, "ad_account_id", "") or "")
    if campaign_account and active_account and campaign_account != active_account:
        account_name = campaign.get("account_name") or campaign_account
        raise ValueError(f"Esa campaña pertenece a {account_name}. Primero cambia la cuenta activa a {campaign_account} en Configuración para evitar tocar la cuenta equivocada.")


def should_stage_action(config, action_type, payload):
    # Admira no longer exposes selectable control modes.
    # The only buyer-facing rule is action risk: the agent may prepare/create
    # no-spend paused structures, while spend-capable or destructive mutations
    # wait for the buyer's explicit approval.
    if action_type == "pause_campaign":
        return True, "approval_required_for_account_change"
    if action_type == "budget_change":
        return True, "approval_required_for_budget_change"
    if action_type == "resume_campaign":
        return True, "activation_requires_approval"
    if action_type == "create_campaign":
        return True, "active_campaign_requires_approval"
    if action_type in {"creative_upload", "create_ad", "create_creative"}:
        return True, "publishing_requires_approval"
    return False, "within_rules"


def execute_approved_account_action(config, action_type, campaign, action_payload):
    require_cloud_license(f"{action_type} requires an active license")
    client = SocialFlowClient(config)
    target_type = campaign.get("target_type", "campaign")
    target_id = campaign.get("target_id", campaign.get("id"))
    if action_type == "pause_campaign":
        result = client.pause(target_type, target_id)
    elif action_type == "resume_campaign":
        result = client.resume(target_type, target_id)
    elif action_type == "budget_change":
        currency = str(action_payload.get("account_currency") or configured_ad_account_currency() or "").strip().upper()
        api_amount = meta_budget_api_amount(action_payload.get("new_budget", 0), currency)
        result = client.set_budget(target_type, target_id, api_amount)
        action_payload["meta_budget_api_amount"] = api_amount
        action_payload["account_currency"] = currency
    else:
        raise ValueError("Unsupported approved account action")
    action_payload["connector"] = "graph_api"
    action_payload["result"] = result
    action_payload["executed"] = bool(result.get("executed") and result.get("returncode") == 0)
    if not action_payload["executed"]:
        log_action(action_type, action_payload, "failed")
        raise ValueError("No pude confirmar el cambio en Meta. La cuenta no fue marcada como modificada; revisa conexión y permisos.")
    return action_payload


def apply_action(payload):
    config = load_config()
    action = payload.get("action")
    if action == "refresh_insights":
        live_dashboard = str(payload.get("refresh_scope") or "").strip().lower() == "dashboard_live"
        selected = current_dashboard_metrics_range(
            payload.get("date_preset") if "date_preset" in payload else None,
            payload.get("since", ""),
            payload.get("until", ""),
        )
        return refresh_managed_real_metrics(
            reason="dashboard_live" if live_dashboard else "dashboard_action",
            live_dashboard=live_dashboard,
            date_preset=selected["preset"],
            since=selected.get("since", ""),
            until=selected.get("until", ""),
        )
    metrics = load_metrics()
    campaign_id = payload.get("campaign_id")
    campaign = campaign_by_id(metrics, campaign_id)
    if action in {"pause", "resume", "adjust_budget", "apply_recommendation"} and not campaign:
        raise ValueError("Campaign not found")
    if action in {"pause", "resume", "adjust_budget", "apply_recommendation"}:
        assert_campaign_uses_active_account(config, campaign)

    if action == "pause":
        action_payload = {"campaign_id": campaign_id, "name": campaign.get("name"), "spend": campaign.get("spend", 0)}
        stage, reason = should_stage_action(config, "pause_campaign", action_payload)
        if stage:
            action_payload["guardrail_reason"] = reason
            return add_pending("pause_campaign", action_payload)
        execute_approved_account_action(config, "pause_campaign", campaign, action_payload)
        campaign["status"] = "paused"
        record_optimization_action(campaign_id)
        save_metrics(metrics)
        return log_action("pause_campaign", action_payload, "completed")

    if action == "resume":
        action_payload = {"campaign_id": campaign_id, "name": campaign.get("name")}
        stage, reason = should_stage_action(config, "resume_campaign", action_payload)
        if stage:
            action_payload["guardrail_reason"] = reason
            return add_pending("resume_campaign", action_payload)
        execute_approved_account_action(config, "resume_campaign", campaign, action_payload)
        campaign["status"] = "active"
        record_optimization_action(campaign_id)
        save_metrics(metrics)
        return log_action("resume_campaign", action_payload, "completed")

    if action in {"adjust_budget", "apply_recommendation"}:
        current = float(campaign.get("daily_budget", 0))
        new_budget = float(payload.get("new_budget", current))
        account_currency = configured_ad_account_currency()
        budget_confirmation = str(payload.get("budget_confirmation") or f"{new_budget:g} {account_currency}").strip()
        budget_contract = confirmed_budget_contract(budget_confirmation, account_currency=account_currency)
        if not budget_contract.get("ok"):
            raise ValueError(
                "No preparé el cambio de presupuesto: el monto y la moneda deben coincidir exactamente "
                f"con la cuenta publicitaria ({account_currency or 'moneda desconocida'})."
            )
        new_budget = float(budget_contract["amount"])
        change_pct = abs((new_budget - current) / current * 100) if current else 100
        action_payload = {
            "campaign_id": campaign_id,
            "name": campaign.get("name"),
            "target_type": campaign.get("target_type", "campaign"),
            "target_id": campaign.get("target_id", campaign_id),
            "current_budget": current,
            "new_budget": new_budget,
            "budget_confirmation": budget_confirmation,
            "account_currency": budget_contract["currency"],
            "meta_budget_api_amount": budget_contract["api_amount"],
            "change_pct": round(change_pct, 1),
        }
        stage, reason = should_stage_action(config, "budget_change", action_payload)
        if stage:
            action_payload["guardrail_reason"] = reason
            return add_pending("budget_change", action_payload)
        execute_approved_account_action(config, "budget_change", campaign, action_payload)
        campaign["daily_budget"] = money(new_budget)
        record_optimization_action(campaign_id)
        save_metrics(metrics)
        return log_action("budget_change", action_payload, "completed")

    if action == "run_agent":
        return run_daily_agent()

    raise ValueError("Unsupported action")


def verified_campaign_stack_execution(result):
    """A campaign exists only after Meta returns IDs for all three levels."""
    if not isinstance(result, dict) or result.get("executed") is not True:
        return False
    campaign_id = str(result.get("campaign_id") or "").strip()
    adset_ids = [str(value).strip() for value in (result.get("adset_ids") or []) if str(value).strip()]
    ad_ids = [str(value).strip() for value in (result.get("ad_ids") or []) if str(value).strip()]
    return bool(campaign_id and adset_ids and ad_ids)


def verify_campaign_stack_with_graph(client, result):
    """Read back every created object and require Meta HTTP 200 + PAUSED.

    A successful write response is necessary but not sufficient evidence for
    buyer-facing success.  This independent read verifies the exact IDs Meta
    returned for the campaign, every ad set, and every ad.  Only configured
    ``status`` is authoritative here; ``effective_status`` may temporarily be
    IN_PROCESS/PENDING_REVIEW even though no object can spend while PAUSED.
    """
    if not verified_campaign_stack_execution(result):
        return {
            "ok": False,
            "verified_by": "graph_readback",
            "reason": "campaign_stack_ids_incomplete",
            "objects": [],
        }
    requested = [
        ("campaign", str(result.get("campaign_id") or "").strip()),
        *[("adset", str(value).strip()) for value in (result.get("adset_ids") or []) if str(value).strip()],
        *[("ad", str(value).strip()) for value in (result.get("ad_ids") or []) if str(value).strip()],
    ]
    requested_ids = [object_id for _kind, object_id in requested]
    if len(requested_ids) != len(set(requested_ids)):
        return {
            "ok": False,
            "verified_by": "graph_readback",
            "reason": "campaign_stack_ids_not_unique",
            "objects": [],
        }
    campaign_id = str(result.get("campaign_id") or "").strip()
    requested_adset_ids = {
        str(value).strip()
        for value in (result.get("adset_ids") or [])
        if str(value).strip()
    }
    objects = []
    for kind, object_id in requested:
        fields = "id,name,status,effective_status"
        if kind == "adset":
            fields += ",campaign_id"
        elif kind == "ad":
            fields += ",campaign_id,adset_id"
        try:
            readback = client.get_graph(object_id, {"fields": fields})
        except Exception as exc:
            objects.append({
                "kind": kind,
                "requested_id": object_id,
                "ok": False,
                "http_status": 0,
                "reason": f"graph_readback_exception:{type(exc).__name__}",
            })
            continue
        body = readback.get("body") if isinstance(readback, dict) and isinstance(readback.get("body"), dict) else {}
        http_status = int(readback.get("status") or 0) if isinstance(readback, dict) else 0
        returned_id = str(body.get("id") or "").strip()
        configured_status = str(body.get("status") or "").strip().upper()
        parent_campaign_id = str(body.get("campaign_id") or "").strip()
        parent_adset_id = str(body.get("adset_id") or "").strip()
        parent_matches = True
        if kind == "adset":
            parent_matches = parent_campaign_id == campaign_id
        elif kind == "ad":
            parent_matches = (
                parent_campaign_id == campaign_id
                and parent_adset_id in requested_adset_ids
            )
        verified = bool(
            readback.get("ok") is True
            and http_status == 200
            and returned_id == object_id
            and configured_status == "PAUSED"
            and parent_matches
        )
        objects.append({
            "kind": kind,
            "requested_id": object_id,
            "returned_id": returned_id,
            "ok": verified,
            "http_status": http_status,
            "status": configured_status,
            "effective_status": str(body.get("effective_status") or "").strip().upper(),
            "campaign_id": parent_campaign_id,
            "adset_id": parent_adset_id,
            "parent_matches": parent_matches,
        })
    covered_adset_ids = {
        item.get("adset_id")
        for item in objects
        if item.get("kind") == "ad" and item.get("adset_id")
    }
    hierarchy_complete = requested_adset_ids.issubset(covered_adset_ids)
    verified_all = bool(
        objects
        and len(objects) == len(requested)
        and all(item.get("ok") for item in objects)
        and hierarchy_complete
    )
    return {
        "ok": verified_all,
        "verified_by": "graph_readback",
        "reason": "" if verified_all else "campaign_stack_graph_readback_failed",
        "hierarchy_complete": hierarchy_complete,
        "objects": objects,
    }


def campaign_location_selection_source(payload):
    """Return structured Meta locations regardless of the model's valid key."""
    explicit = payload.get("targeting_locations_json") or payload.get("targeting_locations")
    if explicit:
        return explicit
    locations = payload.get("locations")
    if isinstance(locations, dict):
        return locations
    if isinstance(locations, list) and any(isinstance(item, dict) for item in locations):
        return locations
    return None


def enrich_campaign_location_selections(items, search=None):
    """Complete abbreviated model locations from Meta before any mutation."""
    search = search or meta_targeting_search
    enriched = []
    for original in items or []:
        item = dict(original) if isinstance(original, dict) else original
        if not isinstance(item, dict):
            enriched.append(item)
            continue
        location_type = str(item.get("type") or "").strip().lower()
        if location_type in {"country", "city", "region", "zip", "geo_market"}:
            enriched.append(item)
            continue
        key = str(item.get("key") or item.get("id") or "").strip()
        query = str(item.get("name") or item.get("label") or key).strip()
        result = search({"kind": "location", "q": query, "limit": 25}) if query else {}
        candidates = result.get("items") or [] if isinstance(result, dict) and result.get("ok") else []
        exact = [candidate for candidate in candidates if str(candidate.get("key") or candidate.get("id") or "").strip() == key]
        if len(exact) == 1:
            item = {**item, **exact[0]}
        enriched.append(item)
    return enriched


def create_campaign(payload):
    payload = normalize_campaign_stack_arguments(payload)
    gender_error = _campaign_gender_contract_error(payload)
    if gender_error:
        raise ValueError(gender_error)
    lead_gen_form_id = str(payload.get("lead_gen_form_id") or "").strip()
    if campaign_arguments_have_lead_intent(payload) and not lead_gen_form_id:
        raise ValueError(
            "lead_gen_form_id: una campaña de formularios necesita el ID del formulario nativo de Meta antes de crear cualquier objeto."
        )
    final_status = str(payload.get("final_status") or "ACTIVE").strip().upper()
    if final_status not in {"PAUSED", "ACTIVE"}:
        final_status = "ACTIVE"
    active_confirmed = boolish(payload.get("active_spend_confirmed")) is True
    if requires_active_confirmation(payload, final_status) and not active_confirmed:
        raise ValueError("Para dejar anuncios activos debes marcar: Sí, crear y dejar activo.")
    budget_plan = normalize_budget_plan(payload, parse_money_like(payload.get("daily_budget"), 50) or 50)
    status_plan = normalize_status_plan(payload, final_status, active_confirmed)
    creator = CampaignCreator()
    selected_interests = parse_targeting_items(payload.get("targeting_interests_json") or payload.get("targeting_interests"), "interest")
    selected_locations = parse_targeting_items(campaign_location_selection_source(payload), "location")
    if selected_locations:
        selected_locations = enrich_campaign_location_selections(selected_locations)
        incomplete_location = next((
            item for item in selected_locations
            if isinstance(item, dict)
            and str(item.get("type") or "").strip().lower() not in {"country", "city", "region", "zip", "geo_market"}
        ), None)
        if incomplete_location:
            raise ValueError(
                "targeting_location_incomplete: Meta no pudo confirmar el tipo de la ubicación estructurada. "
                "No se creó ningún objeto."
            )
    manual_interests = [item.strip() for item in str(payload.get("interests", "")).split(",") if item.strip()]
    if manual_interests and not selected_interests:
        raise ValueError(
            "Los intereses escritos son ideas, no IDs vigentes de Meta. "
            "Busca cada uno con search_meta_targeting y vuelve a enviar targeting_interests con los IDs devueltos por Meta."
        )
    detailed_id_validation = validate_detailed_targeting_ids(payload)
    if not detailed_id_validation.get("ok"):
        first_detail_error = (detailed_id_validation.get("errors") or [{}])[0]
        raise ValueError(
            f"{first_detail_error.get('code') or 'targeting_detail_invalid_id'}: la segmentación detallada contiene un ID que no proviene del catálogo actual de Meta."
        )
    manual_locations = normalize_location_codes(payload.get("locations"), default=[])
    location_queries = list(payload.get("targeting_location_queries") or [])
    if location_queries:
        resolved_locations = resolve_campaign_location_queries(location_queries, manual_locations)
        existing_location_ids = {
            str(item.get("id") or item.get("key") or "").strip()
            for item in selected_locations
            if isinstance(item, dict)
        }
        selected_locations.extend(
            item for item in resolved_locations
            if str(item.get("id") or item.get("key") or "").strip() not in existing_location_ids
        )
    explicit_location_source = any(
        payload.get(key) not in (None, "", [], ())
        for key in ("locations", "targeting_countries", "targeting_locations", "countries", "country_codes")
    )
    if not manual_locations:
        manual_locations = infer_location_codes_from_context(
            payload.get("name"),
            payload.get("market"),
            payload.get("target_market"),
            payload.get("campaign_constraints"),
            payload.get("audience"),
            payload.get("target_audience"),
        )
    if explicit_location_source and not selected_locations and not manual_locations:
        raise ValueError(
            "targeting_location_invalid: no pude convertir la ubicación indicada a códigos de país o selecciones reales de Meta. "
            "Busca el país con search_meta_targeting y usa el resultado exacto."
        )

    age_bounds = normalize_age_bounds(
        payload.get("age_range") or payload.get("targeting_age_range") or payload.get("audience_age_range") or payload.get("age"),
        age_min=payload.get("age_min", payload.get("min_age", payload.get("targeting_age_min", 18))),
        age_max=payload.get("age_max", payload.get("max_age", payload.get("targeting_age_max", 65))),
    )
    if not age_bounds.get("ok"):
        raise ValueError(
            f"{age_bounds.get('error') or 'targeting_age_invalid'}: usa un rango entre 13 y 65 y asegúrate de que la edad máxima no sea menor que la mínima."
        )
    payload["age_min"] = age_bounds["age_min"]
    payload["age_max"] = age_bounds["age_max"]

    validation_locations = selected_locations or [
        {
            "key": code,
            "name": country_name_for_code(code),
            "type": "country",
            "country_code": code,
        }
        for code in manual_locations
    ]
    config_for_targeting = load_config()
    live_search = None
    if str(getattr(config_for_targeting, "meta_access_token", "") or "").strip():
        def live_search(kind, query):
            # Explicit country codes are stable ISO-3166 inputs and may come
            # from a buyer rather than the picker. Meta itself validates them
            # in the ad-set request; only picker selections need a catalog
            # round-trip here (interest IDs always require one).
            if kind == "location" and not selected_locations:
                return {"ok": True, "items": [{"key": str(query or "").strip().upper(), "country_code": str(query or "").strip().upper()}]}
            return meta_targeting_search({"kind": kind, "q": query, "limit": 25})

    targeting_validation = validate_meta_targeting_selection(
        selected_interests,
        validation_locations,
        age_min=payload["age_min"],
        age_max=payload["age_max"],
        live_search=live_search,
        verify_locations=bool(selected_locations),
    )
    if not targeting_validation.get("ok"):
        first_error = (targeting_validation.get("errors") or [{}])[0]
        code = first_error.get("code") or "targeting_invalid"
        raise ValueError(
            f"{code}: la segmentación no pasó la verificación previa de Meta. "
            "Vuelve a buscar ubicaciones/intereses en Meta y usa exactamente los resultados devueltos."
        )
    if selected_interests:
        selected_interests = targeting_validation.get("interests") or selected_interests
    if selected_locations:
        selected_locations = targeting_validation.get("locations") or selected_locations
    interests = [item.get("name") for item in selected_interests if item.get("name")] or manual_interests
    locations = targeting_location_values(selected_locations, manual_locations or [])
    audience = creator.create_audience_targeting(
        locations=locations or ["US"],
        age_min=payload["age_min"],
        age_max=payload["age_max"],
        interests=interests,
    )
    audience = merge_expert_targeting(audience, payload)
    if selected_locations or selected_interests:
        audience["meta_targeting"] = {
            "locations": selected_locations,
            "interests": selected_interests,
        }
    signal_review = review_signal_quality(payload, metrics=load_metrics(), language=chat_lang(payload))
    success_metrics = normalize_success_metrics(payload)
    placement_config = normalize_placement_config(payload.get("placements") or payload.get("placement_preset") or payload.get("manual_placements"))
    schedule = normalize_schedule(payload)
    bidding = normalize_bidding(payload)
    creative_controls = normalize_creative_controls(payload)
    message_destination = message_destination_from_plan(payload)
    whatsapp_phone_number_id = whatsapp_phone_number_id_from_plan(payload)
    if creative_controls.get("manual_creative_completion") or creative_controls.get("create_placeholder_ad"):
        final_status = "PAUSED"
        active_confirmed = False
        status_plan = {"campaign": "PAUSED", "adset": "PAUSED", "ad": "PAUSED"}
    direct_plan = direct_publishing_campaign_plan(payload, creative_controls)
    ad_set = creator.create_ad_set_config(
        f"{payload.get('name', 'New Campaign')} - Core",
        audience,
        budget_plan["adset_daily"],
    )
    if budget_plan.get("is_adset_budget_sharing_enabled") is not None:
        ad_set["is_adset_budget_sharing_enabled"] = bool(budget_plan.get("is_adset_budget_sharing_enabled"))
    if budget_plan.get("adset_lifetime"):
        ad_set["lifetime_budget"] = budget_plan["adset_lifetime"]
    ad_set["placements"] = placement_config
    ad_set["billing_event"] = normalize_billing_event(payload.get("billing_event"))
    if bidding:
        ad_set["bidding"] = bidding
    if message_destination:
        # Persist the destination on the campaign file. The executor is
        # intentionally driven by this durable file, not the transient tool
        # arguments, so losing it here would make a WhatsApp draft revert to
        # the default web-conversion goal on retry.
        ad_set["message_destination"] = message_destination
        if whatsapp_phone_number_id:
            ad_set["whatsapp_phone_number_id"] = whatsapp_phone_number_id
    if schedule.get("start_time"):
        ad_set["start_time"] = schedule["start_time"]
    if schedule.get("end_time"):
        ad_set["end_time"] = schedule["end_time"]
    ad_set["status"] = status_plan["adset"]
    ad_set = apply_signal_quality_to_adset(ad_set, signal_review)

    # Preserve an explicitly requested multi-offer structure.  The legacy
    # path above still builds a safe Core ad set, but a request containing
    # `ad_sets:[{ads:[...]}, ...]` must not be collapsed into that one set.
    # Each nested ad is made durable here so execution can bind it to the
    # matching Meta ad set instead of reusing the first creative globally.
    explicit_ad_sets = [
        item for item in (payload.get("ad_sets") or [])
        if isinstance(item, dict)
    ]
    stored_ad_sets = [ad_set]
    if explicit_ad_sets:
        inherited_ad = {
            "primary_text": str(payload.get("primary_text") or "").strip(),
            "headline": str(payload.get("headline") or payload.get("name") or "Nueva oferta").strip(),
            "creative_image_path": str(payload.get("creative_image_path") or "").strip(),
            "landing_url": str(payload.get("landing_url") or "").strip(),
            "cta": str(payload.get("cta") or ("" if payload.get("on_meta_destination") else "LEARN_MORE")).strip().upper(),
            "cta_link": creative_controls["cta_link"],
            "image_hash": creative_controls["image_hash"],
            "image_url": creative_controls["image_url"],
            "video_url": creative_controls["video_url"],
            "message_destination": message_destination,
            "lead_gen_form_id": lead_gen_form_id,
            "whatsapp_phone_number_id": whatsapp_phone_number_id,
            "prefilled_message": str(payload.get("prefilled_message") or "").strip(),
            "welcome_message": str(payload.get("welcome_message") or payload.get("initial_business_message") or "").strip(),
            "on_meta_destination": bool(payload.get("on_meta_destination")),
            "object_story_spec": creative_controls["object_story_spec"],
            "object_story_id": creative_controls["object_story_id"],
            "use_direct_publishing": creative_controls["use_direct_publishing"],
            "manual_creative_completion": creative_controls["manual_creative_completion"],
            "create_placeholder_ad": creative_controls["create_placeholder_ad"],
            "placeholder_ad_count": creative_controls["placeholder_ad_count"],
            "placeholder_ad_names": creative_controls["placeholder_ad_names"],
            "creative_creation_strategy": creative_controls["creative_creation_strategy"],
            "direct_publishing_plan": direct_plan,
            "creative_format": creative_controls["format"],
            "final_status": final_status,
            "active_spend_confirmed": active_confirmed,
        }

        def inherited_ad_plan(raw_ad, raw_set):
            plan = dict(inherited_ad)
            if isinstance(raw_set, dict):
                # An ad-set-level brief is a valid shorthand for all of its
                # variants. Preserve its approved copy and message opener;
                # previously only destination fields were inherited, so a
                # prefilled WhatsApp message (and sometimes the copy) was
                # silently replaced by the generic fallback at execution.
                for key in (
                    "primary_text", "headline", "description", "cta",
                    "prefilled_message", "welcome_message", "message_destination",
                    "whatsapp_phone_number_id", "lead_gen_form_id", "landing_url",
                    "cta_link", "use_direct_publishing", "creative_creation_strategy",
                ):
                    if raw_set.get(key) not in (None, ""):
                        plan[key] = raw_set[key]
            if isinstance(raw_ad, dict):
                for key, value in raw_ad.items():
                    if value not in (None, ""):
                        plan[key] = value
            plan["cta"] = str(plan.get("cta") or "LEARN_MORE").strip().upper()
            if plan.get("message_destination") and plan["cta"] in {"LEARN_MORE", "APRENDER_MAS", ""}:
                plan["cta"] = SocialFlowClient.message_destination_cta_type(plan["message_destination"]) or plan["cta"]
            return plan

        stored_ad_sets = []
        for index, raw_set in enumerate(explicit_ad_sets):
            raw_targeting = raw_set.get("targeting") if isinstance(raw_set.get("targeting"), dict) else dict(audience)
            nested_location_source = (
                raw_targeting.get("locations")
                or raw_targeting.get("targeting_locations")
                or raw_targeting.get("targeting_countries")
                or raw_targeting.get("countries")
                or raw_targeting.get("geography")
                or raw_targeting.get("geo")
            )
            nested_country_codes = normalize_location_codes(nested_location_source, default=[])
            structured_nested_locations = []
            for item in (
                nested_location_source
                if isinstance(nested_location_source, list)
                else [nested_location_source]
            ):
                if not isinstance(item, dict):
                    continue
                key = str(item.get("key") or item.get("id") or "").strip()
                location_type = str(item.get("type") or item.get("location_type") or "").strip().lower()
                if key and location_type in {"country", "city", "region"}:
                    structured_nested_locations.append(dict(item))
            nested_location_queries = list(raw_targeting.get("targeting_location_queries") or campaign_location_query_terms(nested_location_source))
            if structured_nested_locations:
                # A city/region key selected from Meta is more specific than
                # the accompanying ISO country code.  The latter is useful
                # lookup metadata, not a second audience instruction.
                raw_targeting = dict(raw_targeting)
                raw_targeting["locations"] = structured_nested_locations
                for broad_key in ("countries", "targeting_countries", "country_codes"):
                    raw_targeting.pop(broad_key, None)
                raw_meta_targeting = raw_targeting.get("meta_targeting") if isinstance(raw_targeting.get("meta_targeting"), dict) else {}
                raw_targeting["meta_targeting"] = {**raw_meta_targeting, "locations": structured_nested_locations}
            elif nested_location_queries:
                nested_selected = resolve_campaign_location_queries(nested_location_queries, nested_country_codes)
                raw_targeting = dict(raw_targeting)
                if nested_country_codes:
                    raw_targeting["locations"] = nested_country_codes
                raw_meta_targeting = raw_targeting.get("meta_targeting") if isinstance(raw_targeting.get("meta_targeting"), dict) else {}
                raw_targeting["meta_targeting"] = {**raw_meta_targeting, "locations": nested_selected}
            nested_set = creator.create_ad_set_config(
                str(raw_set.get("name") or raw_set.get("adset_name") or raw_set.get("offer") or raw_set.get("product") or f"{payload.get('name', 'New Campaign')} - Ad Set {index + 1}").strip(),
                raw_targeting,
                parse_money_like(raw_set.get("budget") or raw_set.get("daily_budget") or raw_set.get("adset_daily_budget"), budget_plan["adset_daily"]),
            )
            for key in ("placements", "billing_event", "bidding", "start_time", "end_time", "is_adset_budget_sharing_enabled", "optimization_goal", "promoted_object", "destination_type", "message_destination", "whatsapp_phone_number_id"):
                if raw_set.get(key) not in (None, ""):
                    nested_set[key] = (
                        normalize_placement_config(raw_set[key])
                        if key == "placements"
                        else raw_set[key]
                    )
            if not nested_set.get("message_destination") and message_destination:
                nested_set["message_destination"] = message_destination
            if not nested_set.get("whatsapp_phone_number_id") and whatsapp_phone_number_id:
                nested_set["whatsapp_phone_number_id"] = whatsapp_phone_number_id
            nested_set["status"] = "PAUSED" if final_status == "PAUSED" else status_plan["adset"]
            nested_set = apply_signal_quality_to_adset(nested_set, signal_review)
            ads = raw_set.get("ads") or raw_set.get("creatives") or raw_set.get("ad_variants") or []
            if isinstance(ads, dict):
                ads = [ads]
            if not isinstance(ads, list):
                ads = []
            nested_set["ads"] = [inherited_ad_plan(item, raw_set) for item in ads if isinstance(item, dict)]
            if not nested_set["ads"]:
                nested_set["ads"] = [inherited_ad_plan(raw_set, raw_set)]
            stored_ad_sets.append(nested_set)

    campaign = creator.create_campaign_config(
        name=payload.get("name", "New Campaign"),
        objective=payload.get("objective", "PURCHASES"),
        budget_daily=budget_plan["campaign_daily"],
        budget_total=budget_plan["total_budget"],
        pixel_id=payload.get("pixel_id") or None,
        ad_sets=stored_ad_sets,
    )
    campaign["status"] = status_plan["campaign"]
    campaign["status_plan"] = status_plan
    campaign["budget_plan"] = budget_plan
    campaign["budget_currency"] = payload.get("budget_currency") or "account_default"
    campaign["budget_currency_hint"] = payload.get("budget_currency_hint") or ""
    if payload.get("budget_currency_warning"):
        campaign["budget_currency_warning"] = payload.get("budget_currency_warning")
    campaign["success_metrics"] = success_metrics
    campaign["id"] = creator.generate_campaign_id(campaign)
    campaign["ab_test"] = {
        "enabled": bool(payload.get("ab_test")),
        "creative_variations": int(payload.get("creative_variations", 3)),
    }
    campaign["ad"] = {
        "primary_text": str(payload.get("primary_text") or "").strip(),
        "headline": str(payload.get("headline") or payload.get("name") or "Nueva oferta").strip(),
        "creative_image_path": str(payload.get("creative_image_path") or "").strip(),
        "landing_url": str(payload.get("landing_url") or "").strip(),
        "cta": str(payload.get("cta") or ("" if payload.get("on_meta_destination") else "LEARN_MORE")).strip().upper(),
        "cta_link": creative_controls["cta_link"],
        "image_hash": creative_controls["image_hash"],
        "image_url": creative_controls["image_url"],
        "video_url": creative_controls["video_url"],
        "message_destination": message_destination,
        "lead_gen_form_id": lead_gen_form_id,
        "whatsapp_phone_number_id": whatsapp_phone_number_id,
        "prefilled_message": str(payload.get("prefilled_message") or "").strip(),
        "welcome_message": str(payload.get("welcome_message") or payload.get("initial_business_message") or "").strip(),
        "on_meta_destination": bool(payload.get("on_meta_destination")),
        "object_story_spec": creative_controls["object_story_spec"],
        "object_story_id": creative_controls["object_story_id"],
        "use_direct_publishing": creative_controls["use_direct_publishing"],
        "manual_creative_completion": creative_controls["manual_creative_completion"],
        "create_placeholder_ad": creative_controls["create_placeholder_ad"],
        "placeholder_ad_count": creative_controls["placeholder_ad_count"],
        "placeholder_ad_names": creative_controls["placeholder_ad_names"],
        "creative_creation_strategy": creative_controls["creative_creation_strategy"],
        "direct_publishing_plan": direct_plan,
        "creative_format": creative_controls["format"],
        "final_status": final_status,
        "active_spend_confirmed": active_confirmed,
    }
    # The first ad remains the legacy compatibility view used by previews and
    # older executors; the complete source of truth is ad_sets[*].ads.
    first_durable_ad = next(
        (
            item
            for stored_set in campaign.get("ad_sets", [])
            for item in (stored_set.get("ads") or [])
            if isinstance(item, dict)
        ),
        None,
    )
    if first_durable_ad:
        campaign["ad"] = {**campaign["ad"], **first_durable_ad}
    campaign["ad_count"] = sum(len(stored_set.get("ads") or []) for stored_set in campaign.get("ad_sets", []))
    campaign["ad_set_count"] = len(campaign.get("ad_sets", []))
    campaign["creative_format_review"] = creative_format_review(campaign["ad"], placement_config)
    campaign["signal_quality_review"] = signal_review
    out_path = OUTPUT_DIR / f"{campaign['id']}.json"
    creator.save_campaign(campaign, str(out_path))
    created = read_json(CREATED_FILE, [])
    created.insert(0, {"created_at": now_iso(), "path": str(out_path), "campaign": campaign})
    write_json(CREATED_FILE, created[:100])
    pending_payload = {
        "campaign_id": campaign["id"],
        "name": campaign["name"],
        "path": str(out_path),
        "final_status": final_status,
        "active_spend_confirmed": active_confirmed,
        "requested": {
            "campaign": campaign["name"],
            "daily_budget": campaign["budget"]["daily"],
            "currency": campaign.get("budget_currency"),
            "currency_hint": campaign.get("budget_currency_hint"),
            "currency_warning": campaign.get("budget_currency_warning", ""),
            "budget_plan": budget_plan,
            "status_plan": status_plan,
            "objective": campaign["objective"],
            "success_metrics": success_metrics,
            "ad_sets": [adset.get("name") for adset in campaign.get("ad_sets", [])],
            "creative_image_path": campaign["ad"]["creative_image_path"],
            "creative_controls": {
                "has_object_story_spec": bool(campaign["ad"].get("object_story_spec")),
                "has_object_story_id": bool(campaign["ad"].get("object_story_id")),
                "will_create_object_story_id": bool(campaign["ad"].get("object_story_id")),
                "has_image_hash": bool(campaign["ad"].get("image_hash")),
                "has_image_url": bool(campaign["ad"].get("image_url")),
                "has_video_url": bool(campaign["ad"].get("video_url")),
                "use_direct_publishing": campaign["ad"].get("use_direct_publishing"),
                "manual_creative_completion": campaign["ad"].get("manual_creative_completion"),
                "create_placeholder_ad": campaign["ad"].get("create_placeholder_ad"),
                "placeholder_ad_count": campaign["ad"].get("placeholder_ad_count"),
                "placeholder_ad_names": campaign["ad"].get("placeholder_ad_names"),
                "creative_route": direct_plan.get("creative_route"),
                "cta_link": campaign["ad"].get("cta_link"),
                "format_review": campaign.get("creative_format_review"),
                "direct_publishing_plan": direct_plan,
            },
            "targeting": targeting_summary(audience),
            "placements": placement_config_summary(placement_config),
            "adset_controls": {
                "optimization_goal": ad_set.get("optimization_goal"),
                "billing_event": ad_set.get("billing_event"),
                "promoted_object": ad_set.get("promoted_object"),
                "bidding": ad_set.get("bidding", {}),
                "is_adset_budget_sharing_enabled": ad_set.get("is_adset_budget_sharing_enabled"),
                "schedule": schedule,
            },
            "signal_quality": {
                "status": signal_review.get("status"),
                "recommended_event": signal_review.get("recommended_event"),
                "safe_to_launch_active": signal_review.get("safe_to_launch_active"),
                "checks": signal_review.get("checks", []),
            },
        },
        "guardrail_reason": "active_or_spend_requires_approval",
        "dry_run_preview": campaign_preview(campaign),
        "signal_quality_review": signal_review,
    }
    all_statuses = [final_status, *(status_plan or {}).values()]
    paused_no_spend = (
        not active_confirmed
        and all(str(status or "PAUSED").strip().upper() == "PAUSED" for status in all_statuses)
    )
    if paused_no_spend:
        config = load_config()
        missing_setup = paused_campaign_setup_missing_requirements(config)
        if missing_setup:
            execution_result = {
                "ok": False,
                "mode": getattr(config, "mode", "dry-run"),
                "executed": False,
                "blocked": True,
                "reason": "paused_campaign_creation_missing_meta_connection",
                "missing_requirements": missing_setup,
                "path": str(out_path),
                "planned": {
                    "campaign": campaign.get("name"),
                    "ad_sets": [adset.get("name") for adset in campaign.get("ad_sets", [])],
                    "final_status": "PAUSED",
                    "status_plan": status_plan,
                },
            }
        else:
            require_cloud_license("Paused campaign creation requires an active license")
            campaign_client = SocialFlowClient(config)
            execution_result = execute_campaign_creation(str(out_path), campaign_client, approved=True)
            if execution_result.get("ok") and not execution_result.get("executed"):
                execution_result = {
                    **execution_result,
                    "ok": False,
                    "blocked": True,
                    "reason": "paused_campaign_creation_not_materialized",
                    "message": "Paused campaign creation must materialize Meta objects or return a real blocker; dry-run planned is not a valid success state for this flow.",
                }
            if verified_campaign_stack_execution(execution_result):
                graph_verification = verify_campaign_stack_with_graph(campaign_client, execution_result)
                execution_result = {
                    **execution_result,
                    "graph_verification": graph_verification,
                    "campaign_creation_verified": bool(graph_verification.get("ok")),
                }
                if not graph_verification.get("ok"):
                    execution_result = {
                        **execution_result,
                        "ok": False,
                        "blocked": True,
                        "reason": "campaign_creation_graph_readback_failed",
                        "message": (
                            "Meta returned creation IDs, but the independent read-back did not confirm "
                            "HTTP 200 and PAUSED for the complete campaign stack."
                        ),
                    }
        succeeded = (
            bool(execution_result.get("ok"))
            and not execution_result.get("blocked")
            and verified_campaign_stack_execution(execution_result)
            and bool((execution_result.get("graph_verification") or {}).get("ok"))
        )
        if execution_result.get("ok") and execution_result.get("executed") and not succeeded:
            execution_result = {
                **execution_result,
                "ok": False,
                "blocked": True,
                "reason": "campaign_creation_missing_real_ids",
                "message": "Meta did not confirm campaign, ad-set, and ad IDs; creation cannot be reported as successful.",
            }
        status = "created_paused" if succeeded else "failed"
        action_status = "completed" if status == "created_paused" else "failed"
        log_action(
            "create_campaign",
            {
                "name": campaign["name"],
                "path": str(out_path),
                "final_status": "PAUSED",
                "approval_required": False,
                "result": execution_result,
            },
            action_status,
        )
        return {
            "status": status,
            "executed": succeeded,
            "approval_required": False,
            "payload": pending_payload,
            "result": execution_result,
            "path": str(out_path),
            "dry_run_preview": pending_payload["dry_run_preview"],
            "signal_quality_review": signal_review,
        }
    return add_pending("create_campaign", pending_payload)


