def parse_localized_number_token(token):
    text = str(token or "").strip()
    if not text:
        return None
    if "," in text and "." in text:
        decimal_separator = "," if text.rfind(",") > text.rfind(".") else "."
        thousands_separator = "." if decimal_separator == "," else ","
        normalized = text.replace(thousands_separator, "").replace(decimal_separator, ".")
    elif "." in text:
        parts = text.split(".")
        normalized = "".join(parts) if len(parts) > 1 and all(len(part) == 3 for part in parts[1:]) else text
    elif "," in text:
        parts = text.split(",")
        normalized = "".join(parts) if len(parts) > 1 and all(len(part) == 3 for part in parts[1:]) else text.replace(",", ".")
    else:
        normalized = text
    try:
        return float(normalized)
    except ValueError:
        return None


def parse_money_like(value, default=None):
    if value in (None, ""):
        return default
    if isinstance(value, (int, float)):
        return float(value)
    text = str(value or "").strip()
    if not text:
        return default
    match = re.search(r"[-+]?\d[\d.,]*", text)
    if not match:
        return default
    parsed = parse_localized_number_token(match.group(0))
    return default if parsed is None else parsed


def currency_hint_from_text(value):
    text = str(value or "").strip().upper()
    if not text:
        return ""
    for token, currency in CURRENCY_SYMBOL_HINTS:
        if token in text:
            return currency
    return ""


def configured_ad_account_currency():
    state = normalize_managed_accounts_state(seed=False)
    active_id = clean_ad_account_id(state.get("active_ad_account_id") or "")
    accounts = state.get("accounts") or []
    active = next((account for account in accounts if clean_ad_account_id(account.get("id")) == active_id), None)
    if not active and accounts:
        active = accounts[0]
    return str((active or {}).get("currency") or "").strip().upper()


def confirmed_budget_contract(value, account_currency=""):
    """Resolve one buyer-facing budget quote against the live account currency."""
    raw = str(value or "").strip()
    amount = parse_money_like(raw, default=None)
    currency = str(account_currency or configured_ad_account_currency() or "").strip().upper()
    if amount is None or amount <= 0:
        return {"ok": False, "reason": "invalid_budget_confirmation", "raw": raw}
    if not currency:
        return {"ok": False, "reason": "missing_ad_account_currency", "raw": raw, "amount": amount}
    mentioned_currency = currency_hint_from_text(raw)
    # A bare currency symbol or generic peso wording is intentionally resolved
    # from the selected ad account. Explicit ISO/named currencies must match.
    ambiguous_account_currency = any(token in raw.upper() for token in ("$", "PESO", "PESOS"))
    if not mentioned_currency and not ambiguous_account_currency:
        return {
            "ok": False,
            "reason": "missing_budget_currency",
            "raw": raw,
            "amount": amount,
            "account_currency": currency,
        }
    if mentioned_currency and mentioned_currency != currency:
        return {
            "ok": False,
            "reason": "budget_currency_mismatch",
            "raw": raw,
            "amount": amount,
            "mentioned_currency": mentioned_currency,
            "account_currency": currency,
        }
    api_amount = meta_budget_api_amount(amount, currency)
    if api_amount <= 0:
        return {
            "ok": False,
            "reason": "unsupported_ad_account_currency",
            "raw": raw,
            "amount": amount,
            "account_currency": currency,
        }
    return {
        "ok": True,
        "raw": raw,
        "amount": float(amount),
        "currency": currency,
        "mentioned_currency": mentioned_currency or currency,
        "api_amount": api_amount,
    }


def boolish(value):
    if isinstance(value, bool):
        return value
    if value is None:
        return None
    text = str(value).strip().lower()
    if text in {"1", "true", "yes", "y", "on", "si", "sí", "claro", "confirmado"}:
        return True
    if text in {"0", "false", "no", "n", "off", "pausado", "pausada", "paused"}:
        return False
    return None


def can_execute_paused_campaign_setup(config):
    """True when a buyer-requested no-spend Meta setup can be materialized.

    Spend-capable actions are protected by explicit approval, not by a buyer
    mode switch. A fully PAUSED campaign/ad set/ad stack is a different
    boundary: after the buyer asks to create it, Admira should create the
    no-spend structure whenever the real Meta account connection exists.
    Activation still requires approval.
    """
    return not paused_campaign_setup_missing_requirements(config)


def paused_campaign_setup_missing_requirements(config):
    missing = []
    if not str(getattr(config, "ad_account_id", "") or "").strip():
        missing.append("META_AD_ACCOUNT_ID")
    if not str(getattr(config, "meta_access_token", "") or "").strip():
        missing.append("META_ACCESS_TOKEN")
    return missing


def campaign_status_from_text(value):
    if isinstance(value, dict):
        value = " ".join(str(item or "") for item in value.values())
    text = str(value or "").strip().lower()
    if not text:
        return ""
    if re.search(r"\b(paused|pause|pausar|pausad[oa]|en pausa|draft|borrador)\b", text):
        return "PAUSED"
    if re.search(r"\b(active|activo|activa|encendid[oa]|live|lanzar|publicar)\b", text):
        return "ACTIVE"
    return ""


def campaign_creative_asset_path(asset_id):
    """Resolve a generated creative asset ID without exposing a filesystem path.

    Image 2 returns a relative asset ID and a dashboard-only preview endpoint.
    Neither should be treated as a public CDN URL.  Campaign creation runs in
    the same product workspace, so it can safely resolve the ID and upload the
    local file to Meta or use it for direct publishing.
    """
    raw = str(asset_id or "").strip()
    if not raw:
        return ""
    if raw.startswith("/api/creative-asset?"):
        raw = (parse_qs(urlparse(raw).query).get("id") or [""])[0]
    try:
        return str(creative_asset_path(urllib.parse.unquote(raw)))
    except ValueError:
        return ""


def nested_campaign_creative_arguments(arguments):
    """Return the first usable creative fields supplied inside an ads[] shape.

    Hermes may naturally structure a proposed stack as `{ads: [{...}]}`.  The
    campaign API itself accepts one creative at a time, so normalize the first
    ad deterministically instead of silently discarding its image/video.
    """
    for key in CAMPAIGN_NESTED_CREATIVE_KEYS:
        entries = arguments.get(key)
        if isinstance(entries, dict):
            entries = [entries]
        if not isinstance(entries, (list, tuple)):
            continue
        for entry in entries:
            if not isinstance(entry, dict):
                continue
            candidate = normalize_agent_tool_arguments(entry)
            if any(candidate.get(field) for field in (*CAMPAIGN_CREATIVE_SOURCE_KEYS, *CAMPAIGN_CREATIVE_ALIAS_KEYS)):
                return candidate
    return {}


LEAD_FORM_ID_KEYS = (
    "lead_gen_form_id",
    "lead_form_id",
    "instant_form_id",
    "meta_lead_form_id",
    "form_id",
)


def lead_form_id_from_campaign_arguments(arguments):
    """Resolve a native Meta form ID from the loose shapes Hermes may emit.

    Hermes can place the returned form ID at the top level or inside the
    creative/ad/form object. Losing it makes an otherwise lead-specific plan
    look like a stale sales plan at execution time, so only accept explicit
    Graph IDs from these known containers.
    """
    root = arguments if isinstance(arguments, dict) else {}
    visited = set()

    def visit(value, form_context=False, depth=0):
        if depth > 4 or not isinstance(value, (dict, list, tuple)):
            return ""
        if isinstance(value, (list, tuple)):
            for item in value:
                found = visit(item, form_context=form_context, depth=depth + 1)
                if found:
                    return found
            return ""
        identity = id(value)
        if identity in visited:
            return ""
        visited.add(identity)
        for key in LEAD_FORM_ID_KEYS:
            candidate = str(value.get(key) or "").strip()
            if candidate:
                return candidate
        if form_context:
            candidate = str(value.get("id") or "").strip()
            if candidate:
                return candidate
        for key, child in value.items():
            if key in {"ad", "creative", "form", "lead_form", "destination", "lead_form_config", "ads", "creatives"}:
                found = visit(child, form_context=form_context or key in {"form", "lead_form", "lead_form_config"}, depth=depth + 1)
                if found:
                    return found
        return ""

    resolved = visit(root)
    if resolved:
        return resolved
    return ""


def campaign_arguments_have_lead_intent(arguments):
    """Detect lead-form intent before any campaign object is created."""
    root = arguments if isinstance(arguments, dict) else {}
    values = [
        root.get("objective"),
        root.get("campaign_objective"),
        root.get("goal"),
        root.get("result_type"),
        root.get("campaign_goal"),
        root.get("destination_type"),
        root.get("conversion_location"),
        root.get("form_type"),
    ]
    normalized = {
        str(value or "").strip().upper().replace("-", "_")
        for value in values
    }
    return bool(lead_form_id_from_campaign_arguments(root)) or bool(normalized.intersection({
        "LEADS", "LEAD", "LEAD_GENERATION", "LEAD_FORM", "LEAD_FORMS",
        "INSTANT_FORM", "INSTANT_FORMS", "FORMS", "FORMULARIOS", "OUTCOME_LEADS",
        "OUTCOME_LEAD_GENERATION",
    }))


def normalize_campaign_stack_arguments(arguments, chat_payload=None):
    """Accept the looser shapes Hermes/Telegram may send for campaign staging."""
    args = _canonicalize_campaign_copy(dict(arguments or {}))

    # Canonicalize explicit gender aliases before nested ad-set normalization.
    # Meta expects numeric values (1=men, 2=women); losing this field silently
    # broadens or changes the audience, so unknown labels are never guessed.
    if not args.get("genders"):
        for key in ("gender", "targeting_gender", "targeting_genders", "sex"):
            if args.get(key) not in (None, "", [], ()):
                genders = normalize_gender_values(args.get(key))
                if genders:
                    args["genders"] = genders
                    break
    if args.get("genders") not in (None, "", [], ()):
        genders = normalize_gender_values(args.get("genders"))
        if genders:
            args["genders"] = genders
    if args.get("placements") in (None, "", [], ()):
        for key in (
            "placement_strategy", "placement_mode", "placements_mode", "meta_placements",
            "delivery_placements", "advantage_placements",
        ):
            if args.get(key) not in (None, "", [], ()):
                args["placements"] = args[key]
                break

    # Preserve every lead-form ID alias in the durable campaign contract.
    # Otherwise a model can send `lead_form_id` while the saved ad keeps the
    # generic SALES objective, causing Meta to reject a LEAD_GENERATION ad set.
    lead_form_id = lead_form_id_from_campaign_arguments(args)
    if lead_form_id:
        args["lead_gen_form_id"] = lead_form_id
    if not args.get("objective"):
        for key in ("campaign_objective", "goal", "result_type", "campaign_goal"):
            if args.get(key):
                args["objective"] = args.get(key)
                break
    if campaign_arguments_have_lead_intent(args):
        objective = str(args.get("objective") or args.get("campaign_objective") or "").strip().upper().replace("-", "_")
        if objective in {"", "SALES", "PURCHASES", "CONVERSIONS", "OUTCOME_SALES"}:
            args["objective"] = "LEAD_FORM"

    if not args.get("name"):
        for key in ("campaign_name", "campaign", "campaign_title", "title"):
            if args.get(key):
                args["name"] = args.get(key)
                break

    if not args.get("daily_budget"):
        for key in ("campaign_daily_budget", "adset_daily_budget", "budget", "budget_daily", "daily_budget_usd", "daily_budget_amount", "presupuesto_diario"):
            if args.get(key):
                args["daily_budget"] = args.get(key)
                break
    daily_budget = parse_money_like(args.get("daily_budget"))
    if daily_budget is not None:
        args["daily_budget"] = daily_budget
    total_budget = parse_money_like(args.get("total_budget"))
    if total_budget is not None:
        args["total_budget"] = total_budget
    currency_hint = (
        currency_hint_from_text(args.get("daily_budget_raw"))
        or currency_hint_from_text(arguments.get("daily_budget") if isinstance(arguments, dict) else "")
        or currency_hint_from_text(arguments.get("budget") if isinstance(arguments, dict) else "")
    )
    account_currency = str(
        args.get("ad_account_currency")
        or args.get("account_currency")
        or configured_ad_account_currency()
        or ""
    ).strip().upper()
    if currency_hint:
        args["budget_currency_hint"] = currency_hint
    if account_currency:
        args["ad_account_currency"] = account_currency
        args["budget_currency"] = account_currency
    elif currency_hint:
        args["budget_currency"] = currency_hint
    else:
        args.setdefault("budget_currency", "account_default")
    if currency_hint and account_currency and currency_hint != account_currency:
        args["budget_currency_warning"] = (
            f"El presupuesto se aplicará en la moneda de la cuenta publicitaria ({account_currency}), "
            f"pero el texto enviado mencionaba {currency_hint}. No se hizo conversión automática."
        )

    if not args.get("final_status"):
        for key in ("status_plan", "status", "desired_status", "campaign_status", "adset_status", "ad_set_status", "ad_status"):
            status = campaign_status_from_text(args.get(key))
            if status:
                args["final_status"] = status
                break
    if not args.get("final_status"):
        args["final_status"] = "PAUSED"

    location_source = (
        args.get("locations")
        or args.get("targeting_countries")
        or args.get("targeting_locations")
        or args.get("countries")
        or args.get("country_codes")
        or args.get("market")
        or args.get("target_market")
        or args.get("geography")
        or args.get("geo")
    )
    location_queries = campaign_location_query_terms(location_source)
    if location_queries:
        # Keep the buyer's city/region intent durable across normalization and
        # context compaction. The live Meta lookup happens immediately before
        # campaign materialization.
        args["targeting_location_queries"] = location_queries
    normalized_locations = normalize_location_codes(location_source, default=[])
    if not normalized_locations:
        normalized_locations = infer_location_codes_from_context(
            args.get("name"),
            args.get("market"),
            args.get("target_market"),
            args.get("campaign_constraints"),
            args.get("audience"),
            args.get("target_audience"),
            args.get("offer"),
            args.get("product"),
        )
    if normalized_locations:
        args["locations"] = normalized_locations

    # Preserve the user's explicit geography intent.  A malformed explicit
    # value must not disappear and silently turn into the historical US
    # default; create_campaign will return a field-level validation error.
    if location_source not in (None, "", [], ()) and not normalized_locations and not location_queries:
        args["locations"] = []

    age_value = (
        args.get("age_range")
        or args.get("targeting_age_range")
        or args.get("audience_age_range")
        or args.get("age")
    )
    age_bounds = normalize_age_bounds(
        age_value,
        age_min=args.get("age_min", args.get("min_age", args.get("targeting_age_min"))),
        age_max=args.get("age_max", args.get("max_age", args.get("targeting_age_max"))),
    )
    if age_bounds.get("age_min") is not None:
        args["age_min"] = age_bounds["age_min"]
    if age_bounds.get("age_max") is not None:
        args["age_max"] = age_bounds["age_max"]
    if not age_bounds.get("ok"):
        args["targeting_age_validation_error"] = age_bounds.get("error") or "targeting_age_invalid"

    confirmed = boolish(args.get("active_spend_confirmed"))
    if confirmed is not None:
        args["active_spend_confirmed"] = confirmed

    direct_preference = None
    for key in ("use_direct_publishing", "direct_publishing", "create_as_unpublished_post", "unpublished_post"):
        direct_preference = boolish(args.get(key))
        if direct_preference is not None:
            args["use_direct_publishing"] = direct_preference
            break
    if direct_preference is None:
        strategy = str(args.get("creative_creation_strategy") or args.get("publishing_strategy") or "").strip().lower()
        if strategy in {"direct", "direct_publishing", "native_post", "page_post", "dark_post", "unpublished_post"}:
            args["use_direct_publishing"] = True
        elif strategy in {"direct_creative", "inline_creative", "image_hash", "legacy"}:
            args["use_direct_publishing"] = False

    manual_completion = manual_creative_completion_enabled(args)
    placeholder_static = placeholder_static_ad_enabled(args)
    if manual_completion:
        args["manual_creative_completion"] = True
        args["final_status"] = "PAUSED"
        args["active_spend_confirmed"] = False
    if placeholder_static:
        args["manual_creative_completion"] = True
        args["create_placeholder_ad"] = True
        args["placeholder_ad_count"] = placeholder_ad_count(args, default=len(placeholder_ad_names(args)) or 1)
        args["placeholder_ad_names"] = placeholder_ad_names(args)
        args["final_status"] = "PAUSED"
        args["active_spend_confirmed"] = False

    for key in ("object_story_id", "page_post_id", "post_id", "existing_post_id", "facebook_post_id"):
        if args.get(key):
            args["object_story_id"] = str(args.get(key) or "").strip()
            break

    # Accept either the explicit Image 2 asset ID or a natural ads[] payload.
    # This must happen before checking source keys so the local file is treated
    # as an uploadable Meta asset, never as an inaccessible browser URL.
    if not any(args.get(key) for key in CAMPAIGN_CREATIVE_SOURCE_KEYS):
        # A buyer-approved creative may be stored in the durable content
        # library rather than returned as a raw filesystem path. Resolve the
        # selected content asset before the required-field guard; otherwise a
        # model that correctly names the saved asset still produces
        # `missing_creative_image_path_or_url_or_story_spec`.
        library_references = selected_content_asset_references(args, purpose="ad_creative")
        library_paths = library_references.get("all") if isinstance(library_references, dict) else []
        if library_paths:
            args["creative_image_path"] = library_paths[0]
            args["resolved_content_asset_ids"] = [
                str(item.get("id") or "").strip()
                for item in (library_references.get("items") or [])
                if isinstance(item, dict) and str(item.get("id") or "").strip()
            ]

    if not any(args.get(key) for key in CAMPAIGN_CREATIVE_SOURCE_KEYS):
        for key in ("creative_asset_id", "generated_creative_asset_id", "generated_image_asset_id", "image_asset_id", "asset_id"):
            resolved = campaign_creative_asset_path(args.get(key))
            if resolved:
                args["creative_image_path"] = resolved
                break

    # A dashboard preview URL is private to this installation, not a URL Meta
    # can fetch.  If a model forwards it, recover the underlying asset ID and
    # use the local source file instead of attempting a public-URL flow.
    if not any(args.get(key) for key in CAMPAIGN_CREATIVE_SOURCE_KEYS if key != "image_url"):
        resolved_preview = campaign_creative_asset_path(args.get("image_url"))
        if resolved_preview:
            args["creative_image_path"] = resolved_preview
            args.pop("image_url", None)

    if not any(args.get(key) for key in CAMPAIGN_CREATIVE_SOURCE_KEYS):
        nested = nested_campaign_creative_arguments(args)
        if nested:
            for key in CAMPAIGN_CREATIVE_SOURCE_KEYS:
                if nested.get(key):
                    args[key] = nested[key]
                    break
            if not any(args.get(key) for key in CAMPAIGN_CREATIVE_SOURCE_KEYS):
                for key in ("creative_asset_id", "generated_creative_asset_id", "generated_image_asset_id", "image_asset_id", "asset_id"):
                    resolved = campaign_creative_asset_path(nested.get(key))
                    if resolved:
                        args["creative_image_path"] = resolved
                        break
            if not any(args.get(key) for key in CAMPAIGN_CREATIVE_SOURCE_KEYS):
                nested_paths = safe_image_paths(nested)
                if nested_paths:
                    args["creative_image_path"] = nested_paths[0]

    if not any(args.get(key) for key in CAMPAIGN_CREATIVE_SOURCE_KEYS):
        safe_from_args = safe_image_paths(args)
        safe_from_chat = safe_image_paths(chat_payload or {})
        if safe_from_args:
            args["creative_image_path"] = safe_from_args[0]
        elif safe_from_chat:
            args["creative_image_path"] = safe_from_chat[0]

    if not any(args.get(key) for key in CAMPAIGN_CREATIVE_SOURCE_KEYS):
        alias_value = ""
        for key in CAMPAIGN_CREATIVE_ALIAS_KEYS:
            if args.get(key):
                alias_value = args.get(key)
                break
        if isinstance(alias_value, dict):
            args["object_story_spec"] = alias_value
        elif alias_value:
            parsed_story = None
            if isinstance(alias_value, str):
                try:
                    parsed_story = json.loads(alias_value)
                except json.JSONDecodeError:
                    parsed_story = None
            if isinstance(parsed_story, dict):
                args["object_story_spec"] = parsed_story
            else:
                safe_alias_paths = safe_image_paths({"creative_image_path": alias_value})
                if safe_alias_paths:
                    args["creative_image_path"] = safe_alias_paths[0]
                else:
                    text = str(alias_value or "").strip()
                    lowered = text.lower()
                    if text.startswith(("http://", "https://")):
                        if any(lowered.split("?", 1)[0].endswith(ext) for ext in (".mp4", ".mov", ".m4v", ".webm")):
                            args["video_url"] = text
                    else:
                        args["image_url"] = text

    normalized_ad_sets = normalize_campaign_ad_sets(args)
    if normalized_ad_sets:
        # A flat ads[] payload is materialized as an implicit ad set. Carry
        # the destination-level audience contract into that set as well. The
        # campaign payload is normalized more than once before execution; if
        # an implicit set contains only placements on the second pass,
        # create_campaign() correctly treats it as explicit but would
        # otherwise lose the verified city, ages and genders.
        geo_aliases = ("locations", "targeting_locations", "targeting_countries", "countries", "country_codes")
        targeting_groups = (
            ("age_range", "age_min", "age_max", "min_age", "max_age"),
            ("genders", "gender", "targeting_gender", "targeting_genders", "sex"),
            ("interests", "targeting_interests", "meta_targeting"),
            ("targeting_mode", "targeting_automation"),
        )
        for item in normalized_ad_sets:
            nested_targeting = dict(item.get("targeting") or {}) if isinstance(item.get("targeting"), dict) else {}
            if not any(nested_targeting.get(key) not in (None, "", [], (), {}) for key in geo_aliases):
                # Prefer a verified Meta selection over the derived country
                # fallback. Keeping both makes later code choose `locations`
                # first and discards the exact city key.
                if args.get("targeting_locations") not in (None, "", [], (), {}):
                    value = args["targeting_locations"]
                    nested_targeting["targeting_locations"] = list(value) if isinstance(value, list) else dict(value) if isinstance(value, dict) else value
                else:
                    for key in ("locations", "targeting_countries", "countries", "country_codes"):
                        value = args.get(key)
                        if value not in (None, "", [], (), {}):
                            nested_targeting[key] = list(value) if isinstance(value, list) else value
                            break
            # A first normalization may already have derived the broad
            # country code (for example CO) while retaining the buyer's exact
            # natural city as a live-lookup query.  Propagate that query even
            # when the nested set now contains the derived country; otherwise
            # a second normalization silently broadens Cartagena to Colombia.
            if (
                nested_targeting.get("targeting_location_queries") in (None, "", [], (), {})
                and args.get("targeting_location_queries") not in (None, "", [], (), {})
            ):
                nested_targeting["targeting_location_queries"] = list(args["targeting_location_queries"])
            for aliases in targeting_groups:
                if any(nested_targeting.get(key) not in (None, "", [], (), {}) for key in aliases):
                    continue
                for key in aliases:
                    value = args.get(key)
                    if value in (None, "", [], (), {}):
                        continue
                    if isinstance(value, dict):
                        nested_targeting[key] = dict(value)
                    elif isinstance(value, list):
                        nested_targeting[key] = list(value)
                    else:
                        nested_targeting[key] = value
            if nested_targeting:
                item["targeting"] = nested_targeting
        # Destination MCPs ask for one explicit placement decision at the
        # campaign level. Flat ads are then grouped into an implicit ad set;
        # carry that decision into every set that did not override it. Losing
        # it here used to turn {automatic: true} into the legacy manual
        # feed/story default after an otherwise correct Hermes call.
        top_level_placements = args.get("placements")
        if top_level_placements not in (None, "", [], ()):
            for item in normalized_ad_sets:
                if item.get("placements") in (None, "", [], ()):
                    if isinstance(top_level_placements, dict):
                        item["placements"] = dict(top_level_placements)
                    elif isinstance(top_level_placements, list):
                        item["placements"] = list(top_level_placements)
                    else:
                        item["placements"] = top_level_placements
        args["ad_sets"] = normalized_ad_sets
        # Keep the first creative available to the legacy preview/validation
        # fields while retaining every nested ad for execution.
        first_ad = next((ad for item in normalized_ad_sets for ad in (item.get("ads") or []) if isinstance(ad, dict)), {})
        for key in CAMPAIGN_CREATIVE_SOURCE_KEYS:
            if not args.get(key) and first_ad.get(key):
                args[key] = first_ad[key]
                break

    # A click-to-message destination has its own canonical CTA.  Persisting
    # the generic LEARN_MORE default made the durable campaign file disagree
    # with the native Page post and dropped the buyer's WhatsApp intent on
    # retries.
    destination = message_destination_from_plan(args)
    if destination and str(args.get("cta") or "").strip().upper() in {"", "LEARN_MORE", "APRENDER_MAS"}:
        args["cta"] = SocialFlowClient.message_destination_cta_type(destination) or args.get("cta")

    return args


def create_audience_strategy(payload, language="es"):
    strategy = build_audience_strategy(payload, language)
    write_json(AUDIENCE_FILE, strategy)
    log_action("audience_strategy", {"product": strategy.get("product"), "objective": strategy.get("objective")}, "completed")
    return strategy


def run_daily_agent():
    config = load_config()
    if config.ad_account_id and config.meta_access_token:
        refresh_managed_real_metrics(reason="daily_agent_before_brief")
    report_path, report = run_scheduled_daily()
    actions = read_json(ACTIONS_FILE, [])
    action = actions[0] if actions else log_action("daily_agent_run", {"report_path": str(report_path)}, "completed")
    return action, report


def live_experiment_insight_rows():
    """Read ad-level insights for experiment comparisons without mutating Meta."""
    config = load_config()
    if not (config.ad_account_id or config.meta_access_token):
        return []
    result = SocialFlowClient(config).insights("last_7d", "ad")
    if not result.get("data"):
        return []
    return normalize_experiment_insights(result.get("data"), "ad")


def export_csv():
    metrics = load_metrics()
    out_path = OUTPUT_DIR / f"campaign_report_{datetime.now().strftime('%Y%m%d_%H%M%S')}.csv"
    OUTPUT_DIR.mkdir(parents=True, exist_ok=True)
    fields = ["id", "name", "status", "daily_budget", "spend", "revenue", "roas", "cpa", "ctr", "frequency", "health"]
    with open(out_path, "w", newline="", encoding="utf-8") as handle:
        writer = csv.DictWriter(handle, fieldnames=fields)
        writer.writeheader()
        for campaign in metrics.get("campaigns", []):
            writer.writerow({field: campaign.get(field) for field in fields})
    log_action("export_csv", {"path": str(out_path)})
    return {"path": str(out_path)}


def chat_lang(payload):
    return "es" if payload.get("language") == "es" else "en"


def chat_reply(payload, es, en):
    return es if chat_lang(payload) == "es" else en


def chat_message_requires_live_meta_sync(message):
    text = str(message or "").strip()
    if not text:
        return False
    if re.match(r"^/(?:start|help|model|reset|resume|stop|status|new)(?:\s|$)", text, re.IGNORECASE):
        return False
    # Dashboard chat follows the same manager contract as Telegram: every
    # ordinary buyer turn starts from current Meta state, regardless of topic.
    return True


def load_chat_history():
    items = read_json(CHAT_HISTORY_FILE, [])
    if not isinstance(items, list):
        return []
    history = []
    for item in items[-CHAT_HISTORY_LIMIT:]:
        if not isinstance(item, dict):
            continue
        role = "agent" if item.get("role") == "agent" else "user"
        content = str(item.get("content") or "").strip()
        if content:
            history.append({"role": role, "content": content[:5000], "created_at": item.get("created_at") or now_iso()})
    return history


def save_chat_history(history):
    cleaned = []
    for item in history[-CHAT_HISTORY_LIMIT:]:
        if not isinstance(item, dict):
            continue
        role = "agent" if item.get("role") == "agent" else "user"
        content = str(item.get("content") or "").strip()
        if content:
            cleaned.append({"role": role, "content": content[:5000], "created_at": item.get("created_at") or now_iso()})
    write_json(CHAT_HISTORY_FILE, cleaned)
    return cleaned


def append_chat_turn(message, reply):
    history = load_chat_history()
    if message:
        history.append({"role": "user", "content": str(message), "created_at": now_iso()})
    if reply:
        history.append({"role": "agent", "content": str(reply), "created_at": now_iso()})
    return save_chat_history(history)


def reset_chat_history():
    save_chat_history([])
    reset_creative_memory_wizard()
    log_action("chat_new_conversation", {"cleared": True}, "completed")
    return {"cleared": True}


