def handle_set_campaign_metric_priorities_tool(arguments, chat_payload, tool):
    campaign_id = str(arguments.get("campaign_id") or arguments.get("campaignId") or "").strip()
    metrics = load_metrics()
    campaign = campaign_by_id(metrics, campaign_id)
    if not campaign_id or not campaign:
        return agent_action_result(
            tool,
            False,
            chat_reply(
                chat_payload,
                "Primero necesito identificar una campaña real de Meta antes de elegir sus métricas prioritarias.",
                "I need to identify a real Meta campaign before choosing its priority metrics.",
            ),
            blocked=True,
            reason="unknown_campaign",
        )
    if boolish(arguments.get("reset_to_inferred") or arguments.get("reset")) is True:
        stored = read_json(CAMPAIGN_METRIC_PROFILES_FILE, {"campaigns": {}})
        profiles = stored.get("campaigns", {}) if isinstance(stored, dict) else {}
        if isinstance(profiles, dict):
            profiles.pop(campaign_id, None)
        write_json(CAMPAIGN_METRIC_PROFILES_FILE, {"updated_at": now_iso(), "campaigns": profiles})
        refreshed = campaign_by_id(load_metrics(), campaign_id) or {}
        return agent_action_result(
            tool,
            True,
            chat_reply(chat_payload, "Volví a la selección automática de métricas para esta campaña.", "I restored automatic metric selection for this campaign."),
            campaign_id=campaign_id,
            metric_profile=refreshed.get("metric_profile", {}),
            priority_metrics=refreshed.get("priority_metrics", []),
        )
    keys = normalize_metric_keys(
        arguments.get("metric_keys")
        or arguments.get("metrics")
        or arguments.get("priority_metrics")
        or arguments.get("kpis")
    )
    if not keys:
        return agent_action_result(
            tool,
            False,
            chat_reply(
                chat_payload,
                "No guardé el cambio porque no reconocí métricas válidas. Elige entre las métricas disponibles del dashboard.",
                "I did not save the change because no valid metrics were recognized. Choose from the dashboard metric catalog.",
            ),
            blocked=True,
            reason="invalid_metric_keys",
            metric_catalog=public_metric_catalog(),
        )
    objective_type = str(arguments.get("objective_type") or arguments.get("campaign_type") or "").strip().lower()
    record = {
        "campaign_id": campaign_id,
        "campaign_name": campaign.get("name") or campaign_id,
        "objective_type": objective_type,
        "metric_keys": keys,
        "rationale": str(arguments.get("rationale") or arguments.get("reason") or "")[:600],
        "updated_at": now_iso(),
        "updated_by": "agent",
    }
    stored = read_json(CAMPAIGN_METRIC_PROFILES_FILE, {"campaigns": {}})
    profiles = stored.get("campaigns", {}) if isinstance(stored, dict) else {}
    if not isinstance(profiles, dict):
        profiles = {}
    profiles[campaign_id] = record
    write_json(CAMPAIGN_METRIC_PROFILES_FILE, {"updated_at": now_iso(), "campaigns": profiles})
    refreshed = campaign_by_id(load_metrics(), campaign_id) or {}
    log_action("campaign_metric_priorities", {"campaign_id": campaign_id, "metric_keys": keys, "objective_type": objective_type}, "completed")
    return agent_action_result(
        tool,
        True,
        chat_reply(
            chat_payload,
            f"Listo. El dashboard de {campaign.get('name') or 'esta campaña'} priorizará las métricas que mejor explican su objetivo.",
            f"Done. The dashboard for {campaign.get('name') or 'this campaign'} will prioritize the metrics that best explain its objective.",
        ),
        campaign_id=campaign_id,
        metric_profile=refreshed.get("metric_profile", {}),
        priority_metrics=refreshed.get("priority_metrics", []),
    )


def summarize_cli_result(result, max_items=8):
    result = result or {}
    parsed = None
    try:
        parsed = json.loads(result.get("stdout") or "")
    except (TypeError, json.JSONDecodeError):
        parsed = None
    if isinstance(parsed, dict):
        data = parsed.get("data", parsed)
        if isinstance(data, list):
            data = data[:max_items]
        parsed = data
    elif isinstance(parsed, list):
        parsed = parsed[:max_items]
    return {
        "ok": bool(result.get("executed")) and int(result.get("returncode") or 0) == 0 and not result.get("stderr"),
        "executed": bool(result.get("executed")),
        "returncode": result.get("returncode"),
        "stderr": str(result.get("stderr") or "")[:500],
        "data": redact_payload(parsed) if parsed is not None else None,
    }


def campaign_preflight(arguments, chat_payload):
    arguments = normalize_campaign_stack_arguments(arguments or {}, chat_payload)
    config = load_config()
    client = SocialFlowClient(config)
    account_id = config.ad_account_id or str(arguments.get("ad_account_id") or "").strip()
    signal = review_signal_quality(arguments, metrics=load_metrics(), language=chat_lang(chat_payload))
    placement_config = normalize_placement_config(arguments.get("placements") or arguments.get("placement_preset") or arguments.get("manual_placements"))
    creative_controls = normalize_creative_controls(arguments)
    direct_plan = direct_publishing_campaign_plan(arguments, creative_controls, config=config)
    budget_plan = normalize_budget_plan(arguments, float(arguments.get("daily_budget", 50) or 50))
    success_metrics = normalize_success_metrics(arguments)
    final_status = str(arguments.get("final_status") or "PAUSED").upper()
    active_confirmed = boolish(arguments.get("active_spend_confirmed")) is True
    status_plan = normalize_status_plan(arguments, final_status, active_confirmed)
    preflight = {
        "ok": True,
        "account_id": account_id,
        "checks": {
            "account_status": summarize_cli_result(client.marketing_status()),
            "rate_limits": summarize_cli_result(client.rate_limits()),
            "policy_preflight": summarize_cli_result(client.policy_preflight(arguments.get("intent") or arguments.get("objective") or "create Meta ad")),
        },
        "dry_run_preview": {
            "budget_plan": budget_plan,
            "success_metrics": success_metrics,
            "status_plan": status_plan,
            "placements": placement_config_summary(placement_config),
            "creative_controls": {
                "has_object_story_spec": bool(creative_controls.get("object_story_spec")),
                "has_object_story_id": bool(creative_controls.get("object_story_id")),
                "will_create_object_story_id": bool(creative_controls.get("object_story_id")),
                "has_image_hash": bool(creative_controls.get("image_hash")),
                "has_image_url": bool(creative_controls.get("image_url")),
                "has_video_url": bool(creative_controls.get("video_url")),
                "use_direct_publishing": creative_controls.get("use_direct_publishing"),
                "manual_creative_completion": creative_controls.get("manual_creative_completion"),
                "create_placeholder_ad": creative_controls.get("create_placeholder_ad"),
                "placeholder_ad_count": creative_controls.get("placeholder_ad_count"),
                "placeholder_ad_names": creative_controls.get("placeholder_ad_names"),
                "creative_route": direct_plan.get("creative_route"),
                "cta_link": creative_controls.get("cta_link"),
                "format": creative_controls.get("format"),
                "direct_publishing_plan": direct_plan,
            },
            "signal_quality": {
                "status": signal.get("status"),
                "recommended_event": signal.get("recommended_event"),
                "safe_to_launch_active": signal.get("safe_to_launch_active"),
                "questions": signal.get("questions", []),
            },
        },
    }
    if account_id:
        preflight["checks"]["custom_audiences"] = summarize_cli_result(client.custom_audiences(account_id, limit=25))
        preflight["checks"]["existing_creatives"] = summarize_cli_result(client.creatives(account_id, limit=25))
        if arguments.get("include_recent_insights"):
            preflight["checks"]["recent_insights_by_placement_device"] = summarize_cli_result(
                client.insights(
                    "last_7d",
                    "ad",
                    fields="spend,impressions,clicks,actions,action_values",
                    breakdowns="publisher_platform,platform_position,impression_device",
                    limit=250,
                    timeout=90,
                )
            )
        else:
            metrics = load_metrics()
            preflight["checks"]["recent_insights_by_placement_device"] = {
                "ok": bool((metrics.get("breakdowns") or {}).get("placement_device")),
                "source": metrics.get("source") or "metrics_cache",
                "data": ((metrics.get("breakdowns") or {}).get("placement_device") or [])[:8],
                "skipped_live_read": True,
            }
    preflight["ok"] = all(
        check.get("ok") or check.get("skipped_live_read")
        for check in preflight.get("checks", {}).values()
        if isinstance(check, dict)
    )
    return preflight


