def handle_create_campaign_stack_tool(arguments, chat_payload, tool):
    arguments = normalize_campaign_stack_arguments(arguments or {}, chat_payload)
    creative_controls = normalize_creative_controls(arguments)
    manual_completion = bool(creative_controls.get("manual_creative_completion"))
    placeholder_static = bool(creative_controls.get("create_placeholder_ad"))
    required = ["name", "daily_budget"]
    lead_intent = campaign_arguments_have_lead_intent(arguments)
    has_message_destination = bool(message_destination_from_plan(arguments))
    has_lead_form = bool(
        arguments.get("lead_gen_form_id")
        or arguments.get("lead_form_id")
        or arguments.get("instant_form_id")
        or arguments.get("meta_lead_form_id")
        or arguments.get("form_id")
    )
    has_app_destination = bool(arguments.get("app_destination") or (arguments.get("application_id") and arguments.get("object_store_url")))
    has_on_meta_destination = bool(arguments.get("on_meta_destination"))
    if lead_intent and not has_lead_form:
        # Never let a lead-form request fall through to a stale/default sales
        # campaign. The native form ID is required to build the promoted
        # object and final creative safely.
        required.append("lead_gen_form_id")
    # Messaging and native lead-form ads have no website landing URL. Their
    # destination is carried by the promoted object/CTA instead.
    if not arguments.get("object_story_id") and not has_message_destination and not has_lead_form and not has_app_destination and not has_on_meta_destination:
        required.append("landing_url")
    missing = [key for key in required if not arguments.get(key)]
    if not any(arguments.get(key) for key in CAMPAIGN_CREATIVE_SOURCE_KEYS) and not (manual_completion or placeholder_static):
        missing.append("creative_image_path_or_url_or_story_spec")
    final_status = str(arguments.get("final_status") or "PAUSED").strip().upper()
    active_confirmed = boolish(arguments.get("active_spend_confirmed")) is True
    if manual_completion or placeholder_static:
        final_status = "PAUSED"
        active_confirmed = False
        arguments["final_status"] = "PAUSED"
        arguments["active_spend_confirmed"] = False
    if requires_active_confirmation(arguments, final_status) and not active_confirmed:
        missing.append("active_spend_confirmed")
    if missing:
        return agent_action_result(
            tool,
            False,
            chat_reply(
                chat_payload,
                f"No creé nada en Meta porque falta esto: {', '.join(missing)}. Dame ese dato y crearé la campaña directamente en pausa, sin pedir otra aprobación.",
                f"I did not create anything in Meta because this is missing: {', '.join(missing)}. Send that detail and I will create the campaign directly as paused, without another approval.",
            ),
            blocked=True,
            reason="missing_campaign_creation_detail",
            missing=missing,
        )
    require_cloud_license("Campaign creation requires an active license")
    try:
        result = create_campaign(arguments)
    except ValueError as exc:
        detail = str(exc)
        reason = detail.split(":", 1)[0].strip() if ":" in detail else "campaign_targeting_validation_failed"
        return agent_action_result(
            tool,
            False,
            chat_reply(
                chat_payload,
                f"No creé ningún objeto en Meta porque la segmentación no pasó la verificación previa: {detail}",
                f"I did not create anything in Meta because targeting failed preflight validation: {detail}",
            ),
            blocked=True,
            reason=reason,
            error=detail,
        )
    execution_result = result.get("result") if isinstance(result.get("result"), dict) else {}
    terms_guidance = execution_result.get("buyer_action_required") if isinstance(execution_result, dict) else None
    if isinstance(terms_guidance, dict) and terms_guidance.get("required"):
        # Meta requires a one-time Page-level acceptance before a lead ad set
        # can be created. Make this deterministic and actionable in chat;
        # do not let Hermes retry the same mutation or bury the URL in raw
        # Graph diagnostics.
        reply = chat_reply(
            chat_payload,
            str(terms_guidance.get("message_es") or "Meta requiere aceptar las Condiciones de Lead Ads antes de continuar."),
            str(terms_guidance.get("message_en") or "Meta requires accepting the Lead Ads Terms before continuing."),
        )
    elif result.get("status") == "created_paused":
        reply = chat_reply(
            chat_payload,
            "Hice el análisis y creé la campaña en Meta en pausa. No está gastando dinero; el siguiente paso protegido es activarla cuando la revises.",
            "I analyzed it and created the campaign in Meta as paused. It is not spending money; the protected next step is activating it after review.",
        )
    elif result.get("status") == "planned":
        reply = chat_reply(
            chat_payload,
            "Hice el análisis y dejé la campaña lista en modo prueba/plan. No se creó nada activo ni se gastó dinero.",
            "I analyzed it and prepared the campaign as a dry-run plan. Nothing active was created and no money was spent.",
        )
    elif result.get("status") == "failed":
        reply = chat_reply(
            chat_payload,
            "Intenté crear la campaña en pausa, pero Meta frenó el proceso. Te dejo el detalle para corregir y reintentar sin aprobar otra vez.",
            "I tried to create the paused campaign, but Meta blocked the process. I am keeping the details so we can fix and retry without another approval step.",
        )
    else:
        reply = append_staged_approval_instruction(
            chat_payload,
            chat_reply(
                chat_payload,
                "Hice el analisis y preparé la campaña completa para aprobación.",
                "I analyzed the request and staged the full campaign for approval.",
            ),
            result,
        )
    choices = staged_approval_choices(result)
    return agent_action_result(
        tool,
        bool(result.get("executed")),
        reply,
        staged=bool(choices) or result.get("status") == "pending",
        result=result,
        approval_choices=choices,
    )


def parse_optional_json_object(value):
    if isinstance(value, dict):
        return value
    if isinstance(value, str):
        text = value.strip()
        if text.startswith("{"):
            try:
                parsed = json.loads(text)
            except json.JSONDecodeError:
                return {}
            return parsed if isinstance(parsed, dict) else {}
    return {}


def normalize_lead_form_tool_arguments(arguments, chat_payload):
    payload = dict(arguments or {})
    identity = business_identity(payload)
    page_id = str(payload.get("page_id") or payload.get("facebook_page_id") or identity.get("page_id") or "").strip()
    name = str(payload.get("name") or payload.get("form_name") or payload.get("lead_form_name") or payload.get("title") or "").strip()
    privacy_url = str(
        payload.get("privacy_policy_url")
        or payload.get("privacy_url")
        or payload.get("policy_url")
        or payload.get("privacy_policy")
        or ""
    ).strip()
    # Buyers commonly paste a public domain without a scheme in chat. Treat
    # that as an HTTPS URL instead of making the model ask for the same policy
    # link again. Never guess for whitespace, local paths, or non-host text.
    if privacy_url and not privacy_url.startswith(("http://", "https://")):
        host_candidate = privacy_url.split("/", 1)[0]
        if "." in host_candidate and " " not in privacy_url:
            privacy_url = f"https://{privacy_url.lstrip('/')}"
    link_text = str(payload.get("privacy_policy_link_text") or payload.get("privacy_link_text") or "Política de privacidad").strip()[:70]
    questions = (
        payload.get("questions")
        or payload.get("form_questions")
        or payload.get("fields")
        or payload.get("lead_fields")
        or []
    )
    normalized = {
        "page_id": page_id,
        "name": name,
        "questions": SocialFlowClient.normalize_lead_form_questions(questions),
        "privacy_policy_url": privacy_url,
        "privacy_policy_link_text": link_text or "Política de privacidad",
        "follow_up_action_url": str(payload.get("follow_up_action_url") or payload.get("thank_you_url") or payload.get("landing_url") or payload.get("website_url") or "").strip(),
        "locale": str(payload.get("locale") or "").strip(),
        "form_type": SocialFlowClient.normalize_lead_form_form_type(payload.get("form_type") or payload.get("intent") or "HIGHER_INTENT"),
        "context_card": parse_optional_json_object(payload.get("context_card") or payload.get("intro_card")),
        "thank_you_page": parse_optional_json_object(payload.get("thank_you_page") or payload.get("thank_you")),
        "custom_disclaimer": parse_optional_json_object(payload.get("custom_disclaimer") or payload.get("disclaimer")),
        "business_goal": str(payload.get("business_goal") or payload.get("goal") or "").strip(),
        "notes": str(payload.get("notes") or payload.get("agent_notes") or "").strip(),
    }
    if not normalized["locale"]:
        normalized["locale"] = "es_LA" if chat_lang(chat_payload) == "es" else "en_US"
    return normalized


def stage_lead_form_creation(arguments, chat_payload):
    payload = normalize_lead_form_tool_arguments(arguments, chat_payload)
    missing = []
    if not payload.get("page_id"):
        missing.append("page_id")
    if not payload.get("name"):
        missing.append("name")
    if not str(payload.get("privacy_policy_url") or "").startswith(("http://", "https://")):
        missing.append("privacy_policy_url")
    if not payload.get("questions"):
        missing.append("questions")
    if missing:
        return agent_action_result(
            "stage_lead_form",
            False,
            chat_reply(
                chat_payload,
                f"Puedo diseñar el formulario contigo, pero falta esto: {', '.join(missing)}.",
                f"I can design the form with you, but this is missing: {', '.join(missing)}.",
            ),
            blocked=True,
            reason="missing_lead_form_detail",
            missing=missing,
        )
    forms_dir = OUTPUT_DIR / "lead_forms"
    forms_dir.mkdir(parents=True, exist_ok=True)
    slug = re.sub(r"[^a-z0-9]+", "-", payload["name"].lower()).strip("-")[:50] or "lead-form"
    out_path = forms_dir / f"lead_form_{datetime.now().strftime('%Y%m%d_%H%M%S')}_{slug}.json"
    write_json(out_path, payload)
    manual_steps = [
        "Abre Meta Ads Manager y crea o edita una campaña con el objetivo Clientes potenciales.",
        "En el conjunto de anuncios, elige Formularios instantáneos como ubicación de conversión.",
        "En el nivel Anuncio, abre la sección Formulario instantáneo y pulsa Crear formulario.",
        f"Crea y publica el formulario con el nombre exacto: {payload['name']}.",
        "Vuelve al chat y escribe: ya creé el formulario. Admira lo localizará en Meta y usará su ID real para preparar la campaña.",
    ]
    if chat_lang(chat_payload) != "es":
        manual_steps = [
            "Open Meta Ads Manager and create or edit a campaign with the Leads objective.",
            "At ad-set level, choose Instant forms as the conversion location.",
            "At ad level, open the Instant form section and click Create form.",
            f"Create and publish the form with this exact name: {payload['name']}.",
            "Return to chat and say: I created the form. Admira will locate it in Meta and use its real ID to prepare the campaign.",
        ]
    reply = chat_reply(
        chat_payload,
        (
            f"Ya diseñé la estructura de «{payload['name']}». Por la configuración actual de Meta, "
            "el formulario debe crearse una vez dentro de Ads Manager. Ve a Clientes potenciales → "
            "Formularios instantáneos → nivel Anuncio → Crear formulario, copia las preguntas y la política "
            "que definimos y publícalo. Cuando termines, dime «ya creé el formulario»; lo buscaré directamente "
            "en Meta y usaré su ID real para crear la campaña en pausa."
        ),
        (
            f"I designed the structure for “{payload['name']}”. With the current Meta setup, the form must be "
            "created once inside Ads Manager. Go to Leads → Instant forms → Ad level → Create form, copy the "
            "questions and privacy policy we defined, and publish it. When done, tell me “I created the form”; "
            "I will find it directly in Meta and use its real ID to create the paused campaign."
        ),
    )
    return agent_action_result(
        "stage_lead_form",
        False,
        reply,
        ok=True,
        planned=True,
        manual_creation_required=True,
        reason="meta_instant_form_manual_creation_required",
        draft_path=str(out_path),
        form_blueprint=payload,
        manual_steps=manual_steps,
        next_agent_action={
            "after_buyer_confirmation": "list_lead_forms",
            "match_page_id": payload["page_id"],
            "match_form_name": payload["name"],
            "then": "stage_campaign_with_lead_gen_form_id",
        },
    )


