def handle_save_brand_guide_tool(arguments, chat_payload, tool):
    raw_arguments = dict(arguments or {})
    arguments = normalize_general_payload(raw_arguments)
    image_paths = safe_image_paths(chat_payload)
    logo_signal = (
        "logo" in json.dumps(raw_arguments, ensure_ascii=False).lower()
        or "logo" in json.dumps(arguments, ensure_ascii=False).lower()
        or "logo" in str((chat_payload or {}).get("message", "")).lower()
    )
    if image_paths and logo_signal and not arguments.get("logo_path"):
        arguments = dict(arguments)
        try:
            logo = copy_brand_logo_from_path(image_paths[0], arguments.get("logo_notes") or "")
            arguments.update(logo)
        except ValueError:
            arguments.setdefault("logo_notes", "El comprador envio una imagen como referencia de logo, pero no pude guardarla como archivo de logo.")
    elif arguments.get("logo_path") and not str(arguments.get("logo_path") or "").startswith("brand_guides/assets/"):
        try:
            logo = copy_brand_logo_from_path(arguments.get("logo_path"), arguments.get("logo_notes") or "")
            arguments.update(logo)
        except ValueError:
            # Never turn an arbitrary/nonexistent path into an official logo.
            arguments.pop("logo_path", None)
            arguments["logo_status"] = "pending"
    if not arguments.get("brand_name") and not arguments.get("offer"):
        return agent_action_result(
            tool,
            False,
            chat_reply(chat_payload, "Necesito al menos el nombre de marca o qué vende para guardar la guía.", "I need at least the brand name or what it sells to save the guide."),
            blocked=True,
            reason="missing_brand_core",
        )
    result = save_general_brand_memory(arguments)
    phase = agent_onboarding_phase()
    if result.get("draft"):
        if result.get("saved") is False:
            reply = chat_reply(
                chat_payload,
                "No cambié la identidad oficial. Conservé la propuesta que el comprador realmente vio. No pidas una frase especial ni repitas la confirmación: si existe una marca oficial igual, continúa; si propones un cambio real, muéstralo completo antes de pedir una sola aprobación natural.",
                "I did not change the official identity. I preserved the proposal the buyer actually saw. Do not request a special phrase or repeat confirmation: if the same official brand already exists, continue; if this is a real change, show it completely before asking for one natural approval.",
            )
        else:
            reply = chat_reply(
                chat_payload,
                "Guardé esta dirección de marca como borrador. Preséntala completa al comprador y pide una sola confirmación natural antes de guardarla como buyer_confirmed.",
                "I saved this brand direction as a draft. Present it completely to the buyer and ask for one natural confirmation before saving it as buyer_confirmed.",
            )
    else:
        reply = chat_reply(chat_payload, f"Listo. Guardé la guía visual y verbal de la marca. Siguiente paso: {phase['next_step']}", f"Done. I saved the brand's visual and verbal guide. Next step: {phase['next_step']}")
    official_saved = result.get("saved") is True and result.get("draft") is not True
    return agent_action_result(
        tool,
        official_saved,
        reply,
        blocked=not official_saved,
        reason=result.get("reason", "") if not official_saved else "",
        saved=official_saved,
        draft=bool(result.get("draft")),
        result=result,
    )


